// ==========================================
// calcAvgPrice — harga rata-rata per baris broker_summary.
//
// value_idr = total nilai transaksi (Rp), lot = jumlah lot (1 lot = 100
// lembar di BEI). Kolom `avg_price` di tabel broker_summary sebelumnya
// selalu NULL karena tidak ada bagian aplikasi manapun yang menghitung
// & mengirimkannya saat insert — dipakai di 3 titik insert (bulk tarik
// Broker Stalker, form manual "Simpan" di halaman utama & detail;
// tempel CSV juga bermuara ke form manual yang sama jadi otomatis ikut
// terhitung). null kalau lot tidak ada/0 (avg price tidak bisa dihitung).
// ==========================================
function calcAvgPrice(value_idr, lot){
  const v = Number(value_idr), l = Number(lot);
  if(!Number.isFinite(v) || !Number.isFinite(l) || l <= 0) return null;
  return Math.round(v / (l * 100));
}
// ==========================================
// fmtCompactID — angka besar (lot/Rp) diringkas ala notasi finansial
// Indonesia: Rb=ribu, Jt=juta, M=miliar, T=triliun. Dipakai overlay
// "Broker Accum" di chart (baris "BA:" di tooltip) supaya angka lot/nilai
// yang besar tidak memenuhi tooltip. Selalu pakai tanda +/- di depan
// (dipakai utk net lot/net value yang bisa negatif).
// ==========================================
function fmtCompactID(n){
  if(n==null || !Number.isFinite(n)) return "-";
  const sign = n < 0 ? "-" : "+";
  const abs = Math.abs(n);
  let val, suffix;
  if(abs >= 1e12){ val = abs/1e12; suffix = "T"; }
  else if(abs >= 1e9){ val = abs/1e9; suffix = "M"; }
  else if(abs >= 1e6){ val = abs/1e6; suffix = "Jt"; }
  else if(abs >= 1e3){ val = abs/1e3; suffix = "Rb"; }
  else { val = abs; suffix = ""; }
  const decimals = suffix && val < 10 ? 2 : (suffix && val < 100 ? 1 : 0);
  return `${sign}${val.toFixed(decimals).replace(".", ",")}${suffix}`;
}

function escapeHtml(str){
  return String(str ?? "").replace(/[&<>"']/g, c => ({ "&":"&amp;", "<":"&lt;", ">":"&gt;", '"':"&quot;", "'":"&#39;" }[c]));
}

// ==========================================
// UTILITAS FILTER + SORT GENERIK UNTUK SEMUA TABEL
//
// Dipakai oleh tabel-tabel yang sebelumnya statis (Rekap Backtest,
// Portofolio, Target Bandar, Entry Price Scanner, Kraken Flow, dst) supaya
// tiap tabel punya kotak pencarian (filter teks bebas, dicek ke beberapa
// kolom sekaligus lewat `keys`) + header kolom yang bisa diklik buat sort
// (▲/▼), TANPA numpuk banyak variabel baru per tabel di `state` utama.
// Semua state (kata kunci filter + kolom & arah sort) disimpan per-ID
// tabel di state.tableUI, jadi tabel yang satu tidak saling bentrok
// dengan tabel lain walau dua-duanya kebetulan punya kolom bernama sama.
// ==========================================
function getTableUI(id){
  if(!state.tableUI) state.tableUI = {};
  if(!state.tableUI[id]) state.tableUI[id] = { filter: "", sortCol: null, sortAsc: true };
  return state.tableUI[id];
}

// Cocokkan `filterText` (bebas huruf besar/kecil) ke gabungan nilai-nilai
// yang dikembalikan `getFields(row)` (array of string/number/null).
function tableFilterRows(id, rows, getFields){
  const ui = getTableUI(id);
  const q = (ui.filter || "").trim().toLowerCase();
  if(!q) return rows;
  return rows.filter(row => {
    const fields = getFields(row) || [];
    return fields.some(f => String(f ?? "").toLowerCase().includes(q));
  });
}

// Urutkan `rows` sesuai state.tableUI[id].sortCol, di mana `accessors` adalah
// { [colKey]: row => nilai_untuk_dibandingkan }. Kalau belum ada kolom yang
// dipilih user, urutan asli (dari `rows`) dibiarkan apa adanya.
function tableSortRows(id, rows, accessors){
  const ui = getTableUI(id);
  if(!ui.sortCol || !accessors[ui.sortCol]) return rows;
  const getVal = accessors[ui.sortCol];
  const withIdx = rows.map((r,i) => ({ r, i }));
  withIdx.sort((a,b) => {
    let va = getVal(a.r), vb = getVal(b.r);
    const na = typeof va === "number" || va == null ? va : parseFloat(va);
    const nb = typeof vb === "number" || vb == null ? vb : parseFloat(vb);
    let cmp;
    if(Number.isFinite(na) && Number.isFinite(nb)){ cmp = na - nb; }
    else { cmp = String(va ?? "").localeCompare(String(vb ?? ""), "id"); }
    if(cmp === 0) return a.i - b.i; // stabil kalau nilainya sama
    return ui.sortAsc ? cmp : -cmp;
  });
  return withIdx.map(x => x.r);
}

// Header <th> yang bisa diklik buat sort, dipasangi data-table-sort/data-sort-col
// supaya kena delegasi klik generik di attachContentEvents(). `extraStyle`
// opsional buat kolom yang butuh style tambahan (mis. freeze/lebar).
function tableSortTh(id, label, col, extraStyle){
  const ui = getTableUI(id);
  const style = extraStyle ? ` style="${extraStyle}"` : "";
  let icon = `<span class="sort-icon"></span>`;
  if(ui.sortCol === col) icon = `<span class="sort-icon">${ui.sortAsc ? '▲' : '▼'}</span>`;
  return `<th class="sortable" data-table-sort="${id}" data-sort-col="${col}"${style}>${escapeHtml(label)} ${icon}</th>`;
}

// Kotak pencarian generik buat ditaruh di atas tabel. `id` DOM-nya dibuat
// otomatis (`tblFilter-<id>`) dan di-bind lewat bindSearchInputPreservingCursor
// supaya kursor ketikan tidak lompat-lompat tiap render() penuh dipanggil.
// `showExport` (default true) ikut menaruh tombol "📥 Export Excel" di
// sebelah kotak pencarian -- lihat tableExportBtnHtml()/registerTableExport()
// di bawah untuk cara mendaftarkan sumber datanya.
function tableFilterBoxHtml(id, placeholder, showExport){
  const ui = getTableUI(id);
  const exportBtn = showExport === false ? "" : tableExportBtnHtml(id);
  return `<div class="table-filter-box" style="margin-bottom:10px;display:flex;gap:8px;flex-wrap:wrap;align-items:center;">
    <input type="text" class="input" id="tblFilter-${id}" placeholder="${escapeHtml(placeholder || 'Cari...')}" value="${escapeHtml(ui.filter)}" style="max-width:280px;">
    ${exportBtn}
  </div>`;
}

// ==========================================
// EXPORT EXCEL GENERIK UNTUK SEMUA TABEL YANG PAKAI MEKANISME
// FILTER+SORT DI ATAS.
//
// Berbeda dari fungsi export lama yang ditulis manual per fitur
// (exportScreenerToExcel, exportPortfolioToExcel, dst -- tetap dipakai apa
// adanya karena sudah lebih spesifik/lengkap), ini dipakai untuk tabel yang
// SEBELUMNYA belum punya tombol export sama sekali. Alurnya:
//   1. Di dalam fungsi render tabel, setelah baris sudah difilter+disortir,
//      panggil registerTableExport(id, () => rowsYangLagiTampil, kolom, "Nama_File").
//      Didaftar ulang tiap kali render() penuh dipanggil (murah, cuma nyimpan
//      referensi closure) supaya data yang diekspor SELALU sama dengan yang
//      lagi kefilter/tersortir di layar saat tombol diklik.
//   2. Taruh tableExportBtnHtml(id) di toolbar tabel itu (otomatis ikut kalau
//      pakai tableFilterBoxHtml(id, ...) tanpa showExport=false).
//   3. rebindGenericTable(id) (dipanggil otomatis lewat GENERIC_TABLE_FILTER_IDS)
//      yang mem-bind klik tombolnya ke runTableExport(id).
// ==========================================
const _tableExportRegistry = {};

// `columns`: array of { label, get(row) } -- `get` boleh string nama field
// row juga (shorthand) selain function.
function registerTableExport(id, getRowsFn, columns, filenamePrefix){
  _tableExportRegistry[id] = { getRowsFn, columns, filenamePrefix: filenamePrefix || id };
}

function tableExportBtnHtml(id, label){
  return `<button type="button" class="btn btn-outline" data-table-export="${id}" title="Export data yang sedang tampil (sudah kefilter/tersortir) ke Excel">${escapeHtml(label || "📥 Export Excel")}</button>`;
}

function runTableExport(id){
  const reg = _tableExportRegistry[id];
  if(!reg) return;
  let rows = [];
  try { rows = reg.getRowsFn() || []; } catch(e){ console.warn("[tableExport] gagal ambil rows:", id, e); }
  if(!rows.length){ if(typeof showToast === "function") showToast("Tidak ada data untuk diekspor.", "down"); else alert("Tidak ada data untuk diekspor."); return; }
  const data = rows.map(row => {
    const obj = {};
    reg.columns.forEach(col => {
      obj[col.label] = typeof col.get === "function" ? col.get(row) : row[col.get];
    });
    return obj;
  });
  const worksheet = XLSX.utils.json_to_sheet(data);
  worksheet['!cols'] = Object.keys(data[0] || {}).map(k => ({ wch: Math.max(10, k.length + 2) }));
  const workbook = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(workbook, worksheet, String(reg.filenamePrefix).slice(0,31));
  const dateStr = todayLocalISO();
  XLSX.writeFile(workbook, `${String(reg.filenamePrefix).replace(/\s+/g,"_")}_${dateStr}.xlsx`);
}

// Dipanggil sekali per render dari attachContentEvents() untuk semua tabel
// yang pakai tableFilterBoxHtml() di atas -- cukup daftar ID-nya di
// GENERIC_TABLE_FILTER_IDS (lihat dekat definisi array itu).
function bindGenericTableFilter(id){
  bindSearchInputPreservingCursor(`tblFilter-${id}`, (val) => { getTableUI(id).filter = val; });
}

// Bind kotak pencarian + klik sort utk satu tabel generik. Selain dipanggil
// dari attachContentEvents() (lewat GENERIC_TABLE_FILTER_IDS, tiap render()
// penuh), fungsi ini JUGA dipanggil manual di tempat-tempat yang mengganti
// innerHTML SEBAGIAN tanpa lewat attachContentEvents (mis. update live-tick
// P/L Mengambang di renderPortoPositionsTable) -- supaya kotak pencarian &
// header sort di tabel itu tidak "mati" (kehilangan event listener) begitu
// elemen lamanya diganti elemen baru oleh innerHTML replace tsb.
function rebindGenericTable(id){
  bindGenericTableFilter(id);
  document.querySelectorAll(`[data-table-sort="${id}"]`).forEach(th => {
    th.onclick = () => {
      const col = th.dataset.sortCol;
      const ui = getTableUI(id);
      if(ui.sortCol === col){ ui.sortAsc = !ui.sortAsc; }
      else { ui.sortCol = col; ui.sortAsc = true; }
      render();
    };
  });
  // Tombol export (lihat tableExportBtnHtml()/registerTableExport() dekat
  // tableFilterBoxHtml) -- satu wiring ini otomatis berlaku utk semua tabel
  // yang terdaftar di GENERIC_TABLE_FILTER_IDS.
  document.querySelectorAll(`[data-table-export="${id}"]`).forEach(btn => {
    btn.onclick = () => runTableExport(id);
  });
}

// Daftar ID semua tabel yang pakai mekanisme filter+sort generik di atas.
// Tambahkan ID baru ke sini tiap kali tableFilterBoxHtml(id, ...) dipakai
// di tabel lain supaya kotak pencarian-nya ikut ke-wire otomatis.
const GENERIC_TABLE_FILTER_IDS = [
  "backtestRekap", "backtestScreenerRekap", "fibScan",
  "portoList", "portoPosisi",
  "targetBandar", "targetBandarTop",
  "entryScanner", "krakenFlow",
  // baggerLeaderboard sudah lama pakai tableSortTh() (lihat renderSkorBagger)
  // tapi lupa didaftarkan di sini -- akibatnya klik header di tabel Leaderboard
  // Skor Bagger tidak melakukan apa-apa (▲/▼ tampil tapi tidak ke-bind).
  "baggerLeaderboard",
  // Tabel-tabel di bawah ini sebelumnya statis (tidak bisa disortir sama
  // sekali) -- sekarang dipasangi tableSortTh()/tableSortRows() juga supaya
  // SEMUA tabel data di app ini konsisten bisa diurutkan lewat klik header.
  "dashboardLeaderboard", "detailHistorical", "detailInsider",
  "smartPick", "signalPerformance", "tickerSearchResult",
  // Tabel per-saham di tab mandiri "🧭 Rekap Saham" (lihat renderRekapSaham()).
  "rekapSaham",
  // Tabel ringkasan & detail drill-down panel "📌 Win Rate & Target per
  // Preset" di tab yang sama (lihat computeRekapPresetStats()/
  // rekapHistoryRowsWithLive()).
  "rekapPresetStats", "rekapHistDetail",
];

function getSupaHeaders() {
  return {
    "apikey": SUPABASE_KEY,
    "Authorization": "Bearer " + SUPABASE_KEY,
    "Content-Type": "application/json"
  };
}

// ==========================================
// supaFetch — pengganti fetch() polos untuk semua request TULIS
// (POST/PATCH/DELETE) ke Supabase.
//
// KENAPA INI PERLU: fetch() browser TIDAK melempar error untuk respons
// HTTP 4xx/5xx — hanya melempar kalau koneksi jaringan benar-benar putus.
// Kalau Supabase menolak insert (RLS, kolom salah, atau "Prefer:
// resolution=merge-duplicates" tanpa unique constraint yang cocok di
// tabel), balasannya tetap berupa response yang valid (cuma dengan
// status 400/401/409/dst + body {message,...}). Kode lama membungkus
// fetch dengan try{...}catch(e){} kosong dan TIDAK PERNAH mengecek
// res.ok — jadi kalau Supabase menolak, tidak ada error yang pernah
// muncul: data kelihatan "tersimpan" (karena localStorage sudah lebih
// dulu diupdate) padahal sebenarnya gagal sinkron ke server.
//
// supaFetch melempar Error berisi pesan asli dari Supabase kalau
// res.ok === false, supaya pemanggil bisa menampilkannya ke user lewat
// showError()/alert() alih-alih diam-diam gagal.
// ==========================================
// ==========================================
// LIVE DATA STOCKBIT (tidak resmi, pakai token extension milik user)
//
// PENTING: exodus.stockbit.com/stream/v3/symbol/{ticker} adalah endpoint
// yang diamati dari traffic stockbit.com sendiri (bukan API publik
// terdokumentasi resmi) — jadi bisa berubah/rusak kapan saja, dan skema
// response-nya belum 100% terverifikasi. mapStockbitQuote() di bawah
// mencoba beberapa nama field yang umum (last/close/price, bid/offer,
// volume) secara defensif; kalau tidak cocok, JSON mentah tetap
// ditampilkan apa adanya di UI (lihat renderStockbitPanel) supaya tidak
// ada data yang salah tafsir atau hilang diam-diam.
//
// CORS: karena dipanggil langsung dari browser di origin lain (bukan
// stockbit.com), permintaan LANGSUNG ke exodus.stockbit.com kemungkinan
// besar diblokir browser. Kalau state.stockbitProxyUrl diisi (Supabase
// Edge Function dsb.), request dikirim ke situ sebagai POST {url, token}
// dan proxy itu yang meneruskan ke Stockbit dari sisi server (tidak kena
// CORS) — lihat contoh proxy terpisah yang disediakan.
// ==========================================
// ==========================================
// stockbitRawRequest — satu titik request HTTP ke Stockbit (langsung atau
// lewat proxy), dipakai bersama oleh stockbitFetch, stockbitFetchMarketDetector,
// dan stockbitFetchHistorical. Sebelumnya ketiga fungsi ini menduplikasi logika
// fetch yang sama persis (termasuk tidak ada retry sama sekali untuk 429).
//
// RETRY 429: kalau Stockbit membalas 429 (rate limit) — yang sangat mungkin
// terjadi di tengah bulk fetch banyak ticker/hari — tunggu sesuai header
// "Retry-After" (kalau proxy/Stockbit mengirimnya) atau exponential backoff
// (1s, 2s, 4s) lalu coba lagi, maksimal STOCKBIT_MAX_RETRIES kali. Status
// HTTP lain (401/403/5xx/dst) TIDAK diretry — itu bukan soal rate limit
// sementara, jadi mencoba ulang cuma buang waktu tanpa hasil.
//
// STATUS "TERAKHIR BERHASIL": tiap kali request ini sukses (res.ok), waktunya
// dicatat ke state.stockbitLastSuccessAt supaya UI (lihat
// stockbitLiveDataStatus() & updateStockbitLastSuccessStatusUI()) bisa
// menunjukkan dengan jelas kapan data live terakhir kali benar-benar
// berhasil ditarik, tanpa user perlu buka console untuk tahu data sedang basi.
// ==========================================
const STOCKBIT_MAX_RETRIES = 3;

// Bersihkan whitespace nyasar & prefix "Bearer " yang mungkin kebawa ikut
// tersimpan (baik dari copy-paste manual di Pengaturan, dari tabel Supabase,
// maupun dari extension) — soalnya getSupaHeaders()/stockbitRawRequest() SUDAH
// menambahkan "Bearer " sendiri di depan token saat mengirim request. Kalau
// token yang tersimpan sudah mengandung "Bearer " juga, hasilnya jadi
// "Bearer Bearer eyJ..." (atau ada \n/spasi di ujung) — dan itu 401 instan,
// terus-menerus, TIDAK ADA HUBUNGANNYA dengan token itu sendiri masih
// berlaku/tidak.
function sanitizeStockbitToken(raw){
  let t = String(raw || "").trim();
  if(/^bearer\s+/i.test(t)) t = t.replace(/^bearer\s+/i, "").trim();
  return t;
}

async function stockbitRawRequest(url, extraHeaders = {}, attempt = 0){
  try{
    let res;
    if(state.stockbitProxyUrl){
      res = await fetch(state.stockbitProxyUrl, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ url, token: state.stockbitToken })
      });
    } else {
      res = await fetch(url, { headers: { "Authorization": `Bearer ${state.stockbitToken}`, ...extraHeaders } });
    }
    if(res.status === 429 && attempt < STOCKBIT_MAX_RETRIES){
      const retryAfterHeader = Number(res.headers.get("Retry-After"));
      const waitMs = Number.isFinite(retryAfterHeader) && retryAfterHeader > 0
        ? retryAfterHeader * 1000
        : 1000 * Math.pow(2, attempt); // 1s, 2s, 4s
      await new Promise(r => setTimeout(r, waitMs));
      return stockbitRawRequest(url, extraHeaders, attempt + 1);
    }
    const text = await res.text();
    let json = null;
    try{ json = JSON.parse(text); }catch(e){ /* bukan JSON, biarkan null */ }
    if(!res.ok){
      const retryNote = (res.status === 429 && attempt >= STOCKBIT_MAX_RETRIES)
        ? ` (sudah dicoba ulang ${STOCKBIT_MAX_RETRIES}x dengan backoff, tetap kena rate limit)` : "";
      // Token bisa diputar oleh Stockbit ketika sesi login diperbarui. Minta
      // token terbaru dari stockbit_session lalu ulangi SATU request ini,
      // agar bulk tidak langsung gagal 401 hanya karena state lokal terlambat.
      if(res.status === 401 && attempt === 0){
        maybeResyncStockbitTokenFromSupabase();
        await new Promise(r => setTimeout(r, 250));
        if(state.stockbitToken) return stockbitRawRequest(url, extraHeaders, 1);
      }
      return { error: `HTTP ${res.status}${json && json.message ? " — " + json.message : ""}${retryNote}`, raw: json ?? text };
    }
    state.stockbitLastSuccessAt = Date.now();
    return { raw: json ?? text };
  }catch(e){
    const hint = state.stockbitProxyUrl ? "" : " — kemungkinan diblokir CORS oleh browser karena dipanggil langsung tanpa Proxy URL. Coba isi \"Proxy URL\" di Pengaturan.";
    return { error: e.message + hint };
  }
}

async function stockbitFetch(endpointTemplate, ticker){
  if(!state.stockbitToken) return { error: 'Token Stockbit belum diisi. Buka "⚙️ Pengaturan" → Live Data Stockbit.' };
  if(!endpointTemplate) return { error: "Endpoint belum diisi di Pengaturan." };
  const url = endpointTemplate.replace("{ticker}", encodeURIComponent(ticker));
  return stockbitRawRequest(url);
}

// ==========================================================
// KEANGGOTAAN INDEKS LQ45 & SYARIAH — ditarik dari endpoint internal
// Stockbit "classification/company" (ditemukan lewat DevTools → Network
// di stockbit.com/catalog/indeks/lq45 & /syariah), BUKAN API publik
// terdokumentasi, jadi bisa berubah/rusak kapan saja seperti endpoint
// Stockbit lain di file ini. `parent_id` tampaknya konstan (root
// taksonomi), `ids` beda per kategori:
//   - 628 = Syariah (ISSI) — jumlah konstituennya (617) dekat dengan
//     DES OJK Periode I 2026 (622 saham)
//   - 550 = LQ45
//   - 1000003851 = FCA (Full Call Auction — papan pemantauan khusus)
//   - 1000005130 = Suspend (saham yang sedang disuspend BEI)
// Hasilnya di-upsert ke tabel Supabase `index_membership` (ticker,
// is_lq45, is_syariah, is_fca, is_suspended) lalu dipakai sebagai
// SUMBER UTAMA oleh loadLive() untuk kolom syariah/indexLq45/fca/
// suspended — menggantikan fallback statis SYARIAH_TICKERS & kolom
// lq45 di stocks_screener kalau tabel ini sudah terisi.
const STOCKBIT_CLASSIFICATION_PARENT_ID = 88;
const STOCKBIT_CLASSIFICATION_SYARIAH_ID = 628;
const STOCKBIT_CLASSIFICATION_LQ45_ID = 550;
const STOCKBIT_CLASSIFICATION_FCA_ID = 1000003851;
const STOCKBIT_CLASSIFICATION_SUSPEND_ID = 1000005130;
// Unsuspend (baru dicabut suspensinya) dan FCA Out (baru keluar dari papan
// pemantauan khusus/Full Call Auction) -- filter tambahan di panel
// "Klasifikasi Emiten" screener. ID dikonfirmasi user langsung dari DevTools
// (Network → request "classification/company?ids=...&parent_id=88"):
// 1000005131 = Unsuspend, 1000005132 = FCA Out (satu rangkaian id sama
// Suspend 1000005130 di atas). Filter UMA sengaja tidak dipakai (di-skip).
const STOCKBIT_CLASSIFICATION_UNSUSPEND_ID = 1000005131;
const STOCKBIT_CLASSIFICATION_FCA_OUT_ID = 1000005132;

async function fetchStockbitClassificationTickers(classificationId){
  if(!classificationId) return { error: "ID klasifikasi belum diisi" };
  const url = `https://exodus.stockbit.com/emitten/classification/company?ids=${classificationId}&parent_id=${STOCKBIT_CLASSIFICATION_PARENT_ID}`;
  const res = await stockbitRawRequest(url);
  if(res.error) return res;
  const companies = res.raw?.data?.[0]?.companies || [];
  return { tickers: companies.map(c => String(c.symbol || "").toUpperCase()).filter(Boolean) };
}

// Sync satu klasifikasi (LQ45 atau Syariah) ke tabel index_membership.
// `column` = "is_lq45" atau "is_syariah". Upsert per-batch (satu request
// PATCH/POST ke PostgREST dengan Prefer: resolution=merge-duplicates)
// supaya ticker yang sudah ada baris-nya (misal sudah is_syariah=true)
// tidak tertimpa jadi baris baru, cuma kolomnya yang di-update.
async function syncIndexMembership(classificationId, column){
  const { tickers, error } = await fetchStockbitClassificationTickers(classificationId);
  if(error){ showError(`Gagal sync ${column}: ${error}`); return { error }; }
  if(!tickers.length){ showError(`Sync ${column}: 0 ticker didapat dari Stockbit — cek token/ids klasifikasi.`); return { error: "0 ticker" }; }
  const rows = tickers.map(t => ({ ticker: t, [column]: true }));
  const res = await supaFetch(`${SUPABASE_URL}/index_membership?on_conflict=ticker`, {
    method: "POST",
    headers: { ...getSupaHeaders(), Prefer: "resolution=merge-duplicates" },
    body: JSON.stringify(rows)
  });
  return { count: tickers.length, res };
}

async function syncLq45Membership(){ return syncIndexMembership(STOCKBIT_CLASSIFICATION_LQ45_ID, "is_lq45"); }
async function syncSyariahMembership(){ return syncIndexMembership(STOCKBIT_CLASSIFICATION_SYARIAH_ID, "is_syariah"); }

// FCA & Suspend beda dari LQ45/Syariah: keanggotaannya berubah harian
// (bahkan intraday), bukan per-periode review. syncIndexMembership() cuma
// menambah/meng-upsert baris jadi `true` — TIDAK pernah menurunkan balik
// ke `false` — jadi ticker yang kemarin FCA/suspend tapi hari ini sudah
// dicabut akan tetap kelihatan true kalau tidak direset dulu. Makanya
// sebelum upsert, kolomnya di-reset dulu (PATCH is_fca/is_suspended=false
// yang lagi true) supaya hasil akhirnya selalu snapshot HARI INI, bukan
// akumulasi dari sync-sync sebelumnya.
async function resetIndexMembershipColumn(column){
  try {
    await supaFetch(`${SUPABASE_URL}/index_membership?${column}=eq.true`, {
      method: "PATCH",
      headers: { ...getSupaHeaders(), "Content-Type": "application/json" },
      body: JSON.stringify({ [column]: false })
    });
    return { ok: true };
  } catch (e) {
    // Tabel/kolom belum ada (migration belum dijalankan) — biarkan sync
    // lanjut, nanti error yang lebih jelas muncul dari syncIndexMembership().
    return { ok: false, error: e.message };
  }
}

async function syncFcaMembership(){
  await resetIndexMembershipColumn("is_fca");
  return syncIndexMembership(STOCKBIT_CLASSIFICATION_FCA_ID, "is_fca");
}
async function syncSuspendMembership(){
  await resetIndexMembershipColumn("is_suspended");
  return syncIndexMembership(STOCKBIT_CLASSIFICATION_SUSPEND_ID, "is_suspended");
}
// Unsuspend/FCA Out — sama seperti FCA/Suspend, keanggotaannya berubah
// harian jadi kolomnya di-reset dulu sebelum upsert (lihat komentar
// resetIndexMembershipColumn di atas).
async function syncUnsuspendMembership(){
  await resetIndexMembershipColumn("is_unsuspended");
  return syncIndexMembership(STOCKBIT_CLASSIFICATION_UNSUSPEND_ID, "is_unsuspended");
}
async function syncFcaOutMembership(){
  await resetIndexMembershipColumn("is_fca_out");
  return syncIndexMembership(STOCKBIT_CLASSIFICATION_FCA_OUT_ID, "is_fca_out");
}

// Sync semuanya sekaligus (dipanggil dari console: syncAllIndexMembership(),
// atau tombol "🔄 Sync Klasifikasi Stockbit" di ⚙️ Pengaturan → Live
// Data Stockbit, lihat renderIndexMembershipSyncButton()).
async function syncAllIndexMembership(){
  const results = {
    lq45: await syncLq45Membership(),
    syariah: await syncSyariahMembership(),
    fca: await syncFcaMembership(),
    suspend: await syncSuspendMembership(),
    unsuspend: await syncUnsuspendMembership(),
    fcaOut: await syncFcaOutMembership()
  };
  return results;
}

// Tombol "Sync LQ45/Syariah/FCA/Suspend" di ⚙️ Pengaturan → Live Data
// Stockbit. Elemen ini TIDAK ada di markup HTML statis (app.js tidak
// menyentuh file HTML) — disisipkan sekali lewat JS persis setelah baris
// status token (#stockbitTokenStatus) pakai insertAdjacentHTML, jadi tidak
// perlu edit index.html terpisah. Dipanggil dari openSettings() tiap kali
// modal dibuka; idempotent lewat cek #indexMembershipSyncRow supaya tidak
// disisipkan berkali-kali kalau Pengaturan dibuka-tutup berulang.
function renderIndexMembershipSyncButton(){
  // Kalau #indexMembershipSyncRow belum ada di HTML (mis. index.html versi
  // lama belum diperbarui), sisipkan lewat JS persis setelah status token.
  if(!document.getElementById("indexMembershipSyncRow")){
    const anchor = document.getElementById("stockbitTokenStatus");
    if(!anchor) return; // markup HTML belum/berubah — skip diam-diam, jangan lempar error
    const rowHtml = `
      <div id="indexMembershipSyncRow" style="margin-top:8px;padding-top:8px;border-top:1px dashed color-mix(in srgb, currentColor 15%, transparent);">
        <div style="font-size:10.5px;color:var(--muted);margin-bottom:6px;">Keanggotaan LQ45 / Syariah / FCA / Suspend / Unsuspend / FCA Out (klasifikasi Stockbit → tabel <code>index_membership</code>)</div>
        <button type="button" id="btnSyncIndexMembership" class="btn btn-outline" style="font-size:11px;padding:6px 10px;">🔄 Sync Klasifikasi Stockbit</button>
        <div id="indexMembershipSyncStatus" style="font-size:10.5px;color:var(--muted);margin-top:6px;"></div>
      </div>`;
    anchor.insertAdjacentHTML("afterend", rowHtml);
  }
  // Baik yang sudah statis di HTML maupun yang baru disisipkan, binding
  // onclick selalu dijalankan di sini (elemen HTML statis TIDAK ada
  // onclick bawaan, jadi kalau baris ini di-skip, tombolnya diam saja
  // saat diklik).
  const btn = document.getElementById("btnSyncIndexMembership");
  if(btn) btn.onclick = runIndexMembershipSyncFromUI;
}

async function runIndexMembershipSyncFromUI(){
  const btn = document.getElementById("btnSyncIndexMembership");
  const statusEl = document.getElementById("indexMembershipSyncStatus");
  if(!state.stockbitToken){ if(statusEl) statusEl.textContent = "⚠️ Isi dulu Token Stockbit di atas."; return; }
  if(!SUPABASE_URL || !SUPABASE_KEY){ if(statusEl) statusEl.textContent = "⚠️ Isi dulu Supabase URL & Key."; return; }
  if(btn){ btn.disabled = true; btn.textContent = "⏳ Menyinkronkan..."; }
  if(statusEl) statusEl.textContent = "Menarik 4 klasifikasi dari Stockbit satu per satu, mohon tunggu...";
  try {
    // Dipanggil berurutan (bukan Promise.all) di dalam syncAllIndexMembership()
    // supaya request ke Stockbit tidak numpuk 4x sekaligus (lebih aman utk
    // rate limit token yang sama).
    const results = await syncAllIndexMembership();
    const label = { lq45: "LQ45", syariah: "Syariah", fca: "FCA", suspend: "Suspend", unsuspend: "Unsuspend", fcaOut: "FCA Out" };
    const parts = Object.entries(results).map(([k, v]) => {
      if(v && v.error) return `${label[k] || k}: ❌ ${v.error}`;
      return `${label[k] || k}: ✅ ${v?.count ?? 0} saham`;
    });
    if(statusEl) statusEl.innerHTML = parts.join("<br>");
    // Refresh state.stocks di background supaya badge FCA/Suspend/LQ45/
    // Syariah/Unsuspend/FCA Out di Screener langsung ikut update tanpa
    // perlu tutup-buka modal.
    Promise.resolve(loadLive()).catch(()=>{});
  } catch(e){
    if(statusEl) statusEl.textContent = `❌ Gagal sync: ${e.message}`;
  } finally {
    if(btn){ btn.disabled = false; btn.textContent = "🔄 Sync Klasifikasi Stockbit"; }
  }
}
// ==========================================================
// BROKER SUMMARY OTOMATIS DARI STOCKBIT (top 5 buy/sell per hari bursa)
//
// BEDA dari fitur live quote di atas: ini bisa memicu BANYAK request
// sekaligus (N ticker x M hari), jadi SENGAJA hanya jalan untuk ticker
// yang dicentang manual oleh user (state.selectedForBacktest) — tidak
// ada opsi "semua yang lolos filter" supaya tidak sengaja membombardir
// akun Stockbit sendiri dengan ratusan request.
//
// SKEMA RESPONS BELUM DIKETAHUI: endpoint broker summary Stockbit belum
// diverifikasi (field "Endpoint Broker Summary" di Pengaturan memang
// masih kosong by default, diisi sendiri oleh user dari tab Network).
// mapStockbitBrokerSummary() di bawah ini mencoba beberapa nama field
// yang umum secara defensif. Kalau skemanya tidak cocok, request itu
// ditandai gagal dengan JSON mentah tetap disimpan di
// state.stockbitBrokerBulkResults supaya user bisa lihat & laporkan
// balik nama field yang benar (baru mapping-nya disesuaikan).
// ==========================================================
// Kalender resmi Libur Bursa BEI 2026, dari pengumuman IDX No. Peng-00171/BEI.POP/09-2025
// (idx.co.id/id/berita/jadwal-libur-bursa) + berita yang mengutipnya. 21 tanggal di luar
// weekend, sudah dicocokkan dengan angka resmi "21 hari libur bursa 2026" yang diberitakan.
// PENTING: kalender ini WAJIB diupdate tiap tahun (IDX biasanya umumkan kalender tahun
// berikutnya sekitar September) — kalau BURSA_HOLIDAYS tidak ada entri untuk suatu tahun,
// tradingDaysBack() otomatis fallback ke exclude-weekend-saja untuk tahun itu (lihat di bawah).
const BURSA_HOLIDAYS = new Set([
  // 2026
  "2026-01-01", // Tahun Baru Masehi
  "2026-01-16", // Isra Mikraj Nabi Muhammad SAW
  "2026-02-16", // Cuti Bersama Tahun Baru Imlek 2577 Kongzili
  "2026-02-17", // Tahun Baru Imlek 2577 Kongzili
  "2026-03-18", // Cuti Bersama Hari Suci Nyepi
  "2026-03-19", // Hari Suci Nyepi Tahun Baru Saka 1948
  "2026-03-20", // Cuti Bersama Idul Fitri 1447 H
  "2026-03-23", // Cuti Bersama Idul Fitri 1447 H
  "2026-03-24", // Cuti Bersama Idul Fitri 1447 H
  "2026-04-03", // Wafat Yesus Kristus (Jumat Agung)
  "2026-05-01", // Hari Buruh Internasional
  "2026-05-14", // Kenaikan Yesus Kristus
  "2026-05-27", // Idul Adha 1447 H
  "2026-05-28", // Cuti Bersama Idul Adha 1447 H
  "2026-06-01", // Hari Lahir Pancasila
  "2026-06-16", // Tahun Baru Islam 1448 H (1 Muharram)
  "2026-08-17", // Hari Kemerdekaan RI ke-81
  "2026-08-25", // Maulid Nabi Muhammad SAW
  "2026-12-24", // Cuti Bersama Hari Raya Natal
  "2026-12-25", // Hari Raya Natal
  "2026-12-31", // Libur Bursa (penutup tahun)
]);

// Selalu pakai komponen tanggal LOKAL (getFullYear/getMonth/getDate), JANGAN
// toISOString() untuk merepresentasikan "tanggal kalender" — toISOString()
// mengonversi ke UTC, dan karena WIB = UTC+7, tengah malam lokal (mis. dari
// input <input type="date">, yang selalu diparse sebagai "T00:00:00" lokal)
// mundur jadi jam 17:00 UTC HARI SEBELUMNYA, sehingga tanggalnya salah (bug
// ini yang bikin rentang "28/08–29/08" kepetakan jadi 27/08). Semua tempat
// yang butuh "tanggal hari ini"/"tanggal dari Date object" WAJIB pakai
// helper ini, bukan .toISOString().slice(0,10).
function toLocalISODate(d){
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}
function todayLocalISO(){ return toLocalISODate(new Date()); }

function tradingDaysBack(n, fromDate = new Date()){
  // Hari bursa = Senin-Jumat DIKURANGI tanggal di BURSA_HOLIDAYS (kalau tahunnya terdaftar).
  // Untuk tahun yang belum ada di kalender di atas, otomatis fallback ke exclude-weekend-saja
  // (perilaku lama) — lebih baik sedikit kurang akurat daripada berhenti total.
  const days = [];
  let d = new Date(fromDate);
  while(days.length < n){
    d.setDate(d.getDate() - 1);
    const dow = d.getDay();
    const iso = toLocalISODate(d);
    if(dow !== 0 && dow !== 6 && !BURSA_HOLIDAYS.has(iso)) days.push(iso);
  }
  return days.reverse(); // urut lama -> baru
}

// Sama seperti tradingDaysBack, tapi rentangnya ditentukan lewat tanggal Dari–Sampai
// eksplisit (bukan "mundur N hari dari sekarang") — dipakai untuk Periode Tarik Otomatis
// yang sekarang bisa dipilih bebas lewat 2 input tanggal di UI.
function tradingDaysInRange(fromDateStr, toDateStr){
  const days = [];
  if(!fromDateStr || !toDateStr) return days;
  let d = new Date(fromDateStr + "T00:00:00");
  const end = new Date(toDateStr + "T00:00:00");
  if(d > end) return days; // Dari lebih baru dari Sampai — dianggap tidak valid, biar kelihatan kosong
  while(d <= end){
    const dow = d.getDay();
    const iso = toLocalISODate(d);
    if(dow !== 0 && dow !== 6 && !BURSA_HOLIDAYS.has(iso)) days.push(iso);
    d.setDate(d.getDate() + 1);
  }
  return days; // sudah urut lama -> baru
}

// Limit default kalau template endpoint di Pengaturan masih mengandung
// placeholder literal "{limit}" (mis. hasil copy-paste apa adanya dari
// DevTools Network). 5 dipilih karena app ini cuma memakai/menampilkan
// Top 5 Buy & Top 5 Sell (lihat buildBrokerByDate: .slice(0,5)) — jadi
// menarik lebih dari 5 tidak menambah manfaat apapun untuk fitur ini.
const STOCKBIT_MARKETDETECTOR_DEFAULT_LIMIT = 5;

async function stockbitFetchMarketDetector(ticker, fromDate, toDate, days){
  if(!state.stockbitToken) return { error: 'Token Stockbit belum diisi. Buka "⚙️ Pengaturan" → Live Data Stockbit.' };
  if(!state.stockbitBrokerEndpoint) return { error: 'Endpoint Broker Summary belum diisi di Pengaturan.' };
  // Dipanggil SATU tanggal per request (STOCKBIT_BROKER_CHUNK_DAYS=1, lihat
  // catatan di dekat konstanta itu) — fromDate selalu == toDate di titik ini,
  // jadi aman dipakai untuk mengisi SEMUA placeholder {date} di URL sekaligus
  // (endpoint /marketdetectors butuh {date} DUA KALI, untuk from= dan to=).
  // PENTING: pakai replaceAll, bukan replace() — replace() dengan argumen
  // string cuma mengganti kemunculan PERTAMA, jadi kalau template-nya punya
  // {date} lebih dari sekali (mis. "from={date}&to={date}"), yang kedua akan
  // tertinggal literal "{date}" di URL dan request-nya gagal/salah tanggal.
  //
  // BUG YANG DIPERBAIKI (Sep 2026): {limit} SEBELUMNYA TIDAK PERNAH diganti
  // di sini (beda dari stockbitFetchHistorical yang sudah benar) — kalau
  // template endpoint di Pengaturan menyertakan "&limit={limit}" apa
  // adanya (mis. hasil copy-paste dari DevTools), literal string "{limit}"
  // ikut terkirim sebagai NILAI parameter limit ke Stockbit, dan API-nya
  // menolak dengan HTTP 400 "Your request is invalid" untuk SEMUA ticker
  // tanpa terkecuali. Sekarang diganti otomatis ke angka wajar kalau
  // placeholder-nya masih ada (lihat STOCKBIT_MARKETDETECTOR_DEFAULT_LIMIT).
  const url = state.stockbitBrokerEndpoint
    .replaceAll("{ticker}", encodeURIComponent(ticker))
    .replaceAll("{date}", fromDate)
    .replaceAll("{limit}", encodeURIComponent(STOCKBIT_MARKETDETECTOR_DEFAULT_LIMIT));

  return stockbitRawRequest(url);
}

// Endpoint /order-trade/broker/distribution mengembalikan broker distribution
// untuk SATU tanggal ({date} di URL) — bukan rentang.
//
// SKEMA LAMA (diverifikasi manual dari DevTools 25 Agu 2026): data.brokers_buy /
// data.brokers_sell (alias kemungkinan buy/sell), tiap barisnya berisi broker
// FLAT + lot/value (alias blot/bval untuk buy, slot/sval untuk sell).
//
// SKEMA BARU (ketahuan berubah 08 Sep 2026 — endpoint sama, bentuk beda,
// balikan "message":"Successfully loaded Broker Distribution data"):
// data.by_value.top_broker_buy / data.by_value.top_broker_sell (kemungkinan
// juga ada data.by_volume.* paralel, dipakai sebagai fallback kalau by_value
// tidak ada). Tiap barisnya BUKAN flat lagi, tapi
// { detail:{code,type,amount}, distribute_to:[{code,type,amount},...] } —
// "detail" adalah broker top buy/sell itu sendiri (code+amount total),
// "distribute_to" adalah breakdown lawan transaksinya (di luar cakupan tabel
// Top 5 Buy/Sell yang dipakai app ini, jadi tidak diambil). Parser di bawah
// coba skema baru dulu, baru fallback ke skema lama — kalau Stockbit ganti
// skema lagi di masa depan, tambahkan cabang/alias baru di sini.
function pickAny(obj, keys){
  for(const k of keys){ if(obj?.[k] != null && obj[k] !== "") return obj[k]; }
  return null;
}

function parseStockbitMarketDetector(raw, fetchDate){
  if(!raw || typeof raw !== "object") return null;
  // Stockbit kadang membungkus payload beberapa tingkat (data.data,
  // data.result, result.data), jadi cari objek yang benar-benar memiliki
  // array distribution secara rekursif dangkal.
  let candidates = [raw, raw.data, raw.result, raw.data?.data, raw.data?.result, raw.result?.data, raw.result?.result].filter(v => v && typeof v === "object");
  // Endpoint /marketdetectors (beda dari /order-trade/broker/distribution)
  // membungkus SATU level lagi di ".broker_summary" — mis.
  // raw.data.broker_summary.{brokers_buy,brokers_sell} — yang tidak
  // tercakup kandidat di atas, jadi tanpa ini parser tidak pernah menemukan
  // baris broker sama sekali untuk skema ini (bukan cuma lot/type null,
  // TAPI seluruh baris gagal terbaca). Tambahkan varian ".broker_summary"
  // dari tiap kandidat yang sudah ada.
  candidates = candidates.concat(candidates.map(c => c.broker_summary).filter(v => v && typeof v === "object"));

  // --- Coba skema baru (by_value/by_volume.top_broker_buy/sell) dulu ---
  // PENTING: by_value (nilai transaksi) dan by_volume (jumlah lot) adalah DUA
  // cabang TERPISAH yang bisa muncul BERSAMAAN di payload yang sama — bukan
  // alternatif satu-atau-yang-lain. UI Stockbit sendiri menampilkan B.val DAN
  // B.lot sekaligus untuk broker yang sama, jadi kalau keduanya ada, keduanya
  // harus dibaca lalu digabung per kode broker (value dari by_value, lot dari
  // by_volume). Sebelumnya kode ini pakai `v.by_value || v.by_volume` yang
  // salah — begitu by_value ketemu, by_volume tidak pernah disentuh sama
  // sekali, sehingga lot selalu null walau datanya sebenarnya ada di
  // by_volume.
  const candidateWithByValOrVol = candidates.find(v => v && typeof v === "object" && ((v.by_value && (Array.isArray(v.by_value.top_broker_buy) || Array.isArray(v.by_value.top_broker_sell))) || (v.by_volume && (Array.isArray(v.by_volume.top_broker_buy) || Array.isArray(v.by_volume.top_broker_sell)))));
  if(candidateWithByValOrVol){
    const byValue = candidateWithByValOrVol.by_value;
    const byVolume = candidateWithByValOrVol.by_volume;
    // Tiap item { detail:{code,type,amount}, distribute_to:[...] } → ambil
    // "detail"-nya sebagai baris top-broker (code+amount) SEPERTI SEBELUMNYA,
    // TAPI sekarang "distribute_to" (kalau ada) ikut ditempel ke baris itu
    // sebagai r._distributeTo alih-alih dibuang begitu saja -- lihat
    // pemakaiannya di mergeByCode() & buildBrokerByDate() di bawah. Ini
    // dipasang generik (jalan utk skema respons /marketdetectors MAUPUN
    // /order-trade/broker/distribution, endpoint mana pun yang dites lewat
    // testStockbitBrokerEndpoint()) -- kalau memang tidak ada di skema
    // /marketdetectors, field ini cuma akan selalu null/kosong, tidak error.
    const flatten = (rows) => (rows || [])
      .map(r => {
        if(!r || typeof r !== "object") return null;
        const d = (r.detail && typeof r.detail === "object") ? r.detail : r;
        if(Array.isArray(r.distribute_to) && r.distribute_to.length) return { ...d, _distributeTo: r.distribute_to };
        return d;
      })
      .filter(Boolean);
    // Gabungkan baris value + volume per kode broker jadi satu baris
    // { broker_code, value_idr, lot, counterparties }. Kalau salah satu
    // cabang tidak ada, tetap jalan dengan yang tersedia (value atau lot saja).
    const mergeByCode = (valueRows, volumeRows) => {
      const byCode = {};
      const codeOf = (r) => String(pickAny(r, ["code","broker_code","broker","brokerCode"]) ?? "").toUpperCase();
      const normDist = (arr) => (arr || []).map(r => ({
        code: String(pickAny(r, ["code","broker_code","broker"]) ?? "").toUpperCase(),
        type: pickAny(r, ["type","investor_type"]) || null,
        amount: Number(pickAny(r, ["amount","value","value_idr"])) || 0,
      })).filter(r => r.code).sort((a,b) => Math.abs(b.amount) - Math.abs(a.amount));
      (valueRows || []).forEach(r => {
        const code = codeOf(r); if(!code) return;
        const row = (byCode[code] ||= { broker_code: code });
        row.value_idr = Number(pickAny(r, ["amount","value","value_idr"])) || 0;
        if(r._distributeTo) row.counterparties = normDist(r._distributeTo);
      });
      (volumeRows || []).forEach(r => {
        const code = codeOf(r); if(!code) return;
        const row = (byCode[code] ||= { broker_code: code });
        row.lot = Number(pickAny(r, ["amount","lot","volume","qty"])) || null;
        if(!row.counterparties && r._distributeTo) row.counterparties = normDist(r._distributeTo);
      });
      return Object.values(byCode);
    };
    const buyRows = mergeByCode(flatten(byValue?.top_broker_buy), flatten(byVolume?.top_broker_buy));
    const sellRows = mergeByCode(flatten(byValue?.top_broker_sell), flatten(byVolume?.top_broker_sell));
    return buildBrokerByDate(buyRows, sellRows, fetchDate);
  }

  // --- Fallback skema lama (flat brokers_buy/brokers_sell dst.) ---
  const bs = candidates.find(v => ["brokers_buy","brokers_sell","buy","sell","buy_rows","sell_rows","distribution_buy","distribution_sell"].some(k => Array.isArray(v[k]))) || raw;
  const buyRows = ["brokers_buy", "buy", "buy_rows", "distribution_buy", "buy_data", "buyer", "buyers"]
    .map(k => (Array.isArray(bs[k]) ? bs[k] : null)).find(Boolean) || [];
  const sellRows = ["brokers_sell", "sell", "sell_rows", "distribution_sell", "sell_data", "seller", "sellers"]
    .map(k => (Array.isArray(bs[k]) ? bs[k] : null)).find(Boolean) || [];
  if(!buyRows.length && !sellRows.length) return null;
  return buildBrokerByDate(buyRows, sellRows, fetchDate);
}

// Diambil keluar dari parseStockbitMarketDetector supaya bisa dipakai baik
// oleh cabang skema baru (by_value.top_broker_buy/sell) maupun skema lama
// (brokers_buy/brokers_sell) tanpa duplikasi logika pick/sort/top-5.
function buildBrokerByDate(buyRows, sellRows, fetchDate){
  const byDate = {};
  const ensure = (date) => (byDate[date] ||= { buy: [], sell: [] });
  const dateStr = fetchDate || todayLocalISO();
  const pick = (r, keys) => { for(const k of keys){ if(r?.[k] != null && r[k] !== "") return r[k]; } return null; };
  const mapRows = (rows, side) => rows.forEach(r => {
    // "netbs_broker_code" adalah nama field kode broker di skema
    // /marketdetectors (brokers_buy/brokers_sell) — beda dari skema
    // /order-trade/broker/distribution yang pakai "broker"/"broker_code" polos.
    const broker = pick(r, ["broker","broker_code","brokerCode","broker_id","brokerId","code","broker_name","netbs_broker_code"]);
    // Math.abs() karena skema /marketdetectors mengirim lot & value SISI JUAL
    // dengan tanda negatif (mis. slot:"-387452", sval:"-2.44e+11") — tanda
    // minusnya cuma penanda arah (jual), bukan nilai riil yang mau ditampilkan.
    const lot = Math.abs(Number(pick(r, side === "buy" ? ["lot","blot","buy_lot","quantity","qty"] : ["lot","slot","sell_lot","quantity","qty"]))) || null;
    const value = Math.abs(Number(pick(r, side === "buy" ? ["value","bval","buy_value","value_idr","net_value","amount"] : ["value","sval","sell_value","value_idr","net_value","amount"]))) || 0;
    // Tipe investor per broker (Asing/Lokal/Pemerintah) — field "type" di
    // skema /marketdetectors. Disimpan apa adanya (string dari Stockbit),
    // null kalau memang tidak ada di skema yang sedang dibaca.
    const investorType = pick(r, ["type", "investor_type", "investorType"]);
    if(broker != null) ensure(dateStr)[side].push({ broker_code:String(broker).toUpperCase(), lot, value_idr:value, investor_type: investorType || null });
  });
  mapRows(buyRows, "buy"); mapRows(sellRows, "sell");
  Object.values(byDate).forEach(d => {
    d.buy.sort((a,b) => b.value_idr - a.value_idr);
    d.sell.sort((a,b) => b.value_idr - a.value_idr);
    d.buy = d.buy.slice(0,5).map((r,i) => ({...r, rank:i+1}));
    d.sell = d.sell.slice(0,5).map((r,i) => ({...r, rank:i+1}));
  });
  return byDate;
}

// ==========================================
// HISTORICAL DATA STOCKBIT (tabel Date/Close/Change/Value/Volume di tab
// "Historical Data" halaman detail saham — Daily/Weekly/Monthly).
// Endpoint belum diverifikasi (lihat catatan di STOCKBIT_DEFAULT_HISTORICAL_EP),
// jadi parseStockbitHistorical() di bawah mencoba banyak kemungkinan nama
// field secara defensif (mirip mapStockbitQuote) — kalau skema Stockbit
// ternyata beda, tinggal tambah alias nama field baru di pick(...) masing2
// kolom, tidak perlu ubah struktur lain.
// ==========================================
async function stockbitFetchHistorical(ticker, period, opts = {}){
  if(!state.stockbitToken) return { error: 'Token Stockbit belum diisi. Buka "⚙️ Pengaturan" → Live Data Stockbit.' };
  if(!state.stockbitHistoricalEndpoint) return { error: 'Endpoint Historical Data belum diisi di Pengaturan. Ambil dari DevTools → Network saat membuka tab "Historical Data" di stockbit.com (lihat komentar STOCKBIT_DEFAULT_HISTORICAL_EP di app.js untuk caranya).' };
  // startDate/endDate: ISO YYYY-MM-DD. Default kalau tidak dikasih: 1 tahun
  // terakhir sampai hari ini (cukup luas untuk isi awal chart/backtest).
  const endDate = opts.endDate || todayLocalISO();
  const startDate = opts.startDate || toLocalISODate(new Date(new Date(endDate).setFullYear(new Date(endDate).getFullYear() - 1)));
  const limit = opts.limit || STOCKBIT_HISTORICAL_SAFE_LIMIT;
  const page = opts.page || 1;
  const url = state.stockbitHistoricalEndpoint
    .replace("{ticker}", encodeURIComponent(ticker))
    .replace("{period}", encodeURIComponent(stockbitHistoricalPeriodParam(period)))
    .replace("{start_date}", encodeURIComponent(startDate))
    .replace("{end_date}", encodeURIComponent(endDate))
    .replace("{limit}", encodeURIComponent(limit))
    .replace("{page}", encodeURIComponent(page));
  return stockbitRawRequest(url, { "x-platform": "web" });
}

// ==========================================
// PAGINASI OTOMATIS untuk rentang tanggal panjang.
//
// KENAPA INI PERLU (bug ditemukan 22 Sep 2026): pemanggil lama minta SATU
// halaman raksasa lewat limit = jumlah hari bursa di rentang (bisa 200-300+
// untuk rentang setahun) — Stockbit TERBUKTI menolak ini dengan
// "HTTP 400 — Invalid parameter" untuk SEMUA ticker sekaligus begitu limit
// terlalu besar. Contoh request yang TERBUKTI jalan dari user (22 Sep 2026):
// limit=50 dengan rentang ~4.5 bulan, responsnya lengkap dengan
// `data.paginate.next_page` untuk lanjut ke halaman berikutnya.
//
// Jadi solusinya BUKAN menaikkan limit, tapi memakai limit kecil+aman
// (STOCKBIT_HISTORICAL_SAFE_LIMIT) lalu mengikuti `paginate.next_page`
// berulang kali sampai (a) sudah tidak ada next_page, (b) baris TERTUA yang
// didapat sudah menembus startDate (data terurut baru->lama, jadi begitu
// sudah lewat startDate, halaman selanjutnya pasti di luar rentang yang
// diminta -- tidak perlu ditarik), atau (c) STOCKBIT_HISTORICAL_MAX_PAGES
// tercapai (pengaman terhadap loop tak berujung kalau next_page ternyata
// tidak pernah berhenti).
//
// Kalau nanti batas limit ASLI dari Stockbit sudah dikonfirmasi lebih
// tinggi dari 50 (misal lewat percobaan manual di DevTools), boleh naikkan
// STOCKBIT_HISTORICAL_SAFE_LIMIT -- tapi mekanisme paginate di bawah ini
// TETAP dipertahankan supaya rentang panjang manapun tetap aman walau
// batasnya berubah lagi di masa depan.
// ==========================================
const STOCKBIT_HISTORICAL_SAFE_LIMIT = 50; // dikonfirmasi manual bekerja 22 Sep 2026 -- lihat catatan di atas
const STOCKBIT_HISTORICAL_MAX_PAGES = 40;  // pengaman: 40 x 50 = 2000 baris historical, jauh lebih dari cukup bahkan utk rentang multi-tahun

async function stockbitFetchHistoricalRange(ticker, period, opts = {}){
  const endDate = opts.endDate || todayLocalISO();
  const startDate = opts.startDate || toLocalISODate(new Date(new Date(endDate).setFullYear(new Date(endDate).getFullYear() - 1)));
  const pageLimit = opts.pageLimit || STOCKBIT_HISTORICAL_SAFE_LIMIT;
  let page = 1;
  let allRows = [];
  let firstRaw = null;
  for(let i = 0; i < STOCKBIT_HISTORICAL_MAX_PAGES; i++){
    const res = await stockbitFetchHistorical(ticker, period, { startDate, endDate, limit: pageLimit, page });
    if(res.error) return { error: res.error, raw: firstRaw || res.raw, rows: allRows };
    if(!firstRaw) firstRaw = res.raw;
    const parsed = parseStockbitHistorical(res.raw);
    if(!parsed || !parsed.length) break; // halaman kosong / format tidak dikenali -- data sudah habis atau tidak ada
    allRows = allRows.concat(parsed);
    const oldestDateInPage = parsed.reduce((min,r) => (r.date && (!min || r.date < min)) ? r.date : min, null);
    const nextPage = res.raw?.data?.paginate?.next_page || res.raw?.paginate?.next_page || null;
    if(!nextPage) break; // Stockbit bilang tidak ada halaman lagi
    if(oldestDateInPage && oldestDateInPage <= startDate) break; // sudah cukup jauh ke belakang, tidak perlu halaman lagi
    page = nextPage;
    await new Promise(r => setTimeout(r, 150)); // jeda kecil antar-halaman, jaga rate limit Stockbit
  }
  return { raw: firstRaw, rows: allRows };
}

// Menerima response mentah dan mencoba menormalkannya jadi daftar baris
// { date, close, change, changePct, value, volume }. Mengembalikan null
// kalau tidak ditemukan array baris sama sekali (supaya UI bisa menampilkan
// JSON mentah apa adanya alih-alih data yang salah tafsir/hilang diam-diam).
function parseStockbitHistorical(raw){
  if(!raw || typeof raw !== "object") return null;
  const container = raw.data || raw.result || raw;
  const list = Array.isArray(container) ? container
    : Array.isArray(container?.result) ? container.result   // bentuk asli: { data: { result: [...] } }
    : Array.isArray(container?.rows) ? container.rows
    : Array.isArray(container?.chartbit) ? container.chartbit
    : Array.isArray(container?.data) ? container.data
    : Array.isArray(container?.historical) ? container.historical
    : null;
  if(!list || !list.length) return null;

  const pick = (row, ...keys) => { for(const k of keys){ if(row && row[k]!=null && row[k]!=="") return row[k]; } return null; };
  // Normalisasi berbagai kemungkinan format tanggal Stockbit (epoch ms/detik,
  // "20260828", "28-08-2026", dll.) jadi ISO YYYY-MM-DD lokal, supaya bisa
  // dibandingkan langsung dengan hasil tradingDaysInRange() saat Tarik Otomatis
  // bulk. Kalau gagal diparse, dikembalikan apa adanya (masih tampil di tabel,
  // cuma tidak akan ikut cocok di filter rentang tanggal bulk).
  const normDate = (v) => {
    if(v == null) return null;
    if(typeof v === "number") return toLocalISODate(new Date(v > 2e10 ? v : v * 1000));
    const s = String(v).trim();
    if(/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0,10);
    if(/^\d{8}$/.test(s)) return `${s.slice(0,4)}-${s.slice(4,6)}-${s.slice(6,8)}`;
    const m = s.match(/^(\d{1,2})[-\/](\d{1,2})[-\/](\d{4})$/);
    if(m) return `${m[3]}-${m[2].padStart(2,"0")}-${m[1].padStart(2,"0")}`;
    const parsed = new Date(s);
    return isNaN(parsed) ? s : toLocalISODate(parsed);
  };

  return list.map(row => ({
    date: normDate(pick(row, "date", "trade_date", "netbs_date", "period", "chart_date")),
    close: Number(pick(row, "close", "close_price", "last", "c")) || null,
    change: Number(pick(row, "change", "chg", "price_change")) || null,
    changePct: Number(pick(row, "change_percentage", "change_percent", "changePercent", "pct")) || null,
    value: Number(pick(row, "value", "value_idr", "val", "trade_value")) || null,
    volume: Number(pick(row, "volume", "vol", "trade_volume")) || null,
    // Field bonus yang ternyata sudah disediakan endpoint ini sekalian —
    // termasuk FOREIGN FLOW HARIAN per ticker (foreign_buy/foreign_sell/
    // net_foreign), jadi tidak perlu endpoint marketdetectors terpisah untuk
    // data asing (lihat diskusi "Data foreign bisa diambil dari stockbit?").
    open: Number(pick(row, "open")) || null,
    high: Number(pick(row, "high")) || null,
    low: Number(pick(row, "low")) || null,
    frequency: Number(pick(row, "frequency")) || null,
    foreignBuy: Number(pick(row, "foreign_buy")) || null,
    foreignSell: Number(pick(row, "foreign_sell")) || null,
    netForeign: pick(row, "net_foreign") != null ? Number(pick(row, "net_foreign")) : null,
  })).filter(r => r.date);
}

// Endpoint /marketdetectors membatasi TOTAL baris gabungan lewat "limit" —
// tapi dari pengujian lapangan (25 Agu 2026), ada masalah yang LEBIH
// MENDASAR: endpoint ini kelihatannya TIDAK benar-benar mendukung rentang
// from–to. Waktu dicoba pecah jadi beberapa chunk beberapa hari (mis. 4
// hari per request), hasilnya PERSIS 1 hari data per chunk — cocok dengan
// pola "cuma mengembalikan data untuk tanggal `to`, mengabaikan `from`".
// Jadi satu-satunya cara yang terbukti dapat semua hari adalah: minta
// SATU hari per request (from = to = tanggal itu), bukan rentang.
// Ini artinya jumlah request ke Stockbit jadi = jumlah hari yang diminta
// (bukan lagi dibagi jadi beberapa chunk besar) — lebih banyak request,
// tapi ini yang terbukti benar-benar mengembalikan datanya.
const STOCKBIT_BROKER_CHUNK_DAYS = 1; // JANGAN naikkan kecuali endpoint terbukti mendukung rentang beneran — lihat catatan di atas

function chunkArray(arr, size){
  const out = [];
  for(let i=0; i<arr.length; i+=size) out.push(arr.slice(i, i+size));
  return out;
}

// Cek tanggal mana saja (dari kandidat `dates`) yang SUDAH ada baris
// broker_activity-nya di Supabase untuk ticker ini (dari SUMBER MANAPUN --
// Lacak Broker atau Tarik Otomatis Broker Summary, keduanya sekarang menulis
// ke tabel yang sama), supaya tidak perlu tarik ulang ke Stockbit untuk hari
// yang datanya sudah tersimpan.
async function fetchExistingBrokerDates(ticker, dates){
  if(!dates.length) return new Set();
  try{
    const qs = new URLSearchParams({
      stock_code: `eq.${ticker}`,
      trade_date: `in.(${dates.join(",")})`,
      select: "trade_date",
    });
    const res = await fetch(`${SUPABASE_URL}/broker_activity?${qs}`, { headers: getSupaHeaders(), cache: "no-store" });
    if(!res.ok) return new Set(); // gagal cek = anggap belum ada, biar tetap ditarik (aman, cuma jadi tidak optimal)
    const rows = await res.json();
    return new Set(rows.map(r => r.trade_date));
  }catch(e){
    return new Set();
  }
}

// Progress bar kecil dipakai tarik Broker Activity & Uji Sinyal. `detail` sudah
// harus aman HTML (panggil escapeHtml sendiri untuk teks dinamis).
function bsProgressHtml(title, pct, detail){
  const p = Math.max(0, Math.min(100, Math.round(pct || 0)));
  return `<div style="margin-top:10px;">
    <div style="display:flex;justify-content:space-between;gap:8px;font-size:11.5px;margin-bottom:5px;"><b>${escapeHtml(title)}</b><span class="mono">${p}%</span></div>
    <div style="height:8px;border-radius:99px;background:color-mix(in srgb, currentColor 10%, transparent);overflow:hidden;"><div style="height:100%;width:${p}%;background:linear-gradient(90deg,var(--teal),var(--up));transition:width .2s;"></div></div>
    <div style="font-size:11px;color:var(--muted);margin-top:5px;line-height:1.55;">${detail}</div>
  </div>`;
}
function bsFmtEta(ms){
  if(!Number.isFinite(ms) || ms < 0) return "";
  const sec = Math.round(ms / 1000);
  return sec < 60 ? `${sec} dtk` : `${Math.floor(sec / 60)} mnt ${sec % 60} dtk`;
}
// Susun HTML progress tarik Broker Activity dari state.brokerActivityBulkProgress.
function brokerActivityProgressHtml(){
  const p = state.brokerActivityBulkProgress || {};
  const total = p.total || 1;
  const within = p.phase === "simpan"
    ? 0.9 + 0.1 * (p.saveDone || 0) / Math.max(1, p.saveTotal || 1)
    : 0.9 * (p.dateDone || 0) / Math.max(1, p.dateTotal || 1);
  const pct = ((p.done || 0) + within) / total * 100;
  let eta = "";
  if(p.dateDone > 2 && p.dateTotal > p.dateDone && p.fetchStartedAt){
    eta = ` · sisa ± ${bsFmtEta((Date.now() - p.fetchStartedAt) / p.dateDone * (p.dateTotal - p.dateDone))}`;
  }
  const title = p.broker ? `Broker ${p.broker} (${Math.min((p.done || 0) + 1, total)}/${total})` : "Menyiapkan…";
  let detail;
  if(p.phase === "cek") detail = "Memeriksa hari mana yang sudah ada di database…";
  else if(p.phase === "simpan") detail = `Menyimpan ke Supabase… batch ${p.saveDone || 0}/${p.saveTotal || 1} · ${(p.rows || 0).toLocaleString("id-ID")} baris`;
  else detail = `Menarik dari Stockbit: hari ${p.dateDone || 0}/${p.dateTotal || 0}${p.currentDate ? ` (${escapeHtml(p.currentDate)})` : ""} · ${(p.rows || 0).toLocaleString("id-ID")} baris terkumpul${p.skipped ? ` · ${p.skipped} hari dilewati (sudah ada)` : ""}${eta}`;
  return bsProgressHtml(title, pct, detail);
}
function updateBrokerActivityProgressUI(patch){
  if(patch) Object.assign(state.brokerActivityBulkProgress, patch);
  const el = document.getElementById("baProgressBox");
  if(el) el.innerHTML = brokerActivityProgressHtml();
}

// Pecah input kode broker ("AK, YP CC;BK") jadi array kode unik huruf besar.
function parseBrokerCodesInput(text){
  return [...new Set(String(text||"").split(/[\s,;]+/).map(t=>t.trim().toUpperCase()).filter(t=>/^[A-Z0-9]{2,3}$/.test(t)))];
}

// Kebalikan dari fetchExistingBrokerDates di atas, tapi untuk tabel
// broker_activity (per BROKER, bukan per saham) — dipakai fetchAndSaveBrokerActivityBulk
// supaya hari yang datanya sudah tersimpan untuk broker ini tidak ditarik ulang.
async function fetchExistingBrokerActivityDates(brokerCode, dates){
  if(!dates.length) return new Set();
  try{
    const qs = new URLSearchParams({
      broker_code: `eq.${brokerCode}`,
      trade_date: `in.(${dates.join(",")})`,
      select: "trade_date",
    });
    const res = await fetch(`${SUPABASE_URL}/broker_activity?${qs}`, { headers: getSupaHeaders(), cache: "no-store" });
    if(!res.ok) return new Set();
    const rows = await res.json();
    return new Set(rows.map(r => r.trade_date));
  }catch(e){
    return new Set();
  }
}

// Tarik & simpan Broker Activity (SEMUA saham yang ditransaksikan satu/
// beberapa broker, bukan cuma top-5 seperti Broker Summary) ke tabel
// broker_activity Supabase — strukturnya SENGAJA ditiru dari
// fetchAndSaveBrokerSummaryBulk di atas (skip hari yang sudah ada kecuali
// hari bursa terakhir, chunk 1 hari/request, jeda antar-request, upsert)
// supaya perilakunya konsisten & gampang dirawat bareng.
// Dipanggil dari mode "Lacak Broker" di Broker Stalker — lihat renderBrokerStalker().
async function fetchAndSaveBrokerActivityBulk(brokerCodes, rangeFrom, rangeTo){
  if(state.brokerActivityBulkLoading) return;
  const codes = [...new Set((brokerCodes||[]).map(c => String(c||"").trim().toUpperCase()).filter(Boolean))];
  if(!codes.length){
    state.brokerActivityBulkResults = [{ broker:"-", date:"-", ok:false, msg:"Isi kode broker dulu (mis. AK, YP, CC)." }];
    render(); return;
  }
  if(!state.stockbitToken){ openSettings(); return; }
  if(!state.stockbitBrokerActivityEndpoint){
    state.brokerActivityBulkResults = [{ broker:"-", date:"-", ok:false, msg:'Isi dulu "Endpoint Broker Activity" di ⚙️ Pengaturan.' }];
    render(); return;
  }
  if(!SUPABASE_URL || !SUPABASE_KEY){ openSettings(); return; }

  const tradingDates = tradingDaysInRange(rangeFrom, rangeTo);
  if(!tradingDates.length){
    state.brokerActivityBulkResults = [{ broker:"-", date:"-", ok:false, msg:'Periode tanggal tidak valid atau tidak ada hari bursa di rentang itu.' }];
    render(); return;
  }
  const fromDate = tradingDates[0], toDate = tradingDates[tradingDates.length - 1];
  const latestDate = toDate; // hari bursa terakhir SELALU ditarik ulang (sama seperti Broker Summary — datanya bisa masih berjalan)

  state.brokerActivityBulkLoading = true;
  state.brokerActivityBulkProgress = { done: 0, total: codes.length, broker: codes[0], phase: "cek", dateDone: 0, dateTotal: 0, currentDate: "", rows: 0, skipped: 0, saveDone: 0, saveTotal: 0 };
  state.brokerActivityBulkResults = [];
  render();

  for(const brokerCode of codes){
    updateBrokerActivityProgressUI({ broker: brokerCode, phase: "cek", dateDone: 0, dateTotal: 0, currentDate: "", rows: 0, skipped: 0, saveDone: 0, saveTotal: 0 });
    const existingDates = await fetchExistingBrokerActivityDates(brokerCode, tradingDates);
    const datesToFetch = tradingDates.filter(d => !existingDates.has(d) || d === latestDate);
    const skippedCount = tradingDates.length - datesToFetch.length;
    updateBrokerActivityProgressUI({ phase: "tarik", dateTotal: datesToFetch.length, skipped: skippedCount, fetchStartedAt: Date.now() });

    if(!datesToFetch.length){
      state.brokerActivityBulkResults.push({ broker:brokerCode, date:`${fromDate}..${toDate}`, ok:true, msg:`Semua ${tradingDates.length} hari sudah ada di database, dilewati.` });
      state.brokerActivityBulkProgress.done++;
      render();
      continue;
    }

    let rows = [];
    let lastError = null;
    let anyOk = false;
    const missingDates = [];
    for(const d of datesToFetch){
      updateBrokerActivityProgressUI({ currentDate: d });
      const res = await stockbitFetchBrokerActivity(brokerCode, d, d);
      if(res.error){
        lastError = res.error;
        missingDates.push(d);
      } else {
        const parsed = parseStockbitBrokerActivity(res.raw, d, brokerCode);
        if(parsed && parsed.length){
          rows = rows.concat(parsed);
          anyOk = true;
        } else if(parsed && parsed.length === 0){
          anyOk = true; // 200 sukses, memang tidak ada transaksi broker ini hari itu — bukan error
        } else {
          try{ lastError = `Skema respons tidak dikenali. Raw JSON: ${JSON.stringify(res.raw).slice(0,1600)}`; }
          catch(e){ lastError = "Skema respons tidak dikenali / raw JSON tidak bisa dibaca."; }
          missingDates.push(d);
        }
      }
      updateBrokerActivityProgressUI({ dateDone: (state.brokerActivityBulkProgress.dateDone || 0) + 1, rows: rows.length });
      if(datesToFetch.length > 1) await new Promise(r => setTimeout(r, 300));
    }

    if(!anyOk){
      state.brokerActivityBulkResults.push({ broker:brokerCode, date:`${fromDate}..${toDate}`, ok:false, msg: lastError || "Tidak ada data." });
    } else if(!rows.length){
      let msg = `Tidak ada transaksi untuk broker ${brokerCode} di periode ini.`;
      if(skippedCount) msg += ` (${skippedCount} hari lain dilewati, sudah ada di database.)`;
      state.brokerActivityBulkResults.push({ broker:brokerCode, date:`${fromDate}..${toDate}`, ok:true, msg });
    } else {
      try{
        // Disimpan per batch 1000 baris supaya progress terlihat & request tidak kebesaran.
        const SAVE_BATCH = 1000;
        updateBrokerActivityProgressUI({ phase: "simpan", rows: rows.length, saveDone: 0, saveTotal: Math.ceil(rows.length / SAVE_BATCH) });
        for(let i = 0; i < rows.length; i += SAVE_BATCH){
          await supaFetch(`${SUPABASE_URL}/broker_activity?on_conflict=broker_code,trade_date,stock_code,side`, {
            method: "POST",
            headers: { ...getSupaHeaders(), "Prefer": "resolution=merge-duplicates,return=minimal" },
            body: JSON.stringify(rows.slice(i, i + SAVE_BATCH))
          });
          updateBrokerActivityProgressUI({ saveDone: Math.floor(i / SAVE_BATCH) + 1 });
        }
        let msg = `Tersimpan ${rows.length} baris (${new Set(rows.map(r=>r.stock_code)).size} saham) untuk ${datesToFetch.length - missingDates.length}/${datesToFetch.length} hari.`;
        if(skippedCount) msg += ` (${skippedCount} hari lain dilewati, sudah ada di database.)`;
        if(missingDates.length) msg += ` ⚠️ ${missingDates.length} hari gagal: ${missingDates.join(", ")}.`;
        state.brokerActivityBulkResults.push({ broker:brokerCode, date:`${fromDate}..${toDate}`, ok:true, msg });
      }catch(e){
        state.brokerActivityBulkResults.push({ broker:brokerCode, date:`${fromDate}..${toDate}`, ok:false, msg:"Gagal simpan ke DB: " + e.message });
      }
    }
    state.brokerActivityBulkProgress.done++;
    render();
    await new Promise(r => setTimeout(r, 350));
  }

  state.brokerActivityBulkLoading = false;
  render();
  // Refresh tampilan Broker Stalker kalau sedang menampilkan broker yang baru ditarik ini.
  if(state.brokerStalkerMode === 'broker' && codes.includes(String(state.brokerStalkerQuery||'').trim().toUpperCase())) searchBrokerStalker();
}

// Parse isi file .txt daftar ticker -- terima format bebas: satu ticker per
// baris, dipisah koma, titik-koma, atau spasi/tab, boleh campur. Kode saham
// IDX selalu huruf (kadang diikuti 1 digit untuk saham seri tertentu, mis.
// preferen), jadi validasinya longgar: 2-6 karakter alfanumerik, disaring
// dari baris komentar (diawali # atau //) supaya orang bisa kasih catatan di
// file-nya sendiri. Duplikat dibuang, urutan asli file dipertahankan.
function parseTickerListTxt(text){
  const seen = new Set();
  const out = [];
  String(text || "")
    .split(/[\r\n,;\t ]+/)
    .map(t => t.trim().toUpperCase())
    .filter(t => t && !t.startsWith("#") && !t.startsWith("//"))
    .filter(t => /^[A-Z0-9]{2,6}$/.test(t))
    .forEach(t => { if(!seen.has(t)){ seen.add(t); out.push(t); } });
  return out;
}

// Sumber ticker bersama untuk tombol-tombol bulk (Live Stockbit, Broker
// Summary, Historical Data): kalau ada daftar hasil upload .txt, itu yang
// dipakai (prioritas tertinggi, karena ini pilihan eksplisit paling
// spesifik) -- kalau tidak, fallback ke perilaku lama: baris yang dicentang
// di tabel Screener, atau kalau tidak ada yang dicentang, semua saham yang
// lolos filter saat ini.
function resolveBulkTickers(){
  if(state.uploadedBulkTickers.length) return [...state.uploadedBulkTickers];
  const checked = [...state.selectedForBacktest];
  return checked.length ? checked : getSorted(getFiltered()).map(s => s.ticker);
}

// ==========================================
// SUMBER TICKER untuk tab Watchlist / Portofolio / Backtest — dipakai oleh
// toolbar "Tarik Data Massal" di masing-masing tab itu (lihat
// renderBulkPullToolbar() di bawah), supaya bulk-fetch (Live Stockbit,
// Historical + Update Teknikal) bisa langsung ditarget ke saham yang ADA
// di tab tsb, tanpa perlu pindah dulu ke tab Screener & centang manual.
// ==========================================
function getWatchlistTickers(){
  return [...state.watchlist];
}
function getPortfolioTickers(){
  return [...new Set(state.portfolio.map(p => p.ticker).filter(Boolean))];
}
function getBacktestTickers(){
  const set = new Set();
  state.backtests.forEach(b => (b.items||[]).forEach(it => { if(it && it.ticker) set.add(it.ticker); }));
  return [...set];
}

// Toolbar generik "Tarik Data Massal" — dipakai di tab Watchlist, Portofolio,
// dan Backtest. namespace dipakai untuk prefix id elemen DOM (lihat wiring
// di attachContentEvents, cari "BULK PULL TOOLBAR"), supaya tiap tab punya
// tombol sendiri tapi manggil fungsi bulk yang SAMA PERSIS dengan yang
// dipakai toolbar Screener (fetchStockbitLiveBulk, fetchAndSaveHistoricalBulk,
// updateTechnicalIndicatorsBulk) — cuma daftar tickernya beda sumber.
function renderBulkPullToolbar(namespace, tickers, contextLabel){
  if(!tickers.length){
    return `<div class="bs-msg" style="margin-bottom:14px;font-size:12px;">Belum ada saham di ${escapeHtml(contextLabel)} untuk ditarik datanya.</div>`;
  }
  // Default rentang Dari–Sampai kalau belum pernah diisi sama sekali (state
  // sama dgn "Historical (Daily)" di toolbar Screener) — dipilih ~260 hari
  // bursa (bukan 10), karena update teknikal (RSI/MACD/dst) butuh minimal
  // ~30 bar, dan kolom seperti MA200/52w high-low (lihat TI_MIN_BARS_52W)
  // baru terisi kalau histori yang tersimpan >=252 hari bursa.
  // "Sampai" SELALU tanggal hari ini (bukan hari bursa terakhir) supaya user
  // tidak perlu geser manual tiap hari — tradingDaysBack() sendiri sengaja
  // mundur mulai dari KEMARIN (lihat komentarnya), jadi timpa lagi ke hari
  // ini di sini.
  if(!state.hdAutoBulkFrom || !state.hdAutoBulkTo){
    const defaultHdDates = tradingDaysBack(260);
    state.hdAutoBulkFrom = defaultHdDates[0];
    state.hdAutoBulkTo = todayLocalISO();
  }
  const liveLoading = state.stockbitBulkLoading;
  const hdLoading = state.stockbitHistoricalBulkLoading;
  const tiLoading = state.tiBulkLoading;
  const busy = liveLoading || hdLoading || tiLoading;
  const from = state.hdAutoBulkFrom || "";
  const to = state.hdAutoBulkTo || "";
  let statusLine = "";
  if(liveLoading) statusLine = `🔴 Menarik Live: ${state.stockbitBulkProgress?.done||0}/${state.stockbitBulkProgress?.total||0}...`;
  else if(hdLoading) statusLine = `📅 Menarik Historical: ${state.stockbitHistoricalBulkProgress?.done||0}/${state.stockbitHistoricalBulkProgress?.total||0}...`;
  else if(tiLoading) statusLine = `📊 Menghitung Teknikal: ${state.tiBulkProgress?.done||0}/${state.tiBulkProgress?.total||0}...`;
  return `
    <div class="panel" style="margin-bottom:16px;display:flex;flex-wrap:wrap;align-items:center;gap:10px;">
      <div style="font-size:12px;color:var(--muted);white-space:nowrap;">⬇️ Tarik Data Massal · <b style="color:var(--text);">${tickers.length}</b> saham di ${escapeHtml(contextLabel)}</div>
      <button type="button" class="btn btn-outline" id="${namespace}LiveBulkBtn" ${busy?"disabled":""}
        style="color:#f87171;border-color:rgba(239,68,68,0.4);white-space:nowrap;"
        title="Tarik harga/orderbook live dari Stockbit untuk semua saham di ${escapeHtml(contextLabel)} — butuh Token diisi di Pengaturan">
        🔴 Tarik Live
      </button>
      <input type="date" id="${namespace}HdFromInput" value="${from}" ${busy?"disabled":""}
        style="padding:9.5px 8px;border-radius:8px;border:1px solid var(--border);background:color-mix(in srgb, currentColor 6%, transparent);color:var(--text);font-size:12px;">
      <span style="color:var(--muted);font-size:11px;">&ndash;</span>
      <input type="date" id="${namespace}HdToInput" value="${to}" ${busy?"disabled":""}
        style="padding:9.5px 8px;border-radius:8px;border:1px solid var(--border);background:color-mix(in srgb, currentColor 6%, transparent);color:var(--text);font-size:12px;">
      <button type="button" class="btn btn-outline" id="${namespace}HdTiBulkBtn" ${busy?"disabled":""}
        style="color:#22d3ee;border-color:rgba(34,211,238,0.4);white-space:nowrap;"
        title="Tarik Historical Data (Daily) untuk rentang tanggal di samping, LALU otomatis hitung ulang & simpan indikator teknikal (RSI/MACD/MA/dst) — ini yang mengisi kolom teknikal yang masih kosong di tabel/ekspor">
        📅📊 Tarik Historical &amp; Update Teknikal
      </button>
      ${statusLine ? `<span style="font-size:11px;color:var(--gold);white-space:nowrap;">${statusLine}</span>` : ""}
      ${!state.stockbitToken ? `<span style="font-size:11px;color:var(--down);white-space:nowrap;">⚠️ Token Stockbit belum diisi di Pengaturan</span>` : ""}
    </div>`;
}

// Handler bersama tombol "📅📊 Tarik Historical & Update Teknikal" — dipakai
// oleh ketiga tab (Watchlist/Portofolio/Backtest) DAN bisa dipakai ulang di
// Screener kalau suatu saat mau disatukan. Dibuat terpisah dari
// fetchAndSaveHistoricalBulk supaya urutannya EKSPLISIT: historical harus
// selesai tersimpan dulu ke DB sebelum update teknikal dihitung (soalnya
// updateTechnicalIndicatorsBulk baca bar dari DB, bukan dari hasil fetch
// historical secara langsung).
async function fetchHistoricalThenUpdateTechnicalBulk(tickers, rangeFrom, rangeTo){
  await fetchAndSaveHistoricalBulk(tickers, rangeFrom, rangeTo);
  await updateTechnicalIndicatorsBulk(tickers);
}

// Pola balasan Stockbit yang HTTP-nya SUKSES ("message":"Successfully
// retrieved market detector data") tapi seluruh payload-nya kosong —
// data.broker_summary.symbol ikut balik string kosong, brokers_buy/sell
// keduanya array kosong, data.from/data.to kosong, dan bandar_detector
// semua 0. Ini BUKAN kasus skema JSON berubah (parseStockbitMarketDetector
// di atas justru BERHASIL mengenali bentuknya — brokers_buy/sell memang
// array, cuma isinya kosong) — ini tanda kuat parameter request (ticker
// dan/atau tanggal, atau parameter lain yang endpoint versi ini butuhkan)
// TIDAK sampai/tidak ke-apply di sisi Stockbit, sehingga mereka balas
// struktur default kosong alih-alih data beneran. Dipisah dari pesan
// "Skema respons tidak dikenali" supaya user tidak salah arah diagnosis
// (cari field baru) padahal masalahnya di parameter/template endpoint.
function diagnoseEmptyStockbitBrokerResponse(raw){
  const data = raw && typeof raw === "object" ? (raw.data || raw) : null;
  if(!data || typeof data !== "object") return null;
  const bs = data.broker_summary;
  if(!bs || typeof bs !== "object") return null;
  const symbolEmpty = !bs.symbol || bs.symbol === "";
  const buyEmpty = Array.isArray(bs.brokers_buy) && !bs.brokers_buy.length;
  const sellEmpty = Array.isArray(bs.brokers_sell) && !bs.brokers_sell.length;
  const fromToEmpty = (data.from === "" || data.from == null) && (data.to === "" || data.to == null);
  if(!(symbolEmpty && buyEmpty && sellEmpty && fromToEmpty)) return null;
  return "Stockbit balas SUKSES (200) tapi symbol/from/to ikut balik KOSONG dan brokers_buy/sell dua-duanya array kosong — parser di atas sebenarnya SUDAH mengenali bentuk JSON-nya, cuma isinya memang kosong dari sisi Stockbit. Ini biasanya berarti parameter ticker/tanggal (atau parameter lain yang endpoint versi sekarang butuhkan, mis. board/investor_type) TIDAK ke-apply di request — cek lagi template \"Endpoint Broker Summary\" di ⚙️ Pengaturan dibanding URL asli yang kepakai di tab Broker Summary manual (yang datanya tampil normal), bukan cari nama field baru.";
}

// CATATAN MIGRASI: fungsi ini dulu menulis ke tabel `broker_summary` (top-5
// broker beli/jual per saham/hari, dari endpoint Stockbit /marketdetectors).
// Sekarang ditulis ke `broker_activity` supaya menyatu dengan data yang
// ditarik lewat Broker Stalker > Lacak Broker (dipakai Broker Nyangkut,
// Target Bandar, Entry Price Scanner, Top 5 Broker/Proxy CR3, dst) --
// endpoint & parsing Stockbit-nya TIDAK berubah, cuma tabel tujuan & bentuk
// baris yang disimpan (broker_activity tidak punya kolom `rank`/`avg_price`,
// jadi kedua kolom itu tidak lagi disertakan saat insert; unik per
// broker_code+trade_date+stock_code+side, bukan lagi stock_code+trade_date+side+rank).
async function fetchAndSaveBrokerSummaryBulk(tickers, rangeFrom, rangeTo, opts = {}){
  // opts.retryOnly = true → dipakai tombol "🔁 Tarik Ulang yang Gagal": HANYA
  // menembak ulang `tickers` yang dioper (biasanya daftar hasil ❌ dari run
  // sebelumnya), dan hasil ✅ lama untuk ticker LAIN (yang tidak sedang
  // diulang) tetap dipertahankan di state.stockbitBrokerBulkResults alih-alih
  // ditimpa kosong seperti run biasa. CATATAN PENTING: kalau kegagalannya
  // sistemik (mis. "symbol/from/to ikut balik KOSONG" karena template
  // endpoint salah — lihat diagnoseEmptyStockbitBrokerResponse), mengulang
  // dengan parameter YANG SAMA akan menghasilkan galat YANG SAMA lagi —
  // tombol ini paling berguna untuk kegagalan yang sifatnya sementara
  // (rate limit, koneksi putus, dsb.), bukan pengganti perbaikan template.
  const retryOnly = !!opts.retryOnly;

  if(state.stockbitBrokerBulkLoading) return;
  if(!tickers || !tickers.length){
    if(!retryOnly){
      state.stockbitBrokerBulkResults = [{ ticker:"-", date:"-", ok:false, msg:"Centang minimal 1 saham di tab Screener dulu." }];
      render();
    }
    return;
  }
  if(!state.stockbitToken){ openSettings(); return; }
  if(!state.stockbitBrokerEndpoint){
    state.stockbitBrokerBulkResults = [{ ticker:"-", date:"-", ok:false, msg:'Isi dulu "Endpoint Broker Summary" di ⚙️ Pengaturan.' }];
    render(); return;
  }
  if(!SUPABASE_URL || !SUPABASE_KEY){ openSettings(); return; }

  const tradingDates = tradingDaysInRange(rangeFrom, rangeTo); // urut lama -> baru
  if(!tradingDates.length){
    state.stockbitBrokerBulkResults = [{ ticker:"-", date:"-", ok:false, msg:'Periode tanggal tidak valid atau tidak ada hari bursa di rentang itu — cek lagi tanggal "Dari" dan "Sampai".' }];
    render(); return;
  }
  const fromDate = tradingDates[0];
  const toDate = tradingDates[tradingDates.length - 1];
  const latestDate = toDate; // hari bursa paling baru dalam periode ini — SELALU ditarik ulang, lihat catatan di bawah

  state.stockbitBrokerBulkLoading = true;
  state.stockbitBrokerBulkProgress = { done: 0, total: tickers.length }; // progress tetap dihitung per SAHAM (tiap saham di dalamnya bisa beberapa request kecil)
  if(retryOnly){
    // Buang hasil LAMA untuk ticker yang sedang diulang (supaya tidak dobel
    // dengan hasil BARU yang segera ditambahkan lewat .push() di loop bawah),
    // tapi PERTAHANKAN hasil ticker lain yang tidak ikut diulang (dipakai lagi
    // kalau nanti "Tarik Ulang yang Gagal" dipencet lagi dan butuh hitung
    // ulang failCount total). state.stockbitBrokerBulkRetryTickers dipakai
    // di render() untuk MENYARING tampilan supaya cuma ticker yang sedang
    // diulang ini yang muncul, ticker lain yang tidak diulang tetap
    // disembunyikan dari daftar meski datanya masih ada di array.
    const retrySet = new Set(tickers);
    state.stockbitBrokerBulkResults = (state.stockbitBrokerBulkResults || []).filter(r => !retrySet.has(r.ticker));
    state.stockbitBrokerBulkRetryTickers = retrySet;
  } else {
    state.stockbitBrokerBulkResults = [];
    state.stockbitBrokerBulkRetryTickers = null;
  }
  render();

  for(const ticker of tickers){
    // Skip hari yang datanya SUDAH ada di database (broker summary hari yang
    // sudah lewat itu final, tidak berubah lagi) — kecuali hari bursa paling
    // baru dalam periode ini, yang tetap ditarik ulang tiap kali karena
    // kemungkinan datanya masih berjalan/belum final saat sesi bursa berlangsung.
    const existingDates = await fetchExistingBrokerDates(ticker, tradingDates);
    const datesToFetch = tradingDates.filter(d => !existingDates.has(d) || d === latestDate);
    const skippedCount = tradingDates.length - datesToFetch.length;

    if(!datesToFetch.length){
      state.stockbitBrokerBulkResults.push({ ticker, date: `${fromDate}..${toDate}`, ok:true, msg: `Semua ${tradingDates.length} hari sudah ada di database, dilewati (tidak ada request ke Stockbit).` });
      state.stockbitBrokerBulkProgress.done++;
      render();
      continue; // tidak perlu jeda 350ms karena tidak ada request Stockbit sama sekali
    }

    // Ambil tiap potongan tanggal (yang belum ada) secara berurutan lalu
    // gabungkan byDate-nya, supaya satu request yang gagal/kepotong tidak
    // menghilangkan potongan lain.
    const dateChunks = chunkArray(datesToFetch, STOCKBIT_BROKER_CHUNK_DAYS); // pecah jadi beberapa request kecil, lihat catatan di atas
    let byDate = {};
    let lastError = null;
    let anyOk = false;
    for(const chunk of dateChunks){
      const chunkFrom = chunk[0], chunkTo = chunk[chunk.length - 1];
      const res = await stockbitFetchMarketDetector(ticker, chunkFrom, chunkTo, chunk.length);
      if(res.error){
        lastError = res.error;
      } else {
        const parsed = parseStockbitMarketDetector(res.raw, chunkFrom);
        if(parsed && Object.keys(parsed).length){
          Object.assign(byDate, parsed);
          anyOk = true;
        } else {
          // Endpoint menjawab 200 tetapi bentuk JSON berubah/tidak sesuai
          // parser. Simpan preview raw supaya diagnosis bisa dilakukan tanpa
          // menebak-nebak nama field dan jangan tampilkan pesan generik saja.
          const emptyHint = diagnoseEmptyStockbitBrokerResponse(res.raw);
          try{
            const rawPreview = JSON.stringify(res.raw).slice(0, 1600);
            lastError = emptyHint
              ? `${emptyHint} Raw JSON: ${rawPreview}`
              : `Skema respons tidak dikenali. Raw JSON: ${rawPreview}`;
          }catch(e){ lastError = emptyHint || "Skema respons tidak dikenali / raw JSON tidak bisa dibaca."; }
        }
      }
      if(dateChunks.length > 1) await new Promise(r => setTimeout(r, 300)); // jeda antar-potongan tanggal, jaga rate limit
    }

    if(!anyOk){
      state.stockbitBrokerBulkResults.push({ ticker, date: `${fromDate}..${toDate}`, ok:false, msg: lastError || "Skema respons tidak dikenali / tidak ada data (cek raw JSON manual dulu)." });
    } else {
        const rows = [];
        datesToFetch.forEach(d => {
          const dd = byDate[d];
          if(!dd) return;
          // broker_activity tidak punya kolom rank/avg_price (beda dengan
          // broker_summary lama) -- rank dari market detector (posisi top-5)
          // tetap dipakai untuk urutan pemrosesan tapi tidak disimpan ke DB.
          dd.buy.forEach(r => rows.push({ stock_code:ticker, trade_date:d, side:"buy", broker_code:r.broker_code, lot:r.lot, value_idr:r.value_idr, investor_type:r.investor_type ?? null }));
          dd.sell.forEach(r => rows.push({ stock_code:ticker, trade_date:d, side:"sell", broker_code:r.broker_code, lot:r.lot, value_idr:r.value_idr, investor_type:r.investor_type ?? null }));
        });
        // "Hilang" di sini = hari yang sebelumnya belum ada di DB DAN gagal ditarik sekarang —
        // hari yang sudah ada di DB (di-skip) tidak dianggap hilang.
        const missingDates = datesToFetch.filter(d => !byDate[d]);
        if(!rows.length){
          state.stockbitBrokerBulkResults.push({ ticker, date: `${fromDate}..${toDate}`, ok:false, msg: "Tidak ada baris broker valid di respons ini." });
        } else {
          try{
            await supaFetch(`${SUPABASE_URL}/broker_activity?on_conflict=broker_code,trade_date,stock_code,side`, {
              method: "POST",
              headers: { ...getSupaHeaders(), "Prefer": "resolution=merge-duplicates,return=minimal" },
              body: JSON.stringify(rows)
            });
            let msg = `Tersimpan ${rows.length} baris ke broker_activity untuk ${Object.keys(byDate).length}/${datesToFetch.length} hari yang ditarik.`;
            if(skippedCount) msg += ` (${skippedCount} hari lain dilewati, sudah ada di database.)`;
            // Sekarang tiap request cuma mencakup STOCKBIT_BROKER_CHUNK_DAYS hari
            // (lihat catatan di atas fetchAndSaveBrokerSummaryBulk), jadi kalau
            // masih ada hari kosong itu BUKAN lagi soal "limit" di URL — lebih
            // mungkin memang hari libur bursa, atau salah satu request chunk gagal.
            if(missingDates.length) msg += ` ⚠️ ${missingDates.length} hari tidak ada data: ${missingDates.join(", ")} (cek dulu apakah tanggal itu ada di BURSA_HOLIDAYS di app.js — kalau BUKAN hari libur bursa dan STOCKBIT_BROKER_CHUNK_DAYS sudah 1, kemungkinan besar Stockbit memang tidak punya data broker net untuk saham ini di hari itu, mis. saham tidak likuid / tidak ada transaksi signifikan)`;
            state.stockbitBrokerBulkResults.push({ ticker, date: `${fromDate}..${toDate}`, ok:true, msg });
          }catch(e){
            state.stockbitBrokerBulkResults.push({ ticker, date: `${fromDate}..${toDate}`, ok:false, msg: "Gagal simpan ke DB: " + e.message });
          }
        }
      }
    state.stockbitBrokerBulkProgress.done++;
    render();
    await new Promise(r => setTimeout(r, 350)); // tetap jaga jeda antar-SAHAM (bukan antar-hari lagi)
  }

  state.stockbitBrokerBulkLoading = false;
  render();
  if(state.bsStockCode && state.bsDate) loadBrokerSummary();
}

// Daftar ticker unik yang ❌ gagal di run "Tarik Otomatis Broker Summary"
// TERAKHIR (state.stockbitBrokerBulkResults) — dipakai tombol "🔁 Tarik Ulang
// yang Gagal". Ticker placeholder "-" (mis. pesan "Isi dulu Endpoint..." saat
// belum ada saham dicentang sama sekali) sengaja dibuang karena itu bukan
// ticker beneran yang bisa ditarik ulang satu-satu.
function getFailedBrokerSummaryTickers(){
  if(!state.stockbitBrokerBulkResults) return [];
  return [...new Set(
    state.stockbitBrokerBulkResults
      .filter(r => r.ok === false && r.ticker && r.ticker !== "-")
      .map(r => r.ticker)
  )];
}

// Tarik ulang HANYA ticker yang gagal di run terakhir, pakai rentang tanggal
// "Dari–Sampai" yang sama seperti terakhir kali dipakai (state.bsAutoBulkFrom/
// bsAutoBulkTo — sama input yang dipakai tombol "📊 Broker Summary" / "Tarik
// Otomatis" di kedua tab). Kalau semua kegagalannya sistemik (bukan sekadar
// rate limit/koneksi), hasilnya kemungkinan besar ❌ lagi dengan pesan yang
// SAMA PERSIS — itu sinyal untuk cek template "Endpoint Broker Summary" di
// ⚙️ Pengaturan, BUKAN diulang terus-menerus.
async function retryFailedBrokerSummaryBulk(){
  if(state.stockbitBrokerBulkLoading) return;
  const failedTickers = getFailedBrokerSummaryTickers();
  if(!failedTickers.length) return;
  await fetchAndSaveBrokerSummaryBulk(failedTickers, state.bsAutoBulkFrom, state.bsAutoBulkTo, { retryOnly: true });
}

// Pencarian field case/underscore-insensitive, MENELUSURI SELURUH kedalaman
// objek respons (maks 5 level) — bukan cuma level teratas seperti versi lama.
// Ini penting karena field ini sekarang juga dipakai untuk endpoint yang
// TIDAK terjamin bentuknya rata (mis. kalau user mengarahkan "Endpoint
// Quote/Orderbook" ke URL orderbook yang sama dengan kartu Orderbook Depth —
// keduanya endpoint sah, tapi belum tentu sama-sama membawa field harga
// Open/High/Low di lokasi yang sama).
function deepPickQuoteField(node, keys, depth = 0, seen = new Set()){
  if(node == null || depth > 5 || typeof node !== "object") return null;
  if(seen.has(node)) return null;
  seen.add(node);
  if(!Array.isArray(node)){
    for(const rk of Object.keys(node)){
      const norm = rk.toLowerCase().replace(/_/g,"");
      if(keys.includes(norm) && node[rk] != null && node[rk] !== "" && typeof node[rk] !== "object") return node[rk];
    }
  }
  const children = Array.isArray(node) ? node.slice(0,10) : Object.values(node);
  for(const child of children){
    const found = deepPickQuoteField(child, keys, depth+1, seen);
    if(found != null) return found;
  }
  return null;
}

function mapStockbitQuote(raw){
  if(!raw || typeof raw !== "object") return null;
  const pick = (...keys) => deepPickQuoteField(raw, keys);
  return {
    last: pick("last","close","price","c","lasttradeprice","lastprice"),
    open: pick("open","openprice","previousopen","o"),
    high: pick("high","highprice","h"),
    low: pick("low","lowprice","l"),
    prevClose: pick("previous","prevclose","previousclose","yesterdayprice"),
    change: pick("change","chg"),
    changePct: pick("changepercent","percentagechange","pct"),
    bid: pick("bid","bestbid","bidprice"),
    offer: pick("offer","ask","bestoffer","offerprice","askprice"),
    volume: pick("volume","vol"),
    frequency: pick("frequency","freq"),
    time: pick("timestamp","time","updatedat","lastupdate"),
  };
}
// ==========================================================
// AUTO-SYNC TOKEN dari tabel `stockbit_session` (diisi oleh extension
// Chrome stockbit-token-extension via sql/05_stockbit_token_sync.sql).
// Kalau tabelnya belum dibuat (migration SQL belum dijalankan), fetch ini
// gagal diam-diam — fitur live Stockbit tetap jalan dengan token manual.
// ==========================================================
// Throttle + util usia token untuk auto-resync (lihat syncStockbitTokenFromSupabase).
let lastStockbitAutoResyncAt = 0;
function tokenSyncedAtMs(){
  const v = state.stockbitTokenSyncedAt;
  if(v == null) return 0;
  if(typeof v === "number") return v;
  const parsed = Date.parse(v);
  return isNaN(parsed) ? 0 : parsed;
}
// Dipanggil otomatis saat request Stockbit kena 401 (token ditolak) —
// di-throttle 10 detik supaya bulk fetch yang gagal ratusan kali tidak
// membanjiri Supabase dengan request sync.
function maybeResyncStockbitTokenFromSupabase(){
  const now = Date.now();
  if(now - lastStockbitAutoResyncAt < 10000) return;
  lastStockbitAutoResyncAt = now;
  syncStockbitTokenFromSupabase();
}

// Kebalikan dari syncStockbitTokenFromSupabase(): menulis token yang diisi
// MANUAL di modal Pengaturan ke tabel stockbit_session, supaya browser/device
// lain ikut dapat token yang sama. Sebelumnya jalur tulis ini TIDAK ADA —
// token manual cuma mendarat di localStorage, jadi begitu dibuka di browser
// lain, kolom token kosong lagi dan semua fitur live Stockbit mati.
//
// Dua pengaman penting:
// 1. Token kosong TIDAK PERNAH ditulis — kalau tidak, membuka Pengaturan lalu
//    klik Simpan (tanpa mengisi apa-apa) akan menghapus token yang sudah
//    ditangkap extension untuk SEMUA device.
// 2. Token yang sama persis dengan yang sudah ada di server juga dilewati,
//    supaya updated_at tidak ikut berubah tanpa alasan dan tidak memicu
//    syncStockbitTokenFromSupabase() di device lain secara sia-sia.
async function saveStockbitTokenToSupabase(token){
  if(!SUPABASE_URL || !SUPABASE_KEY) return;
  const clean = sanitizeStockbitToken(token);
  if(!clean) return; // pengaman 1
  try{
    const res = await fetch(`${SUPABASE_URL}/stockbit_session?id=eq.1&select=token`, { headers: getSupaHeaders(), cache: "no-store" });
    if(res.ok){
      const rows = await res.json();
      const existing = Array.isArray(rows) ? rows[0] : null;
      if(existing && sanitizeStockbitToken(existing.token) === clean) return; // pengaman 2
    }
    // Upsert (bukan PATCH): kalau baris id=1 belum pernah dibuat — mis. di
    // project Supabase baru yang belum pernah dipakai extension — PATCH akan
    // sukses tanpa menulis apa pun, dan tokennya hilang diam-diam.
    await supaFetch(`${SUPABASE_URL}/stockbit_session`, {
      method: "POST",
      headers: { ...getSupaHeaders(), "Prefer": "resolution=merge-duplicates,return=minimal" },
      body: JSON.stringify({ id: 1, token: clean, updated_at: new Date().toISOString() })
    });
  }catch(e){
    showError("Token Stockbit tersimpan di browser ini, tapi GAGAL disimpan ke Supabase: " + e.message + " — jalankan sql/07_stockbit_session.sql supaya token ikut terbawa ke browser/device lain.");
  }
}

async function syncStockbitTokenFromSupabase(){
  if(!SUPABASE_URL || !SUPABASE_KEY) return false;
  try{
    const res = await fetch(`${SUPABASE_URL}/stockbit_session?id=eq.1&select=token,expires_at,updated_at`, { headers: getSupaHeaders(), cache: "no-store" });
    if(!res.ok) return false;
    const rows = await res.json();
    const row = Array.isArray(rows) ? rows[0] : null;
    if(row && row.token){
      const newTok = sanitizeStockbitToken(row.token);
      if(!newTok) return false;
      // Token yang baru ditulis extension ke Supabase harus menjadi sumber
      // kebenaran, termasuk ketika token lokal sebelumnya bertanda extension.
      // Jangan memakai freshness gate berbasis waktu lokal: timestamp browser
      // dan timestamp server bisa berbeda beberapa detik.
      if(newTok === state.stockbitToken) return false;
      state.stockbitToken = newTok;
      state.stockbitTokenExpiresAt = row.expires_at || null;
      state.stockbitTokenSyncedAt = row.updated_at || Date.now();
      state.stockbitTokenSource = "auto";
      try{
        localStorage.setItem(LS_STOCKBIT_TOKEN, newTok);
        localStorage.setItem(LS_STOCKBIT_TOKEN_SOURCE, "auto");
      }catch(e){}
      updateStockbitTokenStatusUI();
      return true;
    }
  }catch(e){ /* tabel belum ada / offline — biarkan token manual yang dipakai */ }
  return false;
}

// ==========================================================
// AUTO-PICKUP TOKEN dari extension Chrome "WS Interceptor"
// (background.js + content_screener.js) — jalur INI TERPISAH TOTAL dari
// syncStockbitTokenFromSupabase() di atas. Extension itu menangkap header
// Authorization langsung dari request stockbit.com lalu menulisnya ke
// localStorage['ihsg_stockbit_token'] di tab aplikasi ini (lewat
// chrome.storage.local -> content_screener.js) — TIDAK PERNAH menyentuh
// tabel Supabase `stockbit_session`. Jadi badge "Auto-sync dari extension"
// yang sebelumnya cuma bersumber dari Supabase itu SAMA SEKALI TIDAK
// MEREFLEKSIKAN token yang ditulis extension ini.
//
// KENAPA HARUS DI-POLL (bukan cukup addEventListener('storage', ...)):
// event `storage` browser HANYA terpicu di tab/dokumen LAIN yang beda dari
// yang melakukan penulisan — dan content_screener.js menulis ke
// localStorage di DALAM tab aplikasi ini sendiri (document yang sama,
// cuma beda isolated world JS). Jadi event storage TIDAK PERNAH nyala di
// sini walau extension berhasil menulis token baru. Satu-satunya cara
// yang reliable untuk pick up perubahan itu tanpa reload manual adalah
// baca ulang localStorage secara berkala dan bandingkan.
//
// Kalau token yang ditemukan beda dari yang sedang dipakai, expires_at
// lama (kalau ada, dari sync Supabase sebelumnya) DIBUANG — itu milik
// token yang BEDA, jadi countdown lama yang ditampilkan ke user tidak lagi
// relevan/menyesatkan untuk token baru ini.
// ==========================================================
function pollExtensionStockbitToken(){
  let raw;
  try{ raw = localStorage.getItem(LS_STOCKBIT_TOKEN); }catch(e){ return; }
  const clean = sanitizeStockbitToken(raw);
  if(!clean || clean === state.stockbitToken) return;
  applyExtensionStockbitToken(clean, null);
}

function applyExtensionStockbitToken(token, expiresAt){
  const clean = sanitizeStockbitToken(token);
  if(!clean) return;
  state.stockbitToken = clean;
  state.stockbitTokenSource = "extension";
  state.stockbitTokenSyncedAt = Date.now();
  state.stockbitTokenExpiresAt = expiresAt || null;
  try{
    localStorage.setItem(LS_STOCKBIT_TOKEN, clean);
    localStorage.setItem(LS_STOCKBIT_TOKEN_SOURCE, "extension");
    localStorage.setItem(LS_STOCKBIT_TOKEN_SYNCED_AT, String(state.stockbitTokenSyncedAt));
  }catch(e){}
  const stbTokenEl = document.getElementById("setStockbitToken");
  if(stbTokenEl && document.activeElement !== stbTokenEl) stbTokenEl.value = clean;
  updateStockbitTokenStatusUI();
}

window.addEventListener("message", (event) => {
  if(event.source !== window || event.data?.type !== "STOCKBIT_TOKEN_UPDATED") return;
  applyExtensionStockbitToken(event.data.token, event.data.expiresAt);
});

// ==========================================================
// 🧪 WS DEBUG — terima traffic WebSocket Stockbit yang diteruskan ekstensi
// lewat window.postMessage (lihat content_screener.js: window.postMessage
// ({type:'FROM_EXTENSION_WS_TRAFFIC', payload:{type,direction,url,data,ts}})).
// HANYA disimpan ke buffer kalau user sedang aktif menekan "Mulai Rekam"
// (state.wsDebugRecording) -- traffic WS bisa puluhan pesan/detik saat tab
// Stockbit user terbuka, jadi kalau fitur ini tidak sedang dipakai, frame
// yang lewat dibuang begitu saja (tidak numpuk di memori percuma).
//
// scheduleWsDebugRender() SENGAJA tidak langsung memanggil render() tiap
// frame masuk -- render() di app ini mengganti innerHTML SELURUH tab aktif
// (lihat function render()), dan WS bisa jauh lebih cepat dari kecepatan
// re-render DOM yang wajar. Di-throttle maksimal 1x per 200ms, dan cuma
// kalau tab #wsdebug sedang aktif (kalau user di tab lain, buffer tetap
// terisi di state, tapi DOM tidak disentuh sampai user pindah ke tab ini).
// ==========================================================
window.addEventListener("message", (event) => {
  if(event.source !== window || event.data?.type !== "FROM_EXTENSION_WS_TRAFFIC") return;
  if(!state.wsDebugRecording) return;
  const f = event.data.payload;
  if(!f) return;
  state.wsDebugFrames.push({ ts: f.ts || Date.now(), direction: f.direction || "?", url: f.url || "", data: f.data ?? "" });
  if(state.wsDebugFrames.length > state.wsDebugMaxFrames){
    state.wsDebugFrames.splice(0, state.wsDebugFrames.length - state.wsDebugMaxFrames);
  }
  scheduleWsDebugRender();
});

let wsDebugRenderPending = false;
function scheduleWsDebugRender(){
  if(state.tab !== "wsdebug" || wsDebugRenderPending) return;
  wsDebugRenderPending = true;
  setTimeout(() => { wsDebugRenderPending = false; if(state.tab === "wsdebug") render(); }, 200);
}

// Format selisih waktu jadi teks singkat berbahasa Indonesia, dipakai untuk
// banner "terakhir berhasil ditarik" di bawah ini (dan bisa dipakai ulang di
// tempat lain kalau perlu format relatif serupa).
function fmtRelativeTimeID(ts){
  if(!ts) return null;
  const sec = Math.max(0, Math.round((Date.now() - ts) / 1000));
  if(sec < 5) return "baru saja";
  if(sec < 60) return `${sec} detik lalu`;
  const min = Math.round(sec / 60);
  if(min < 60) return `${min} menit lalu`;
  const hr = Math.round(min / 60);
  if(hr < 24) return `${hr} jam lalu`;
  return new Date(ts).toLocaleString("id-ID");
}

// ==========================================
// stockbitLiveDataStatus — status ringkas dipakai untuk banner "terakhir
// berhasil ditarik: [waktu]" (lihat catatan performa & keandalan data:
// endpoint Stockbit tidak resmi & rawan berhenti berfungsi tanpa
// pemberitahuan, jadi user perlu tahu dari UI kalau data live sedang basi
// tanpa perlu buka console). Dianggap "basi" (stale, warna kuning) kalau
// sudah lebih dari 5 menit sejak sukses terakhir — angka ini sengaja longgar
// karena live data di sini memang ditarik manual per klik, bukan auto-poll
// tiap detik.
// ==========================================
const STOCKBIT_STALE_AFTER_MS = 5 * 60 * 1000;
function stockbitLiveDataStatus(){
  if(!state.stockbitLastSuccessAt){
    return { text: "Belum pernah berhasil menarik data live dari Stockbit.", color: "var(--muted)" };
  }
  const rel = fmtRelativeTimeID(state.stockbitLastSuccessAt);
  const isStale = (Date.now() - state.stockbitLastSuccessAt) > STOCKBIT_STALE_AFTER_MS;
  return {
    text: `${isStale ? "⚠️ " : "✅ "}Terakhir berhasil ditarik: ${rel}${isStale ? " — mungkin sudah basi, coba tarik ulang" : ""}`,
    color: isStale ? "var(--gold)" : "var(--up)"
  };
}
function updateStockbitLastSuccessStatusUI(){
  const el = document.getElementById("stockbitLastSuccessStatus");
  if(!el) return;
  const st = stockbitLiveDataStatus();
  el.textContent = st.text;
  el.style.color = st.color;
}

function stockbitTokenStatus(){
  if(!state.stockbitToken) return { text: "Belum ada token.", color: "var(--muted)" };
  const nowSec = Date.now()/1000;
  // Sumber "extension" TIDAK punya info expires_at yang valid (extension WS
  // Interceptor cuma menangkap nilai token mentah, tidak tahu klaim `exp`
  // JWT-nya) — jadi jangan pernah tampilkan countdown untuk sumber ini,
  // supaya tidak menyesatkan seperti badge lama yang basi.
  if(state.stockbitTokenSource === "extension"){
    const rel = state.stockbitTokenSyncedAt ? fmtRelativeTimeID(state.stockbitTokenSyncedAt) : null;
    return { text: `🧩 Auto dari extension (WS Interceptor)${rel ? " · ditangkap " + rel : ""} — belum tentu masih valid di sisi server Stockbit, cek dari hasil tarik data.`, color: "var(--up)" };
  }
  let expiryTxt = "";
  if(state.stockbitTokenExpiresAt){
    if(state.stockbitTokenExpiresAt < nowSec){
      return { text: "⚠️ Token kadaluarsa — buka stockbit.com & login ulang supaya extension menyinkron token baru.", color: "var(--down)" };
    }
    const minsLeft = Math.round((state.stockbitTokenExpiresAt - nowSec)/60);
    expiryTxt = ` · berlaku ~${minsLeft} menit lagi`;
  }
  const src = state.stockbitTokenSource === "auto" ? "🔄 Auto-sync dari Supabase" : "✍️ Diisi manual";
  return { text: `${src}${expiryTxt}`, color: "var(--up)" };
}

async function fetchStockbitLive(ticker){
  state.stockbitLive[ticker] = { ...(state.stockbitLive[ticker]||{}), loading: true, error: null };
  render();
  const res = await stockbitFetch(state.stockbitQuoteEndpoint, ticker);
  const mapped = res.raw ? mapStockbitQuote(res.raw) : null;
  state.stockbitLive[ticker] = { loading: false, error: res.error || null, raw: res.raw ?? null, mapped, fetchedAt: Date.now() };
  render();
}
// Tarik live data berurutan (bukan paralel) dengan jeda antar-request,
// KHUSUS untuk ticker yang lolos filter Screener saat ini — supaya tidak
// membombardir Stockbit dengan puluhan request sekaligus pakai 1 token
// akun pribadi (rawan rate-limit/flag oleh sistem mereka).
async function fetchStockbitLiveBulk(tickers){
  if(state.stockbitBulkLoading) return;
  state.stockbitBulkLoading = true;
  state.stockbitBulkProgress = { done: 0, total: tickers.length };
  render();
  for(const t of tickers){
    await fetchStockbitLive(t);
    state.stockbitBulkProgress = { done: state.stockbitBulkProgress.done + 1, total: tickers.length };
    render();
    await new Promise(r => setTimeout(r, 350)); // jeda 350ms antar-request
  }
  state.stockbitBulkLoading = false;
  state.stockbitBulkProgress = null;
  render();
}

// ==========================================================
// ORDERBOOK DEPTH 10-LEVEL — endpoint terverifikasi dari katalog API
// komunitas (lihat catatan di STOCKBIT_DEFAULT_ORDERBOOK_EP), TAPI skema
// field respons JSON-nya BELUM diverifikasi langsung dari akun kita
// (dokumentasi komunitas tidak menyertakan contoh body). Parser di bawah
// karena itu mencoba BANYAK kemungkinan nama field sekaligus (pola sama
// seperti mapStockbitBrokerSummary()), dan SELALU menyimpan raw JSON di
// state supaya kalau semua percobaan gagal, kita masih bisa lihat bentuk
// asli responsnya lewat tombol "Lihat JSON Mentah" di kartu — daripada
// gagal diam-diam seperti yang sempat terjadi di endpoint Quote lama.
// ==========================================================

// Satu level di dalam array belum pasti nama field harga/lot-nya
// (mis. "price" vs "px", "volume" vs "lot" vs "qty") — coba beberapa.
function pickDepthLevel(row){
  if(!row || typeof row !== "object") return null;
  const pick = (...keys) => {
    for(const k of keys){
      // cocokkan case-insensitive + abaikan underscore, supaya "bidPrice",
      // "BID_PRICE", dan "bid_price" sama-sama kena.
      const hit = Object.keys(row).find(rk => rk.toLowerCase().replace(/_/g,"") === k);
      if(hit && row[hit]!=null && row[hit]!=="") return row[hit];
    }
    return null;
  };
  const price  = Number(pick("price","px","bidprice","offerprice","askprice","p"));
  const rawVol = Number(pick("volume","vol","lot","lots","qty","quantity","totalvolume","queuevolume","bidvolume","offervolume","askvolume","size","v"));
  if(!price || isNaN(price)) return null;
  // Beberapa API bursa mengirim volume dalam LEMBAR (butuh /100 jadi lot),
  // sebagian sudah dalam LOT. Tidak ada cara pasti membedakan dari satu
  // angka saja — disimpan APA ADANYA (rawVol), label unit sengaja netral.
  return {
    price,
    rawVol: isNaN(rawVol) ? 0 : rawVol,
    order: Number(pick("order","orders","numorder","totalorder","queue","freq")) || null
  };
}

// Sebuah array dianggap "kandidat ladder" kalau isinya objek-objek yang
// punya field harga yang bisa diparse. Ini yang bikin parser tahan banting:
// kita tidak lagi menebak nama BUNGKUSnya, cuma mengenali BENTUK isinya.
function looksLikeLadder(arr){
  if(!Array.isArray(arr) || !arr.length) return false;
  const ok = arr.filter(r => pickDepthLevel(r)).length;
  return ok >= Math.max(1, Math.floor(arr.length * 0.5));
}

// Telusuri SELURUH objek respons (rekursif, maks kedalaman 6) dan kumpulkan
// setiap array yang bentuknya seperti ladder, lengkap dengan jalur kuncinya
// ("data.orderbook.bid"). Jalur inilah yang dipakai menebak sisi bid/offer.
function collectDepthCandidates(node, path, out, depth){
  if(depth > 6 || node == null) return out;
  if(Array.isArray(node)){
    if(looksLikeLadder(node)) out.push({ path, arr: node });
    else node.slice(0,5).forEach((v,i)=> collectDepthCandidates(v, `${path}[${i}]`, out, depth+1));
    return out;
  }
  if(typeof node === "object"){
    for(const k of Object.keys(node)) collectDepthCandidates(node[k], path ? `${path}.${k}` : k, out, depth+1);
  }
  return out;
}

const DEPTH_BID_HINTS  = ["bid","buy","beli","demand"];
const DEPTH_ASK_HINTS  = ["ask","offer","sell","jual","supply"];
function depthSideFromPath(path){
  const p = String(path).toLowerCase();
  // cek ask dulu: "ask"/"offer" lebih spesifik dan tidak bertabrakan dengan "bid"
  if(DEPTH_ASK_HINTS.some(h => p.includes(h))) return "ask";
  if(DEPTH_BID_HINTS.some(h => p.includes(h))) return "bid";
  return null;
}

function parseStockbitOrderbookDepth(raw){
  const fail = (note) => ({ bids: [], asks: [], unrecognized: true, note, candidates: [], topKeys: [], raw });
  if(raw == null) return fail("Respons kosong (tidak ada body sama sekali).");
  if(typeof raw === "string") return fail("Respons bukan JSON — server mengirim teks/HTML. Biasanya tanda endpoint salah atau token ditolak sebelum sampai API.");
  if(typeof raw !== "object") return fail("Respons bukan objek JSON.");

  const cands = collectDepthCandidates(raw, "", [], 0);
  // Daftar kunci di level atas — ditampilkan di kartu saat gagal, supaya kamu
  // bisa lihat sekilas bentuk responsnya tanpa membuka JSON mentah.
  const d = raw.data || raw.result || raw;
  const topKeys = (d && typeof d === "object" && !Array.isArray(d)) ? Object.keys(d).slice(0,25) : [];

  if(!cands.length){
    return { ...fail("Tidak ada satupun array berisi field harga di dalam respons."), topKeys };
  }

  let bidsRaw = null, asksRaw = null;
  for(const c of cands){
    const side = depthSideFromPath(c.path);
    if(side === "bid" && !bidsRaw) bidsRaw = c;
    if(side === "ask" && !asksRaw) asksRaw = c;
  }
  // Fallback: tidak ada petunjuk nama sama sekali, tapi ketemu tepat 2 array
  // ladder. Asumsi urutan konvensional bursa: yang pertama = bid.
  if(!bidsRaw && !asksRaw && cands.length === 2){ bidsRaw = cands[0]; asksRaw = cands[1]; }

  const bids = (bidsRaw?.arr || []).map(pickDepthLevel).filter(Boolean).sort((a,b)=>b.price-a.price);
  const asks = (asksRaw?.arr || []).map(pickDepthLevel).filter(Boolean).sort((a,b)=>a.price-b.price);

  const totalVol = [...bids, ...asks].reduce((a,l)=>a+l.rawVol, 0);
  return {
    bids, asks,
    bidPath: bidsRaw?.path || null,
    askPath: asksRaw?.path || null,
    // "unrecognized" = struktur tidak terbaca sama sekali.
    // "empty" = struktur TERBACA tapi antriannya nol (bursa tutup / pre-opening
    // / saham suspend). Dua hal ini dulu tercampur jadi satu tampilan kosong
    // tanpa penjelasan — itulah kenapa kelihatannya "datanya kosong".
    unrecognized: bids.length === 0 && asks.length === 0,
    empty: (bids.length || asks.length) > 0 && totalVol === 0,
    note: (bids.length === 0 && asks.length === 0)
      ? `Ketemu ${cands.length} array kandidat (${cands.map(c=>c.path||"(root)").slice(0,5).join(", ")}) tapi tidak ada yang bisa dipetakan ke sisi bid/offer.`
      : null,
    candidates: cands.map(c => ({ path: c.path || "(root)", n: c.arr.length })),
    topKeys,
    raw,
  };
}

async function fetchStockbitOrderbookDepth(ticker){
  state.stockbitOrderbook[ticker] = { ...(state.stockbitOrderbook[ticker]||{}), loading: true, error: null };
  render();
  const res = await stockbitFetch(state.stockbitOrderbookEndpoint, ticker);
  const parsed = res.raw !== undefined ? parseStockbitOrderbookDepth(res.raw) : null;
  state.stockbitOrderbook[ticker] = {
    loading: false,
    error: res.error || null,
    parsed,
    fetchedAt: Date.now(),
  };
  render();
}

async function supaFetch(url, options) {
  const res = await fetch(url, options);
  if (!res.ok) {
    let msg = `HTTP ${res.status} ${res.statusText}`;
    try {
      const body = await res.json();
      if (body && body.message) {
        msg = body.message;
        if (body.hint) msg += ` (hint: ${body.hint})`;
      }
    } catch (e) { /* body bukan JSON, pakai status text saja */ }
    // Sertakan nama tabel/endpoint di pesan error — tanpa ini, error yang
    // sama persis bisa muncul dari beberapa request berbeda (mis.
    // backtest_sessions vs backtest_items) dan tidak mungkin dibedakan
    // dari pesan Postgrest saja.
    const table = url.replace(/^.*\/rest\/v1\//, "").split("?")[0];
    throw new Error(`[${table}] ${msg}`);
  }
  return res;
}

// ==========================================
// UJI ENDPOINT STOCKBIT (dipanggil tombol "🧪 Uji" di modal Pengaturan)
//
// Sengaja baca langsung dari INPUT field (bukan state yang sudah tersimpan),
// supaya user bisa coba-coba endpoint/token baru dulu sebelum klik "Simpan
// & Reload" — tidak perlu simpan dulu baru ketahuan salah.
//
// CATATAN: fungsi ini menimpa state.stockbitToken /
// state.stockbitHistoricalEndpoint SEMENTARA selama request berlangsung,
// lalu mengembalikannya. Kalau kebetulan auto-refresh Stockbit (lihat blok
// AUTO-REFRESH LIVE STOCKBIT di bagian akhir file) jalan tepat di detik yang
// sama, ada kemungkinan kecil 1 request nyasar pakai token/endpoint uji —
// bukan masalah serius untuk skala testing manual, tapi disebutkan di sini
// supaya tidak membingungkan kalau terlihat di Network tab.
// ==========================================
async function testStockbitQuoteEndpoint(){
  const resultEl = document.getElementById("testStockbitQuoteResult");
  const tickerEl = document.getElementById("testStockbitTicker");
  const epEl = document.getElementById("setStockbitQuoteEndpoint");
  const tokenEl = document.getElementById("setStockbitToken");
  if(!resultEl || !tickerEl || !epEl) return;
  const ticker = (tickerEl.value||"").trim().toUpperCase();
  if(!ticker){ resultEl.innerHTML = `<div style="font-size:11.5px;color:var(--down);">Isi ticker uji dulu (mis. BBCA).</div>`; return; }
  const endpointTemplate = (epEl.value||"").trim() || STOCKBIT_DEFAULT_QUOTE_EP;

  const prevToken = state.stockbitToken;
  if(tokenEl && tokenEl.value.trim()) state.stockbitToken = tokenEl.value.trim();
  resultEl.innerHTML = `<div style="font-size:11.5px;color:var(--muted);">Menguji ${escapeHtml(ticker)}...</div>`;
  const res = await stockbitFetch(endpointTemplate, ticker);
  state.stockbitToken = prevToken;

  if(res.error){
    resultEl.innerHTML = `<div style="font-size:11.5px;color:var(--down);">⚠️ ${escapeHtml(res.error)}</div>`;
    return;
  }
  const mapped = mapStockbitQuote(res.raw) || {};
  const foundFields = ["open","high","low","last"].filter(k => mapped[k]!=null);
  const verdict = foundFields.length
    ? `<span style="color:var(--up);">✅ Ketemu field: ${foundFields.join(", ")} (Last=${mapped.last}, O/H/L=${mapped.open}/${mapped.high}/${mapped.low}). Kalau angkanya masuk akal, endpoint ini kemungkinan besar BENAR — klik "Simpan &amp; Reload".</span>`
    : `<span style="color:var(--down);">❌ Open/High/Low/Last tidak ketemu — kemungkinan besar ini BUKAN endpoint harga (mis. masih endpoint stream/komentar). Cek struktur JSON mentah di bawah, cari nama field harga aslinya lalu beri tahu saya supaya mapStockbitQuote() disesuaikan.</span>`;
  resultEl.innerHTML = `
    <div style="font-size:11.5px;margin-bottom:6px;">${verdict}</div>
    <details><summary style="cursor:pointer;font-size:11px;color:var(--teal);">Lihat JSON mentah</summary>
      <pre style="font-size:10.5px;background:color-mix(in srgb, currentColor 9%, transparent);padding:8px;border-radius:6px;overflow-x:auto;max-height:200px;">${escapeHtml(JSON.stringify(res.raw, null, 2))}</pre>
    </details>`;
}

async function testStockbitHistoricalEndpoint(){
  const resultEl = document.getElementById("testStockbitHistResult");
  const tickerEl = document.getElementById("testStockbitHistTicker");
  const periodEl = document.getElementById("testStockbitHistPeriod");
  const epEl = document.getElementById("setStockbitHistoricalEndpoint");
  const tokenEl = document.getElementById("setStockbitToken");
  if(!resultEl || !tickerEl || !epEl) return;
  const ticker = (tickerEl.value||"").trim().toUpperCase();
  const period = periodEl ? periodEl.value : "daily";
  if(!ticker){ resultEl.innerHTML = `<div style="font-size:11.5px;color:var(--down);">Isi ticker uji dulu.</div>`; return; }

  const prevEndpoint = state.stockbitHistoricalEndpoint;
  const prevToken = state.stockbitToken;
  state.stockbitHistoricalEndpoint = (epEl.value||"").trim() || STOCKBIT_DEFAULT_HISTORICAL_EP;
  if(tokenEl && tokenEl.value.trim()) state.stockbitToken = tokenEl.value.trim();
  resultEl.innerHTML = `<div style="font-size:11.5px;color:var(--muted);">Menguji mode ${escapeHtml(period)}...</div>`;
  const res = await stockbitFetchHistorical(ticker, period, { limit: 10 });
  state.stockbitHistoricalEndpoint = prevEndpoint;
  state.stockbitToken = prevToken;

  if(res.error){
    resultEl.innerHTML = `<div style="font-size:11.5px;color:var(--down);">⚠️ ${escapeHtml(res.error)}</div>`;
    return;
  }
  const parsed = parseStockbitHistorical(res.raw);
  const verdict = (parsed && parsed.length)
    ? `<span style="color:var(--up);">✅ Terbaca ${parsed.length} baris. Baris pertama: tanggal ${escapeHtml(parsed[0]?.date||"-")}, Close ${parsed[0]?.close ?? "-"}. Cek jarak antar tanggal di JSON mentah — untuk mode "${escapeHtml(period)}" jaraknya seharusnya mingguan/bulanan, bukan harian, kalau period-nya benar-benar berpengaruh di sisi server.</span>`
    : `<span style="color:var(--down);">❌ Formatnya tidak dikenali parseStockbitHistorical() untuk mode "${escapeHtml(period)}" — kemungkinan besar nama parameter period salah tebak. Cek JSON mentah di bawah lalu beri tahu saya strukturnya.</span>`;
  resultEl.innerHTML = `
    <div style="font-size:11.5px;margin-bottom:6px;">${verdict}</div>
    <details><summary style="cursor:pointer;font-size:11px;color:var(--teal);">Lihat JSON mentah</summary>
      <pre style="font-size:10.5px;background:color-mix(in srgb, currentColor 9%, transparent);padding:8px;border-radius:6px;overflow-x:auto;max-height:200px;">${escapeHtml(JSON.stringify(res.raw, null, 2))}</pre>
    </details>`;
}

// Uji Endpoint Broker Summary — dibuat khusus untuk mengecek pertanyaan
// "kenapa kolom Lot selalu kosong di broker_summary". Baca endpoint LANGSUNG
// dari kotak input (sama seperti dua tester di atas), supaya bisa coba-coba
// ganti data_type=..._VALUE jadi ..._VOLUME di URL tanpa perlu Simpan &
// Reload dulu. Verdict di bawah secara eksplisit mengecek ada/tidaknya nilai
// Lot pada baris yang berhasil diparse -- itu jawaban langsung ke pertanyaan
// "apakah cabang by_volume memang tidak dikirim Stockbit, atau ada tapi
// gagal dibaca parser".
async function testStockbitBrokerEndpoint(){
  const resultEl = document.getElementById("testStockbitBrokerResult");
  const tickerEl = document.getElementById("testStockbitBrokerTicker");
  const fromEl = document.getElementById("testStockbitBrokerFrom");
  const toEl = document.getElementById("testStockbitBrokerTo");
  const epEl = document.getElementById("setStockbitBrokerEndpoint");
  const tokenEl = document.getElementById("setStockbitToken");
  if(!resultEl || !tickerEl || !epEl) return;
  const ticker = (tickerEl.value||"").trim().toUpperCase();
  if(!ticker){ resultEl.innerHTML = `<div style="font-size:11.5px;color:var(--down);">Isi ticker uji dulu (mis. BBCA).</div>`; return; }
  const fromStr = (fromEl?.value||"").trim() || todayLocalISO();
  const toStr = (toEl?.value||"").trim() || fromStr;

  // Endpoint ini cuma menerima SATU tanggal per request (lihat
  // STOCKBIT_BROKER_CHUNK_DAYS=1), jadi periode "Dari–Sampai" di sini
  // ditembak sebagai beberapa request terpisah (satu per hari bursa),
  // BUKAN satu request dengan rentang beneran — sama seperti pola yang
  // dipakai fetchAndSaveBrokerSummaryBulk(), tapi tanpa simpan ke DB.
  const tradingDates = tradingDaysInRange(fromStr, toStr);
  if(!tradingDates.length){
    resultEl.innerHTML = `<div style="font-size:11.5px;color:var(--down);">Periode tanggal tidak valid atau tidak ada hari bursa di rentang itu — cek lagi "Dari" harus &le; "Sampai", dan bukan cuma Sabtu/Minggu/libur bursa.</div>`;
    return;
  }

  const prevEndpoint = state.stockbitBrokerEndpoint;
  const prevToken = state.stockbitToken;
  state.stockbitBrokerEndpoint = (epEl.value||"").trim() || STOCKBIT_DEFAULT_BROKER_EP;
  if(tokenEl && tokenEl.value.trim()) state.stockbitToken = tokenEl.value.trim();

  const perDate = []; // { date, ok, error?, raw, buy, sell, total, withLot, withType, sampleLot, sampleType }
  for(let i = 0; i < tradingDates.length; i++){
    const dateStr = tradingDates[i];
    resultEl.innerHTML = `<div style="font-size:11.5px;color:var(--muted);">Menguji ${escapeHtml(ticker)}... ${i+1}/${tradingDates.length} (${escapeHtml(dateStr)})</div>`;
    const res = await stockbitFetchMarketDetector(ticker, dateStr, dateStr, 1);
    if(res.error){
      perDate.push({ date: dateStr, ok:false, error: res.error, raw: res.raw ?? null });
    } else {
      const byDate = parseStockbitMarketDetector(res.raw, dateStr);
      const dayRows = byDate ? byDate[dateStr] : null;
      const buy = dayRows?.buy || [];
      const sell = dayRows?.sell || [];
      const allRows = [...buy, ...sell];
      const withLot = allRows.filter(r => r.lot != null && r.lot > 0);
      const withType = allRows.filter(r => r.investor_type);
      perDate.push({ date: dateStr, ok: allRows.length>0, buy: buy.length, sell: sell.length, total: allRows.length, withLot: withLot.length, withType: withType.length, sampleLot: withLot[0]||null, sampleType: withType[0]||null, raw: res.raw });
    }
    if(tradingDates.length > 1) await new Promise(r => setTimeout(r, 300)); // jaga rate limit antar-tanggal, sama seperti bulk pull
  }
  state.stockbitBrokerEndpoint = prevEndpoint;
  state.stockbitToken = prevToken;

  const periodLabel = fromStr === toStr ? escapeHtml(fromStr) : `${escapeHtml(fromStr)}..${escapeHtml(toStr)}`;
  const totalRows = perDate.reduce((s,d)=>s+(d.total||0),0);
  const totalWithLot = perDate.reduce((s,d)=>s+(d.withLot||0),0);
  const totalWithType = perDate.reduce((s,d)=>s+(d.withType||0),0);
  const daysWithData = perDate.filter(d=>d.total).length;
  const sampleLotEntry = perDate.find(d=>d.sampleLot)?.sampleLot;
  const sampleTypeEntry = perDate.find(d=>d.sampleType)?.sampleType;

  let verdict;
  if(!totalRows){
    verdict = `<span style="color:var(--down);">❌ Tidak ada baris Top Buy/Sell yang terbaca sama sekali untuk ${escapeHtml(ticker)} di ${tradingDates.length} hari bursa (${periodLabel}) — coba periode/hari bursa lain (bukan Sabtu/Minggu/libur), atau kemungkinan skema respons berubah lagi. Cek rincian &amp; JSON mentah per-tanggal di bawah.</span>`;
  } else if(totalWithLot){
    verdict = `<span style="color:var(--up);">✅ Terbaca ${totalRows} baris di ${daysWithData}/${tradingDates.length} hari — ${totalWithLot}/${totalRows} baris PUNYA Lot terisi${sampleLotEntry ? ` (contoh: ${escapeHtml(sampleLotEntry.broker_code)} = ${sampleLotEntry.lot} lot)` : ""}, dan ${totalWithType}/${totalRows} baris PUNYA Tipe Investor terisi${sampleTypeEntry ? ` (contoh: ${escapeHtml(sampleTypeEntry.broker_code)} = ${escapeHtml(sampleTypeEntry.investor_type)})` : ""}. Kalau salah satu dari dua ini masih 0, kemungkinan skema respons endpoint yang sedang dites ini memang tidak menyertakan field itu — cek JSON mentah di bawah untuk pastikan nama field aslinya.</span>`;
  } else {
    verdict = `<span style="color:var(--gold);">⚠️ Terbaca ${totalRows} baris di ${daysWithData}/${tradingDates.length} hari, TAPI semua baris Lot-nya kosong/null (cuma value_idr yang terisi, tipe investor: ${totalWithType}/${totalRows} terisi). Untuk endpoint /order-trade/broker/distribution ini biasanya berarti cabang by_volume memang tidak dikirim Stockbit untuk data_type yang sedang dites — coba timpa data_type di kotak endpoint jadi BROKER_DISTRIBUTION_DATA_TYPE_VOLUME lalu tes ulang. Untuk endpoint /marketdetectors, cek JSON mentah untuk nama field lot yang sebenarnya (mis. blot/slot).</span>`;
  }

  const perDateListHtml = perDate.map(d => {
    if(d.error) return `<div style="padding:3px 0;border-bottom:1px solid var(--border);color:var(--down);">❌ ${escapeHtml(d.date)} — ${escapeHtml(d.error)}</div>`;
    if(!d.total) return `<div style="padding:3px 0;border-bottom:1px solid var(--border);color:var(--down);">❌ ${escapeHtml(d.date)} — tidak ada baris.</div>`;
    return `<div style="padding:3px 0;border-bottom:1px solid var(--border);color:${d.withLot ? 'var(--up)' : 'var(--gold)'};">${d.withLot ? '✅' : '⚠️'} ${escapeHtml(d.date)} — ${d.buy} Buy, ${d.sell} Sell, Lot ${d.withLot}/${d.total}, Tipe ${d.withType}/${d.total}</div>`;
  }).join("");

  const rawJsonHtml = tradingDates.length > 1
    ? perDate.map(d => `
        <details style="margin-top:4px;">
          <summary style="cursor:pointer;font-size:10.5px;color:var(--teal);">${escapeHtml(d.date)} — JSON mentah</summary>
          <pre style="font-size:10.5px;background:color-mix(in srgb, currentColor 9%, transparent);padding:8px;border-radius:6px;overflow-x:auto;max-height:200px;">${escapeHtml(JSON.stringify(d.raw ?? {}, null, 2))}</pre>
        </details>`).join("")
    : `<pre style="font-size:10.5px;background:color-mix(in srgb, currentColor 9%, transparent);padding:8px;border-radius:6px;overflow-x:auto;max-height:200px;">${escapeHtml(JSON.stringify(perDate[0]?.raw ?? {}, null, 2))}</pre>`;

  resultEl.innerHTML = `
    <div style="font-size:11.5px;margin-bottom:6px;">${verdict}</div>
    ${tradingDates.length > 1 ? `
    <details open style="margin-bottom:6px;">
      <summary style="cursor:pointer;font-size:11px;color:var(--teal);">Rincian per-tanggal (${tradingDates.length} hari)</summary>
      <div class="mono" style="margin-top:6px;font-size:11px;max-height:180px;overflow-y:auto;">${perDateListHtml}</div>
    </details>` : ""}
    <details><summary style="cursor:pointer;font-size:11px;color:var(--teal);">Lihat JSON mentah${tradingDates.length>1 ? " (per tanggal)" : ""}</summary>
      ${rawJsonHtml}
    </details>`;
}

// ==========================================
// PENGATURAN UI KONEKSI (sekarang tab biasa, bukan modal popup — lihat
// renderSettingsTab()/initSettingsTabUI() di bawah, dipanggil dari
// render() saat state.tab==="settings")
// ==========================================
function renderSettingsTab(){
  return `
    <div class="settings-page">
      <style>
        .settings-page{max-width:1100px;margin:0 auto;}
        .settings-hero{display:flex;align-items:center;gap:14px;margin-bottom:20px;padding:18px 22px;border-radius:16px;background:linear-gradient(135deg, color-mix(in srgb, var(--teal) 12%, transparent), color-mix(in srgb, var(--gold) 8%, transparent));border:1px solid var(--border);}
        .settings-hero-icon{width:44px;height:44px;border-radius:13px;background:var(--panel,var(--bg));border:1px solid var(--border);display:flex;align-items:center;justify-content:center;font-size:21px;flex-shrink:0;}
        .settings-hero h2{margin:0 0 3px;font-size:17px;}
        .settings-hero p{margin:0;font-size:12px;color:var(--muted);line-height:1.5;}
        .settings-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:16px;align-items:start;}
        .settings-card{background:var(--panel,var(--bg));border:1px solid var(--border);border-radius:16px;padding:20px 22px;box-shadow:0 1px 2px rgba(0,0,0,.04);}
        .settings-card.full{grid-column:1/-1;}
        .settings-card-head{display:flex;align-items:center;gap:11px;margin-bottom:4px;}
        .settings-card-icon{width:36px;height:36px;border-radius:11px;display:flex;align-items:center;justify-content:center;font-size:17px;flex-shrink:0;background:color-mix(in srgb, var(--teal) 15%, transparent);}
        .settings-card-icon.gold{background:color-mix(in srgb, var(--gold) 18%, transparent);}
        .settings-card-icon.down{background:color-mix(in srgb, var(--down) 15%, transparent);}
        .settings-card-title{font-size:14.5px;font-weight:700;margin:0;line-height:1.3;}
        .settings-card-desc{font-size:11.5px;color:var(--muted);line-height:1.6;margin:8px 0 16px;}
        .settings-row2{display:grid;grid-template-columns:1fr 1fr;gap:12px;}
        @media (max-width:480px){ .settings-row2{grid-template-columns:1fr;} }
        .settings-card .field input[type="text"],
        .settings-card .field input[type="password"],
        .settings-card .field input[type="number"],
        .settings-card .field input[type="date"],
        .settings-card .field select,
        .settings-card .field textarea{
          border-radius:10px !important;
          border:1px solid var(--border) !important;
          background:color-mix(in srgb, currentColor 4%, transparent) !important;
          color:var(--text) !important;
          transition:border-color .15s ease, box-shadow .15s ease, background .15s ease;
        }
        .settings-card .field input[type="text"]:hover,
        .settings-card .field input[type="password"]:hover,
        .settings-card .field input[type="number"]:hover,
        .settings-card .field select:hover{
          border-color:color-mix(in srgb, var(--teal) 45%, var(--border)) !important;
        }
        .settings-card .field input:focus,
        .settings-card .field select:focus,
        .settings-card .field textarea:focus{
          outline:none !important;
          border-color:var(--teal) !important;
          box-shadow:0 0 0 3px color-mix(in srgb, var(--teal) 16%, transparent);
        }
        .settings-note{font-size:11.5px;line-height:1.6;padding:11px 13px;border-radius:10px;margin:10px 0;}
        .settings-note.info{color:var(--teal);background:rgba(6,182,212,.1);border:1px solid rgba(6,182,212,.2);}
        .settings-note.warn{color:var(--gold);background:color-mix(in srgb, var(--gold) 14%, transparent);border:1px solid color-mix(in srgb, var(--gold) 38%, transparent);}
        details.settings-adv{margin-top:10px;border:1px dashed var(--border);border-radius:12px;padding:0 16px;}
        details.settings-adv summary{cursor:pointer;padding:12px 0;font-size:12.5px;font-weight:700;color:var(--teal);list-style:none;display:flex;align-items:center;gap:7px;}
        details.settings-adv summary::-webkit-details-marker{display:none;}
        details.settings-adv summary:before{content:'▸';display:inline-block;transition:transform .15s ease;font-size:11px;}
        details.settings-adv[open] summary:before{transform:rotate(90deg);}
        details.settings-adv[open] summary{border-bottom:1px solid var(--border);margin-bottom:14px;}
        details.settings-adv > .field:last-child, details.settings-adv > div:last-child{margin-bottom:0;}
        .settings-actionbar{display:flex;gap:10px;padding:18px 4px 4px;margin-top:4px;border-top:1px solid var(--border);}
      </style>

      <div class="settings-hero">
        <div class="settings-hero-icon">⚙️</div>
        <div>
          <h2>Pengaturan</h2>
          <p>Koneksi data, fee portofolio, live data Stockbit, AI, dan notifikasi — semua tersimpan lokal di browser ini.</p>
        </div>
      </div>

      <div class="settings-grid">

        <div class="settings-card full">
          <div class="settings-card-head">
            <div class="settings-card-icon">🔌</div>
            <h3 class="settings-card-title">Koneksi Supabase</h3>
          </div>
          <div class="settings-card-desc">Wajib diisi supaya data screener bisa dimuat.</div>
          <div class="settings-row2">
            <div class="field">
              <label>Supabase REST URL</label>
              <input id="setSupaUrl" type="text" placeholder="https://xyz.supabase.co">
            </div>
            <div class="field">
              <label>Supabase Anon Key</label>
              <input id="setSupaKey" type="password" placeholder="eyJhbG...">
            </div>
          </div>
          <div class="field">
            <label>Kolom Frequency Analyzer (opsional)</label>
            <input id="setFreqAnalyzerCol" type="text" placeholder="freq_ma20">
          </div>
          <div class="settings-note info">
            ℹ️ Kredensial disimpan lokal di browser Anda (Local Storage). <b>Pakai anon key saja</b> —
            jangan pernah masukkan service_role key di sini: halaman ini publik dan bisa dibaca siapa saja
            lewat "View Source", sedangkan service_role bisa menulis/menghapus seluruh database.
          </div>
        </div>

        <div class="settings-card">
          <div class="settings-card-head">
            <div class="settings-card-icon gold">💰</div>
            <h3 class="settings-card-title">Fee Default Portofolio</h3>
          </div>
          <div class="settings-card-desc">
            Dipakai sebagai nilai awal field Fee di form Tambah Transaksi Portofolio (baru &amp; impor Excel/CSV),
            dan sebagai estimasi fee jual untuk menghitung <b>P/L Mengambang</b> supaya angkanya net-fee —
            sejajar dengan P/L Realisasi transaksi yang sudah closed. Sesuaikan dengan tarif fee broker Anda.
          </div>
          <div class="settings-row2">
            <div class="field">
              <label>Fee Beli Default (%)</label>
              <input id="setFeeBeliDefault" type="number" step="0.01" placeholder="0.15">
            </div>
            <div class="field">
              <label>Fee Jual Default (%)</label>
              <input id="setFeeJualDefault" type="number" step="0.01" placeholder="0.25">
            </div>
          </div>
        </div>

        <div class="settings-card">
          <div class="settings-card-head">
            <div class="settings-card-icon">🧭</div>
            <h3 class="settings-card-title">Tampilan</h3>
          </div>
          <label style="display:grid;grid-template-columns:16px 1fr;align-items:center;gap:8px;font-size:12.5px;padding:10px 0 4px;cursor:pointer;">
            <input type="checkbox" id="setAdvancedMode" class="custom-checkbox" style="margin:0;justify-self:start;" onchange="setAdvancedMode(this.checked)">
            <span style="text-align:left;">Mode Lanjutan — tampilkan tab developer/eksperimental (🧪 WS Debug) di menu</span>
          </label>
          <div style="font-size:11px;color:var(--muted);">Berlaku langsung, tidak perlu "Simpan &amp; Reload".</div>
        </div>

        <div class="settings-card full">
          <div class="settings-card-head">
            <div class="settings-card-icon down">🔴</div>
            <h3 class="settings-card-title">Live Data Stockbit</h3>
          </div>
          <div class="settings-card-desc">
            Pakai token dari extension Chrome Stockbit milikmu sendiri untuk menarik harga/orderbook <b>live</b>
            untuk saham yang lolos filter Screener saat ini. Ini API tidak resmi (bukan API publik Stockbit) —
            endpoint bisa berubah kapan saja, dan token disimpan HANYA di Local Storage browser ini (tidak
            dikirim ke server manapun selain langsung ke Stockbit/proxy yang kamu tentukan sendiri).
          </div>
          <div class="field">
            <label>Stockbit Token</label>
            <input id="setStockbitToken" type="password" placeholder="Bearer token dari extension">
          </div>
          <div id="stockbitTokenStatus" style="font-size:11px;color:var(--muted);margin:-8px 0 4px;">Belum ada token.</div>
          <div id="stockbitLastSuccessStatus" style="font-size:11px;color:var(--muted);margin:-4px 0 12px;">Belum pernah berhasil menarik data live dari Stockbit.</div>
          <div id="indexMembershipSyncRow" style="margin:0 0 4px;padding-top:10px;border-top:1px dashed color-mix(in srgb, currentColor 15%, transparent);">
            <div style="font-size:10.5px;color:var(--muted);margin-bottom:6px;">Keanggotaan LQ45 / Syariah / FCA / Suspend / Unsuspend / FCA Out (klasifikasi Stockbit → tabel <code>index_membership</code>)</div>
            <button type="button" id="btnSyncIndexMembership" class="btn btn-outline" style="font-size:11px;padding:6px 10px;">🔄 Sync Klasifikasi Stockbit</button>
            <div id="indexMembershipSyncStatus" style="font-size:10.5px;color:var(--muted);margin-top:6px;"></div>
          </div>

          <details class="settings-adv">
            <summary>🔧 Endpoint API Lanjutan (opsional — untuk pengguna advanced)</summary>
            <div class="field">
              <label>Endpoint Quote (harga Open/High/Low/Last/Bid/Offer per ticker — WAJIB pakai {ticker}, jangan diganti kode saham tertentu)</label>
              <input id="setStockbitQuoteEndpoint" type="text" placeholder="https://exodus.stockbit.com/stream/v3/symbol/{ticker}">
            </div>
            <div class="settings-note warn">
              ⚠️ Endpoint default TERBUKTI SALAH (itu API "Stream"/linimasa komentar, bukan API harga) — Open/High/Low/Last
              tidak akan pernah muncul benar selama field ini masih kosong/default. Pakai kotak uji di bawah untuk mencari
              &amp; memverifikasi endpoint yang benar lewat DevTools browser (Network tab) di stockbit.com, sebelum disimpan.
              <br><br>
              Beda dari field <b>"Endpoint Orderbook Depth 10-Level"</b> di bawah ini — field itu khusus tangga bid/offer
              dan sudah terbukti berfungsi. Kalau mau mencoba endpoint yang sama untuk field ini juga, tempel URL yang
              SAMA PERSIS tapi tetap dengan placeholder <code>{ticker}</code> (bukan kode saham tertentu seperti
              <code>BIPI</code> — kalau di-hardcode begitu, aplikasi cuma akan menarik data BIPI untuk semua saham).
              Perlu diuji dulu: endpoint orderbook belum tentu membawa field Open/High/Low/Last, mungkin cuma bid/offer saja.
              <div style="display:flex;gap:8px;align-items:center;margin-top:10px;flex-wrap:wrap;">
                <input id="testStockbitTicker" type="text" placeholder="Ticker uji, mis. BBCA" maxlength="6" style="text-transform:uppercase;max-width:140px;">
                <button type="button" class="btn btn-outline" onclick="testStockbitQuoteEndpoint()" style="font-size:11.5px;padding:6px 10px;">🧪 Uji Endpoint Ini</button>
              </div>
              <div id="testStockbitQuoteResult" style="margin-top:8px;"></div>
            </div>
            <div class="field">
              <label>Endpoint Orderbook Depth 10-Level (pakai {ticker} sebagai placeholder)</label>
              <input id="setStockbitOrderbookEndpoint" type="text" placeholder="https://exodus.stockbit.com/company-price-feed/v2/orderbook/companies/{ticker}">
              <div style="font-size:11px;color:var(--muted);margin-top:4px;">✅ Sudah terverifikasi berfungsi. Beda dari "Endpoint Quote/Orderbook" di atas — yang ini khusus tangga bid/offer 10 level di panel Detail Emiten, dan nilainya ikut tersimpan ke Supabase supaya tidak hilang saat dibuka di browser lain.</div>
            </div>
            <div class="field">
              <label>Endpoint Broker Activity (per broker — dipakai mode "Lacak Broker" di Broker Stalker; sudah terisi default)</label>
              <input id="setStockbitBrokerActivityEndpoint" type="text" placeholder="https://exodus.stockbit.com/order-trade/broker/activity?broker_code={broker_code}&limit={limit}&page=1&transaction_type=TRANSACTION_TYPE_NET&market_board=MARKET_TYPE_REGULER&investor_type=INVESTOR_TYPE_ALL&from={date}&to={date}">
              <div style="font-size:11px;color:var(--muted);margin-top:4px;">Placeholder wajib ada: <code>{broker_code}</code>, <code>{date}</code> (dipakai 2x, untuk from= dan to=), dan sebaiknya <code>{limit}</code>. Endpoint ini per BROKER dan mengembalikan SEMUA saham yang ditransaksikan broker itu, bukan cuma top-5.</div>
              <div style="display:flex;gap:8px;align-items:center;margin-top:10px;flex-wrap:wrap;">
                <input id="testStockbitBrokerActivityCode" type="text" placeholder="Kode broker uji, mis. AK" maxlength="3" style="text-transform:uppercase;max-width:150px;">
                <input id="testStockbitBrokerActivityFrom" type="date" title="Dari tanggal" style="background:color-mix(in srgb, currentColor 6%, transparent);border:1px solid var(--border);color:var(--text);font-size:11.5px;border-radius:6px;padding:6px;">
                <span style="color:var(--muted);font-size:11px;">&ndash;</span>
                <input id="testStockbitBrokerActivityTo" type="date" title="Sampai tanggal" style="background:color-mix(in srgb, currentColor 6%, transparent);border:1px solid var(--border);color:var(--text);font-size:11.5px;border-radius:6px;padding:6px;">
                <button type="button" class="btn btn-outline" onclick="testStockbitBrokerActivityEndpoint()" style="font-size:11.5px;padding:6px 10px;">🧪 Uji Endpoint Ini</button>
              </div>
              <div style="font-size:10.5px;color:var(--muted);margin-top:4px;">Tes ini baca langsung dari kotak endpoint di atas (belum perlu Simpan) dan TIDAK menyimpan apa pun ke database. Kosongkan "Dari" untuk pakai hari ini; kosongkan "Sampai" untuk 1 hari saja. Pilih hari bursa.</div>
              <div id="testStockbitBrokerActivityResult" style="margin-top:8px;"></div>
            </div>
            <div class="field">
              <label>Endpoint Historical Data (sudah terisi default — timpa hanya kalau Stockbit ganti skemanya)</label>
              <input id="setStockbitHistoricalEndpoint" type="text" placeholder="https://exodus.stockbit.com/company-price-feed/historical/summary/{ticker}?period={period}&start_date={start_date}&end_date={end_date}&limit={limit}&page={page}">
              <div style="font-size:11px;color:var(--muted);margin-top:4px;">✅ Endpoint sudah dicek manual lewat DevTools (mode Daily). Mode Weekly/Monthly baru tebakan pola nama parameter — kalau ternyata salah/data janggal, kabari supaya bisa dikoreksi.</div>
              <div style="display:flex;gap:8px;align-items:center;margin-top:8px;flex-wrap:wrap;">
                <input id="testStockbitHistTicker" type="text" placeholder="Ticker uji" maxlength="6" style="text-transform:uppercase;max-width:120px;">
                <select id="testStockbitHistPeriod" style="background:color-mix(in srgb, currentColor 6%, transparent);border:1px solid var(--border);color:var(--text);font-size:11.5px;border-radius:6px;padding:6px;">
                  <option value="daily">Daily</option>
                  <option value="weekly">Weekly</option>
                  <option value="monthly">Monthly</option>
                </select>
                <button type="button" class="btn btn-outline" onclick="testStockbitHistoricalEndpoint()" style="font-size:11.5px;padding:6px 10px;">🧪 Uji Mode Ini</button>
              </div>
              <div id="testStockbitHistResult" style="margin-top:8px;"></div>
            </div>
            <div class="field">
              <label>Endpoint Insider / Pemegang Saham Utama (dipakai tab "🕵️ Insider" di Detail Emiten)</label>
              <input id="setStockbitInsiderEndpoint" type="text" placeholder="https://exodus.stockbit.com/insider/company/majorholder?insider={insider}&symbol={ticker}&date_start={date_start}&date_end={date_end}&page={page}">
              <div style="font-size:11px;color:var(--muted);margin-top:4px;">⚠️ Belum diverifikasi manual (baru contoh URL dari user, belum contoh response) — kalau tabel di tab Insider kosong/tidak terbaca, cek "Lihat JSON mentah" di tab itu lalu sesuaikan parseStockbitInsider() di app.js. Placeholder wajib ada: <code>{ticker}</code>; <code>{insider}</code>, <code>{date_start}</code>, <code>{date_end}</code>, <code>{page}</code> boleh dikosongkan hasilnya (default = semua data).</div>
            </div>
            <div class="field">
              <label>Proxy URL (opsional — isi kalau permintaan langsung gagal karena CORS)</label>
              <input id="setStockbitProxyUrl" type="text" placeholder="https://xxxx.supabase.co/functions/v1/stockbit-proxy">
            </div>
            <div class="settings-note warn">
              ⚠️ Endpoint di atas belum terverifikasi 100% (hasil pengamatan komunitas, bukan dokumentasi resmi
              Stockbit) dan browser <b>kemungkinan besar akan memblokirnya karena CORS</b> kalau dipanggil langsung
              dari halaman ini. Kalau muncul error CORS, isi "Proxy URL" dengan Supabase Edge Function kecil yang
              meneruskan request + header Authorization dari sisi server (lihat file <code>stockbit-proxy</code>
              yang disediakan terpisah). Pakai token akunmu sendiri secara bertanggung jawab dan hormati rate limit.
            </div>
            <div class="settings-note info">
              🔄 Field Token di atas bisa terisi <b>otomatis</b> lewat extension Chrome <code>stockbit-token-extension</code>
              (jalankan dulu <code>sql/05_stockbit_token_sync.sql</code> di Supabase). Kalau sudah terpasang &amp; kamu
              pernah buka stockbit.com dalam kondisi login, token akan tersinkron sendiri setiap kali tab ini dibuka.
            </div>
          </details>
        </div>

        <div class="settings-card">
          <div class="settings-card-head">
            <div class="settings-card-icon">🤖</div>
            <h3 class="settings-card-title">Analisis AI (Gemini)</h3>
          </div>
          <div class="settings-card-desc">
            Menghasilkan ringkasan analisis berbahasa natural per emiten (tab "🤖 AI (Gemini)" di Detail Emiten),
            memakai data yang SUDAH ada di screener (harga, fundamental, teknikal, Bandarmologi) sebagai konteks.
            Dipanggil <b>langsung dari browser ke Google</b> pakai API key milik Anda sendiri — bukan lewat
            server/Supabase manapun. Ambil API key gratis di
            <a href="https://aistudio.google.com/apikey" target="_blank" rel="noopener" style="color:var(--teal);">aistudio.google.com/apikey</a>.
          </div>
          <div class="field">
            <label>Gemini API Key</label>
            <input id="setGeminiApiKey" type="password" placeholder="AIzaSy...">
          </div>
          <div class="field">
            <label>Model (opsional — default alias resmi Google, otomatis ke Flash stabil terbaru)</label>
            <input id="setGeminiModel" type="text" placeholder="gemini-flash-latest">
          </div>
          <div class="settings-note warn">
            ⚠️ API key disimpan HANYA di Local Storage browser ini (sama seperti Token Stockbit di atas) — jangan
            pakai perangkat/browser publik. Hasil analisis AI bersifat ringkasan otomatis dari data yang tersedia,
            <b>BUKAN rekomendasi/nasihat investasi</b> — selalu lakukan riset mandiri sebelum mengambil keputusan.
          </div>
        </div>

        <div class="settings-card">
          <div class="settings-card-head">
            <div class="settings-card-icon gold">📑</div>
            <h3 class="settings-card-title">Fundamental Screener (Arjum)</h3>
          </div>
          <div class="settings-card-desc">
            Menampilkan Laporan Keuangan (Laba Rugi/Neraca/Arus Kas) &amp; Seasonality bulanan per emiten (panel
            "💰 Laporan Keuangan &amp; Seasonality" di tab "💰 Fundamental" pada Detail Emiten), memakai IDX Edge PRO dari
            <a href="https://stock.arjum.com" target="_blank" rel="noopener" style="color:var(--teal);">stock.arjum.com</a>
            (daftar gratis untuk dapat API key). Dipanggil langsung dari browser pakai API key milik Anda sendiri.
          </div>
          <div class="field">
            <label>Arjum API Key</label>
            <input id="setArjumApiKey" type="password" placeholder="X-API-Key dari stock.arjum.com">
          </div>
          <div class="field">
            <label>Proxy URL (opsional)</label>
            <input id="setArjumProxyUrl" type="text" placeholder="https://xxxx.supabase.co/functions/v1/arjum-proxy">
          </div>
          <div class="settings-note warn">
            ⚠️ API key disimpan HANYA di Local Storage browser ini. Kalau panggilan langsung ke stock.arjum.com
            diblokir CORS oleh browser, isi "Proxy URL" dengan Edge Function kecil yang meneruskan request +
            header X-API-Key dari sisi server (pola sama seperti Proxy URL Stockbit di atas).
          </div>
        </div>

        <div class="settings-card full">
          <div class="settings-card-head">
            <div class="settings-card-icon">🔔</div>
            <h3 class="settings-card-title">Notifikasi Telegram (Rules Kustom)</h3>
          </div>
          <div class="settings-card-desc">
            Kirim notifikasi Telegram otomatis kalau ada saham baru yang lolos preset Rules Kustom pilihanmu —
            jalan di server (Cron), jadi tetap terkirim walau aplikasi ini tidak sedang dibuka.
            Butuh setup 1x: jalankan <code>sql/06_telegram_notifikasi.sql</code> di Supabase, deploy
            <code>functions/telegram-notifier</code>, lalu isi field di bawah ini.
          </div>
          <details style="margin-bottom:12px;">
            <summary style="cursor:pointer; font-size:12px; color:var(--teal);">📖 Cara bikin Bot Telegram & dapat Chat ID (belum punya?)</summary>
            <ol style="font-size:11.5px; color:var(--muted); line-height:1.7; padding-left:18px; margin:8px 0 0;">
              <li>Buka Telegram, cari <b>@BotFather</b>, kirim perintah <code>/newbot</code>, ikuti instruksinya (kasih nama & username bot).</li>
              <li>BotFather akan membalas dengan <b>token</b> (contoh: <code>123456789:AAExxxxxxxxxxxxxxxxxxxxxxxxxxxxxx</code>) — salin ke field "Bot Token" di bawah.</li>
              <li>Cari & mulai chat dengan bot barumu (klik link dari BotFather atau cari usernamenya), kirim pesan apa saja (mis. "hi") supaya bot "kenal" kamu.</li>
              <li>Untuk dapat <b>Chat ID</b>: cari <b>@userinfobot</b> di Telegram, kirim <code>/start</code>, dia akan membalas dengan ID akunmu (angka, contoh: <code>987654321</code>) — salin ke field "Chat ID".</li>
              <li>Kalau mau notifikasi masuk ke grup, tambahkan bot ke grup itu, lalu pakai Chat ID grup (biasanya diawali tanda minus, mis. <code>-1001234567890</code> — bisa dicek lewat @RawDataBot atau membuka <code>https://api.telegram.org/bot&lt;token&gt;/getUpdates</code> setelah mengirim pesan ke grup).</li>
            </ol>
          </details>
          <div class="settings-row2">
            <div class="field">
              <label>Bot Token</label>
              <input id="setTelegramBotToken" type="password" placeholder="123456789:AAExxxxxxxxxxxxxxxxxxxxxxxxxxxxxx">
            </div>
            <div class="field">
              <label>Chat ID</label>
              <input id="setTelegramChatId" type="text" placeholder="987654321">
            </div>
          </div>
          <div class="field">
            <label>URL Edge Function (untuk tombol "Uji Kirim" di bawah)</label>
            <input id="setTelegramFunctionUrl" type="text" placeholder="https://xxxx.supabase.co/functions/v1/telegram-notifier">
          </div>
          <label style="display:grid;grid-template-columns:16px 1fr;align-items:center;gap:8px;font-size:12.5px;padding:6px 0;cursor:pointer;">
            <input type="checkbox" id="setTelegramEnabled" class="custom-checkbox" style="margin:0;justify-self:start;">
            <span style="text-align:left;">Aktifkan notifikasi otomatis (Cron server akan mengecek & mengirim)</span>
          </label>
          <label style="display:grid;grid-template-columns:16px 1fr;align-items:center;gap:8px;font-size:12.5px;padding:6px 0 10px;cursor:pointer;">
            <input type="checkbox" id="setTelegramOnlyMarketHours" class="custom-checkbox" style="margin:0;justify-self:start;">
            <span style="text-align:left;">Hanya kirim di jam bursa (≈09:00–17:00 WIB, Senin–Jumat)</span>
          </label>
          <div class="field">
            <label>Preset yang dipantau (Rules Kustom tersimpan)</label>
            <div id="telegramPresetChecklist" style="background:color-mix(in srgb, currentColor 3%, transparent);border:1px solid var(--border);border-radius:8px;padding:8px 12px;max-height:160px;overflow-y:auto;">
              <div style="font-size:12px;color:var(--muted);">Memuat preset...</div>
            </div>
          </div>
          <div style="display:flex;align-items:center;gap:10px;margin:4px 0 6px;">
            <button type="button" class="btn btn-outline" onclick="testTelegramNotification()">📤 Uji Kirim Notifikasi</button>
            <span id="telegramTestStatus" style="font-size:11.5px;color:var(--muted);"></span>
          </div>
          <div id="telegramLastRunStatus" style="font-size:11px;color:var(--muted);"></div>
        </div>

      </div>

      <div class="settings-actionbar">
        <button class="btn btn-primary" onclick="saveSettings()">💾 Simpan &amp; Reload</button>
        <button class="btn btn-outline" onclick="closeSettings()">↩ Kembali ke Dashboard</button>
      </div>
    </div>
  `;
}

// ------------------------------------------------------------------
// PENGAMAN TERHADAP "KERESET": field Bot Token / Chat ID / centang Telegram
// baru terisi SESUDAH beberapa await (sync token Stockbit + fetch
// telegram_settings) di initSettingsTabUI(). Kalau user (atau render ulang
// tab) menekan Simpan / Uji Kirim sebelum itu selesai, field masih kosong
// -> dulu nilai kosong itu ikut ditulis ke database & menimpa token/chat id
// asli. state.telegramFieldsPopulated = true HANYA setelah field benar-benar
// diisi dari state; selama false, nilai state dipertahankan (DOM diabaikan).
// ------------------------------------------------------------------
function tgFieldFromDom(id, current){
  const el = document.getElementById(id);
  if(!el || !state.telegramFieldsPopulated) return current;
  return (el.value || "").trim();
}
function tgCheckFromDom(id, current){
  const el = document.getElementById(id);
  if(!el || !state.telegramFieldsPopulated) return current;
  return !!el.checked;
}
async function initSettingsTabUI() {
  state.telegramFieldsPopulated = false; // form Telegram di bawah belum terisi
  let urlDisp = SUPABASE_URL;
  if(urlDisp.endsWith("/rest/v1")) urlDisp = urlDisp.replace("/rest/v1", "");
  document.getElementById("setSupaUrl").value = urlDisp;
  document.getElementById("setSupaKey").value = SUPABASE_KEY;
  const freqEl = document.getElementById("setFreqAnalyzerCol");
  if(freqEl) freqEl.value = state.freqAnalyzerCol;
  const stbToken = document.getElementById("setStockbitToken");
  if(stbToken) stbToken.value = state.stockbitToken || "";
  const stbQuote = document.getElementById("setStockbitQuoteEndpoint");
  if(stbQuote) stbQuote.value = state.stockbitQuoteEndpoint || STOCKBIT_DEFAULT_QUOTE_EP;
  const stbBroker = document.getElementById("setStockbitBrokerEndpoint");
  if(stbBroker) stbBroker.value = state.stockbitBrokerEndpoint || STOCKBIT_DEFAULT_BROKER_EP;
  const stbBrokerActivity = document.getElementById("setStockbitBrokerActivityEndpoint");
  if(stbBrokerActivity) stbBrokerActivity.value = state.stockbitBrokerActivityEndpoint || STOCKBIT_DEFAULT_BROKER_ACTIVITY_EP;
  const stbHistorical = document.getElementById("setStockbitHistoricalEndpoint");
  if(stbHistorical) stbHistorical.value = state.stockbitHistoricalEndpoint || STOCKBIT_DEFAULT_HISTORICAL_EP;
  const stbInsider = document.getElementById("setStockbitInsiderEndpoint");
  if(stbInsider) stbInsider.value = state.stockbitInsiderEndpoint || STOCKBIT_DEFAULT_INSIDER_EP;
  const stbOrderbook = document.getElementById("setStockbitOrderbookEndpoint");
  if(stbOrderbook) stbOrderbook.value = state.stockbitOrderbookEndpoint || STOCKBIT_DEFAULT_ORDERBOOK_EP;
  const stbProxy = document.getElementById("setStockbitProxyUrl");
  if(stbProxy) stbProxy.value = state.stockbitProxyUrl || "";
  const geminiKeyEl = document.getElementById("setGeminiApiKey");
  if(geminiKeyEl) geminiKeyEl.value = state.geminiApiKey || "";
  const geminiModelEl = document.getElementById("setGeminiModel");
  setGeminiModelSelectValue(geminiModelEl, state.geminiModel || GEMINI_DEFAULT_MODEL);
  const arjumKeyEl = document.getElementById("setArjumApiKey");
  if(arjumKeyEl) arjumKeyEl.value = state.arjumApiKey || "";
  const arjumProxyEl = document.getElementById("setArjumProxyUrl");
  if(arjumProxyEl) arjumProxyEl.value = state.arjumProxyUrl || "";
  const feeBeliDefEl = document.getElementById("setFeeBeliDefault");
  if(feeBeliDefEl) feeBeliDefEl.value = state.feeBeliDefaultPct ?? FEE_BELI_DEFAULT_PCT;
  const feeJualDefEl = document.getElementById("setFeeJualDefault");
  if(feeJualDefEl) feeJualDefEl.value = state.feeJualDefaultPct ?? FEE_JUAL_DEFAULT_PCT;
  updateStockbitTokenStatusUI();
  updateStockbitLastSuccessStatusUI();
  renderIndexMembershipSyncButton();
  // Coba tarik token terbaru dari Supabase di background — kalau berhasil,
  // timpa field token yang baru saja ditampilkan supaya selalu yang terbaru.
  // (syncStockbitTokenFromSupabase() sendiri akan no-op kalau token yang
  // aktif sekarang datang dari extension — lihat catatan di fungsi itu.)
  const synced = await syncStockbitTokenFromSupabase();
  if(synced && stbToken) stbToken.value = state.stockbitToken;
  updateStockbitTokenStatusUI();

  // --- Notifikasi Telegram ---
  // BUG (ditemukan lewat uji jalan aktual, bukan cuma baca kode): baris di
  // bawah sebelumnya "const tgFnEl = ..." nyasar ke DALAM komentar baris di
  // atas (satu baris yang sama), jadi javascript menganggap deklarasinya
  // TIDAK PERNAH ADA. Akibatnya baris "if(tgFnEl)..." di bawah selalu
  // lempar ReferenceError SETIAP KALI modal Pengaturan dibuka — bagian
  // kode setelah baris itu (refresh custom presets, isi ulang field
  // Gemini/Telegram) jadi tidak pernah jalan karena errornya mematahkan
  // sisa fungsi async ini.
  const tgFnEl = document.getElementById("setTelegramFunctionUrl");
  if(tgFnEl) tgFnEl.value = state.telegramFunctionUrl || ""; // isi awal dari localStorage, sambil menunggu fetch di bawah
  await Promise.all([refreshCustomPresets(), loadTelegramSettingsFromSupabase()]);
  // Timpa lagi setelah fetch selesai — kalau Supabase punya function_url tersimpan,
  // itu yang dipakai (lihat loadTelegramSettingsFromSupabase), bukan cuma localStorage.
  if(tgFnEl) tgFnEl.value = state.telegramFunctionUrl || "";
  if(geminiKeyEl) geminiKeyEl.value = state.geminiApiKey || "";
  setGeminiModelSelectValue(geminiModelEl, state.geminiModel || GEMINI_DEFAULT_MODEL);
  const tgTokenEl = document.getElementById("setTelegramBotToken");
  if(tgTokenEl) tgTokenEl.value = state.telegramBotToken || "";
  const tgChatEl = document.getElementById("setTelegramChatId");
  if(tgChatEl) tgChatEl.value = state.telegramChatId || "";
  const tgEnabledEl = document.getElementById("setTelegramEnabled");
  if(tgEnabledEl) tgEnabledEl.checked = !!state.telegramEnabled;
  const tgHoursEl = document.getElementById("setTelegramOnlyMarketHours");
  if(tgHoursEl) tgHoursEl.checked = state.telegramOnlyMarketHours !== false;
  if(tgTokenEl) state.telegramFieldsPopulated = true; // form sudah terisi -> aman dibaca saat Simpan
  renderTelegramPresetChecklist();
  const tgLastRunEl = document.getElementById("telegramLastRunStatus");
  if(tgLastRunEl){
    tgLastRunEl.textContent = state.telegramLastRunAt
      ? `Terakhir cek server: ${new Date(state.telegramLastRunAt).toLocaleString("id-ID")} — ${state.telegramLastRunNote || ""}`
      : "Belum pernah dijalankan Cron server (atau tabel telegram_settings belum dibuat).";
  }
}
function updateStockbitTokenStatusUI(){
  const el = document.getElementById("stockbitTokenStatus");
  if(!el) return;
  const st = stockbitTokenStatus();
  el.textContent = st.text;
  el.style.color = st.color;
}

// Dipanggil dari banyak tempat (tombol header, link "Buka ⚙️ Pengaturan" di
// pesan error token/API key kosong, dsb.) — dulu membuka modal, sekarang
// cukup pindah ke tab "settings". Pengisian field (initSettingsTabUI())
// otomatis jalan lewat hook di render(), BUKAN dipanggil manual di sini,
// supaya navigasi via klik menu sidebar (bukan lewat fungsi ini) tetap
// mengisi field dengan benar juga.
function openSettings() {
  selectMainTab("settings");
}

// Dulu menutup modal Pengaturan; sekarang tab "settings" bukan overlay jadi
// tidak ada yang perlu ditutup — cukup pindah balik ke Dashboard. Dipakai
// tombol "↩ Kembali ke Dashboard" & dipanggil otomatis di akhir saveSettings().
function closeSettings() {
  selectMainTab("dashboard");
}

function saveSettings() {
  let supaUrlInput = document.getElementById("setSupaUrl").value.trim();
  // Validasi URL dan otomatisasi append path /rest/v1
  if (supaUrlInput) {
    if (supaUrlInput.endsWith("/")) supaUrlInput = supaUrlInput.slice(0, -1);
    if (!supaUrlInput.endsWith("/rest/v1")) supaUrlInput += "/rest/v1";
  }
  
  SUPABASE_URL = supaUrlInput;
  SUPABASE_KEY = document.getElementById("setSupaKey").value.trim();

  localStorage.setItem("ihsg_supa_url", SUPABASE_URL);
  localStorage.setItem("ihsg_supa_key", SUPABASE_KEY);

  const freqColInput = (document.getElementById("setFreqAnalyzerCol")?.value || "").trim();
  state.freqAnalyzerCol = freqColInput || "freq_ma20";
  localStorage.setItem(LS_FREQ_ANALYZER_COL, state.freqAnalyzerCol);

  state.stockbitToken = sanitizeStockbitToken(document.getElementById("setStockbitToken")?.value);
  state.stockbitTokenSource = "manual"; // ditimpa balik ke "auto"/"extension" oleh sync yang berjalan otomatis kalau memang datang dari situ
  state.stockbitTokenSyncedAt = Date.now();
  try{
    localStorage.setItem(LS_STOCKBIT_TOKEN_SOURCE, "manual");
    localStorage.setItem(LS_STOCKBIT_TOKEN_SYNCED_AT, String(state.stockbitTokenSyncedAt));
  }catch(e){}
  state.stockbitQuoteEndpoint = (document.getElementById("setStockbitQuoteEndpoint")?.value || "").trim() || STOCKBIT_DEFAULT_QUOTE_EP;
  state.stockbitBrokerEndpoint = (document.getElementById("setStockbitBrokerEndpoint")?.value || "").trim() || STOCKBIT_DEFAULT_BROKER_EP;
  state.stockbitBrokerActivityEndpoint = (document.getElementById("setStockbitBrokerActivityEndpoint")?.value || "").trim() || STOCKBIT_DEFAULT_BROKER_ACTIVITY_EP;
  state.stockbitHistoricalEndpoint = (document.getElementById("setStockbitHistoricalEndpoint")?.value || "").trim() || STOCKBIT_DEFAULT_HISTORICAL_EP;
  state.stockbitInsiderEndpoint = (document.getElementById("setStockbitInsiderEndpoint")?.value || "").trim() || STOCKBIT_DEFAULT_INSIDER_EP;
  state.stockbitOrderbookEndpoint = (document.getElementById("setStockbitOrderbookEndpoint")?.value || "").trim() || STOCKBIT_DEFAULT_ORDERBOOK_EP;
  state.stockbitProxyUrl = (document.getElementById("setStockbitProxyUrl")?.value || "").trim();
  localStorage.setItem(LS_STOCKBIT_TOKEN, state.stockbitToken);
  localStorage.setItem(LS_STOCKBIT_QUOTE_EP, state.stockbitQuoteEndpoint);
  localStorage.setItem(LS_STOCKBIT_BROKER_EP, state.stockbitBrokerEndpoint);
  localStorage.setItem(LS_STOCKBIT_BROKER_ACTIVITY_EP, state.stockbitBrokerActivityEndpoint);
  localStorage.setItem(LS_STOCKBIT_HISTORICAL_EP, state.stockbitHistoricalEndpoint);
  localStorage.setItem(LS_STOCKBIT_INSIDER_EP, state.stockbitInsiderEndpoint);
  localStorage.setItem(LS_STOCKBIT_ORDERBOOK_EP, state.stockbitOrderbookEndpoint);
  localStorage.setItem(LS_STOCKBIT_PROXY, state.stockbitProxyUrl);

  state.geminiApiKey = (document.getElementById("setGeminiApiKey")?.value || "").trim();
  state.geminiModel = (document.getElementById("setGeminiModel")?.value || "").trim() || GEMINI_DEFAULT_MODEL;
  localStorage.setItem(LS_GEMINI_API_KEY, state.geminiApiKey);
  localStorage.setItem(LS_GEMINI_MODEL, state.geminiModel);

  state.arjumApiKey = (document.getElementById("setArjumApiKey")?.value || "").trim();
  state.arjumProxyUrl = (document.getElementById("setArjumProxyUrl")?.value || "").trim();
  localStorage.setItem(LS_ARJUM_API_KEY, state.arjumApiKey);
  localStorage.setItem(LS_ARJUM_PROXY, state.arjumProxyUrl);

  const feeBeliDefRaw = parseFloat(document.getElementById("setFeeBeliDefault")?.value);
  state.feeBeliDefaultPct = Number.isFinite(feeBeliDefRaw) && feeBeliDefRaw >= 0 ? feeBeliDefRaw : FEE_BELI_DEFAULT_PCT;
  const feeJualDefRaw = parseFloat(document.getElementById("setFeeJualDefault")?.value);
  state.feeJualDefaultPct = Number.isFinite(feeJualDefRaw) && feeJualDefRaw >= 0 ? feeJualDefRaw : FEE_JUAL_DEFAULT_PCT;
  localStorage.setItem(LS_FEE_BELI_DEFAULT, String(state.feeBeliDefaultPct));
  localStorage.setItem(LS_FEE_JUAL_DEFAULT, String(state.feeJualDefaultPct));

  state.telegramFunctionUrl = (document.getElementById("setTelegramFunctionUrl")?.value || "").trim();
  localStorage.setItem(LS_TELEGRAM_FUNCTION_URL, state.telegramFunctionUrl);
  state.telegramBotToken = tgFieldFromDom("setTelegramBotToken", state.telegramBotToken);
  state.telegramChatId = tgFieldFromDom("setTelegramChatId", state.telegramChatId);
  state.telegramEnabled = tgCheckFromDom("setTelegramEnabled", state.telegramEnabled);
  state.telegramOnlyMarketHours = tgCheckFromDom("setTelegramOnlyMarketHours", state.telegramOnlyMarketHours);
  saveTelegramSettingsToSupabase();
  // Token Stockbit TIDAK ikut di telegram_settings — tabelnya sendiri
  // (stockbit_session) yang juga dipakai extension. Lihat catatan di sana.
  saveStockbitTokenToSupabase(state.stockbitToken);

  closeSettings();
  
  if(SUPABASE_URL && SUPABASE_KEY) {
    loadLive();
  } else {
    document.getElementById("content").innerHTML = `<div class="empty-box">Koneksi belum diatur. Klik "⚙️ Pengaturan" di pojok kanan atas.</div>`;
  }
}

// ==========================================
// NOTIFIKASI TELEGRAM (tabel telegram_settings di Supabase)
//
// Dipantau & dikirim oleh Edge Function `telegram-notifier` yang jalan
// di server lewat Cron (lihat sql/06_telegram_notifikasi.sql) — bagian
// di sini hanya UI untuk mengisi/menyimpan konfigurasinya dan tombol
// uji-kirim manual.
// ==========================================
async function loadTelegramSettingsFromSupabase(){
  if(!SUPABASE_URL || !SUPABASE_KEY) return;
  try{
    const res = await fetch(`${SUPABASE_URL}/telegram_settings?id=eq.1&select=*`, { headers: getSupaHeaders(), cache: "no-store" });
    if(!res.ok) return; // tabel belum ada (belum jalankan sql/06_telegram_notifikasi.sql) — biarkan default
    const rows = await res.json();
    const row = Array.isArray(rows) ? rows[0] : null;
    if(!row) return;
    state.telegramSettingsLoaded = true; // baris DB berhasil dibaca -> state boleh dianggap cerminan DB
    state.telegramBotToken = row.bot_token || "";
    state.telegramChatId = row.chat_id || "";
    state.telegramEnabled = !!row.enabled;
    state.telegramOnlyMarketHours = row.only_market_hours !== false;
    state.telegramPresetIds = Array.isArray(row.preset_ids) ? row.preset_ids.map(String) : [];
    state.telegramLastRunAt = row.last_run_at || null;
    state.telegramLastRunNote = row.last_run_note || null;
    // API key Gemini juga dititipkan di tabel telegram_settings (kolom
    // gemini_api_key/gemini_model) supaya tidak perlu diisi ulang tiap
    // buka aplikasi di device/browser lain — sebelumnya cuma di localStorage.
    if(row.gemini_api_key){
      state.geminiApiKey = row.gemini_api_key;
      try{ localStorage.setItem(LS_GEMINI_API_KEY, state.geminiApiKey); }catch(e){}
    }
    if(row.gemini_model){
      state.geminiModel = row.gemini_model;
      try{ localStorage.setItem(LS_GEMINI_MODEL, state.geminiModel); }catch(e){}
    }
    // API key & Proxy URL Arjum (IDX Edge PRO) -- sama seperti Gemini di atas:
    // ikut disimpan di telegram_settings (kolom arjum_api_key/arjum_proxy_url)
    // supaya tidak hilang saat ganti device/browser. Key: kalau kolom masih
    // kosong (null/""), pakai nilai localStorage lama. Proxy URL boleh sengaja
    // dikosongkan user, jadi string kosong dari DB tetap menimpa (non-null).
    if(row.arjum_api_key){
      state.arjumApiKey = row.arjum_api_key;
      try{ localStorage.setItem(LS_ARJUM_API_KEY, state.arjumApiKey); }catch(e){}
    }
    if(Object.prototype.hasOwnProperty.call(row, "arjum_proxy_url") && row.arjum_proxy_url !== null){
      state.arjumProxyUrl = row.arjum_proxy_url;
      try{ localStorage.setItem(LS_ARJUM_PROXY, state.arjumProxyUrl); }catch(e){}
    }
    // function_url disimpan di Supabase (kolom telegram_settings.function_url)
    // supaya tidak perlu diisi ulang tiap buka Pengaturan di device/browser lain.
    // Kalau kolomnya belum pernah diisi (null), tetap pakai nilai localStorage lama.
    if(row.function_url){
      state.telegramFunctionUrl = row.function_url;
      try{ localStorage.setItem(LS_TELEGRAM_FUNCTION_URL, state.telegramFunctionUrl); }catch(e){}
    }
    // --- Field tambahan (sebelumnya CUMA localStorage, jadi hilang tiap
    // ganti device/browser): kolom Frequency Analyzer, 3 endpoint Stockbit,
    // dan proxy URL Stockbit. Sama seperti gemini_api_key/function_url di
    // atas: kalau kolomnya null (migration belum dijalankan / belum pernah
    // disimpan dari device manapun), biarkan nilai localStorage lama dipakai.
    if(row.freq_analyzer_col){
      state.freqAnalyzerCol = row.freq_analyzer_col;
      try{ localStorage.setItem(LS_FREQ_ANALYZER_COL, state.freqAnalyzerCol); }catch(e){}
    }
    if(row.stockbit_quote_ep){
      state.stockbitQuoteEndpoint = row.stockbit_quote_ep;
      try{ localStorage.setItem(LS_STOCKBIT_QUOTE_EP, state.stockbitQuoteEndpoint); }catch(e){}
    }
    if(row.stockbit_broker_ep){
      state.stockbitBrokerEndpoint = row.stockbit_broker_ep;
      try{ localStorage.setItem(LS_STOCKBIT_BROKER_EP, state.stockbitBrokerEndpoint); }catch(e){}
    }
    if(row.stockbit_broker_activity_ep){
      state.stockbitBrokerActivityEndpoint = row.stockbit_broker_activity_ep;
      try{ localStorage.setItem(LS_STOCKBIT_BROKER_ACTIVITY_EP, state.stockbitBrokerActivityEndpoint); }catch(e){}
    }
    if(row.stockbit_historical_ep){
      state.stockbitHistoricalEndpoint = row.stockbit_historical_ep;
      try{ localStorage.setItem(LS_STOCKBIT_HISTORICAL_EP, state.stockbitHistoricalEndpoint); }catch(e){}
    }
    if(row.stockbit_orderbook_ep){
      state.stockbitOrderbookEndpoint = row.stockbit_orderbook_ep;
      try{ localStorage.setItem(LS_STOCKBIT_ORDERBOOK_EP, state.stockbitOrderbookEndpoint); }catch(e){}
    }
    // Proxy URL boleh sengaja dikosongkan (mis. user hapus proxy), jadi cek
    // key-nya ada di row (bukan cuma truthy) supaya string kosong dari
    // Supabase tetap menimpa nilai localStorage lama, bukan diabaikan.
    if(Object.prototype.hasOwnProperty.call(row, "stockbit_proxy_url") && row.stockbit_proxy_url !== null){
      state.stockbitProxyUrl = row.stockbit_proxy_url;
      try{ localStorage.setItem(LS_STOCKBIT_PROXY, state.stockbitProxyUrl); }catch(e){}
    }
  }catch(e){ /* offline / tabel belum ada — abaikan, form tetap terisi default */ }
}

async function saveTelegramSettingsToSupabase(){
  if(!SUPABASE_URL || !SUPABASE_KEY) return;
  try{
    const tgBody = {
        bot_token: state.telegramBotToken,
        chat_id: state.telegramChatId,
        enabled: state.telegramEnabled,
        only_market_hours: state.telegramOnlyMarketHours,
        preset_ids: state.telegramPresetIds,
        function_url: state.telegramFunctionUrl,
        gemini_api_key: state.geminiApiKey,
        gemini_model: state.geminiModel,
        arjum_api_key: state.arjumApiKey,
        arjum_proxy_url: state.arjumProxyUrl,
        // Field tambahan supaya ikut tersimpan di Supabase (lihat catatan
        // di loadTelegramSettingsFromSupabase() di atas) — tanpa ini,
        // 5 field berikut cuma hidup di localStorage dan hilang tiap
        // pindah device/browser.
        freq_analyzer_col: state.freqAnalyzerCol,
        stockbit_quote_ep: state.stockbitQuoteEndpoint,
        stockbit_broker_ep: state.stockbitBrokerEndpoint,
        stockbit_broker_activity_ep: state.stockbitBrokerActivityEndpoint,
        stockbit_historical_ep: state.stockbitHistoricalEndpoint,
        stockbit_orderbook_ep: state.stockbitOrderbookEndpoint,
        stockbit_proxy_url: state.stockbitProxyUrl,
        updated_at: new Date().toISOString()
      };
    // Kalau isi tabel BELUM berhasil dibaca di sesi ini (fetch gagal / belum
    // selesai), state cuma berisi default kosong -- jangan kirim nilai kosong/
    // false/[] karena itu menimpa token, chat id, preset, dll. yang asli.
    if(!state.telegramSettingsLoaded){
      Object.keys(tgBody).forEach(k => {
        if(k === "updated_at") return;
        const v = tgBody[k];
        if(v === "" || v == null || v === false || (Array.isArray(v) && !v.length)) delete tgBody[k];
      });
    }
    await supaFetch(`${SUPABASE_URL}/telegram_settings?id=eq.1`, {
      method: "PATCH",
      headers: { ...getSupaHeaders(), "Prefer": "return=minimal" },
      body: JSON.stringify(tgBody)
    });
  }catch(e){
    showError("Gagal menyimpan Pengaturan Notifikasi Telegram: " + e.message + " — pastikan sudah menjalankan sql/06_telegram_notifikasi.sql di Supabase.");
  }
}

// Centang/hapus centang 1 preset di daftar "preset yang dipantau" —
// langsung disimpan ke Supabase supaya Edge Function di server melihat
// perubahan ini di cron berikutnya, tidak perlu klik "Simpan & Reload".
function toggleTelegramPreset(id){
  const key = String(id);
  const idx = state.telegramPresetIds.indexOf(key);
  if(idx === -1) state.telegramPresetIds.push(key); else state.telegramPresetIds.splice(idx, 1);
  renderTelegramPresetChecklist();
  saveTelegramSettingsToSupabase();
}

function renderTelegramPresetChecklist(){
  const el = document.getElementById("telegramPresetChecklist");
  if(!el) return;

  // Grup 1: 9 Preset DSI bawaan. Kunci disimpan dengan prefix "dsi:" (mis.
  // "dsi:bagger") supaya Edge Function bisa bedakan dari id Preset Kustom
  // (angka polos, tanpa prefix) — lihat functions/telegram-notifier/index.ts.
  const dsiKeys = Object.keys(PRESET_LABELS);
  const dsiHtml = dsiKeys.map(key => {
    const fullId = `dsi:${key}`;
    return `
    <label style="display:grid;grid-template-columns:16px 1fr;align-items:center;gap:8px;font-size:12.5px;padding:6px 0;cursor:pointer;">
      <input type="checkbox" class="custom-checkbox" style="margin:0;justify-self:start;" ${state.telegramPresetIds.includes(fullId) ? "checked" : ""} onchange="toggleTelegramPreset('${fullId}')">
      <span style="text-align:left;">${escapeHtml(PRESET_LABELS[key])}</span>
    </label>`;
  }).join("");

  // Grup 2: Preset Kustom (id polos angka, TANPA prefix — sama seperti
  // sebelumnya, supaya query custom_presets?id=in.(...) di Edge Function
  // tidak perlu diubah untuk yang ini).
  const customHtml = state.customPresets.length
    ? state.customPresets.map(p => `
      <label style="display:grid;grid-template-columns:16px 1fr;align-items:center;gap:8px;font-size:12.5px;padding:6px 0;cursor:pointer;">
        <input type="checkbox" class="custom-checkbox" style="margin:0;justify-self:start;" ${state.telegramPresetIds.includes(String(p.id)) ? "checked" : ""} onchange="toggleTelegramPreset('${p.id}')">
        <span style="text-align:left;">${escapeHtml(p.name)}</span>
      </label>`).join("")
    : `<div style="font-size:11.5px;color:var(--muted);padding:4px 0;">Belum ada Preset Kustom tersimpan. Buat dulu lewat "+ Tambah Rule" di tab Screener, lalu "💾 Simpan sebagai Preset…".</div>`;

  el.innerHTML = `
    <div style="font-size:10.5px;color:var(--muted);text-transform:uppercase;letter-spacing:.04em;margin-bottom:2px;">Preset DSI Bawaan</div>
    ${dsiHtml}
    <div style="font-size:10.5px;color:var(--muted);text-transform:uppercase;letter-spacing:.04em;margin:10px 0 2px;border-top:1px solid var(--border);padding-top:8px;">Preset Kustom Saya</div>
    ${customHtml}
    ${renderLiveAlertPanelHtml()}
  `;
  wireLiveAlertPanelStatic();
}

// renderLiveAlertPanelHtml — panel "Alert Live (Live Stockbit -> Telegram,
// tanpa nunggu EOD)". Disuntik di sini (bukan lewat index.html, karena file
// itu tidak ikut ter-upload/diedit) supaya tetap muncul di modal Pengaturan
// yang sudah ada tiap kali renderTelegramPresetChecklist() dipanggil (saat
// modal dibuka & tiap kali user centang/hapus centang preset). State-nya
// SEPENUHNYA lokal (LS_LIVE_ALERT_SETTINGS) — lihat catatan panjang di
// dekat evaluateLiveAlerts().
function renderLiveAlertPanelHtml(){
  return `
    <div id="liveAlertPanel" style="margin-top:14px;padding-top:12px;border-top:1px solid var(--border);">
      <div style="font-size:10.5px;color:var(--muted);text-transform:uppercase;letter-spacing:.04em;margin-bottom:6px;">🔴 Alert Live (Stockbit live → Telegram, tidak nunggu EOD)</div>
      <div style="font-size:11.5px;color:var(--muted);margin-bottom:8px;line-height:1.5;">
        Alert ini dikirim LANGSUNG dari browser ini begitu ada tick harga baru dari extension WS Stockbit — beda dari notifikasi Telegram di atas (yang jalan via Cron server, sumbernya data EOD). Konsekuensinya: <b>hanya aktif selama tab ini terbuka</b> & extension menangkap WS Stockbit. Pakai Bot Token / Chat ID yang sama seperti di atas.
      </div>
      <label style="display:flex;align-items:center;gap:8px;font-size:12.5px;margin-bottom:10px;cursor:pointer;">
        <input type="checkbox" id="liveAlertEnabled" class="custom-checkbox" style="margin:0;" ${state.liveAlertEnabled ? "checked" : ""}>
        Aktifkan Alert Live
      </label>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:8px;">
        <label style="font-size:11.5px;color:var(--muted);">Ambang perubahan harga (%)
          <input type="number" id="liveAlertPctThreshold" step="0.1" min="0.1" value="${state.liveAlertPctThreshold}" style="width:100%;margin-top:4px;" class="input">
        </label>
        <label style="font-size:11.5px;color:var(--muted);">Ambang volume spike (x EOD)
          <input type="number" id="liveAlertVolMultiplier" step="0.1" min="1.01" value="${state.liveAlertVolMultiplier}" style="width:100%;margin-top:4px;" class="input">
        </label>
      </div>
      <label style="font-size:11.5px;color:var(--muted);display:block;margin-bottom:8px;">Cooldown per saham+kondisi (menit) — jangan alert ulang sebelum ini lewat
        <input type="number" id="liveAlertCooldownMin" step="1" min="1" value="${state.liveAlertCooldownMin}" style="width:100%;margin-top:4px;" class="input">
      </label>
      <label style="display:flex;align-items:center;gap:8px;font-size:12.5px;margin-bottom:10px;cursor:pointer;">
        <input type="checkbox" id="liveAlertUsePresets" class="custom-checkbox" style="margin:0;" ${state.liveAlertUsePresets ? "checked" : ""}>
        Ikut cek Preset Kustom yang dicentang di atas (preset DSI bawaan belum didukung di jalur live)
      </label>
      <div style="display:flex;align-items:center;gap:10px;">
        <button type="button" class="btn btn-outline" id="testLiveAlertBtn">🧪 Test Alert Live</button>
        <span id="liveAlertTestStatus" style="font-size:11.5px;color:var(--muted);"></span>
      </div>
    </div>
  `;
}

// Semua field panel di atas auto-save ke localStorage tiap kali diubah
// (bukan nunggu tombol "Simpan" utama di modal Pengaturan) — supaya tidak
// ketinggalan tersimpan kalau user cuma menutup modal tanpa klik Simpan,
// dan supaya konsisten dengan pola auto-save toggleTelegramPreset() di atas.
function wireLiveAlertPanelStatic(){
  ["liveAlertEnabled","liveAlertPctThreshold","liveAlertVolMultiplier","liveAlertCooldownMin","liveAlertUsePresets"].forEach(id=>{
    const elx = document.getElementById(id);
    if(elx) elx.onchange = saveLiveAlertSettingsFromUI;
  });
  const btn = document.getElementById("testLiveAlertBtn");
  if(btn) btn.onclick = testLiveAlertNotification;
}

async function testTelegramNotification(){
  const statusEl = document.getElementById("telegramTestStatus");
  const fnUrl = (document.getElementById("setTelegramFunctionUrl")?.value || state.telegramFunctionUrl || "").trim();
  if(!fnUrl){
    if(statusEl){ statusEl.textContent = "Isi dulu \"URL Edge Function\" di bawah."; statusEl.style.color = "var(--down)"; }
    return;
  }
  // Simpan dulu token/chat_id/preset yang sedang diketik supaya Edge
  // Function di server (yang membaca dari Supabase, bukan dari body
  // request ini) memakai nilai terbaru saat mengirim test.
  state.telegramBotToken = tgFieldFromDom("setTelegramBotToken", state.telegramBotToken);
  state.telegramChatId = tgFieldFromDom("setTelegramChatId", state.telegramChatId);
  state.telegramFunctionUrl = fnUrl;
  localStorage.setItem(LS_TELEGRAM_FUNCTION_URL, state.telegramFunctionUrl);
  await saveTelegramSettingsToSupabase();

  state.telegramTesting = true;
  if(statusEl){ statusEl.textContent = "Mengirim test..."; statusEl.style.color = "var(--muted)"; }
  try{
    const res = await fetch(fnUrl, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ test: true }) });
    const body = await res.json().catch(()=>({}));
    if(!res.ok) throw new Error(body.message || `HTTP ${res.status}`);
    if(statusEl){ statusEl.textContent = "✅ Test terkirim — cek chat Telegram kamu."; statusEl.style.color = "var(--up)"; }
  }catch(e){
    if(statusEl){ statusEl.textContent = "❌ Gagal: " + e.message; statusEl.style.color = "var(--down)"; }
  }
  state.telegramTesting = false;
}

