function fmtNum(n){ if(n===null||n===undefined) return "-"; return new Intl.NumberFormat("id-ID").format(n); }
function fmtDateID(iso){ // "2026-08-24" atau timestamp -> "24/08/2026"
  if(!iso) return "-";
  const raw = String(iso).slice(0, 10);
  const [y,m,d] = raw.split("-");
  if(!y||!m||!d || y.length !== 4) return iso;
  return `${d}/${m}/${y}`;
}
// ==========================================
// HARI SEJAK TANGGAL ENTRY — dipakai kolom "Hari" di tab Backtest.
// Dihitung dari tanggal kalender lokal (bukan selisih ms mentah, supaya
// tidak kepengaruh jam/timezone — lihat catatan toLocalISODate di atas).
// Menerima "YYYY-MM-DD"; kalau kosong/tidak valid, return null (dirender "-").
// ==========================================
function daysSinceEntry(entryDateIso){
  if(!entryDateIso) return null;
  const parts = String(entryDateIso).slice(0, 10).split("-").map(Number);
  if(parts.length !== 3 || parts.some(isNaN)) return null;
  const [y,m,d] = parts;
  const entry = new Date(y, m-1, d);
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const diffDays = Math.round((today - entry) / 86400000);
  return diffDays < 0 ? 0 : diffDays;
}
function numOrNull(n){ if(n===null||n===undefined||n==="") return null; const v=parseFloat(n); return isNaN(v) ? null : v; }
function boolLabel(v){
  if(v===true || v==="true" || v==="Ya" || v===1 || v==="1") return "Ya";
  if(v===false || v==="false" || v==="Tidak" || v===0 || v==="0") return "Tidak";
  return v ?? "-";
}
function pillHtml(text, tone){ return `<span class="pill pill-${tone}">${text}</span>`; }
function trendTone(t){
  t = String(t||"");
  if(t.indexOf("Bullish")===0) return "up";
  if(t.indexOf("Bearish")===0) return "down";
  if(t.indexOf("Sideways")===0) return "gold";
  return "muted";
}
function polaTone(p){
  p = String(p||"");
  if(p==="-"||!p) return "muted";
  if(p.indexOf("Bullish")>=0 || p.indexOf("Hammer")===0 || p.indexOf("Inverted Hammer")>=0) return "up";
  if(p.indexOf("Bearish")>=0 || p.indexOf("Shooting Star")>=0 || p.indexOf("Hanging Man")>=0) return "down";
  if(p.indexOf("Doji")>=0) return "gold";
  return "muted";
}
function valuasiTone(v){
  v = String(v||"");
  if(/murah|undervalued/i.test(v)) return "up";
  if(/mahal|overvalued/i.test(v)) return "down";
  if(/wajar|fair/i.test(v)) return "gold";
  return "muted";
}
function rsiGaugeHtml(value){
  if(value===null||value===undefined||isNaN(value)) return `<span class="mono" style="color:var(--muted);font-size:11px;">-</span>`;
  const pct=Math.max(0,Math.min(100,value));
  const angle=(pct/100)*180-90;
  const color = pct<=30 ? "var(--down)" : pct>=70 ? "var(--up)" : "var(--gold)";
  const cx=15+11*Math.sin(angle*Math.PI/180), cy=16-11*Math.cos(angle*Math.PI/180);
  return `<div class="gauge-wrap">
    <svg width="30" height="18" viewBox="0 0 30 18">
      <path d="M2,16 A13,13 0 0 1 28,16" fill="none" stroke="color-mix(in srgb, currentColor 8%, transparent)" stroke-width="3" stroke-linecap="round"/>
      <path d="M2,16 A13,13 0 0 1 28,16" fill="none" stroke="${color}" stroke-width="3" stroke-linecap="round" stroke-dasharray="${(pct/100)*40.8} 40.8"/>
      <circle cx="${cx}" cy="${cy}" r="1.6" fill="${color}" style="filter: drop-shadow(0 0 2px ${color});"/>
    </svg>
    <span class="mono" style="color:${color};font-size:11.5px;font-weight:700;">${value.toFixed(1)}</span>
  </div>`;
}

function loadSettings(){
  try{ const wl=JSON.parse(localStorage.getItem(LS_WATCHLIST)||"[]"); state.watchlist=new Set(wl); }catch(e){}
  try{ state.backtests=JSON.parse(localStorage.getItem(LS_BACKTEST)||"[]"); }catch(e){}
  try{ state.portfolio=JSON.parse(localStorage.getItem(LS_PORTO)||"[]"); }catch(e){}
  try{
    const saved = JSON.parse(localStorage.getItem(LS_VISIBLE_COLS)||"null");
    state.visibleCols = new Set(Array.isArray(saved) ? saved : DEFAULT_VISIBLE_COLS);
  }catch(e){ state.visibleCols = new Set(DEFAULT_VISIBLE_COLS); }
  try{ state.freqAnalyzerCol = localStorage.getItem(LS_FREQ_ANALYZER_COL) || "freq_ma20"; }catch(e){ state.freqAnalyzerCol = "freq_ma20"; }
  state.bsjpParams = loadBsjpParams();
  state.baggerParams = loadBaggerParams();
  try{
    state.stockbitToken = sanitizeStockbitToken(localStorage.getItem(LS_STOCKBIT_TOKEN) || "");
    state.stockbitQuoteEndpoint = localStorage.getItem(LS_STOCKBIT_QUOTE_EP) || STOCKBIT_DEFAULT_QUOTE_EP;
    // Guard: endpoint lama (baik versi marketdetectors dengan {from}/{to}
    // tanpa {date}, MAUPUN versi order-trade/broker/distribution, MAUPUN
    // versi /marketdetectors yang sudah punya {date} tapi belum menyertakan
    // transaction_type/market_board/investor_type) tidak lagi jalan — cek
    // jalan aktual 22 Sep 2026: Stockbit balas 200 "sukses" tapi PAYLOAD
    // KOSONG TOTAL kalau salah satu dari 3 parameter itu tidak ada (lihat
    // catatan panjang di STOCKBIT_DEFAULT_BROKER_EP). Kalau endpoint
    // tersimpan tidak punya {date} ATAU tidak menyertakan ketiganya, paksa
    // balik ke default terverifikasi supaya user lama tidak diam2 kena
    // request yang selalu kosong tanpa pesan error yang jelas.
    const savedBrokerEp = localStorage.getItem(LS_STOCKBIT_BROKER_EP) || "";
    const savedBrokerEpUsable = savedBrokerEp
      && savedBrokerEp.includes("{date}")
      && /transaction_type/i.test(savedBrokerEp)
      && /market_board/i.test(savedBrokerEp)
      && /investor_type/i.test(savedBrokerEp);
    state.stockbitBrokerEndpoint = savedBrokerEpUsable ? savedBrokerEp : STOCKBIT_DEFAULT_BROKER_EP;
    state.stockbitHistoricalEndpoint = localStorage.getItem(LS_STOCKBIT_HISTORICAL_EP) || STOCKBIT_DEFAULT_HISTORICAL_EP;
    state.stockbitInsiderEndpoint = localStorage.getItem(LS_STOCKBIT_INSIDER_EP) || STOCKBIT_DEFAULT_INSIDER_EP;
    state.stockbitOrderbookEndpoint = localStorage.getItem(LS_STOCKBIT_ORDERBOOK_EP) || STOCKBIT_DEFAULT_ORDERBOOK_EP;
    // Guard sama seperti Broker Summary di atas: kalau endpoint tersimpan
    // tidak punya {broker_code}/{date} ATAU tidak menyertakan ketiga
    // parameter wajib, paksa balik ke default supaya tidak diam2 gagal.
    const savedBrokerActivityEp = localStorage.getItem(LS_STOCKBIT_BROKER_ACTIVITY_EP) || "";
    const savedBrokerActivityEpUsable = savedBrokerActivityEp
      && savedBrokerActivityEp.includes("{broker_code}")
      && savedBrokerActivityEp.includes("{date}")
      && /transaction_type/i.test(savedBrokerActivityEp)
      && /market_board/i.test(savedBrokerActivityEp)
      && /investor_type/i.test(savedBrokerActivityEp);
    state.stockbitBrokerActivityEndpoint = savedBrokerActivityEpUsable ? savedBrokerActivityEp : STOCKBIT_DEFAULT_BROKER_ACTIVITY_EP;
    state.stockbitProxyUrl = localStorage.getItem(LS_STOCKBIT_PROXY) || "";
    const savedSrc = localStorage.getItem(LS_STOCKBIT_TOKEN_SOURCE);
    if(savedSrc === "extension" || savedSrc === "manual") state.stockbitTokenSource = savedSrc;
    const savedSyncedAt = parseInt(localStorage.getItem(LS_STOCKBIT_TOKEN_SYNCED_AT), 10);
    if(Number.isFinite(savedSyncedAt)) state.stockbitTokenSyncedAt = savedSyncedAt;
  }catch(e){}
  try{
    state.stockbitAutoRefresh = localStorage.getItem(LS_STOCKBIT_AUTOREFRESH) === "1";
    const savedSec = parseInt(localStorage.getItem(LS_STOCKBIT_AUTOREFRESH_SEC), 10);
    state.stockbitAutoRefreshIntervalSec = (Number.isFinite(savedSec) && savedSec >= STOCKBIT_AUTOREFRESH_MIN_SEC) ? savedSec : 60;
  }catch(e){}
  try{
    const savedRules = JSON.parse(localStorage.getItem(LS_CUSTOM_RULES)||"[]");
    state.customRules = Array.isArray(savedRules) ? savedRules : [];
  }catch(e){ state.customRules = []; }
  try{ state.telegramFunctionUrl = localStorage.getItem(LS_TELEGRAM_FUNCTION_URL) || ""; }catch(e){}
  try{
    const savedTp = parseFloat(localStorage.getItem(LS_BACKTEST_TARGET_TP));
    state.backtestTargetTpPct = Number.isFinite(savedTp) && savedTp > 0 ? savedTp : 5;
    const savedMode = localStorage.getItem(LS_BACKTEST_TP_MODE);
    state.backtestTpMode = savedMode === "auto" ? "auto" : "percent";
  }catch(e){ state.backtestTargetTpPct = 5; state.backtestTpMode = "percent"; }
  try{
    state.geminiApiKey = localStorage.getItem(LS_GEMINI_API_KEY) || "";
    state.geminiModel = localStorage.getItem(LS_GEMINI_MODEL) || GEMINI_DEFAULT_MODEL;
  }catch(e){}
  try{
    state.arjumApiKey = localStorage.getItem(LS_ARJUM_API_KEY) || "";
    state.arjumProxyUrl = localStorage.getItem(LS_ARJUM_PROXY) || "";
  }catch(e){}
  try{
    const savedFeeBeli = parseFloat(localStorage.getItem(LS_FEE_BELI_DEFAULT));
    state.feeBeliDefaultPct = Number.isFinite(savedFeeBeli) && savedFeeBeli >= 0 ? savedFeeBeli : FEE_BELI_DEFAULT_PCT;
    const savedFeeJual = parseFloat(localStorage.getItem(LS_FEE_JUAL_DEFAULT));
    state.feeJualDefaultPct = Number.isFinite(savedFeeJual) && savedFeeJual >= 0 ? savedFeeJual : FEE_JUAL_DEFAULT_PCT;
  }catch(e){ state.feeBeliDefaultPct = FEE_BELI_DEFAULT_PCT; state.feeJualDefaultPct = FEE_JUAL_DEFAULT_PCT; }
  loadFibScanCache();
  loadBsScanFilters();
  loadBsTrapFilters();
  loadLiveAlertSettings(); // function declaration di-hoist, aman dipanggil di sini walau definisinya jauh di bawah (dekat handleLiveTick)
}
function saveVisibleCols(){ localStorage.setItem(LS_VISIBLE_COLS, JSON.stringify([...state.visibleCols])); }
function toggleColumn(key){
  if(state.visibleCols.has(key)) state.visibleCols.delete(key); else state.visibleCols.add(key);
  saveVisibleCols(); render();
}
function setColumnPreset(preset){
  if(preset === "ringkas") state.visibleCols = new Set(DEFAULT_VISIBLE_COLS);
  else if(preset === "semua") state.visibleCols = new Set(SCREENER_COLUMNS.map(c=>c.key));
  else if(preset === "kosong") state.visibleCols = new Set();
  saveVisibleCols(); render();
}
function saveWatchlist(){ localStorage.setItem(LS_WATCHLIST, JSON.stringify([...state.watchlist])); }
function saveBacktests(){ localStorage.setItem(LS_BACKTEST, JSON.stringify(state.backtests)); }
function savePortoLocal(){ localStorage.setItem(LS_PORTO, JSON.stringify(state.portfolio)); }

function bandarmologi(row, ratio){
  if(ratio===null || ratio===undefined || isNaN(ratio)) return {label:"-", tone:"muted"};
  const naik = row.cClose>row.cOpen;
  if(ratio>=1.5 && naik) return {label:"Indikasi Akumulasi", tone:"up"};
  if(ratio>=1.5 && !naik) return {label:"Indikasi Distribusi", tone:"down"};
  if(ratio>=1.0 && naik) return {label:"Minat Beli Naik", tone:"up"};
  if(ratio>=1.0 && !naik) return {label:"Tekanan Jual", tone:"down"};
  return {label:"Netral", tone:"muted"};
}
function volumeSignal(row, ratio){
  if(ratio===null || ratio===undefined || isNaN(ratio)) return { ratio:null, label:"-", tone:"muted" };
  let label, tone;
  if(ratio>=2)      { label="Sangat Tinggi"; tone="up"; }
  else if(ratio>=1.5){ label="Tinggi"; tone="up"; }
  else if(ratio>=0.8){ label="Normal"; tone="muted"; }
  else               { label="Rendah"; tone="down"; }
  return { ratio, label, tone };
}
// ==========================================
// FREQUENCY ANALYZER (mirip kolom "Frequency" di screener Stockbit)
//
// "Frekuensi" = jumlah transaksi (kali matched) suatu saham dalam sehari —
// beda dari Volume (jumlah lembar/lot). Frekuensi tinggi dengan volume
// relatif kecil sering menandakan banyak investor ritel aktif keluar-masuk
// (bukan satu order besar), jadi dianalisis terpisah dari Volume.
//
// Rasio dihitung dari `frequency / freqAnalyzer` kalau backend sudah mengirim
// rata-rata 20 hari (freq_ma20); kalau kolom itu belum ada di skema DB,
// ratio-nya null dan UI menampilkan "-" (bukan 0) — sama seperti pola
// avgVolume3m/vol_ma20 di atas.
// ==========================================
function frequencySignal(ratio){
  if(ratio===null || ratio===undefined || isNaN(ratio)) return { ratio:null, label:"-", tone:"muted" };
  let label, tone;
  if(ratio>=2.5)      { label="Sangat Ramai"; tone="up"; }
  else if(ratio>=1.5) { label="Ramai"; tone="up"; }
  else if(ratio>=0.7) { label="Normal"; tone="muted"; }
  else                { label="Sepi"; tone="down"; }
  return { ratio, label, tone };
}
function keyakinanNaik(row, vol){
  let score=0;
  if(row.cekHarga && row.cekHarga.includes("crossup")) score+=25;
  else if(row.cekHarga && row.cekHarga.includes("diatas ema 21 L")) score+=10;
  if(row.cekRsi && row.cekRsi.includes("cross up")) score+=20;
  if(row.statusRsi==="bullish") score+=15;
  else if(row.statusRsi==="netral") score+=5;
  if(row.cekMacd && (row.cekMacd.includes("Buy")||row.cekMacd.includes("Bullish"))) score+=25;
  if((vol.label==="Tinggi"||vol.label==="Sangat Tinggi") && row.cClose>row.cOpen) score+=15;
  score = Math.min(100, score);
  let label, tone;
  if(score>=70)      { label="Tinggi"; tone="up"; }
  else if(score>=40) { label="Sedang"; tone="gold"; }
  else                { label="Rendah"; tone="down"; }
  return { score, label, tone };
}
function keyakinanToneFromLabel(label){
  const l = String(label||"");
  if(/^Sangat Tinggi|^Tinggi/.test(l)) return "up";
  if(/^Sedang/.test(l)) return "gold";
  if(/^Waspada|^Sangat Waspada/.test(l)) return "down";
  if(/^Rendah/.test(l)) return "down";
  return "muted";
}

// ==========================================
// SKOR BAGGER — implementasi persis dari formula_screening_saham_bagger.md
//
// Composite score 0-100 = Fundamental (40) + Momentum Teknikal (35) +
// Volume/Smart Money (25). Tiap sub-kriteria pass/fail sesuai section 2
// file .md tsb (tidak ada nilai parsial), supaya hasilnya bisa diaudit
// satu-satu lewat breakdown di Detail Emiten > tab Analisa.
//
// ≥75 = kandidat kuat, 50-74 = menarik tunggu konfirmasi, <50 = skip.
// Red flag (section 4 file .md) dihitung terpisah dari skor — dipakai
// sebagai peringatan tambahan, bukan pengurang skor.
// ==========================================
function computeBaggerScore(s, params){
  const p = params || state.baggerParams || BAGGER_DEFAULT_PARAMS;
  const num = v => (v===null || v===undefined || v==="" || isNaN(v)) ? null : Number(v);
  const rsi14 = num(s.rsi14);
  const rsiCrossUp = String(s.cekRsi||"").toLowerCase().includes("cross up");

  // Label ikut menampilkan angka yang SEDANG dipakai (bukan teks statis
  // "15%" dst) — supaya breakdown di Detail Emiten selalu jujur soal
  // threshold mana yang benar-benar dievaluasi, termasuk kalau user sudah
  // mengubahnya lewat panel Kustomisasi Skor Bagger.
  const fundItems = [
    { label:`Revenue Growth > ${p.revGrowthMin}%`, pass: num(s.revenueGrowth) > p.revGrowthMin, points:p.revGrowthPts },
    { label:`Earnings Growth > ${p.earnGrowthMin}%`, pass: num(s.earningsGrowth) > p.earnGrowthMin, points:p.earnGrowthPts },
    { label:`ROE > ${p.roeMin}%`, pass: num(s.roe) > p.roeMin, points:p.roePts },
    { label:`DER < ${p.derMax}`, pass: num(s.der) != null && num(s.der) < p.derMax, points:p.derPts },
    { label:`PEG < ${p.pegMax}`, pass: num(s.peg) != null && num(s.peg) > 0 && num(s.peg) < p.pegMax, points:p.pegPts },
  ];

  const momItems = [
    { label:`RSI7 cross up RSI21 (RSI14 < ${p.rsiCrossMax})`, pass: rsiCrossUp && rsi14 != null && rsi14 < p.rsiCrossMax, points:p.rsiCrossPts },
    { label:"MACD Histogram negatif → positif", pass: num(s.prevMacdHist) != null && num(s.hist) != null && num(s.prevMacdHist) <= 0 && num(s.hist) > 0, points:p.macdCrossPts },
    { label:"Harga > MA21 > MA50 > MA200", pass: [s.cClose,s.ma21,s.ma50,s.ma200].every(v=>v!=null) && s.cClose > s.ma21 && s.ma21 > s.ma50 && s.ma50 > s.ma200, points:p.maStackPts },
    { label:`Stoch K cross up Stoch D dari oversold (≤${p.stochOversoldMax})`, pass: [s.prevStochK,s.prevStochD,s.stochK,s.stochD].every(v=>v!=null) && s.prevStochK < s.prevStochD && s.stochK > s.stochD && s.prevStochK <= p.stochOversoldMax, points:p.stochPts },
  ];

  const volItems = [
    { label:`Volume Ratio > ${p.volRatioMin}x`, pass: num(s.volRatio) > p.volRatioMin, points:p.volRatioPts },
    { label:`Foreign Net 5D > 0 & Hari Asing+ ≥ ${p.foreignDaysMin}`, pass: num(s.foreignNet5D) > 0 && num(s.foreignUpDays) >= p.foreignDaysMin, points:p.foreignPts },
    { label:"BB Squeeze lalu breakout EMA21 H", pass: String(s.isBBSqueeze||"").includes("Ya") && s.cClose != null && s.ema21H != null && s.cClose > s.ema21H, points:p.bbSqueezePts },
  ];

  const sum = items => items.reduce((a,i)=> a + (i.pass ? i.points : 0), 0);
  const maxOf = items => items.reduce((a,i)=> a + i.points, 0);
  const fundScore = sum(fundItems), momScore = sum(momItems), volScore = sum(volItems);
  const maxFund = maxOf(fundItems), maxMom = maxOf(momItems), maxVol = maxOf(volItems);
  const total = fundScore + momScore + volScore;
  // maxTotal DIHITUNG dari poin yang sedang dikonfigurasi (bukan hardcode
  // 100) — kalau user mengubah bobot kriteria, "X/maxTotal" di semua
  // tampilan tetap akurat mencerminkan skor maksimum yang bisa dicapai.
  const maxTotal = maxFund + maxMom + maxVol;

  let tier, tone;
  if (total >= p.strongCutoff) { tier = "Kandidat Kuat"; tone = "up"; }
  else if (total >= p.watchCutoff) { tier = "Menarik, Tunggu Konfirmasi"; tone = "gold"; }
  else { tier = "Skip"; tone = "down"; }

  // Red flag — section 4 formula.md
  const flags = [];
  if (String(s.valuasi||"").includes("Kemahalan") && rsi14 != null && rsi14 > 80) {
    flags.push("Valuasi Overvalued + RSI14 > 80 → rawan profit taking, hati-hati entry baru (pola ini persis kasus AADI di contoh formula).");
  }
  const der = num(s.der), currentRatio = num(s.currentRatio);
  if (der != null && der > 1 && currentRatio != null && currentRatio < 1) {
    flags.push("DER tinggi (>1) & Current Ratio < 1 → risiko keuangan, gain teknikal bisa berbalik cepat kalau ada bad news.");
  }
  const fn5 = num(s.foreignNet5D), fn20 = num(s.foreignNet20D);
  if (num(s.volRatio) > 1.5 && fn5 != null && fn5 < 0 && fn20 != null && fn20 < 0) {
    flags.push("Volume breakout tapi Net Asing negatif terus → kemungkinan cuma ritel/bandar lokal, lebih rawan distribusi.");
  }
  const pola = String(s.polaCandle||"");
  if (/bearish|shooting star|hanging man/i.test(pola) && s.resistance != null && s.cClose != null && s.cClose >= s.resistance*0.98) {
    flags.push("Pola candle bearish reversal di area resisten kuat → tunda entry meski skor fundamental tinggi.");
  }

  return { total, maxTotal, fundScore, maxFund, momScore, maxMom, volScore, maxVol, fundItems, momItems, volItems, tier, tone, flags };
}

// Panel "⚙️ Kustomisasi Skor Bagger" — pola input sama seperti paramField()
// di panel Parameter BSJP: satu <input type="number" data-bagger-param="key">
// per angka, langsung nulis ke state.baggerParams saat berubah (wiring di
// attachContentEvents). Dikelompokkan per section formula (Fundamental/
// Momentum/Volume/Tier) supaya tetap mudah diaudit sumber tiap angkanya.
function renderBaggerParamsPanel(){
  const p = state.baggerParams;
  const field = (key, label, step) => `<div class="field" style="min-width:150px;"><label style="font-size:10.5px;">${label}</label><input type="number" step="${step||1}" data-bagger-param="${key}" value="${p[key]}"></div>`;
  const groupTotal = (...pts) => pts.reduce((a,k)=>a+(Number(p[k])||0),0);
  const groupRow = (title, totalPts, fields) => `
    <div style="margin-bottom:14px;">
      <div style="font-size:11px;font-weight:700;color:var(--text);margin-bottom:8px;">${title} <span style="color:var(--muted);font-weight:500;">— total poin saat ini: <b class="mono">${totalPts}</b></span></div>
      <div style="display:flex;flex-wrap:wrap;gap:10px;">${fields}</div>
    </div>`;

  return `
    <div style="font-size:11.5px;color:var(--muted);line-height:1.6;margin-bottom:14px;">
      Semua angka ambang batas & bobot poin di formula Skor Bagger bisa diubah di sini. Skor maksimum total (
      <span class="mono">/${groupTotal("revGrowthPts","earnGrowthPts","roePts","derPts","pegPts","rsiCrossPts","macdCrossPts","maStackPts","stochPts","volRatioPts","foreignPts","bbSqueezePts")}</span>
      ) mengikuti jumlah poin yang kamu atur — tidak dipaksa selalu 100. Disimpan otomatis ke browser ini (localStorage), berlaku untuk semua saham begitu diubah.
    </div>

    ${groupRow("💰 Fundamental", groupTotal("revGrowthPts","earnGrowthPts","roePts","derPts","pegPts"), `
      ${field("revGrowthMin","Revenue Growth min (%)",1)} ${field("revGrowthPts","→ Poin",1)}
      ${field("earnGrowthMin","Earnings Growth min (%)",1)} ${field("earnGrowthPts","→ Poin",1)}
      ${field("roeMin","ROE min (%)",1)} ${field("roePts","→ Poin",1)}
      ${field("derMax","DER maks",0.1)} ${field("derPts","→ Poin",1)}
      ${field("pegMax","PEG maks",0.1)} ${field("pegPts","→ Poin",1)}
    `)}

    ${groupRow("📊 Momentum Teknikal", groupTotal("rsiCrossPts","macdCrossPts","maStackPts","stochPts"), `
      ${field("rsiCrossMax","RSI14 maks saat RSI7 cross up RSI21",1)} ${field("rsiCrossPts","→ Poin",1)}
      ${field("macdCrossPts","Poin: MACD Hist neg→pos (tanpa angka ambang)",1)}
      ${field("maStackPts","Poin: Harga&gt;MA21&gt;MA50&gt;MA200 (tanpa angka ambang)",1)}
      ${field("stochOversoldMax","Batas oversold Stoch K/D saat cross up",1)} ${field("stochPts","→ Poin",1)}
    `)}

    ${groupRow("🐋 Volume/Smart Money", groupTotal("volRatioPts","foreignPts","bbSqueezePts"), `
      ${field("volRatioMin","Volume Ratio min (x)",0.1)} ${field("volRatioPts","→ Poin",1)}
      ${field("foreignDaysMin","Min hari Net Asing+ (dari 5D)",1)} ${field("foreignPts","→ Poin",1)}
      ${field("bbSqueezePts","Poin: BB Squeeze breakout EMA21 H (tanpa angka ambang)",1)}
    `)}

    <div style="margin-bottom:4px;">
      <div style="font-size:11px;font-weight:700;color:var(--text);margin-bottom:8px;">🏁 Cutoff Tier</div>
      <div style="display:flex;flex-wrap:wrap;gap:10px;">
        ${field("strongCutoff","Skor min \u2192 \"Kandidat Kuat\"",1)}
        ${field("watchCutoff","Skor min \u2192 \"Menarik, Tunggu Konfirmasi\"",1)}
      </div>
    </div>

    <div style="margin-top:12px;"><button class="btn btn-outline" id="baggerResetParamsBtn">↺ Kembalikan ke Default Formula</button></div>
  `;
}

// ==========================================
// TAB MANDIRI "🎯 Skor Bagger" (state.tab === "bagger")
//
// Sebelumnya panel Kustomisasi Skor Bagger cuma "diselipkan" 2 lapis di
// dalam tab Screener (Filter & Screener > adv-toggle Kustomisasi). Sekarang
// dipindah jadi halaman sendiri di menu samping supaya lebih gampang
// ditemukan & tidak numpuk sama filter-filter lain. Halaman ini punya:
//   1) Ringkasan jumlah saham per tier (Kandidat Kuat / Menarik / Skip)
//   2) Panel Kustomisasi formula (persis renderBaggerParamsPanel() lama,
//      cuma pindah lokasi — id "baggerParamsPanel" & wiring toggle-nya
//      TETAP SAMA, jadi tidak perlu wiring baru)
//   3) Leaderboard semua saham terurut Skor Bagger tertinggi -> terendah,
//      dengan search & filter tier sendiri (state.baggerSearch/
//      baggerTierFilter/baggerPage) supaya tidak bentrok dengan state
//      pencarian & pagination punya tab Screener.
// ==========================================
function renderSkorBagger(){
  const list = enriched();
  const p = state.baggerParams;

  const q = (state.baggerSearch || "").trim().toUpperCase();
  const tierFilter = state.baggerTierFilter || "all";

  let data = list;
  if(q) data = data.filter(s => String(s.ticker||"").toUpperCase().includes(q) || String(s.name||"").toUpperCase().includes(q));
  if(tierFilter === "strong") data = data.filter(s => (s.baggerScoreTotal||0) >= p.strongCutoff);
  else if(tierFilter === "watch") data = data.filter(s => (s.baggerScoreTotal||0) >= p.watchCutoff && (s.baggerScoreTotal||0) < p.strongCutoff);
  else if(tierFilter === "skip") data = data.filter(s => (s.baggerScoreTotal||0) < p.watchCutoff);
  data = [...data].sort((a,b) => (b.baggerScoreTotal||0) - (a.baggerScoreTotal||0)); // default: skor tertinggi dulu
  // Sort per kolom (opsional) lewat header yang bisa diklik -- infrastruktur
  // generik yang sama dengan tabel Screener utama/Portofolio/dll (lihat
  // tableSortTh/tableSortRows/getTableUI di dekat awal file). Kalau user
  // belum klik header manapun, urutan default skor tertinggi di atas tetap
  // dipakai (tableSortRows tidak mengubah apa-apa kalau ui.sortCol kosong).
  data = tableSortRows("baggerLeaderboard", data, {
    ticker: s=>s.ticker, name: s=>s.name, sektor: s=>s.sektor,
    harga: s=>s.cClose, chg: s=>s.changePct,
    score: s=>s.baggerScoreTotal, tier: s=>s.baggerTier,
  });

  const nStrong = list.filter(s => (s.baggerScoreTotal||0) >= p.strongCutoff).length;
  const nWatch = list.filter(s => (s.baggerScoreTotal||0) >= p.watchCutoff && (s.baggerScoreTotal||0) < p.strongCutoff).length;
  const nSkip = list.length - nStrong - nWatch;
  const avgScore = list.length ? (list.reduce((a,s)=>a+(Number(s.baggerScoreTotal)||0),0) / list.length) : 0;

  const effectiveLimit = state.baggerLimit === "all" ? Math.max(data.length, 1) : (state.baggerLimit || 25);
  const totalPages = Math.ceil(data.length / effectiveLimit) || 1;
  if(state.baggerPage > totalPages) state.baggerPage = totalPages;
  if(!state.baggerPage) state.baggerPage = 1;
  const startIdx = (state.baggerPage - 1) * effectiveLimit;
  const paged = data.slice(startIdx, startIdx + effectiveLimit);

  const tierBtn = (key, label, tone) => `<button type="button" class="pill ${tierFilter===key ? 'pill-'+tone : 'pill-muted'}" data-bagger-tier="${key}">${label}</button>`;

  registerTableExport("baggerLeaderboard", () => data, [
    { label: "Ticker", get: "ticker" }, { label: "Nama", get: s=>s.name||"-" }, { label: "Sektor", get: s=>s.sektor||"-" },
    { label: "Harga", get: s=>Math.round(s.cClose||0) },
    { label: "Perubahan (%)", get: s=>Math.round((s.changePct||0)*100)/100 },
    { label: "Skor Bagger", get: s=>s.baggerScoreTotal }, { label: "Skor Maks", get: s=>s.baggerScoreMax },
    { label: "Tier", get: "baggerTier" },
  ], "Leaderboard_Skor_Bagger");

  const rows = paged.map(s => `
    <tr>
      <td class="ticker-cell"><button class="ticker-link" data-detail="${escapeHtml(s.ticker)}" title="Lihat detail ${escapeHtml(s.ticker)}">${escapeHtml(s.ticker)}</button>${s.uangGedeMasuk==="Ya" ? ' <span title="Indikasi uang gede masuk">💰</span>' : ''}</td>
      <td>${escapeHtml(s.name||"-")}</td>
      <td>${escapeHtml(s.sektor||"-")}</td>
      <td class="mono">${dNum(s.cClose)}</td>
      <td class="mono" style="color:${(s.changePct||0)>=0 ? 'var(--up)' : 'var(--down)'};">${dNum(s.changePct,{plusSign:true,decimals:2,suffix:'%'})}</td>
      <td class="mono" style="font-weight:800;font-size:13.5px;color:var(--${s.baggerTone});">${s.baggerScoreTotal}<span style="font-size:10px;font-weight:500;color:var(--muted);"> /${s.baggerScoreMax}</span></td>
      <td>${pillHtml(s.baggerTier, s.baggerTone)}</td>
      <td><button type="button" class="btn btn-outline" data-detail="${escapeHtml(s.ticker)}" style="font-size:11px;padding:4px 10px;">Detail</button></td>
    </tr>`).join("");

  return `
    <div class="panel" style="flex-direction:column;align-items:stretch;margin-bottom:16px;">
      <div class="filter-section-title" style="margin-bottom:6px;">🎯 Skor Bagger — Formula Multibagger</div>
      <div style="font-size:12px;color:var(--muted);line-height:1.55;margin-bottom:12px;">
        Skor komposit dari <i>formula_screening_saham_bagger.md</i>: Fundamental + Momentum Teknikal + Volume/Smart Money. Semua ambang batas &amp; bobot poin bisa diatur di panel Kustomisasi di bawah, tersimpan otomatis ke browser ini.
      </div>
      <div class="summary-grid">
        <button type="button" class="summary-card dash-card" data-dash-metric="total" title="Klik untuk lihat detail"><div class="summary-lbl">Total Emiten</div><div class="summary-val">${list.length}</div></button>
        <button type="button" class="summary-card tone-up dash-card" data-dash-metric="bagger_strong" title="Klik untuk lihat detail"><div class="summary-lbl">Kandidat Kuat (≥${p.strongCutoff})</div><div class="summary-val">${nStrong}</div></button>
        <button type="button" class="summary-card tone-gold dash-card" data-dash-metric="bagger_watch" title="Klik untuk lihat detail"><div class="summary-lbl">Menarik (${p.watchCutoff}–${p.strongCutoff-1})</div><div class="summary-val">${nWatch}</div></button>
        <button type="button" class="summary-card tone-down dash-card" data-dash-metric="bagger_skip" title="Klik untuk lihat detail"><div class="summary-lbl">Skip (&lt;${p.watchCutoff})</div><div class="summary-val">${nSkip}</div></button>
        <button type="button" class="summary-card dash-card" data-dash-metric="bagger_avg" title="Klik untuk lihat detail"><div class="summary-lbl">Rata-rata Skor</div><div class="summary-val">${avgScore.toFixed(1)}</div></button>
      </div>
    </div>

    <div class="panel" style="flex-direction:column;align-items:stretch;margin-bottom:16px;">
      <div class="filter-section" id="baggerParamsPanel" style="border:none;padding:0;">
        <button type="button" class="adv-toggle ${state.showFilterKustomBagger ? 'open' : ''}" id="filterKustomBaggerToggleBtn">
          <span class="chev">▶</span> ⚙️ Kustomisasi Formula (poin &amp; threshold)
        </button>
        <div class="adv-body ${state.showFilterKustomBagger ? 'open' : ''}">
          ${renderBaggerParamsPanel()}
        </div>
      </div>
    </div>

    <div class="panel" style="flex-direction:column;align-items:stretch;">
      <div class="filter-section-title" style="margin-bottom:10px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;">
        <span>📋 Leaderboard Skor Bagger</span>
        ${tableExportBtnHtml("baggerLeaderboard")}
      </div>
      <div class="filter-toolbar" style="margin-bottom:12px;">
        <div class="field" style="min-width:220px;flex:1 1 260px;">
          <label>Cari Ticker / Nama</label>
          <input type="text" id="baggerSearchInput" placeholder="mis. BBCA" value="${escapeHtml(state.baggerSearch||'')}">
        </div>
        <div class="field">
          <label>Tier</label>
          <div style="display:flex;gap:8px;flex-wrap:wrap;">
            ${tierBtn("all","Semua","up")}
            ${tierBtn("strong","Kandidat Kuat","up")}
            ${tierBtn("watch","Menarik","gold")}
            ${tierBtn("skip","Skip","down")}
          </div>
        </div>
        <div class="field">
          <label>Tampilkan</label>
          <select id="baggerLimitSelect">
            ${PAGE_SIZE_OPTIONS.map(n=>`<option value="${n}" ${String(state.baggerLimit)===String(n)?'selected':''}>${n}</option>`).join("")}
            <option value="all" ${state.baggerLimit==="all"?'selected':''}>Semua</option>
          </select>
        </div>
      </div>
      <div class="table-wrap">
        <table class="data-table">
          <thead><tr>${tableSortTh("baggerLeaderboard","Ticker","ticker")}${tableSortTh("baggerLeaderboard","Nama","name")}${tableSortTh("baggerLeaderboard","Sektor","sektor")}${tableSortTh("baggerLeaderboard","Harga","harga")}${tableSortTh("baggerLeaderboard","Perubahan","chg")}${tableSortTh("baggerLeaderboard","Skor Bagger","score")}${tableSortTh("baggerLeaderboard","Tier","tier")}<th></th></tr></thead>
          <tbody>${rows || `<tr><td colspan="8"><div class="empty-box">Tidak ada emiten yang cocok.</div></td></tr>`}</tbody>
        </table>
      </div>
      <div class="pagination" style="margin-top:12px;">
        <button class="btn btn-outline" id="baggerPrevPage" ${state.baggerPage <= 1 ? 'disabled' : ''}>&laquo; Prev</button>
        <span style="font-size:12px;color:var(--text);font-weight:500;">Halaman <b style="color:var(--gold)">${state.baggerPage}</b> dari ${totalPages} (${data.length} emiten)</span>
        <button class="btn btn-outline" id="baggerNextPage" ${state.baggerPage >= totalPages ? 'disabled' : ''}>Next &raquo;</button>
      </div>
    </div>`;
}

// ==========================================
// SKOR GABUNGAN (Fundamental 0–60 + Teknikal 0–40)
//
// Screener publik acuan menampilkan skor gabungan dengan struktur
// "Fundamental X/60 · Teknikal Y/40" tetapi tidak mempublikasikan rumus
// pastinya. Versi di bawah adalah rekonstruksi TRANSPARAN: tiap
// sub-kriteria punya poin tetap & bisa dilihat breakdown-nya di UI.
// Kriteria fundamental dipinjam dari preset Deep Value/Multibagger/Growth
// yang terlihat publik; teknikal dari indikator standar yang sudah ada
// di DB (trend MA, MACD hist, RSI, stoch, posisi 52W).
// Null diperlakukan netral (poin tidak didapat, bukan didiskon ekstra).
// ==========================================
function computeFundTekScore(s){
  const num = v => (v===null || v===undefined || v==="" || isNaN(v)) ? null : Number(v);
  const per = num(s.per), pbv = num(s.pbv), roe = num(s.roe), der = num(s.der);
  const npm = num(s.npm), roa = num(s.roa);
  const revG = num(s.revenueGrowth), earnG = num(s.earningsGrowth);
  const divY = num(s.divYield);

  // --- Fundamental 60 poin ---
  // Setiap kelompok memakai tier yang saling eksklusif. Bobot maksimum:
  // ROE 15 + NPM 10 + DER 10 + PER 8 + PBV 5 + ROA 4 + Growth 4 + Dividen 4 = 60.
  const fundItems = [
    { label:"ROE ≥ 15%", pass: roe != null && roe >= 15, points:15 },
    { label:"ROE 8–15%", pass: roe != null && roe >= 8 && roe < 15, points:8 },
    { label:"NPM ≥ 10%", pass: npm != null && npm >= 10, points:10 },
    { label:"NPM 5–10%", pass: npm != null && npm >= 5 && npm < 10, points:5 },
    { label:"DER ≤ 1", pass: der != null && der <= 1, points:10 },
    { label:"DER 1–2", pass: der != null && der > 1 && der <= 2, points:5 },
    { label:"PER ≤ 15 & > 0", pass: per != null && per > 0 && per <= 15, points:8 },
    { label:"PER 15–25", pass: per != null && per > 15 && per <= 25, points:4 },
    { label:"PBV ≤ 1.5 & > 0", pass: pbv != null && pbv > 0 && pbv <= 1.5, points:5 },
    { label:"ROA ≥ 5%", pass: roa != null && roa >= 5, points:4 },
    { label:"Revenue Growth > 10%", pass: revG != null && revG > 10, points:2 },
    { label:"Earnings Growth > 10%", pass: earnG != null && earnG > 10, points:2 },
    { label:"Dividend Yield ≥ 2%", pass: divY != null && divY >= 2, points:4 },
  ];

  // --- Teknikal 40 poin ---
  const trendBull = String(s.trendHarga||"").indexOf("Bullish") === 0;
  const macdUp = num(s.prevMacdHist) != null && num(s.hist) != null && num(s.prevMacdHist) <= 0 && num(s.hist) > 0;
  const macdPos = num(s.hist) != null && num(s.hist) > 0;
  const rsiSehat = num(s.rsi7) != null && num(s.rsi7) >= 50 && num(s.rsi7) <= 75;
  const stochCross = [s.prevStochK,s.prevStochD,s.stochK,s.stochD].every(v=>v!=null) && s.prevStochK < s.prevStochD && s.stochK > s.stochD;
  const pos52 = num(s.pos52w) ?? spPos52w(s);
  const priceVsMa50 = s.cClose != null && num(s.ma50) != null ? s.cClose > num(s.ma50) : null;

  const techItems = [
    { label:"Trend Bullish (MA)", pass: trendBull, points:10 },
    { label:"MACD Histogram positif", pass: macdPos, points:5 },
    { label:"MACD cross up (neg → pos)", pass: macdUp, points:5 },
    { label:"RSI 7 di 50–75", pass: rsiSehat, points:5 },
    { label:"Stoch K cross up D", pass: stochCross, points:5 },
    { label:"Harga > MA50", pass: priceVsMa50 === true, points:5 },
    { label:"Posisi 52W ≤ 60%", pass: pos52 != null && pos52 <= 60, points:5 },
  ];

  const sum = items => items.reduce((a,i)=> a + (i.pass ? i.points : 0), 0);
  const fund = Math.min(60, sum(fundItems));
  const tech = Math.min(40, sum(techItems));
  const total = fund + tech;

  let label, tone;
  if (total >= 80) { label = "Sangat Kuat"; tone = "up"; }
  else if (total >= 65) { label = "Kuat"; tone = "up"; }
  else if (total >= 50) { label = "Cukup Baik"; tone = "gold"; }
  else { label = "Lemah"; tone = "down"; }

  return { total, fund, tech, fundItems, techItems, label, tone };
}

// ==========================================
// BSJP — "Beli Sore, Jual Pagi" ENGINE
//
// Terinspirasi struktur strategi momentum institusional ala
// idx-bsjp-screener: entry di jendela Pre-Closing/Post-Closing Auction
// (15:50–16:15 WIB), exit di jendela liquidity surge sesi berikutnya
// (09:00–09:30 WIB). Filter deterministik 8 kriteria + skor komposit
// 0–100, lalu trade plan otomatis (Entry/TP1/TP2/Stop-loss/R:R).
//
// Semua threshold BISA DIUBAH lewat panel di tab BSJP (state.bsjpParams),
// disimpan ke localStorage supaya tidak hilang setelah reload.
// ==========================================
const BSJP_DEFAULT_PARAMS = {
  minTurnover: 5e9,        // Kriteria 1: turnover harian minimum (Rp)
  minVolRatio: 1.5,        // Kriteria 2: vs 20-day Average Daily Volume
  minChangePct: 2.0,       // Kriteria 3: kenaikan harian minimum
  maxChangePct: 15.0,      // Kriteria 3: kenaikan harian maksimum (hindari ARA)
  closeProximity: 0.25,    // Kriteria 4: Close harus di top X% dari range hari itu
  minBidAskRatio: 1.10,    // Kriteria 7: rasio antrian bid/offer minimum
  tp1Pct: 2.0, tp2Pct: 3.4, slPct: 2.5, // Trade plan default (%)
  feePct: 0.4,             // Estimasi fee beli+jual (bolak-balik, %) — sesuaikan dengan broker Anda
  modal: 0,                // Modal (Rp) untuk hitung ukuran posisi; 0 = tidak dihitung
  riskPct: 1.0             // Risiko maksimum per trade (% dari modal)
};
const LS_BSJP_PARAMS = "ihsg_bsjp_params_v1";

function loadBsjpParams(){
  try{
    const raw = localStorage.getItem(LS_BSJP_PARAMS);
    return raw ? { ...BSJP_DEFAULT_PARAMS, ...JSON.parse(raw) } : { ...BSJP_DEFAULT_PARAMS };
  }catch(e){ return { ...BSJP_DEFAULT_PARAMS }; }
}
function saveBsjpParams(){
  try{ localStorage.setItem(LS_BSJP_PARAMS, JSON.stringify(state.bsjpParams)); }catch(e){}
}

// ==========================================
// PARAMETER SKOR BAGGER — SEMUA angka & poin di computeBaggerScore() BISA
// DIUBAH lewat panel "🎯 Kustomisasi Skor Bagger" di tab Screener
// (state.baggerParams), disimpan ke localStorage. Pola sama persis dengan
// BSJP_DEFAULT_PARAMS di atas.
//
// Poin per kriteria SENGAJA tidak dipaksa selalu berjumlah 100 — kalau user
// mengubahnya, total maksimum (maxTotal) dihitung ulang dari jumlah poin
// yang benar-benar dikonfigurasi, dan itulah yang dipakai di semua tampilan
// ("X/maxTotal"), bukan angka 100 yang dihardcode. Konsisten walau user
// menaikkan/menurunkan bobot kriteria tertentu.
// ==========================================
const BAGGER_DEFAULT_PARAMS = {
  // --- Fundamental (default total 40) ---
  revGrowthMin: 15,  revGrowthPts: 10,   // Kriteria F1: Revenue Growth > X%
  earnGrowthMin: 20, earnGrowthPts: 10,  // Kriteria F2: Earnings Growth > X%
  roeMin: 15,        roePts: 10,         // Kriteria F3: ROE > X%
  derMax: 0.8,       derPts: 5,          // Kriteria F4: DER < X
  pegMax: 1,         pegPts: 5,          // Kriteria F5: PEG < X (dan > 0)
  // --- Momentum Teknikal (default total 35) ---
  rsiCrossMax: 70,     rsiCrossPts: 10,  // Kriteria M1: RSI7 cross up RSI21, RSI14 < X
  macdCrossPts: 10,                      // Kriteria M2: MACD Hist negatif→positif (boolean, tanpa angka)
  maStackPts: 10,                        // Kriteria M3: Harga > MA21 > MA50 > MA200 (boolean, tanpa angka)
  stochOversoldMax: 30, stochPts: 5,     // Kriteria M4: Stoch K cross up D dari area oversold ≤ X
  // --- Volume/Smart Money (default total 25) ---
  volRatioMin: 1.5,    volRatioPts: 10,  // Kriteria V1: Volume Ratio > X
  foreignDaysMin: 3,   foreignPts: 10,   // Kriteria V2: Foreign Net 5D > 0 & Hari Asing+ ≥ X
  bbSqueezePts: 5,                       // Kriteria V3: BB Squeeze lalu breakout EMA21 H (boolean, tanpa angka)
  // --- Tier (default 75 / 50, sama seperti formula_screening_saham_bagger.md) ---
  strongCutoff: 75, watchCutoff: 50,
};
const LS_BAGGER_PARAMS = "ihsg_bagger_params_v1";

function loadBaggerParams(){
  try{
    const raw = localStorage.getItem(LS_BAGGER_PARAMS);
    return raw ? { ...BAGGER_DEFAULT_PARAMS, ...JSON.parse(raw) } : { ...BAGGER_DEFAULT_PARAMS };
  }catch(e){ return { ...BAGGER_DEFAULT_PARAMS }; }
}
function saveBaggerParams(){
  try{ localStorage.setItem(LS_BAGGER_PARAMS, JSON.stringify(state.baggerParams)); }catch(e){}
}

// Proxy Top-3 Buyer vs Top-3 Seller (CR3) — data broker_activity asli kalau
// tersedia (state.top5BrokerData, sama yang dipakai rule kustom "Top 5
// Broker", dipindah dari broker_summary — lihat loadTop5BrokerActivityData()),
// fallback ke sinyal band.tone (proxy volume) + arah Net Asing 1D kalau
// broker_activity belum ada datanya untuk emiten ini hari itu (mis. broker
// yang aktif di saham itu belum pernah ditarik lewat Lacak Broker).
function bsjpCr3Proxy(s){
  const t3 = state.top5BrokerData && state.top5BrokerData[s.ticker];
  if (t3 && (t3.buy?.length || t3.sell?.length)) {
    // Tidak ada volume per-broker di top5BrokerData (hanya daftar kode),
    // jadi dipakai sebagai sinyal biner: broker Top-3 Beli tercatat & tidak
    // overlap penuh dengan Top-3 Jual → indikasi akumulasi net oleh pihak berbeda.
    const buySet = new Set(t3.buy||[]), sellSet = new Set(t3.sell||[]);
    const overlap = [...buySet].filter(b=>sellSet.has(b)).length;
    return { value: null, pass: buySet.size > 0 && overlap < buySet.size, source: "broker_activity", trackedCount: t3.trackedCount || 0 };
  }
  const bandUp = s.band && s.band.tone === "up";
  const foreignUp = (s.foreignNet1D || 0) > 0;
  return { value: null, pass: bandUp || foreignUp, source: "proxy", trackedCount: 0 };
}

function computeBsjpEngine(s, params){
  const p = params || BSJP_DEFAULT_PARAMS;
  const num = v => (v===null || v===undefined || v==="" || isNaN(v)) ? null : Number(v);
  const turnover = num(s.turnover) ?? num(s.valueTraded);
  const volRatio = num(s.volRatio);
  const changePct = num(s.changePct);
  const cClose = num(s.cClose), cHigh = num(s.cHigh), cLow = num(s.cLow);
  const emaFast = num(s.ema20) ?? num(s.ma21);
  const emaSlow = num(s.ema50) ?? num(s.ma50);
  const bidVol = num(s.bidVolume), offerVol = num(s.offerVolume);
  const hasOrderbook = bidVol != null && offerVol != null && offerVol > 0;
  const bidAskRatio = hasOrderbook ? bidVol / offerVol : null;
  const cr3 = bsjpCr3Proxy(s);
  // Notasi Khusus / Papan Pemantauan Khusus (FCA) belum ada kolomnya di
  // skema stocks_screener saat ini — kalau suatu hari ditambahkan
  // (r.notasi_khusus / r.papan_pemantauan), otomatis ikut dicek di sini.
  const hasNotasiData = s.notasiKhusus !== undefined && s.notasiKhusus !== null;
  const isClean = !hasNotasiData || (!/[XBEM]/i.test(String(s.notasiKhusus)) && !/fca|watchlist/i.test(String(s.papanPemantauan||"")));

  const closeProximityOk = (cClose!=null && cHigh!=null && cLow!=null)
    ? cClose >= (cHigh - p.closeProximity * (cHigh - cLow))
    : null;
  const trendOk = (cClose!=null && emaFast!=null && emaSlow!=null) ? (cClose > emaFast && cClose > emaSlow) : null;

  const checks = [
    { label:`Turnover ≥ Rp ${fmtNum(p.minTurnover)}`, pass: turnover != null && turnover >= p.minTurnover, na: turnover == null },
    { label:`Volume Ratio > ${p.minVolRatio}x (vs 20-ADV)`, pass: volRatio != null && volRatio > p.minVolRatio, na: volRatio == null },
    { label:`Gain harian ${p.minChangePct}%–${p.maxChangePct}% (hindari ARA)`, pass: changePct != null && changePct >= p.minChangePct && changePct <= p.maxChangePct, na: changePct == null },
    { label:`Close di top ${(p.closeProximity*100).toFixed(0)}% range hari ini`, pass: !!closeProximityOk, na: closeProximityOk == null },
    { label:"Trend Alignment (Close > EMA20 & EMA50)", pass: !!trendOk, na: trendOk == null },
    { label: cr3.source === "broker_activity" ? `Bandar Accumulation Proxy (CR3 / Net Asing) — broker_activity: ${cr3.trackedCount} kode tertarik` : "Bandar Accumulation Proxy (CR3 / Net Asing) — proxy volume", pass: !!cr3.pass, na: false },
    { label:`Orderbook: Bid/Offer ≥ ${p.minBidAskRatio}x`, pass: hasOrderbook ? bidAskRatio >= p.minBidAskRatio : false, na: !hasOrderbook },
    { label:"Bebas Notasi Khusus / Papan Pemantauan Khusus", pass: isClean, na: !hasNotasiData }
  ];
  // Lolos filter deterministik: semua kriteria yang PUNYA DATA harus pass.
  // Kriteria tanpa data (na:true) tidak menggugurkan (dihitung netral),
  // supaya fitur tetap berjalan meski sebagian kolom belum tersinkron.
  const passedCount = checks.filter(c=>c.pass).length;
  const naCount = checks.filter(c=>c.na).length;
  const lolos = checks.every(c=>c.pass || c.na);

  // --- Skor komposit 0-100 ---
  const volSurgeScore = volRatio != null ? 25 * clamp01((volRatio - 1) / 3) : 12.5;
  const proximity = (cClose!=null && cHigh!=null && cLow!=null && (cHigh-cLow) > 0) ? (cClose - cLow) / (cHigh - cLow) : null;
  const priceStructScore = proximity != null ? 20 * clamp01(proximity) : 10;
  const bandarScore = (cr3.pass ? 15 : 0) + 10 * clamp01((num(s.foreignNet1D) || 0) / 5e9);
  const orderbookScore = hasOrderbook ? 15 * clamp01((bidAskRatio - 1) / 1) : 7.5;
  const trendTurnoverScore = (trendOk ? 8 : 0) + (turnover != null ? 7 * clamp01(turnover / 20e9) : 3.5);
  const score = Math.round(volSurgeScore + priceStructScore + bandarScore + orderbookScore + trendTurnoverScore);

  let signal, signalTone;
  if (changePct != null && changePct > p.maxChangePct) { signal = "OVEREXTENDED"; signalTone = "gold"; }
  else if (!lolos && naCount < checks.length) { signal = "AVOID"; signalTone = "down"; }
  else if (score >= 80) { signal = "STRONG_BUY"; signalTone = "up"; }
  else if (score >= 65) { signal = "BUY"; signalTone = "up"; }
  else if (score >= 50) { signal = "WATCH"; signalTone = "gold"; }
  else { signal = "AVOID"; signalTone = "down"; }

  // --- Trade Plan otomatis: Entry saat closing auction, exit besok pagi ---
  const entry = cClose;
  const tp1 = entry != null ? entry * (1 + p.tp1Pct/100) : null;
  const tp2 = entry != null ? entry * (1 + p.tp2Pct/100) : null;
  const sl = entry != null ? entry * (1 - p.slPct/100) : null;
  const rr = (entry != null && sl != null && tp1 != null && (entry - sl) > 0) ? (tp1 - entry) / (entry - sl) : null;

  // --- Fee bolak-balik, ukuran posisi, dan flag distribusi ---
  // Ketiganya SENGAJA tidak mengubah `score`/`lolos`/`signal` di atas —
  // hanya informasi tambahan di Trade Plan dan tabel.
  const feePctNum = Math.max(0, Number(p.feePct) || 0);
  const feeCost = entry != null ? entry * feePctNum / 100 : null;
  const netRr = (entry != null && sl != null && tp1 != null && feeCost != null && ((entry - sl) + feeCost) > 0)
    ? ((tp1 - entry) - feeCost) / ((entry - sl) + feeCost) : null;
  const tp1NetPct = p.tp1Pct - feePctNum;
  let lots = null, lotCost = null, riskRp = null;
  if (entry != null && sl != null && entry > 0 && Number(p.modal) > 0 && Number(p.riskPct) > 0) {
    riskRp = Number(p.modal) * Number(p.riskPct) / 100;
    const perShareRisk = (entry - sl) + feeCost; // rugi per lembar kalau kena SL, termasuk fee
    if (perShareRisk > 0) {
      const byRisk = Math.floor(riskRp / perShareRisk / 100);
      const byCapital = Math.floor(Number(p.modal) / (entry * 100));
      lots = Math.max(0, Math.min(byRisk, byCapital));
      lotCost = lots * 100 * entry;
    }
  }
  // Effort vs result versi data harian: volume jauh di atas normal tapi harga
  // tidak maju (gain < 1%) atau close lemah (di bawah tengah range) —
  // ciri klasik distribusi. Bukan pengganti membaca tape langsung.
  const flags = [];
  if (volRatio != null && volRatio >= 2 && ((changePct != null && changePct < 1) || (proximity != null && proximity < 0.5))) {
    flags.push("Volume besar tapi harga tidak maju / close lemah — kemungkinan distribusi");
  }

  return {
    flags,
    checks, passedCount, naCount, totalChecks: checks.length, lolos,
    score: Math.max(0, Math.min(100, score)),
    breakdown: { volSurgeScore, priceStructScore, bandarScore, orderbookScore, trendTurnoverScore },
    signal, signalTone,
    tradePlan: { entry, tp1, tp2, sl, rr, netRr, tp1NetPct, lots, lotCost, riskRp },
    // Angka mentah di balik tiap skor breakdown, dipakai kartu Trade Plan
    // untuk anotasi kecil (mis. "(3.07x)", "(81%)") tanpa parsing ulang.
    metrics: { volRatio, proximity, bidAskRatio: hasOrderbook ? bidAskRatio : null, foreignNet1D: num(s.foreignNet1D), turnover }
  };
}

function supabaseFetchJson(path, label, retries = 2){
  const url = `${SUPABASE_URL}/${path}`;
  return fetch(url, { headers: getSupaHeaders(), cache: "no-store" })
    .then(async r => {
      const text = await r.text();
      let data;
      try { data = text ? JSON.parse(text) : null; } catch(e) { data = text; }
      if(!r.ok){
        const msg = data && typeof data === "object" ? (data.message || data.error || `HTTP ${r.status}`) : `HTTP ${r.status}`;
        const err = new Error(`${label}: ${msg}`);
        // Timeout statement di sisi Postgres (kode 57014) atau error 5xx bersifat
        // sementara: coba ulang otomatis sebelum menyerah (lihat catch di bawah).
        err.retryable = /statement timeout|57014/i.test(msg) || r.status >= 500;
        throw err;
      }
      return data;
    })
    .catch(async e => {
      if(e && e.retryable && retries > 0){
        await new Promise(res => setTimeout(res, 1500 * (3 - retries)));
        return supabaseFetchJson(path, label, retries - 1);
      }
      // Browser menampilkan "Failed to fetch" tanpa detail untuk CORS/DNS/offline.
      // Tambahkan endpoint yang gagal agar sumber masalah bisa langsung diketahui.
      if(String(e.message).toLowerCase().includes("failed to fetch")){
        throw new Error(`${label}: Failed to fetch (${url}) — cek URL Supabase, koneksi, dan CORS`);
      }
      throw e;
    });
}

// ==========================================
// HEMAT EGRESS SUPABASE (Free Plan = 5 GB/bulan)
// Sebelumnya tiap siklus auto-refresh (45 dtk, 24 jam selama tab terbuka)
// mengunduh ULANG semua tabel: stocks_screener, portfolios, backtest_sessions
// + items, custom_presets, flows (gabungan IDX+Stockbit), dan Top 5 Broker.
// Sekarang siklus auto (opts.auto) hanya menarik stocks_screener + market_index;
// data yang jarang berubah dipertahankan dari muat penuh terakhir dan baru
// diunduh ulang tiap LIVE_STATIC_TTL_MS. Muat manual (tombol Refresh, setelah
// simpan, dsb.) tetap menarik semuanya seperti biasa.
// ==========================================
const LIVE_STATIC_TTL_MS = 10 * 60 * 1000;
const LIVE_TOP5_TTL_MS = 30 * 60 * 1000;
let _liveStaticReady = false, _liveStaticAt = 0, _liveFlowsCache = [], _top5At = 0, lastLiveLoadAt = 0;

async function loadLive(opts){
  if (!SUPABASE_URL || !SUPABASE_KEY) {
    openSettings();
    return;
  }

  state.loading = true; showError(""); render();
  try {
    const skipStatic = !!(opts && opts.auto) && _liveStaticReady && (Date.now() - _liveStaticAt) < LIVE_STATIC_TTL_MS;
    const [stocksRes, portoRes, backtestRes, wlRes, presetsRes, stockbitHistRes, orcaSnapshotRes, marketIndexRes, indexMembershipRes] = await Promise.all([
      // Ambil dari VIEW gabungan, bukan tabel stocks mentah: stocks_screener
      // sudah menggabungkan fundamental+teknikal (tabel stocks) dengan
      // bandarmologi asli dari IDX (view flow_summary), lewat left join.
      supabaseFetchJson("stocks_screener?select=*", "stocks_screener"),
      skipStatic ? null : supabaseFetchJson("portfolios?select=*", "portfolios"),
      skipStatic ? null : supabaseFetchJson("backtest_sessions?select=*,backtest_items(*)", "backtest_sessions"),
      skipStatic ? null : supabaseFetchJson("watchlists?select=ticker", "watchlists"),
      skipStatic ? null : supabaseFetchJson("custom_presets?select=*&order=created_at.desc", "custom_presets"),
      // Riwayat Value (Rp) harian (tabel `flows`, sejak migrasi flows+src
      // sudah gabungan IDX + Stockbit) — dipakai Smart Pick (Area Demand &
      // Liquidity Sweep) untuk memvalidasi volume spike pakai NILAI transaksi
      // riil, bukan cuma rasio volume lembar. Kolom high & close juga
      // diambil untuk Backtest (harga tertinggi + P/L sejak tanggal entry).
      // Sebelum migrasi ini hanya mencakup ticker yang PERNAH ditarik manual
      // lewat "📅 Historical" (isi flows via src=stockbit); sekarang otomatis
      // mencakup semua ticker yang sudah disync sync-idx-full.mjs juga, jadi
      // cakupannya lebih luas. .catch(()=>[]) supaya kalau tabelnya kosong,
      // loadLive() tidak ikut gagal.
      skipStatic ? null : fetch(`${SUPABASE_URL}/flows?select=ticker,date,value,high,close&order=date.desc&limit=4000`, { headers: getSupaHeaders(), cache: "no-store" })
        .then(r => r.ok ? r.json() : [])
        .catch(() => []),
      // Baris `flows` hari bursa TERBARU (semua emiten) — sumber fallback
      // ATS (value/frequency), net asing (foreign_buy/sell), & Non-Regular%
      // (nonreg_value) untuk tab Kraken Flow (ORCA) kalau kolom ringkasan
      // di stocks_screener (avg_ticket, crossing_pct, foreign_net_1d) tidak
      // tersedia. .catch(()=>[]) supaya kalau tabel flows kosong/belum ada,
      // loadLive() tidak ikut gagal.
      skipStatic ? _liveFlowsCache : fetch(`${SUPABASE_URL}/flows?select=ticker,value,frequency,nonreg_value,foreign_buy,foreign_sell,close&order=date.desc&limit=1200`, { headers: getSupaHeaders(), cache: "no-store" })
        .then(r => r.ok ? r.json() : [])
        .catch(() => []),
      // Harga IHSG live/EOD dari tabel market_index, diisi Edge Function
      // fetch-ihsg-index (cron, lihat supabase/functions/fetch-ihsg-index/).
      // .catch(()=>[]) supaya kalau tabelnya belum dibuat (migration belum
      // dijalankan) atau Edge Function belum di-deploy, loadLive() tetap
      // jalan normal -- checklist otomatis fallback ke IHSG Estimasi.
      fetch(`${SUPABASE_URL}/market_index?select=*&symbol=eq.IHSG&limit=1`, { headers: getSupaHeaders(), cache: "no-store" })
        .then(r => r.ok ? r.json() : [])
        .catch(() => []),
      // Keanggotaan LQ45, Syariah, FCA, Suspend, Unsuspend & FCA Out
      // hasil sync manual dari Stockbit (lihat syncLq45Membership()/
      // syncSyariahMembership()/syncFcaMembership()/syncSuspendMembership()/
      // syncUnsuspendMembership()/syncFcaOutMembership(),
      // atau sekaligus lewat syncAllIndexMembership()) — kalau tabel/kolom
      // belum ada (mis. is_unsuspended/is_fca_out belum dimigrasikan)
      // atau masih kosong, .catch(()=>[]) supaya loadLive() tetap jalan dan
      // otomatis fallback ke kolom lq45 di stocks_screener / SYARIAH_TICKERS
      // (FCA/Suspend/Unsuspend/FCA Out tidak punya fallback statis, jadi
      // kalau tabel/kolom kosong nilainya false untuk semua saham).
      fetch(`${SUPABASE_URL}/index_membership?select=ticker,is_lq45,is_syariah,is_fca,is_suspended,is_unsuspended,is_fca_out`, { headers: getSupaHeaders(), cache: "no-store" })
        .then(r => r.ok ? r.json() : [])
        .catch(() => [])
    ]);
    lastLiveLoadAt = Date.now();

    if (stocksRes.message) throw new Error(stocksRes.message);

    // Map keanggotaan LQ45/Syariah dari tabel index_membership (sumber utama,
    // hasil sync dari Stockbit) — dipakai di mapping stocks di bawah untuk
    // override fallback DB-view/statis kalau tickernya ada di tabel ini.
    const lq45Set = new Set(), syariahSet = new Set(), fcaSet = new Set(), suspendSet = new Set();
    const unsuspendSet = new Set(), fcaOutSet = new Set();
    if (Array.isArray(indexMembershipRes)) {
      indexMembershipRes.forEach(row => {
        const t = String(row.ticker || "").toUpperCase();
        if (!t) return;
        if (row.is_lq45) lq45Set.add(t);
        if (row.is_syariah) syariahSet.add(t);
        if (row.is_fca) fcaSet.add(t);
        if (row.is_suspended) suspendSet.add(t);
        if (row.is_unsuspended) unsuspendSet.add(t);
        if (row.is_fca_out) fcaOutSet.add(t);
      });
    }

    // Baris flows terbaru per ticker (fallback bandarmologi utk ORCA) —
    // dibangun jadi map sebelum mapping stocks supaya bisa diakses inline.
    const orcaFlowSnap = {};
    if (Array.isArray(orcaSnapshotRes)) {
      orcaSnapshotRes.forEach(fr => {
        const t = String(fr.ticker || "").toUpperCase();
        if (!t || orcaFlowSnap[t]) return; // baris pertama = tanggal terbaru
        orcaFlowSnap[t] = fr;
      });
    }

    state.stocks = stocksRes.map(r => {
      // Fallback ORCA: kalau kolom ringkasan (avg_ticket/crossing_pct/
      // foreign_net_1d) tidak ada di view, hitung dari baris flows
      // terbaru. Semua null-safe — kalau ticker tidak ada di flows,
      // hasilnya null dan ORCA menampilkan "-".
      const fbRow = orcaFlowSnap[String(r.ticker || "").toUpperCase()] || null;
      const fbFreq = fbRow ? numOrNull(fbRow.frequency) : null;
      const fbValue = fbRow ? numOrNull(fbRow.value) : null;
      const flowAvgTicket = (fbValue != null && fbFreq != null && fbFreq > 0) ? fbValue / fbFreq : null;
      const flowCrossingPct = (fbRow && fbValue != null && fbValue > 0 && numOrNull(fbRow.nonreg_value) != null) ? (numOrNull(fbRow.nonreg_value) / fbValue) * 100 : null;
      const flowForeignNet = (fbRow && (numOrNull(fbRow.foreign_buy) != null || numOrNull(fbRow.foreign_sell) != null))
        ? ((numOrNull(fbRow.foreign_buy) || 0) - (numOrNull(fbRow.foreign_sell) || 0)) * (numOrNull(fbRow.close) || 0)
        : null;
      return {
        ticker: r.ticker, sektor: r.sector, name: r.name, industry: r.industry,
      // Prioritas sumber syariah: (1) tabel index_membership (hasil sync
      // dari klasifikasi Syariah/ISSI Stockbit — lihat syncSyariahMembership()),
      // (2) kolom `syariah` di DB view kalau sudah diisi, (3) fallback daftar
      // statis SYARIAH_TICKERS supaya filter tetap bisa dipakai walau belum
      // pernah sync sama sekali.
      syariah: syariahSet.size
        ? syariahSet.has(String(r.ticker || "").toUpperCase())
        : ((r.syariah === null || r.syariah === undefined || r.syariah === "") ? isSyariah(r.ticker) : r.syariah),
      // Catatan mapping: skema gabungan tidak lagi punya c_high/c_low/c_vol
      // terpisah — dipetakan ke kolom fundamental yang sudah ada supaya
      // tidak ada dua kolom untuk hal yang sama (day_high dulu diisi Yahoo
      // quote, sekarang jadi satu-satunya sumber High hari ini).
      cOpen: r.c_open, cHigh: r.day_high, cLow: r.day_low, cClose: r.price, cVol: r.volume,
      changePct: r.change_pct, turnover: r.turnover, valueTraded: numOrNull(r.value_traded), vwap20: r.vwap20,
      volRatio: numOrNull(r.vol_ratio), volMA20: numOrNull(r.vol_ma20), avgVolume3m: numOrNull(r.avg_volume_3m),
      // Frekuensi transaksi (jumlah kali matched, bukan jumlah lembar) —
      // nama kolom di beberapa skema IDX kadang "frequency", kadang
      // "frekuensi", jadi dua-duanya dicoba.
      // "freqAnalyzer" = baseline rata-rata Frekuensi (mirip "Volume MA 100"
      // punya Volume) yang dipakai rule builder, misal "Frequency > 5 *
      // Frequency Analyzer" — nama kolomnya di DB dikonfigurasi lewat
      // Pengaturan (state.freqAnalyzerCol) karena bisa beda tiap skema.
      frequency: numOrNull(r.frequency ?? r.frekuensi),
      freqAnalyzer: numOrNull(r[state.freqAnalyzerCol] ?? r.freq_ma20 ?? r.frequency_ma20),
      avgFrequency3m: numOrNull(r.avg_frequency_3m ?? r.avg_frekuensi_3m),
      // Antrian bid/offer terbaik — snapshot EOD dari sync-idx-full.mjs
      // (bukan live order book, lihat catatan di skrip). Null kalau
      // memang tidak ada antrian tercatat hari itu.
      bid: numOrNull(r.bid), bidVolume: numOrNull(r.bid_volume),
      offer: numOrNull(r.offer), offerVolume: numOrNull(r.offer_volume),
      per: r.per, forwardPer: numOrNull(r.forward_per), pbv: r.pbv, roe: r.roe, divYield: r.dividend_yield,
      bookValue: numOrNull(r.book_value), psr: numOrNull(r.psr), peg: numOrNull(r.peg),
      roa: numOrNull(r.roa), npm: numOrNull(r.npm), opm: numOrNull(r.opm), eps: numOrNull(r.eps),
      revenueGrowth: numOrNull(r.revenue_growth), earningsGrowth: numOrNull(r.earnings_growth),
      dividendRate: numOrNull(r.dividend_rate), payoutRatio: numOrNull(r.payout_ratio),
      beta: numOrNull(r.beta), der: numOrNull(r.der), currentRatio: numOrNull(r.current_ratio),
      support: r.support, resistance: r.resistance, high52w: r.week52_high, low52w: r.week52_low,
      week52ChangePct: numOrNull(r.week52_change_pct),
      weekChangePct: numOrNull(r.week_change_pct), monthChangePct: numOrNull(r.month_change_pct),
      // Field tambahan untuk paritas screener publik: beberapa deployment
      // memakai nama kolom berbeda, jadi normalisasi dilakukan dengan fallback.
      ytdPct: numOrNull(r.ytd_pct ?? r.ytd_change_pct ?? r.ytd),
      // Prioritas sumber LQ45: tabel index_membership (hasil sync dari
      // klasifikasi LQ45 Stockbit — lihat syncLq45Membership()) kalau sudah
      // terisi, kalau belum fallback ke kolom referensi lama di DB view.
      indexLq45: lq45Set.size ? lq45Set.has(String(r.ticker || "").toUpperCase()) : (r.lq45 ?? r.is_lq45 ?? r.idx_lq45 ?? r.index_lq45 ?? null),
      // FCA (Full Call Auction) & Suspend — hanya dari tabel index_membership
      // (hasil syncFcaMembership()/syncSuspendMembership()), tidak ada
      // fallback statis/kolom DB lama seperti LQ45/Syariah. Kalau tabel
      // belum pernah disync, nilainya false untuk semua ticker (bukan null)
      // supaya filter/badge di UI tidak perlu menangani 3 state sekaligus.
      fca: fcaSet.has(String(r.ticker || "").toUpperCase()),
      suspended: suspendSet.has(String(r.ticker || "").toUpperCase()),
      // Unsuspend (baru dicabut suspensinya),
      // FCA Out (baru keluar dari papan pemantauan khusus) — sumber & catatan
      // sama seperti fca/suspended di atas: hanya dari index_membership hasil
      // sync Stockbit, false untuk semua saham selama belum pernah disync
      // (lihat STOCKBIT_CLASSIFICATION_UNSUSPEND_ID dkk).
      unsuspended: unsuspendSet.has(String(r.ticker || "").toUpperCase()),
      fcaOut: fcaOutSet.has(String(r.ticker || "").toUpperCase()),
      ema21H: r.ema21h, ema21L: r.ema21l, ma21: r.ma21, ma50: r.ma50, ma100: r.ma100, ma200: r.ma200,
      rsi7: r.rsi7, rsi21: r.rsi21, hist: r.macd_hist,
      fib: r.fibonacci, 
      swingHigh: numOrNull(r.swing_high), swingLow: numOrNull(r.swing_low),
      cekHarga: r.cek_harga, cekRsi: r.cek_rsi, statusRsi: r.status_rsi, cekMacd: r.cek_macd, cekVolume: r.cek_volume,
      keyakinanNaik: r.keyakinan_naik,
      trendHarga: r.trend_harga, candleKemarin: r.candle_kemarin, candleHariIni: r.candle_hari_ini, polaCandle: r.pola_candle,
      uangGedeMasuk: boolLabel(r.uang_gede_masuk), bbWidth: numOrNull(r.bb_width),
      isBBSqueeze: boolLabel(r.is_bb_squeeze), atr14: numOrNull(r.atr14), valuasi: r.valuasi ?? "-", clv: numOrNull(r.clv),
      ema89: numOrNull(r.ema89), prevHigh: numOrNull(r.prev_high), prevLow: numOrNull(r.prev_low), prevVol: numOrNull(r.prev_vol),
      stochK: numOrNull(r.stoch_k), stochD: numOrNull(r.stoch_d), prevStochK: numOrNull(r.prev_stoch_k), prevStochD: numOrNull(r.prev_stoch_d),

      // --- Sudah ada di DB tapi sebelumnya belum pernah dipetakan ---
      prevClose: numOrNull(r.prev_close), macd: numOrNull(r.macd), signal: numOrNull(r.signal),
      changeAbs: numOrNull(r.change_abs),
      // Kapan baris ini terakhir diupdate sync-idx-full.mjs — dipakai untuk
      // indikator "data seberapa fresh" di UI (mis. badge "diupdate 2j lalu"
      // atau warning kalau data lebih tua dari 1 hari bursa).
      updatedAt: r.updated_at,

      // --- Perluasan indikator dari stock_indicators_ext (via stocks_screener) ---
      priceMa5: numOrNull(r.price_ma5), priceMa10: numOrNull(r.price_ma10), priceMa20: numOrNull(r.price_ma20),
      prevPriceMa5: numOrNull(r.prev_price_ma5), prevPriceMa10: numOrNull(r.prev_price_ma10),
      prevPriceMa20: numOrNull(r.prev_price_ma20), prevPriceMa50: numOrNull(r.prev_price_ma50),
      prevPriceMa100: numOrNull(r.prev_price_ma100), prevPriceMa200: numOrNull(r.prev_price_ma200),
      volumeMa5: numOrNull(r.volume_ma5), volumeMa10: numOrNull(r.volume_ma10),
      volumeMa50: numOrNull(r.volume_ma50), volumeMa100: numOrNull(r.volume_ma100), volumeMa200: numOrNull(r.volume_ma200),
      prevVolumeMa5: numOrNull(r.prev_volume_ma5), prevVolumeMa10: numOrNull(r.prev_volume_ma10),
      prevVolumeMa20: numOrNull(r.prev_volume_ma20), prevVolumeMa50: numOrNull(r.prev_volume_ma50),
      prevVolumeMa100: numOrNull(r.prev_volume_ma100),
      valueMa5: numOrNull(r.value_ma5), valueMa10: numOrNull(r.value_ma10), valueMa20: numOrNull(r.value_ma20),
      valueMa50: numOrNull(r.value_ma50), valueMa100: numOrNull(r.value_ma100), valueMa200: numOrNull(r.value_ma200),
      frequencyMa50: numOrNull(r.frequency_ma50), freqSpike: r.freq_spike,
      rsi14: numOrNull(r.rsi14), prevRsi14: numOrNull(r.prev_rsi14),
      prevMacd: numOrNull(r.prev_macd), prevSignal: numOrNull(r.prev_signal), prevMacdHist: numOrNull(r.prev_macd_hist),
      bbUpper: numOrNull(r.bb_upper), bbLower: numOrNull(r.bb_lower),
      adr14: numOrNull(r.adr14), prevAtr14: numOrNull(r.prev_atr14), prevAdr14: numOrNull(r.prev_adr14),
      vwap: numOrNull(r.vwap),
      ema5: numOrNull(r.ema5), ema9: numOrNull(r.ema9), ema10: numOrNull(r.ema10), ema20: numOrNull(r.ema20),
      ema21: numOrNull(r.ema21), prevEma9: numOrNull(r.prev_ema9), prevEma21: numOrNull(r.prev_ema21),
      ema50: numOrNull(r.ema50), ema100: numOrNull(r.ema100), ema200: numOrNull(r.ema200),
      prevEma200: numOrNull(r.prev_ema200),
      fibP: numOrNull(r.fib_p), fibR1: numOrNull(r.fib_r1), fibR2: numOrNull(r.fib_r2), fibR3: numOrNull(r.fib_r3),
      fibS1: numOrNull(r.fib_s1), fibS2: numOrNull(r.fib_s2), fibS3: numOrNull(r.fib_s3),

      // --- Bandarmologi ASLI dari IDX (bukan proxy volume) ---
      // Null berarti "belum ditransaksikan" (suspensi dsb), bukan nol —
      // lihat catatan flow_summary di database. Jangan format null jadi 0.
      capCategory: r.cap_category ?? null, pos52w: numOrNull(r.pos_52w),
      // Market Cap: dipakai kalau kolom `market_cap` sudah ada di
      // stocks_screener. Kalau belum, coba turunkan dari
      // `shares_outstanding` x harga. Kalau dua-duanya belum ada di
      // skema, nilainya null dan UI menampilkan "-" (bukan 0) —
      // lihat catatan di README/SQL soal menambah kolom ini.
      sharesOutstanding: numOrNull(r.shares_outstanding),
      marketCap: numOrNull(r.market_cap) ?? (numOrNull(r.shares_outstanding) != null ? numOrNull(r.shares_outstanding) * (numOrNull(r.price) || 0) : null),
      // Free float (%) — opsional, hanya terisi kalau kolomnya ada di stocks_screener.
      // Dipakai filter "Serap FF" di Broker Stalker > Pindai Akumulasi.
      freeFloatPct: (() => { const v = numOrNull(r.free_float_pct ?? r.free_float ?? r.ff_pct); return v == null ? null : (v > 0 && v <= 1 ? v * 100 : v); })(),
      vsMa50Pct: numOrNull(r.vs_ma50_pct), vsMa200Pct: numOrNull(r.vs_ma200_pct),
      avgTicket: numOrNull(r.avg_ticket) ?? flowAvgTicket,
      crossingPct: numOrNull(r.crossing_pct) ?? flowCrossingPct,
      foreignNet1D: numOrNull(r.foreign_net_1d) ?? flowForeignNet,
      foreignNet5D: numOrNull(r.foreign_net_5d),
      foreignNet20D: numOrNull(r.foreign_net_20d), foreignUpDays: numOrNull(r.foreign_up_days),
      flowSeries: Array.isArray(r.flow_series) ? r.flow_series : null,
      flowDate: r.flow_date, flowDays: numOrNull(r.flow_days),
      };
    });

    // Kalau salah satu dari ketiga fetch ini gagal (mis. RLS menolak),
    // Supabase membalas objek {message:...}, bukan array — dulu ini
    // dilewati diam-diam tanpa pemberitahuan apa pun ke user. Sekarang
    // dikumpulkan jadi peringatan yang ditampilkan di errorMsg supaya
    // kelihatan kalau porto/backtest/watchlist gagal dimuat.
    const warnings = [];

    if (skipStatic) {
       // auto-refresh ringan: portofolio dipertahankan dari muat penuh terakhir
    } else if (Array.isArray(portoRes)) {
       state.portfolio = portoRes.map(p => ({
         id: p.id, ticker: p.ticker, jenisPorto: p.jenis_porto || PORTO_JENIS_DEFAULT, status: p.status,
         tglBeli: p.tgl_beli, hargaBeli: p.harga_beli, lotBeli: p.lot_beli, feeBeliPct: p.fee_beli_pct, totalBeli: p.total_beli,
         support: p.support, resistance: p.resistance, fib618: p.fib618, targetTP: p.target_tp, cutLoss: p.cut_loss,
         tglJual: p.tgl_jual, hargaJual: p.harga_jual, lotJual: p.lot_jual, feeJualPct: p.fee_jual_pct, netJual: p.net_jual,
         jangkaWaktu: p.jangka_waktu, persenPL: p.persen_pl, nilaiPL: p.nilai_pl, catatan: p.catatan,
         entries: p.entries 
       }));
       savePortoLocal();
    } else {
       console.warn("Gagal memuat portfolios:", portoRes);
       warnings.push("Portofolio gagal dimuat" + (portoRes && portoRes.message ? ` (${portoRes.message})` : ""));
    }

    if (skipStatic) {
       // dipertahankan
    } else if (Array.isArray(backtestRes)) {
       state.backtests = backtestRes.map(b => ({
         id: b.id, date: b.session_date,
         // Guard Array: sesi tanpa relasi backtest_items (null/undefined)
         // tidak boleh membuat seluruh loadLive() gagal — perlakukan
         // saja sebagai sesi kosong.
         items: (Array.isArray(b.backtest_items) ? b.backtest_items : []).map(it => ({
            ticker: it.ticker, entryPrice: it.entry_price, filterStr: it.notes, sumber: it.source, kriteria: it.criteria,
            // it.entry_date butuh kolom `entry_date` di backtest_items (lihat
            // catatan migrasi di syncBacktestToSupabase). Selama kolom itu
            // belum ada di server, it.entry_date akan undefined — fallback ke
            // tanggal sesi (b.session_date, format "YYYY-MM-DD" dari Supabase)
            // supaya kolom "Tanggal Entry"/"Hari" tetap menampilkan sesuatu
            // yang masuk akal, bukan kosong.
            entryDate: it.entry_date || b.session_date || null
         }))
       })).sort((a,b) => String(b.id).localeCompare(String(a.id)));
       saveBacktests();
    } else {
       console.warn("Gagal memuat backtest_sessions:", backtestRes);
       warnings.push("Backtest gagal dimuat" + (backtestRes && backtestRes.message ? ` (${backtestRes.message})` : ""));
    }

    if (skipStatic) {
        // dipertahankan
    } else if (Array.isArray(wlRes)) {
        state.watchlist = new Set(wlRes.map(w => w.ticker));
        saveWatchlist();
    } else {
        console.warn("Gagal memuat watchlists:", wlRes);
        warnings.push("Watchlist gagal dimuat" + (wlRes && wlRes.message ? ` (${wlRes.message})` : ""));
    }

    if (skipStatic) {
       // dipertahankan
    } else if (Array.isArray(presetsRes)) {
       state.customPresets = presetsRes;
    } else {
       console.warn("Gagal memuat custom_presets:", presetsRes);
       warnings.push("Preset screener gagal dimuat" + (presetsRes && presetsRes.message ? ` (${presetsRes.message})` : ""));
    }

    // market_index: diam-diam null kalau tabel belum ada/kosong -- BUKAN
    // error, karena fitur ini opsional (fallback ke IHSG Estimasi). Tidak
    // ditambahkan ke `warnings` supaya tidak memunculkan notifikasi error
    // ke user yang belum setup Edge Function fetch-ihsg-index.
    state.ihsgIndexLive = (Array.isArray(marketIndexRes) && marketIndexRes[0]) ? marketIndexRes[0] : null;

    // Cron Edge Function fetch-ihsg-index kadang berhenti jalan tanpa error
    // yang terlihat -- kalau baris market_index basi/kosong, coba tarik
    // langsung dari Stockbit di background (tidak menunda render loadLive()
    // yang lain). Lihat fetchIhsgQuoteFromStockbitFallback() & refreshIhsgLive().
    if (!isIhsgIndexRowFresh(state.ihsgIndexLive) && state.stockbitToken) {
      fetchIhsgQuoteFromStockbitFallback().then(fb => {
        if (fb.row) {
          state.ihsgIndexLive = fb.row;
          upsertMarketIndexRow(fb.row);
          render();
        }
      }).catch(()=>{});
    }

    if (warnings.length) showError(warnings.join(" · "));

    // Susun state.stockbitValueHistory: { TICKER: [{date, value_idr}, ...] }
    // Tidak perlu warning kalau kosong — ini fitur opsional (fallback ke
    // volRatio biasa kalau tidak ada), bukan data wajib.
    if(skipStatic){
      // riwayat Stockbit dipertahankan dari muat penuh terakhir
    } else if(Array.isArray(stockbitHistRes) && stockbitHistRes.length){
      const grouped = {};
      const priceGrouped = {};
      stockbitHistRes.forEach(r => {
        const ticker = String(r.ticker || "").trim().toUpperCase();
        if(!ticker) return;
        if(r.value != null){
          (grouped[ticker] ||= []).push({ date: r.date, value_idr: Number(r.value) || 0 });
        }
        // Simpan OHLC yang sudah tersedia dari `flows`. Data ini dipakai
        // Backtest untuk menghitung high dan P/L sepanjang periode.
        if(r.high != null || r.close != null){
          (priceGrouped[ticker] ||= []).push({
            date: r.date, high: numOrNull(r.high), close: numOrNull(r.close)
          });
        }
      });
      state.stockbitValueHistory = grouped;
      state.stockbitPriceHistory = priceGrouped;
    } else {
      state.stockbitValueHistory = {};
      state.stockbitPriceHistory = {};
    }
    // loadLive() menimpa state.stockbitPriceHistory dari query global; pulihkan
    // riwayat khusus ticker Backtest (lihat loadBacktestPriceHistory).
    applyBacktestPriceHistoryCache();

    if(!skipStatic){
      _liveStaticReady = Array.isArray(portoRes) && Array.isArray(backtestRes) && Array.isArray(wlRes) && Array.isArray(presetsRes);
      _liveStaticAt = Date.now();
      _liveFlowsCache = Array.isArray(orcaSnapshotRes) ? orcaSnapshotRes : [];
    }

  } catch (e) {
    // Siklus auto-refresh yang gagal (mis. statement timeout sesaat) tidak perlu
    // menimpa tampilan: kalau data lama sudah ada, pertahankan dan coba lagi
    // di siklus berikutnya. Error tetap ditampilkan untuk muat manual / pertama.
    if (opts && opts.auto && Array.isArray(state.stocks) && state.stocks.length) {
      console.warn("Auto-refresh gagal, memakai data sebelumnya:", e.message);
    } else {
      showError("Gagal terhubung ke Database Supabase: " + e.message);
    }
  }
  state.loading = false; render();

  // Top 5 Broker Beli/Jual dimuat terpisah (tidak di-await bareng fetch di
  // atas) supaya screener utama tetap cepat tampil — begitu selesai, dia
  // render() ulang sendiri untuk mengisi filter "Top 5 Broker".
  loadTop5BrokerActivityData({ auto: !!(opts && opts.auto) });
  loadBacktestPriceHistory();
}

// ------------------------------------------------------------------
// Riwayat harga (high & close) KHUSUS ticker yang ada di Backtest, sejak
// tanggal entry paling awal. Sebelumnya kolom "Harga Tertinggi"/"Capai P/L"
// hanya memakai query global loadLive() — "baris terbaru 4000 (di server
// Supabase biasanya terpotong jadi 1000) untuk SEMUA ticker" — sehingga
// ticker/tanggal yang lebih lama ikut terpotong dan kolomnya kosong ("-")
// walau datanya sebenarnya ada di database. Di sini datanya diambil per
// ticker Backtest, dipaginasi per 1000 baris, lalu menimpa hasil query global.
// Di-cache 5 menit (loadLive jalan tiap 45 detik) kecuali dipaksa
// (_btHistMeta.at = 0), mis. setelah tombol 📅 Historical selesai.
// ------------------------------------------------------------------
let _btHistMeta = { key: null, at: 0 };
let _btHistData = {}; // hasil terakhir, dipertahankan karena loadLive() menimpa state.stockbitPriceHistory tiap 45 detik
function applyBacktestPriceHistoryCache(){
  Object.keys(_btHistData).forEach(t => { state.stockbitPriceHistory[t] = _btHistData[t]; });
}
async function loadBacktestPriceHistory(){
  if(!SUPABASE_URL || !SUPABASE_KEY) return;
  try{
    const tickers = new Set();
    let minDate = null;
    for(const sess of (state.backtests || [])){
      for(const it of (sess.items || [])){
        const t = String(it.ticker || "").trim().toUpperCase();
        if(!t) continue;
        tickers.add(t);
        const d = String(it.entryDate || "").slice(0, 10);
        if(d && (!minDate || d < minDate)) minDate = d;
      }
    }
    if(!tickers.size) return;
    const list = [...tickers].sort();
    const key = list.join(",") + "|" + (minDate || "");
    if(_btHistMeta.key === key && (Date.now() - _btHistMeta.at) < 5 * 60 * 1000) return;

    const PAGE = 1000;
    const rows = [];
    for(const chunk of chunkArray(list, 60)){
      for(let page = 0; page < 60; page++){
        const qs = new URLSearchParams({
          ticker: `in.(${chunk.join(",")})`,
          select: "ticker,date,high,close",
          order: "date.asc,ticker.asc",
          limit: String(PAGE), offset: String(page * PAGE)
        });
        if(minDate) qs.set("date", `gte.${minDate}`);
        const res = await fetch(`${SUPABASE_URL}/flows?${qs}`, { headers: getSupaHeaders(), cache: "no-store" });
        if(!res.ok) throw new Error(`HTTP ${res.status} saat baca flows`);
        const part = await res.json();
        if(!Array.isArray(part)) break;
        rows.push(...part);
        if(part.length < PAGE) break;
      }
    }

    const grouped = {};
    rows.forEach(r => {
      const t = String(r.ticker || "").trim().toUpperCase();
      if(!t || (r.high == null && r.close == null)) return;
      (grouped[t] ||= []).push({ date: r.date, high: numOrNull(r.high), close: numOrNull(r.close) });
    });
    _btHistData = grouped;
    applyBacktestPriceHistoryCache();
    _btHistMeta = { key, at: Date.now() };
    if(!shouldSkipAutoRefreshLive()) render(); // kalau sedang mengetik, biarkan render berikutnya yang memakai datanya
  }catch(e){
    console.warn("Gagal memuat riwayat harga Backtest:", e.message);
  }
}

// Ambil top 3 broker BELI dan top 3 broker JUAL per saham, dari trade_date
// PALING BARU yang tercatat di tabel broker_activity (dipindah dari
// broker_summary — RPC/tabel lama tidak diubah/dihapus). broker_activity
// tidak punya kolom `rank` (beda dengan broker_summary), jadi Top-3 di sini
// dihitung manual di klien: jumlahkan lot per broker/sisi untuk saham itu,
// lalu urutkan & ambil 5 teratas. KETERBATASAN: broker_activity cuma berisi
// broker yang sudah pernah ditarik lewat Lacak Broker (bukan seluruh pasar
// seperti broker_summary top-5 dulu), jadi "Top 5" di sini relatif terhadap
// broker yang tersedia — makin banyak broker ditarik, makin akurat.
async function loadTop5BrokerActivityData(opts){
  if(!SUPABASE_URL || !SUPABASE_KEY) return;
  // Siklus auto-refresh: broker_activity hanya berubah saat ditarik, jadi
  // cukup dimuat ulang tiap LIVE_TOP5_TTL_MS. Pemanggil manual (tanpa opts.auto) selalu memuat.
  if(opts && opts.auto && _top5At && (Date.now() - _top5At) < LIVE_TOP5_TTL_MS) return;
  state.top5BrokerLoading = true;
  try{
    const dateRes = await fetch(`${SUPABASE_URL}/broker_activity?select=trade_date&order=trade_date.desc&limit=1`, { headers: getSupaHeaders(), cache: "no-store" });
    const dateRows = await dateRes.json();
    const latestDate = Array.isArray(dateRows) && dateRows[0] ? dateRows[0].trade_date : null;
    if(!latestDate){
      state.top5BrokerData = {}; state.top5BrokerDate = null;
      state.top5BrokerLoading = false; render();
      return;
    }

    // Tidak dibatasi rank=lte.3 seperti broker_summary dulu (kolomnya tidak
    // ada) — ambil SEMUA baris hari itu (bisa ribuan tergantung berapa
    // banyak broker sudah ditarik), paging paralel via fetchAllPagesParallel.
    const PAGE = 1000;
    const rows = await fetchAllPagesParallel(async (offset) => {
      const qs = new URLSearchParams({
        select: "stock_code,side,broker_code,lot",
        trade_date: `eq.${latestDate}`,
        order: "stock_code.asc,side.asc,broker_code.asc",
        limit: String(PAGE), offset: String(offset)
      });
      const res = await fetch(`${SUPABASE_URL}/broker_activity?${qs}`, { headers: getSupaHeaders(), cache: "no-store" });
      const chunk = await res.json();
      if(!res.ok || !Array.isArray(chunk)) throw new Error((chunk && chunk.message) || `HTTP ${res.status}`);
      return chunk;
    }, PAGE);

    // Agregasi lot per (saham, sisi, broker) — bisa ada beberapa baris per
    // broker/hari kalau pernah ditarik ulang — baru diranking 5 teratas.
    // trackedSet dipakai untuk indikator "N kode broker sudah ditarik" per
    // saham (buy+sell digabung, dedup) — makin besar makin lengkap top-5-nya
    // dibanding kondisi pasar sebenarnya (lihat catatan KETERBATASAN di atas).
    const agg = {};
    const trackedSet = {};
    rows.forEach(r => {
      const ticker = String(r.stock_code || "").trim().toUpperCase();
      const side = r.side;
      const code = String(r.broker_code || "").trim().toUpperCase();
      if(!ticker || !code || (side !== "buy" && side !== "sell")) return;
      if(!agg[ticker]) agg[ticker] = { buy: {}, sell: {} };
      agg[ticker][side][code] = (agg[ticker][side][code] || 0) + (Number(r.lot) || 0);
      if(!trackedSet[ticker]) trackedSet[ticker] = new Set();
      trackedSet[ticker].add(code);
    });
    const map = {};
    Object.keys(agg).forEach(ticker => {
      const top5 = side => Object.entries(agg[ticker][side]).sort((a,b)=>b[1]-a[1]).slice(0,5).map(x=>x[0]);
      map[ticker] = { buy: top5("buy"), sell: top5("sell"), trackedCount: trackedSet[ticker] ? trackedSet[ticker].size : 0 };
    });
    // Indikator global: total kode broker unik yang tertarik hari itu (lintas
    // semua saham) — dipakai sebagai suffix di label field rule builder
    // "Top 5 Broker" supaya user tahu seberapa lengkap datanya secara umum.
    state.top5BrokerGlobalCount = new Set(rows.map(r => String(r.broker_code || "").trim().toUpperCase()).filter(Boolean)).size;
    state.top5BrokerData = map;
    state.top5BrokerDate = latestDate;
    _top5At = Date.now();
  }catch(e){
    console.warn("Gagal memuat Top 5 Broker (broker_activity):", e);
  }
  state.top5BrokerLoading = false;
  render();
}

function showError(msg){
  const el=document.getElementById("errorMsg");
  el.style.display = msg ? "block" : "none";
  el.textContent = msg;
}

async function toggleFav(ticker){
  const isFav = state.watchlist.has(ticker);
  isFav ? state.watchlist.delete(ticker) : state.watchlist.add(ticker);
  if(!isFav) {
    try { const p=JSON.parse(localStorage.getItem("ihsg_watchlist_meta")||"{}"); const s=state.stocks.find(x=>x.ticker===ticker); p[ticker]={entry:Number(s?.cClose)||null,date:todayLocalISO()}; localStorage.setItem("ihsg_watchlist_meta",JSON.stringify(p)); } catch(e) {}
  } else {
    try { const p=JSON.parse(localStorage.getItem("ihsg_watchlist_meta")||"{}"); delete p[ticker]; localStorage.setItem("ihsg_watchlist_meta",JSON.stringify(p)); } catch(e) {}
  }
  saveWatchlist();
  render();

  try{ 
    if(!isFav) {
      await supaFetch(`${SUPABASE_URL}/watchlists`, { method: "POST", headers: { ...getSupaHeaders(), "Prefer": "resolution=merge-duplicates" }, body: JSON.stringify({ticker}) });
    } else {
      await supaFetch(`${SUPABASE_URL}/watchlists?ticker=eq.${ticker}`, { method: "DELETE", headers: getSupaHeaders() });
    }
  } catch(e){
    // Gagal sinkron ke Supabase — batalkan perubahan lokal supaya UI
    // tidak "berbohong" bahwa item sudah tersimpan, dan beri tahu user
    // alasannya (bukan diam-diam gagal seperti sebelumnya).
    isFav ? state.watchlist.add(ticker) : state.watchlist.delete(ticker);
    saveWatchlist();
    showError(`Gagal menyimpan watchlist ke Supabase: ${e.message}`);
    render();
  }
}

// render() mengganti seluruh innerHTML modal, sehingga posisi geser baris tab
// selalu kembali ke kiri — pulihkan di sini, lalu pastikan tab aktif terlihat.
function restoreDetailTabsScroll(prevLeft){
  const bar = document.querySelector("#detailModalContent .detail-tabs");
  if(!bar) return;
  bar.scrollLeft = prevLeft || 0;
  const act = bar.querySelector(".detail-tab-btn.active");
  if(act){
    const l = act.offsetLeft, r = l + act.offsetWidth;
    if(l < bar.scrollLeft || r > bar.scrollLeft + bar.clientWidth){
      bar.scrollLeft = Math.max(0, l - (bar.clientWidth - act.offsetWidth) / 2);
    }
  }
  // Roda mouse vertikal di atas baris tab → geser ke samping (kecuali sudah
  // mentok di ujung, supaya scroll halaman tidak "terkunci").
  bar.onwheel = (e) => {
    if(bar.scrollWidth <= bar.clientWidth || Math.abs(e.deltaY) <= Math.abs(e.deltaX)) return;
    const atStart = bar.scrollLeft <= 0 && e.deltaY < 0;
    const atEnd = bar.scrollLeft + bar.clientWidth >= bar.scrollWidth - 1 && e.deltaY > 0;
    if(atStart || atEnd) return;
    bar.scrollLeft += e.deltaY;
    e.preventDefault();
  };
}

function openDetail(ticker, opts){
  const keepTab = !!(opts && opts.keepTab);
  const keepNav = !!(opts && opts.keepNav);
  state.detailTicker = ticker;
  if(!keepTab) state.detailTab = "teknikal";
  // Daftar navigasi Sebelumnya/Berikutnya: hanya kalau modal dibuka dari tab
  // Screener — pakai daftar hasil filter+urut yang sama persis dengan tabel
  // (seluruh halaman, bukan cuma halaman yang sedang tampil), dibekukan saat
  // dibuka supaya urutannya tidak melompat kena auto-refresh 45 detik.
  if(!keepNav){
    try{
      state.detailNavList = state.tab === "screener" ? getSorted(getFiltered()).map(x => x.ticker) : null;
    }catch(e){ state.detailNavList = null; }
  }
  state.detailBsRows = []; state.detailBsEditRows = [];
  state.detailBsMsg = ""; state.detailBsMsgError = false;
  state.detailBsEditorOpen = false; state.detailBsCsvText = "";
  state.detailBsRangeMode = false; state.detailBsDateFrom = ""; state.detailBsDateTo = "";
  state.detailBsRangeAgg = null; state.detailBsRangeDatesCount = 0;
  state.detailBsCounterpartyOpenCode = null; state.detailBsCounterpartyMsg = "";
  state.detailBsCounterpartyRows = []; state.detailBsCounterpartyDate = null;
  state.detailHistoricalRows = []; state.detailHistoricalMsg = ""; state.detailHistoricalMsgError = false;
  state.detailCompareRows = []; state.detailCompareMsg = ""; state.detailCompareOpen = false;
  state.detailInsiderRows = []; state.detailInsiderMsg = ""; state.detailInsiderMsgError = false;
  state.detailInsiderRaw = null; state.detailInsiderPage = 1; state.detailInsiderHasMore = false;
  state.detailInsiderSourceFilter = "ALL"; state.detailInsiderActionFilter = "ALL";
  render();
}
function closeDetail(){
  state.detailTicker = null;
  state.detailNavList = null;
  render();
}
// Pindah ke saham sebelumnya (-1) / berikutnya (+1) di hasil screener.
// Tab yang sedang dibuka (Teknikal/Broker Summary/dst) dipertahankan.
function navigateDetail(delta){
  const list = state.detailNavList;
  if(!list || !list.length) return;
  const i = list.indexOf(state.detailTicker);
  if(i < 0) return;
  const next = list[i + delta];
  if(!next) return;
  const tab = state.detailTab;
  openDetail(next, { keepTab: true, keepNav: true });
  // Tab Historical Data memuat dari database otomatis (sama seperti saat tab dibuka)
  if(tab === "historical") loadDetailHistoricalFromDb();
  // Kembali ke atas supaya langsung melihat header saham baru
  ["detailModalContent","detailModalOverlay"].forEach(id => {
    const el = document.getElementById(id);
    if(el){ el.scrollTop = 0; if(el.parentElement) el.parentElement.scrollTop = 0; }
  });
}
function setDetailTab(tab){
  state.detailTab = tab;
  // Auto-muat Historical Data dari database (tabel flows)
  // begitu tab dibuka, kalau belum ada baris & tidak sedang loading — supaya
  // user tidak harus klik apa pun untuk lihat histori yang sudah pernah
  // ditarik lewat Stockbit sebelumnya (lihat loadDetailHistoricalFromDb()).
  if(tab === "historical" && !(state.detailHistoricalRows && state.detailHistoricalRows.length) && !state.detailHistoricalLoading){
    loadDetailHistoricalFromDb();
    return; // loadDetailHistoricalFromDb() sudah memanggil render()
  }
  // Auto-muat tab Insider begitu dibuka pertama kali (belum ada baris &
  // tidak sedang loading) — beda dari historical, ini live-pull langsung
  // ke Stockbit (tidak ada cache database), sama seperti Broker Summary.
  if(tab === "insider" && !(state.detailInsiderRows && state.detailInsiderRows.length) && !state.detailInsiderLoading){
    loadDetailInsider();
    return; // loadDetailInsider() sudah memanggil render()
  }
  render();
}

function openSmartPickList(defId){
  state.spListOpenDefId = defId;
  render();
}
function closeSmartPickList(){
  state.spListOpenDefId = null;
  render();
}

function dItem(label, valueHtml, isText){
  return `<div class="detail-item"><div class="lbl">${label}</div><div class="val ${isText?'text':''}">${valueHtml==null||valueHtml===""?'-':valueHtml}</div></div>`;
}
function baggerBreakdownRows(items){
  return items.map(i => `<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;padding:3px 0;font-size:11.5px;line-height:1.3;">
    <span style="color:${i.pass?'var(--up)':'var(--muted)'};">${i.pass?'✅':'▫️'} ${i.label}</span>
    <span class="mono" style="color:${i.pass?'var(--up)':'var(--muted)'};white-space:nowrap;">${i.pass?'+':''}${i.pass?i.points:0}/${i.points}</span>
  </div>`).join("");
}
function dNum(n, opts){
  opts = opts || {};
  if(n===null||n===undefined||n==="") return "-";
  const num = Number(n);
  if(isNaN(num)) return String(n);
  return (opts.plusSign && num>=0 ? "+" : "") + fmtNum(opts.decimals!=null ? +num.toFixed(opts.decimals) : num) + (opts.suffix||"");
}

function renderImbalanceBar(bidVol, offerVol) {
    const tb = Number(bidVol) || 0;
    const to = Number(offerVol) || 0;
    const total = tb + to;
    if(total === 0) return '';
    const bidPct = (tb / total) * 100;
    const offerPct = 100 - bidPct;
    return `
    <div style="margin-top:12px; margin-bottom:12px; padding: 12px; background: color-mix(in srgb, currentColor 6%, transparent); border-radius: 8px; border: 1px solid var(--border);">
        <div style="font-size:11px; color:var(--muted); text-transform:uppercase; margin-bottom:8px; text-align:center;">⚖️ Tekanan Orderbook (Bid vs Offer)</div>
        <div style="display:flex; justify-content:space-between; font-size:11px; margin-bottom:4px; font-weight:bold;">
            <span style="color:var(--up);">Bid Power: ${bidPct.toFixed(1)}%</span>
            <span style="color:var(--down);">Offer Power: ${offerPct.toFixed(1)}%</span>
        </div>
        <div style="height:8px; background:var(--down); border-radius:4px; display:flex; overflow:hidden; box-shadow: inset 0 1px 3px rgba(0,0,0,0.5);">
            <div style="width:${bidPct}%; background:var(--up); height:100%;"></div>
        </div>
    </div>`;
}

// ==========================================================
// KARTU ORDERBOOK DEPTH 10-LEVEL (live, Stockbit) — beda dari
// renderImbalanceBar() di atas: itu snapshot EOD dari tabel `stocks`
// (top-of-book saja), ini live 10-20 level bid/offer ditarik manual per
// klik dari Stockbit (lihat fetchStockbitOrderbookDepth). Skema field
// respons Stockbit-nya masih dugaan (lihat catatan di
// parseStockbitOrderbookDepth) — makanya selalu ada tombol "Lihat JSON
// Mentah" supaya kalau tampilannya kosong/aneh, kamu bisa cek & laporkan
// bentuk asli datanya.
// ==========================================================
function renderOrderbookDepthCard(ticker){
  const st = state.stockbitOrderbook[ticker];

  // Semua permukaan kartu memakai turunan currentColor (color-mix), BUKAN
  // rgba hitam/putih tetap — supaya kontrasnya benar di mode terang MAUPUN
  // gelap tanpa perlu tahu palet mana yang sedang aktif.
  const shell = (accent, body) => `<div style="margin:12px 0; padding:14px; background:${accent || "color-mix(in srgb, currentColor 5%, transparent)"}; border-radius:10px; border:1px solid color-mix(in srgb, currentColor 16%, transparent);">${body}</div>`;
  const header = `<div style="font-size:12px; font-weight:700; letter-spacing:.03em; margin-bottom:10px; text-align:center;">📶 ORDERBOOK DEPTH 10-LEVEL <span style="font-weight:500; color:var(--muted);">· Live Stockbit</span></div>`;
  const btn = `<button class="btn btn-outline" data-stockbit-depth-btn="${ticker}" ${st?.loading?"disabled":""} style="width:100%;">${st?.loading?"⏳ Menarik...":"🔴 Tarik Orderbook Depth Live"}</button>`;
  const rawBlock = (raw, label) => `<details style="margin-top:10px;">
      <summary style="cursor:pointer;font-size:11px;color:var(--teal);font-weight:600;">🔍 ${label}</summary>
      <pre style="margin-top:6px;max-height:260px;overflow:auto;font-size:11px;line-height:1.5;background:color-mix(in srgb, currentColor 8%, transparent);padding:10px;border-radius:6px;white-space:pre-wrap;word-break:break-all;">${escapeHtml(JSON.stringify(raw, null, 2).slice(0, 6000))}</pre>
    </details>`;

  if(!st || (!st.loading && !st.parsed && !st.error)){
    return shell(null, `${header}${btn}
      <div style="margin-top:10px;font-size:12px;color:var(--muted);text-align:center;line-height:1.5;">Belum ditarik — data live, tidak disimpan ke histori.<br>Butuh Token Stockbit terisi di ⚙️ Pengaturan.</div>`);
  }
  if(st.loading) return shell(null, `${header}${btn}`);

  if(st.error){
    return shell("color-mix(in srgb, var(--down) 12%, transparent)", `${header}${btn}
      <div style="margin-top:10px;font-size:12px;color:var(--down);font-weight:600;line-height:1.5;">⚠️ ${escapeHtml(st.error)}</div>
      ${st.parsed?.raw != null ? rawBlock(st.parsed.raw, "Lihat body respons server") : ""}`);
  }

  const { bids, asks, unrecognized, empty, note, candidates, topKeys, bidPath, askPath, raw } = st.parsed;
  const rel = fmtRelativeTimeID(st.fetchedAt);

  // Struktur JSON tidak terbaca sama sekali.
  if(unrecognized){
    const hint = [
      note ? `<div style="margin-top:6px;">${escapeHtml(note)}</div>` : "",
      topKeys?.length ? `<div style="margin-top:6px;">Kunci yang ada di respons: <span class="mono">${escapeHtml(topKeys.join(", "))}</span></div>` : "",
      candidates?.length ? `<div style="margin-top:6px;">Array kandidat: <span class="mono">${escapeHtml(candidates.map(c=>`${c.path} (${c.n})`).join(", "))}</span></div>` : "",
    ].join("");
    return shell("color-mix(in srgb, var(--gold) 12%, transparent)", `${header}${btn}
      <div style="margin-top:10px;font-size:12px;color:var(--gold);font-weight:600;line-height:1.5;">⚠️ Respons diterima (${rel}) tapi ladder bid/offer tidak ditemukan.</div>
      <div style="font-size:11.5px;color:var(--muted);line-height:1.6;">${hint}</div>
      ${rawBlock(raw, "Lihat JSON Mentah — kirim isinya ke saya untuk dipetakan")}`);
  }

  const sumBid = bids.reduce((a,l)=>a+l.rawVol,0);
  const sumAsk = asks.reduce((a,l)=>a+l.rawVol,0);

  // Struktur terbaca tapi antrian nol — ini BUKAN bug, dibedakan supaya tidak
  // terlihat seperti tampilan gagal yang kosong melompong.
  if(empty){
    return shell("color-mix(in srgb, var(--gold) 10%, transparent)", `${header}${btn}
      <div style="margin-top:10px;font-size:12px;color:var(--gold);font-weight:600;line-height:1.5;">Struktur data terbaca (${bids.length} level bid, ${asks.length} level offer) tapi semua volumenya 0.</div>
      <div style="margin-top:4px;font-size:11.5px;color:var(--muted);line-height:1.6;">Normal kalau bursa sedang tutup, pre-opening, atau saham disuspend. Coba lagi saat jam bursa (09:00–15:50 WIB).</div>
      ${rawBlock(raw, "Lihat JSON Mentah")}`);
  }

  const maxVol = Math.max(1, ...bids.map(b=>b.rawVol), ...asks.map(a=>a.rawVol));
  const cell = (lvl, side) => {
    const align = side === "bid" ? "right" : "left";
    if(!lvl) return `<div style="height:22px;"></div>`;
    const pct = Math.max(3, (lvl.rawVol / maxVol) * 100);
    const tone = side === "bid" ? "var(--up)" : "var(--down)";
    // Bar dijadikan LATAR baris (di belakang teks) supaya angka tetap
    // terbaca penuh — versi sebelumnya menaruh bar di kolom terpisah
    // sehingga harga & volume terjepit sempit.
    const fill = `background:linear-gradient(to ${side==="bid"?"left":"right"}, color-mix(in srgb, ${tone} 30%, transparent) ${pct}%, transparent ${pct}%);`;
    return `<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;height:22px;padding:0 8px;border-radius:4px;${fill}${side==="bid"?"flex-direction:row-reverse;":""}">
      <span style="font-weight:700;font-size:12.5px;color:${tone};font-variant-numeric:tabular-nums;">${fmtNum(lvl.price)}</span>
      <span style="font-size:11.5px;color:var(--muted);font-variant-numeric:tabular-nums;text-align:${align};">${fmtNum(lvl.rawVol)}${lvl.order?` <span style="opacity:.65;">·${lvl.order}</span>`:""}</span>
    </div>`;
  };
  let ladder = "";
  for(let i=0;i<Math.min(Math.max(bids.length, asks.length), 10);i++){
    ladder += `<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:3px;">${cell(bids[i],"bid")}${cell(asks[i],"offer")}</div>`;
  }

  const total = sumBid + sumAsk;
  const bidPct = total ? (sumBid/total)*100 : 50;
  const ratio = sumAsk ? (sumBid/sumAsk) : null;
  const verdict = ratio == null ? "-" : ratio >= 1.5 ? "Tekanan BELI dominan" : ratio <= 0.67 ? "Tekanan JUAL dominan" : "Relatif seimbang";
  const verdictTone = ratio == null ? "var(--muted)" : ratio >= 1.5 ? "var(--up)" : ratio <= 0.67 ? "var(--down)" : "var(--gold)";

  return shell(null, `${header}${btn}
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:12px 0 6px;font-size:11px;font-weight:800;letter-spacing:.06em;">
      <div style="text-align:right;color:var(--up);">BID ◀</div><div style="color:var(--down);">▶ OFFER</div>
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:6px;font-size:10px;color:var(--muted);">
      <div style="display:flex;justify-content:space-between;flex-direction:row-reverse;padding:0 8px;"><span>Harga</span><span>Volume</span></div>
      <div style="display:flex;justify-content:space-between;padding:0 8px;"><span>Harga</span><span>Volume</span></div>
    </div>
    ${ladder}
    <div style="margin-top:12px;padding-top:10px;border-top:1px solid color-mix(in srgb, currentColor 16%, transparent);">
      <div style="display:flex;justify-content:space-between;font-size:11.5px;font-weight:700;margin-bottom:6px;">
        <span style="color:var(--up);">Total Bid ${fmtNum(sumBid)}</span>
        <span style="color:var(--down);">${fmtNum(sumAsk)} Total Offer</span>
      </div>
      <div style="height:8px;border-radius:4px;overflow:hidden;display:flex;background:color-mix(in srgb, currentColor 12%, transparent);">
        <div style="width:${bidPct}%;background:var(--up);"></div><div style="flex:1;background:var(--down);"></div>
      </div>
      <div style="margin-top:6px;font-size:11.5px;text-align:center;color:${verdictTone};font-weight:700;">${verdict}${ratio!=null?` · rasio ${ratio.toFixed(2)}x`:""}</div>
    </div>
    <div style="margin-top:10px;font-size:10.5px;color:var(--muted);text-align:center;line-height:1.5;">Ditarik ${rel} · sumber field: <span class="mono">${escapeHtml(bidPath||"?")}</span> / <span class="mono">${escapeHtml(askPath||"?")}</span> · satuan volume (lot vs lembar) belum dipastikan</div>
    ${rawBlock(raw, "Lihat JSON Mentah")}`);
}

