function fmtRp(n){
  if(n===null||n===undefined) return "-";
  const num = Number(n);
  if(isNaN(num)) return "-";
  const abs = Math.abs(num);
  const sign = num<0 ? "-" : "+";
  if(abs>=1e12) return sign+(abs/1e12).toFixed(2)+" T";
  if(abs>=1e9)  return sign+(abs/1e9).toFixed(2)+" M";
  if(abs>=1e6)  return sign+(abs/1e6).toFixed(1)+" jt";
  return sign+fmtNum(abs);
}
// Sama seperti fmtRp tapi tanpa tanda +/- di depan — dipakai untuk
// kuantitas non-arah seperti Market Cap (bukan Net Asing yang berarah).
function fmtCap(n){
  if(n===null||n===undefined) return "-";
  const num = Number(n);
  if(isNaN(num)) return "-";
  const abs = Math.abs(num);
  if(abs>=1e12) return (num/1e12).toFixed(2)+" T";
  if(abs>=1e9)  return (num/1e9).toFixed(2)+" M";
  if(abs>=1e6)  return (num/1e6).toFixed(1)+" jt";
  return fmtNum(num);
}
// Nilai Wajar (Graham Number) = sqrt(22.5 x EPS x BVPS).
// EPS dan BVPS tidak disimpan mentah di DB, tapi bisa diturunkan dari
// rasio yang sudah ada: PER = harga/EPS -> EPS = harga/PER,
// PBV = harga/BVPS -> BVPS = harga/PBV. Jadi Graham Number bisa
// dihitung tanpa perlu kolom baru, selama PER & PBV positif (EPS/BVPS
// negatif membuat akar tidak valid secara matematis -> null / "-").
function grahamFairValue(s){
  const per = numOrNull(s.per), pbv = numOrNull(s.pbv), price = numOrNull(s.cClose);
  if(per==null || pbv==null || price==null || per<=0 || pbv<=0) return null;
  return price * Math.sqrt(22.5 / (per * pbv));
}

function flowBarsHtml(series){
  if(!Array.isArray(series) || !series.length){
    return `<div class="empty-box" style="padding:20px;font-size:12px;">Belum ada riwayat 20 hari untuk emiten ini.</div>`;
  }
  const max = Math.max(1, ...series.map(v=>Math.abs(Number(v)||0)));
  const bars = series.map(v=>{
    const val = Number(v)||0;
    const h = Math.max(4, Math.round(Math.abs(val)/max*48));
    const color = val>=0 ? "var(--up)" : "var(--down)";
    return `<div title="${fmtRp(val)}" style="width:6px;height:${h}px;background:${color};border-radius:2px;align-self:${val>=0?'flex-end':'flex-start'};"></div>`;
  }).join("");
  return `<div style="display:flex;align-items:center;gap:3px;height:56px;padding:4px 0;">${bars}</div>`;
}

function renderDetailBandarmologi(s){
  const belumAdaData = s.foreignNet20D==null && s.foreignNet5D==null && s.foreignNet1D==null;
  if(belumAdaData){
    return `<div class="empty-box" style="padding:24px;">
      Emiten ini belum punya data aliran dana IDX (kemungkinan suspensi atau nyaris tidak diperdagangkan
      dalam 20 hari terakhir). Kosong di sini artinya "tidak ada transaksi untuk dinilai", bukan nol.
    </div>`;
  }
  return `
    <div class="detail-subtitle">Net Beli Asing (Rupiah)</div>
    <div class="detail-grid">
      ${dItem("1 Hari", `<span style="color:${(s.foreignNet1D??0)>=0?'var(--up)':'var(--down)'}">${fmtRp(s.foreignNet1D)}</span>`, true)}
      ${dItem("5 Hari", `<span style="color:${(s.foreignNet5D??0)>=0?'var(--up)':'var(--down)'}">${fmtRp(s.foreignNet5D)}</span>`, true)}
      ${dItem("20 Hari", `<span style="color:${(s.foreignNet20D??0)>=0?'var(--up)':'var(--down)'}">${fmtRp(s.foreignNet20D)}</span>`, true)}
      ${dItem("Hari Asing Positif", s.foreignUpDays!=null ? `${s.foreignUpDays} / ${s.flowDays??20} hari` : "-", true)}
    </div>

    <div class="detail-subtitle">Grafik Aliran Dana 20 Hari (hijau = net beli, merah = net jual)</div>
    ${flowBarsHtml(s.flowSeries)}

    <div class="detail-subtitle">Karakter Transaksi</div>
    <div class="detail-grid">
      ${dItem("Rata-rata Tiket", s.avgTicket!=null ? fmtRp(s.avgTicket)+"/transaksi" : "-", true)}
      ${dItem("Transaksi Negosiasi", s.crossingPct!=null ? dNum(s.crossingPct,{decimals:1,suffix:'%'}) : "-", true)}
      ${dItem("Update Terakhir", s.flowDate || "-", true)}
    </div>

    <div class="detail-narrative">
      <b>Data asing bukan data bandar.</b> Ini proksi, dan proksi yang kasar — institusi lokal besar
      (dana pensiun, asuransi, manajer investasi dalam negeri) tidak muncul sebagai "asing" sama sekali,
      sementara sebagian dana lokal yang dititipkan lewat kustodian asing justru tercatat sebagai asing.
      Data ini juga harian (bukan real-time) — angka di atas adalah data ${s.flowDate || "hari perdagangan terakhir"},
      berguna untuk pola berminggu-minggu, bukan keputusan intraday. Sumber: IDX resmi, terpisah dari
      indikator "BPJS" di tab Analisa yang murni proxy dari lonjakan volume — dua hal ini tidak sama.
    </div>
  `;
}

function emptyDbsRow(side, rank){ return { side, rank, broker_code:"", lot:"", value_idr:"" }; }

function renderDetailBrokerSummary(s){
  const ticker = s.ticker;
  const rangeMode = !!state.detailBsRangeMode;

  const modeToggle = `
    <div class="bs-mode-toggle" style="display:flex;gap:6px;">
      <button type="button" class="btn btn-outline" data-bs-period-mode="single" style="${!rangeMode?'background:var(--gold);color:#111;border-color:var(--gold);':''}">🗓️ Tanggal</button>
      <button type="button" class="btn btn-outline" data-bs-period-mode="range" style="${rangeMode?'background:var(--gold);color:#111;border-color:var(--gold);':''}">📊 Periode</button>
    </div>`;

  const toolbarInputs = rangeMode ? `
      <input id="dbsDateFrom" class="bs-input" type="date" value="${state.detailBsDateFrom||""}" title="Dari tanggal">
      <span style="color:var(--muted);">–</span>
      <input id="dbsDateTo" class="bs-input" type="date" value="${state.detailBsDateTo||""}" title="Sampai tanggal">
    ` : `<input id="dbsDate" class="bs-input" type="date" value="${state.detailBsDate||""}">`;

  return `
    <div class="bs-wrap">
      <div class="bs-toolbar" style="flex-wrap:wrap;gap:8px;">
        <span class="mono" style="font-weight:700;font-size:14px;">${escapeHtml(ticker)}</span>
        ${modeToggle}
        ${toolbarInputs}
        <button class="btn btn-outline" id="dbsLoadBtn" ${state.detailBsLoading?"disabled":""}>${state.detailBsLoading?"Memuat...":"Muat Data"}</button>
      </div>

      ${state.detailBsMsg ? `<div class="bs-msg ${state.detailBsMsgError?"bs-msg-error":"bs-msg-ok"}">${escapeHtml(state.detailBsMsg)}</div>` : ""}

      ${rangeMode ? renderDetailBrokerSummaryRangeBody() : renderDetailBrokerSummarySingleBody()}
    </div>`;
}

// Mode tanggal tunggal: tampilan Top 5 Buy/Sell untuk SATU hari + editor
// manual (input/edit dari screenshot Stockbit / tempel CSV). Ini perilaku
// asli renderDetailBrokerSummary(), dipisah ke fungsi sendiri supaya bisa
// ditukar dengan renderDetailBrokerSummaryRangeBody() lewat mode toggle.
function renderDetailBrokerSummarySingleBody(){
  const editRows = state.detailBsEditRows && state.detailBsEditRows.length ? state.detailBsEditRows : [];
  const buyEdit = [0,1,2,3,4].map(i => editRows.find(r=>r.side==="buy" && r.rank===i+1) || emptyDbsRow("buy", i+1));
  const sellEdit = [0,1,2,3,4].map(i => editRows.find(r=>r.side==="sell" && r.rank===i+1) || emptyDbsRow("sell", i+1));

  const editRowsHtml = (rows, label) => rows.map((r,i)=>`
    <div class="bs-row">
      <input class="bs-cell" id="dbs${label}Broker${i}" placeholder="Kode" maxlength="6" style="text-transform:uppercase" value="${escapeHtml(r.broker_code||"")}">
      <input class="bs-cell" id="dbs${label}Lot${i}" type="number" placeholder="Lot" value="${r.lot ?? ""}">
      <input class="bs-cell" id="dbs${label}Value${i}" type="number" placeholder="Nilai (Rp)" value="${r.value_idr ?? ""}">
    </div>`).join("");

  const dRows = state.detailBsRows || [];
  const dBuy = dRows.filter(r=>r.side==="buy").sort((a,b)=>a.rank-b.rank);
  const dSell = dRows.filter(r=>r.side==="sell").sort((a,b)=>a.rank-b.rank);
  const maxVal = Math.max(1, ...dRows.map(r=> Number(r.value_idr)||0));

  // Panel breakdown "🔍 Lawan Transaksi" (distribute_to) — lihat catatan
  // panjang di STOCKBIT_DISTRIBUTE_EP & state.detailBsCounterpartyOpenCode.
  // Ditarik LIVE per klik, endpoint-nya cuma balas HARI BURSA TERAKHIR
  // (bukan tanggal yang sedang dipilih di 🗓️), jadi tombol ini tetap
  // ditampilkan apa pun tanggalnya, tapi hasilnya diberi label tanggal
  // ASLI yang dibalas Stockbit + peringatan kalau beda dari tanggal terpilih.
  const counterpartyPanelHtml = (side, code) => {
    const key = `${side.toUpperCase()}:${code}`;
    if(state.detailBsCounterpartyOpenCode !== key) return "";
    let body;
    if(state.detailBsCounterpartyLoading){
      body = `<div class="empty-box" style="padding:10px;font-size:11.5px;">Memuat lawan transaksi ${escapeHtml(code)}…</div>`;
    } else if(state.detailBsCounterpartyMsg){
      body = `<div class="bs-msg bs-msg-error" style="font-size:11.5px;">${escapeHtml(state.detailBsCounterpartyMsg)}</div>`;
    } else {
      const rows = state.detailBsCounterpartyRows || [];
      const dateNote = state.detailBsCounterpartyDate && state.detailBsCounterpartyDate !== state.detailBsDate
        ? `<div style="font-size:10px;color:var(--gold);margin-bottom:6px;">⚠️ Endpoint Stockbit ini cuma menyediakan hari bursa terakhir (${escapeHtml(fmtDateID(state.detailBsCounterpartyDate))}), bukan tanggal yang sedang dipilih (${escapeHtml(fmtDateID(state.detailBsDate))}). Breakdown di bawah untuk ${escapeHtml(fmtDateID(state.detailBsCounterpartyDate))}.</div>`
        : "";
      const maxAmt = Math.max(1, ...rows.map(r=>Math.abs(r.amount)));
      body = rows.length ? `
        ${dateNote}
        <div style="font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px;">Lawan transaksi ${escapeHtml(code)} (${side==="buy"?"jual ke":"beli dari"} broker berikut)</div>
        ${rows.map(r => `
          <div class="bs-bar-row" style="padding:2px 0;">
            <span class="bs-bar-broker mono" style="font-size:11px;">${escapeHtml(r.code)}${r.type ? ` <span style="font-size:9px;color:var(--muted);font-weight:400;">(${escapeHtml(r.type)})</span>` : ""}</span>
            <div class="bs-bar-track"><div class="bs-bar-fill ${side==="buy"?"bs-fill-sell":"bs-fill-buy"}" style="width:${(Math.abs(r.amount)/maxAmt)*100}%"></div></div>
            <span class="bs-bar-value mono" style="font-size:11px;">${fmtNum(r.amount)}</span>
          </div>`).join("")}
      ` : `${dateNote}<div class="empty-box" style="padding:8px;font-size:11px;">Tidak ada breakdown lawan transaksi utk broker ini di respons Stockbit.</div>`;
    }
    return `<div class="bs-counterparty-panel" style="margin:2px 0 8px;padding:8px 10px;background:color-mix(in srgb, currentColor 5%, transparent);border:1px solid var(--border);border-radius:8px;">${body}</div>`;
  };

  const barHtml = (r, cls, side) => {
    const key = `${side.toUpperCase()}:${r.broker_code}`;
    const isOpen = state.detailBsCounterpartyOpenCode === key;
    return `
    <div class="bs-bar-row">
      <span class="bs-bar-broker mono">${escapeHtml(r.broker_code)}${r.investor_type ? ` <span style="font-size:9px;color:var(--muted);font-weight:400;">(${escapeHtml(r.investor_type)})</span>` : ""}</span>
      <div class="bs-bar-track"><div class="bs-bar-fill ${cls}" style="width:${(Number(r.value_idr)/maxVal)*100}%"></div></div>
      <span class="bs-bar-value mono">${fmtNum(r.value_idr)}</span>
      <button type="button" class="link-btn" data-bs-counterparty="${side}:${escapeHtml(r.broker_code)}" title="Lihat lawan transaksi broker ini (live dari Stockbit)" style="font-size:10px;white-space:nowrap;margin-left:4px;">${isOpen?"✕":"🔍"}</button>
    </div>
    ${counterpartyPanelHtml(side, r.broker_code)}`;
  };

  return `
      ${bsStatusRowHtml(dRows)}

      <div class="bs-display-grid">
        <div>
          <div class="bs-col-title bs-buy">Top 5 Buy</div>
          ${dBuy.length ? dBuy.map(r=>barHtml(r,"bs-fill-buy","buy")).join("") : `<div class="empty-box" style="padding:16px;font-size:12px;">Belum ada data untuk tanggal ini.</div>`}
        </div>
        <div>
          <div class="bs-col-title bs-sell">Top 5 Sell</div>
          ${dSell.length ? dSell.map(r=>barHtml(r,"bs-fill-sell","sell")).join("") : `<div class="empty-box" style="padding:16px;font-size:12px;">Belum ada data untuk tanggal ini.</div>`}
        </div>
      </div>

      <details class="bs-editor-panel" id="dbsEditorPanel" ${state.detailBsEditorOpen?"open":""}>
        <summary>✏️ Input / Edit Manual (dari screenshot Stockbit Anda)</summary>
        <div class="bs-editor-grid">
          <div>
            <div class="bs-col-title bs-buy">Top 5 Buy</div>
            <div class="bs-header-row"><span>Broker</span><span>Lot</span><span>Nilai (Rp)</span></div>
            ${editRowsHtml(buyEdit,"Buy")}
          </div>
          <div>
            <div class="bs-col-title bs-sell">Top 5 Sell</div>
            <div class="bs-header-row"><span>Broker</span><span>Lot</span><span>Nilai (Rp)</span></div>
            ${editRowsHtml(sellEdit,"Sell")}
          </div>
        </div>
        <div class="bs-toolbar" style="margin-top:12px;">
          <button class="btn btn-primary" id="dbsSaveBtn">Simpan ke Database</button>
        </div>
        <div class="bs-csv-panel">
          <label>Atau tempel CSV (format per baris: side,rank,broker_code,lot,value_idr)</label>
          <textarea id="dbsCsvInput" rows="6" placeholder="buy,1,YP,1200000,45000000000">${escapeHtml(state.detailBsCsvText||"")}</textarea>
          <button class="btn btn-outline" id="dbsCsvFillBtn">Isi ke Form dari CSV</button>
        </div>
      </details>`;
}

// Mode periode (rentang tanggal): agregasi Top 5 Buy/Sell (jumlah Lot &
// Nilai) SELAMA rentang "Dari"–"Sampai", dihitung dari baris broker_activity
// harian yang sudah ada di database (data yang sama dengan mode tanggal
// tunggal, cuma dijumlahkan per broker lintas hari). Murni tampilan — tidak
// ada editor manual di sini (edit tetap lewat mode 🗓️ Tanggal per hari).
function renderDetailBrokerSummaryRangeBody(){
  const agg = state.detailBsRangeAgg || { buy: [], sell: [] };
  const allVals = [...agg.buy, ...agg.sell].map(r => Number(r.value_idr) || 0);
  const maxVal = Math.max(1, ...allVals);
  const barHtml = (r, cls) => `
    <div class="bs-bar-row">
      <span class="bs-bar-broker mono">${escapeHtml(r.broker_code)}${r.investor_type ? ` <span style="font-size:9px;color:var(--muted);font-weight:400;">(${escapeHtml(r.investor_type)})</span>` : ""}</span>
      <div class="bs-bar-track"><div class="bs-bar-fill ${cls}" style="width:${(Number(r.value_idr)/maxVal)*100}%"></div></div>
      <span class="bs-bar-value mono">${fmtNum(r.value_idr)} <span style="color:var(--muted);font-size:10px;">· ${r.days}h</span></span>
    </div>`;

  return `
      <div class="bs-display-grid">
        <div>
          <div class="bs-col-title bs-buy">Top 5 Buy (akumulasi periode)</div>
          ${agg.buy.length ? agg.buy.map(r=>barHtml(r,"bs-fill-buy")).join("") : `<div class="empty-box" style="padding:16px;font-size:12px;">Belum ada data untuk periode ini. Isi dulu lewat mode 🗓️ Tanggal (input manual/CSV di tab 📊 Broker Summary).</div>`}
        </div>
        <div>
          <div class="bs-col-title bs-sell">Top 5 Sell (akumulasi periode)</div>
          ${agg.sell.length ? agg.sell.map(r=>barHtml(r,"bs-fill-sell")).join("") : `<div class="empty-box" style="padding:16px;font-size:12px;">Belum ada data untuk periode ini. Isi dulu lewat mode 🗓️ Tanggal (input manual/CSV di tab 📊 Broker Summary).</div>`}
        </div>
      </div>
      <div style="font-size:10.5px;color:var(--muted);margin-top:10px;">
        Nilai = total akumulasi Lot/Nilai broker tsb selama periode yang dipilih (bukan rata-rata harian). "h" = jumlah hari broker itu masuk Top 5 pada rentang ini. Mode Periode hanya untuk melihat ringkasan — untuk input/edit data manual per hari, beralih ke mode 🗓️ Tanggal.
      </div>`;
}

// Tarik breakdown "distribute_to" (lawan transaksi) untuk SATU broker+sisi
// secara live dari Stockbit, lalu tampilkan di counterpartyPanelHtml (lihat
// renderDetailBrokerSummarySingleBody). Toggle: klik broker yang panelnya
// sudah terbuka akan menutupnya lagi tanpa fetch ulang.
async function loadDetailBsCounterparty(side, code){
  const key = `${side.toUpperCase()}:${code}`;
  if(state.detailBsCounterpartyOpenCode === key){
    state.detailBsCounterpartyOpenCode = null;
    render();
    return;
  }
  const ticker = state.detailTicker;
  state.detailBsCounterpartyOpenCode = key;
  state.detailBsCounterpartyLoading = true;
  state.detailBsCounterpartyMsg = "";
  state.detailBsCounterpartyRows = [];
  state.detailBsCounterpartyDate = null;
  render();
  try{
    const raw = await stockbitFetchBrokerDistribution(ticker);
    if(raw?.error) throw new Error(raw.error);
    const parsed = parseStockbitDistributeTo(raw, code, side);
    if(!parsed){
      state.detailBsCounterpartyMsg = `Broker ${code} tidak ditemukan di respons Stockbit untuk hari bursa terakhir (kemungkinan broker ini baru masuk Top 5 di tanggal yang berbeda dari hari terakhir — endpoint breakdown ini cuma menyediakan hari bursa terakhir, lihat catatan STOCKBIT_DISTRIBUTE_EP).`;
    } else {
      state.detailBsCounterpartyRows = parsed.rows;
      state.detailBsCounterpartyDate = parsed.date;
    }
  } catch(e){
    state.detailBsCounterpartyMsg = "Gagal memuat lawan transaksi: " + e.message;
  }
  state.detailBsCounterpartyLoading = false;
  render();
}

async function loadDetailBrokerSummary(){
  const ticker = state.detailTicker;
  if(!SUPABASE_URL || !SUPABASE_KEY){ openSettings(); return; }

  if(state.detailBsRangeMode) return loadDetailBrokerSummaryRange();

  const dateEl = document.getElementById("dbsDate");
  const date = dateEl?.value || "";
  state.detailBsDate = date;
  // Ganti tanggal -> breakdown lawan transaksi yang lagi terbuka (kalau ada)
  // sudah tidak relevan lagi (data live utk broker+tanggal sebelumnya), jadi
  // ditutup supaya tidak menampilkan info basi/menyesatkan.
  state.detailBsCounterpartyOpenCode = null;
  state.detailBsCounterpartyMsg = "";
  if(!ticker || !date){ state.detailBsMsg = "Tanggal belum diisi."; state.detailBsMsgError = true; render(); return; }

  state.detailBsLoading = true; state.detailBsMsg = ""; render();
  try {
    // CATATAN MIGRASI: baca broker_activity (bukan broker_summary lagi) --
    // tidak ada kolom rank, jadi urutkan value_idr desc lalu ambil Top 5/sisi
    // DI SINI, sama seperti loadBrokerSummary() di tab Broker Summary utama.
    const qs = new URLSearchParams({ stock_code: `eq.${ticker}`, trade_date: `eq.${date}`, order: "side.asc,value_idr.desc" });
    const res = await fetch(`${SUPABASE_URL}/broker_activity?${qs}`, { headers: getSupaHeaders(), cache: "no-store" });
    if(!res.ok) throw new Error(`HTTP ${res.status} ${res.statusText}`);
    const rawRows = await res.json();
    const bySide = { buy: [], sell: [] };
    rawRows.forEach(r => { if(bySide[r.side]) bySide[r.side].push(r); });
    const top5 = side => bySide[side].slice(0,5).map((r,i)=>({ ...r, rank:i+1 }));
    const rows = [...top5("buy"), ...top5("sell")];
    state.detailBsRows = rows;
    state.detailBsEditRows = rows.map(r=>({ side:r.side, rank:r.rank, broker_code:r.broker_code, lot:r.lot, value_idr:r.value_idr }));
    state.detailBsMsg = rawRows.length
      ? `Menampilkan Top 5/sisi (dari ${rawRows.length} baris broker_activity hari ini).`
      : "Belum ada data broker_activity untuk tanggal ini.";
    state.detailBsMsgError = false;
  } catch(e) {
    state.detailBsMsg = "Gagal memuat: " + e.message;
    state.detailBsMsgError = true;
  }
  state.detailBsLoading = false;
  render();
}

// Mode periode: tarik SEMUA baris broker_activity ticker ini dalam rentang
// tanggal Dari–Sampai (inklusif di kedua ujung, dua filter trade_date lewat
// URLSearchParams.append supaya PostgREST membacanya sebagai AND: gte + lte
// pada kolom yang sama — kalau dibuat lewat object biasa, key kedua akan
// menimpa key pertama karena namanya sama), lalu jumlahkan Lot & Nilai per
// broker+side lintas hari untuk dapat Top 5 Buy/Sell akumulasi periode.
async function loadDetailBrokerSummaryRange(){
  const ticker = state.detailTicker;
  const fromEl = document.getElementById("dbsDateFrom");
  const toEl = document.getElementById("dbsDateTo");
  const from = fromEl?.value || state.detailBsDateFrom || "";
  const to = toEl?.value || state.detailBsDateTo || "";
  state.detailBsDateFrom = from;
  state.detailBsDateTo = to;

  if(!ticker || !from || !to){ state.detailBsMsg = 'Tanggal "Dari" dan "Sampai" belum diisi.'; state.detailBsMsgError = true; render(); return; }
  if(from > to){ state.detailBsMsg = 'Tanggal "Dari" harus sebelum atau sama dengan "Sampai".'; state.detailBsMsgError = true; render(); return; }

  state.detailBsLoading = true; state.detailBsMsg = ""; render();
  try {
    const qs = new URLSearchParams();
    qs.append("stock_code", `eq.${ticker}`);
    qs.append("trade_date", `gte.${from}`);
    qs.append("trade_date", `lte.${to}`);
    qs.append("order", "trade_date.asc,side.asc"); // broker_activity tidak punya kolom rank
    const res = await fetch(`${SUPABASE_URL}/broker_activity?${qs.toString()}`, { headers: getSupaHeaders(), cache: "no-store" });
    if(!res.ok) throw new Error(`HTTP ${res.status} ${res.statusText}`);
    const rows = await res.json();

    if(!rows.length){
      state.detailBsRangeAgg = { buy: [], sell: [] };
      state.detailBsRangeDatesCount = 0;
      state.detailBsMsg = `Belum ada data broker_activity untuk ${ticker} pada periode ${from} s/d ${to}.`;
      state.detailBsMsgError = true;
    } else {
      const datesSet = new Set(rows.map(r=>r.trade_date));
      const agg = {};
      rows.forEach(r=>{
        const key = r.side + "|" + r.broker_code;
        if(!agg[key]) agg[key] = { side: r.side, broker_code: r.broker_code, lot: 0, value_idr: 0, days: 0, investor_type: r.investor_type || null };
        agg[key].lot += Number(r.lot) || 0;
        agg[key].value_idr += Number(r.value_idr) || 0;
        agg[key].days += 1;
        if(!agg[key].investor_type && r.investor_type) agg[key].investor_type = r.investor_type;
      });
      const aggArr = Object.values(agg);
      const buy = aggArr.filter(a=>a.side==="buy").sort((a,b)=>b.value_idr-a.value_idr).slice(0,5);
      const sell = aggArr.filter(a=>a.side==="sell").sort((a,b)=>b.value_idr-a.value_idr).slice(0,5);
      state.detailBsRangeAgg = { buy, sell };
      state.detailBsRangeDatesCount = datesSet.size;
      state.detailBsMsg = `Menampilkan agregasi ${rows.length} baris dari ${datesSet.size} hari trading (${from} s/d ${to}).`;
      state.detailBsMsgError = false;
    }
  } catch(e) {
    state.detailBsMsg = "Gagal memuat: " + e.message;
    state.detailBsMsgError = true;
    state.detailBsRangeAgg = { buy: [], sell: [] };
  }
  state.detailBsLoading = false;
  render();
}

// CATATAN MIGRASI: sama seperti readBsEditorRows() di tab Broker Summary
// utama -- rank cuma dipakai untuk posisi slot editor, TIDAK dikirim ke
// Supabase (broker_activity tidak punya kolom rank/avg_price, unik per
// broker_code+trade_date+stock_code+side).
function readDbsEditorRows(side, code, date){
  const label = side === "buy" ? "Buy" : "Sell";
  const rows = [];
  for(let i=0;i<5;i++){
    const brokerEl = document.getElementById(`dbs${label}Broker${i}`);
    const lotEl = document.getElementById(`dbs${label}Lot${i}`);
    const valEl = document.getElementById(`dbs${label}Value${i}`);
    const broker_code = (brokerEl?.value||"").trim().toUpperCase();
    const value_idr = valEl?.value;
    if(!broker_code || !value_idr) continue;
    const lot = lotEl?.value ? Number(lotEl.value) : null;
    rows.push({
      stock_code: code, trade_date: date, side,
      broker_code, lot,
      value_idr: Number(value_idr)
    });
  }
  return rows;
}

async function saveDetailBrokerSummaryRows(){
  const code = state.detailTicker;
  const date = state.detailBsDate || document.getElementById("dbsDate")?.value;
  if(!code || !date){ state.detailBsMsg = "Tanggal belum diisi."; state.detailBsMsgError = true; render(); return; }
  if(!SUPABASE_URL || !SUPABASE_KEY){ openSettings(); return; }

  const rows = [...readDbsEditorRows("buy", code, date), ...readDbsEditorRows("sell", code, date)];
  if(!rows.length){ state.detailBsMsg = "Belum ada baris terisi."; state.detailBsMsgError = true; render(); return; }

  try {
    await supaFetch(`${SUPABASE_URL}/broker_activity?on_conflict=broker_code,trade_date,stock_code,side`, {
      method: "POST",
      headers: { ...getSupaHeaders(), "Prefer": "resolution=merge-duplicates,return=representation" },
      body: JSON.stringify(rows)
    });
    state.detailBsMsg = `Tersimpan ${rows.length} baris.`;
    state.detailBsMsgError = false;
    state.detailBsEditorOpen = true;
    render();
    loadDetailBrokerSummary();
  } catch(e) {
    state.detailBsMsg = "Gagal menyimpan: " + e.message;
    state.detailBsMsgError = true;
    render();
  }
}

function fillDbsFromCsv(){
  const textEl = document.getElementById("dbsCsvInput");
  const text = textEl?.value || "";
  state.detailBsCsvText = text;
  try {
    const lines = text.trim().split("\n").filter(Boolean);
    const rows = lines.map(line=>{
      const [side, rank, broker_code, lot, value_idr] = line.split(",").map(s=>s.trim());
      if(side!=="buy" && side!=="sell") throw new Error(`side harus 'buy'/'sell', dapat: "${side}"`);
      return {
        side, rank: Number(rank),
        broker_code: (broker_code||"").toUpperCase(),
        lot: lot ? Number(lot) : null,
        value_idr: Number(value_idr)
      };
    });
    state.detailBsEditRows = rows;
    state.detailBsEditorOpen = true;
    state.detailBsMsg = "CSV berhasil dibaca ke form. Cek lagi lalu klik Simpan.";
    state.detailBsMsgError = false;
  } catch(e) {
    state.detailBsMsg = "Format CSV tidak valid: " + e.message;
    state.detailBsMsgError = true;
  }
  render();
}

function renderDetailHistorical(s){
  const ticker = s.ticker;
  let rows = state.detailHistoricalRows || [];
  rows = tableSortRows("detailHistorical", rows, {
    date: r=>r.date, close: r=>r.close, change: r=>r.change, value: r=>r.value,
    volume: r=>r.volume, netForeign: r=>r.netForeign,
  });
  const periodBtn = (key, label) => `<button type="button" class="btn ${state.detailHistoricalPeriod===key?'btn-primary':'btn-outline'}" data-hist-period="${key}" ${state.detailHistoricalLoading?"disabled":""}>${label}</button>`;

  registerTableExport("detailHistorical", () => rows, [
    { label: "Date", get: "date" }, { label: "Close", get: r=>r.close!=null?Math.round(r.close):"" },
    { label: "Change", get: r=>r.change!=null?Math.round(r.change*100)/100:"" },
    { label: "Change %", get: r=>r.changePct!=null?Math.round(r.changePct*100)/100:"" },
    { label: "Value", get: r=>r.value!=null?Math.round(r.value):"" },
    { label: "Volume", get: r=>r.volume!=null?Math.round(r.volume):"" },
    { label: "Net Foreign", get: r=>r.netForeign!=null?Math.round(r.netForeign):"" },
  ], `Historical_${ticker}`);

  const tableRows = rows.map(r => `
    <tr>
      <td class="mono">${escapeHtml(r.date)}</td>
      <td class="mono" style="text-align:right;">${r.close!=null?fmtNum(r.close):"-"}</td>
      <td class="mono" style="text-align:right;color:${(r.change??0)>=0?'var(--up)':'var(--down)'}">${r.change!=null?dNum(r.change,{plusSign:true}):"-"}${r.changePct!=null?` (${dNum(r.changePct,{plusSign:true,decimals:2,suffix:'%'})})`:""}</td>
      <td class="mono" style="text-align:right;">${r.value!=null?fmtNum(r.value):"-"}</td>
      <td class="mono" style="text-align:right;">${r.volume!=null?fmtNum(r.volume):"-"}</td>
      <td class="mono" style="text-align:right;color:${r.netForeign==null?'inherit':(r.netForeign>=0?'var(--up)':'var(--down)')}" title="Foreign Buy: ${r.foreignBuy!=null?fmtNum(r.foreignBuy):'-'} · Foreign Sell: ${r.foreignSell!=null?fmtNum(r.foreignSell):'-'}">${r.netForeign!=null?dNum(r.netForeign,{plusSign:true}):"-"}</td>
    </tr>`).join("");

  return `
    <div class="bs-wrap">
      <div class="bs-toolbar" style="flex-wrap:wrap;gap:8px;">
        <span class="mono" style="font-weight:700;font-size:14px;">${escapeHtml(ticker)}</span>
        ${periodBtn("daily","Daily")}
        ${periodBtn("weekly","Weekly")}
        ${periodBtn("monthly","Monthly")}
        <button class="btn btn-outline" id="dhistDbBtn" ${state.detailHistoricalLoading?"disabled":""} title="Baca dari tabel flows di Supabase (data yang sudah pernah ditarik, dari IDX maupun Stockbit) — tidak memanggil Stockbit sama sekali.">${state.detailHistoricalLoading?"Memuat...":"🔄 Muat dari Database"}</button>
        <button class="btn btn-outline" id="dhistLoadBtn" ${state.detailHistoricalLoading?"disabled":""} title="Panggil langsung endpoint Stockbit (live) lalu simpan manual ke database.">${state.detailHistoricalLoading?"Menarik data...":"⬇️ Tarik Data dari Stockbit"}</button>
        ${rows.length ? `<button class="btn btn-outline" id="dhistSaveBtn">💾 Simpan ke Database</button>` : ""}
        ${rows.length ? `<button class="btn btn-outline" id="dhistCompareBtn" ${state.detailCompareLoading?"disabled":""} style="color:#a78bfa;border-color:rgba(167,139,250,0.4);">${state.detailCompareLoading?"Membandingkan...":"🔍 Bandingkan dengan IDX"}</button>` : ""}
        ${rows.length ? tableExportBtnHtml("detailHistorical") : ""}
      </div>

      ${state.detailHistoricalMsg ? `<div class="bs-msg ${state.detailHistoricalMsgError?"bs-msg-error":"bs-msg-ok"}">${escapeHtml(state.detailHistoricalMsg)}</div>` : ""}

      ${!rows.length ? `<div class="empty-box" style="margin-top:12px;">Belum ada data. Klik "🔄 Muat dari Database" di atas kalau sudah pernah ditarik sebelumnya (lewat sini atau "Tarik Otomatis" di tab Screener), atau klik "⬇️ Tarik Data dari Stockbit" untuk menariknya langsung (butuh Token Stockbit &amp; Endpoint Historical Data terisi di ⚙️ Pengaturan).</div>` : `
      <div style="overflow-x:auto;margin-top:12px;">
        <table style="width:100%;border-collapse:collapse;font-size:12.5px;">
          <thead>
            <tr style="color:var(--muted);text-align:right;">
              ${tableSortTh("detailHistorical","Date","date","text-align:left;padding:6px 8px;")}
              ${tableSortTh("detailHistorical","Close","close","padding:6px 8px;")}
              ${tableSortTh("detailHistorical","Change","change","padding:6px 8px;")}
              ${tableSortTh("detailHistorical","Value","value","padding:6px 8px;")}
              ${tableSortTh("detailHistorical","Volume","volume","padding:6px 8px;")}
              ${tableSortTh("detailHistorical","Net Foreign","netForeign","padding:6px 8px;")}
            </tr>
          </thead>
          <tbody>${tableRows}</tbody>
        </table>
      </div>`}

      ${state.detailCompareMsg || (state.detailCompareRows && state.detailCompareRows.length) ? `
      <div style="margin-top:16px;">
        <details id="dhistComparePanel" ${state.detailCompareOpen?"open":""}>
          <summary style="cursor:pointer; font-size:12px; color:var(--muted); user-select:none;">
            🔍 Bandingkan dengan IDX (flows) ${state.detailCompareMsg ? `— ${escapeHtml(state.detailCompareMsg)}` : ""}
          </summary>
          ${state.detailCompareRows && state.detailCompareRows.length ? `
          <div style="overflow-x:auto;margin-top:10px;">
            <table style="width:100%;border-collapse:collapse;font-size:11.5px;">
              <thead>
                <tr style="color:var(--muted);text-align:right;">
                  <th style="text-align:left;padding:6px 8px;">Date</th>
                  <th style="padding:6px 8px;" colspan="2">Close (SB / IDX)</th>
                  <th style="padding:6px 8px;" colspan="2">Value (SB / IDX)</th>
                  <th style="padding:6px 8px;" colspan="2">Volume (SB / IDX)</th>
                  <th style="padding:6px 8px;" colspan="2">Net Foreign (SB / IDX)</th>
                </tr>
              </thead>
              <tbody>
                ${state.detailCompareRows.map(r => {
                  const pctDiff = (a,b) => (a==null||b==null||b===0) ? null : Math.abs((a-b)/b);
                  const cellPair = (a,b,fmt=fmtNum) => {
                    const diff = pctDiff(a,b);
                    const warn = diff != null && diff > 0.01; // beda >1% -> tandai kuning
                    const color = a==null||b==null ? 'var(--muted)' : (warn ? 'var(--gold)' : 'inherit');
                    return `<td class="mono" style="text-align:right;color:${color};">${a!=null?fmt(a):"-"}</td><td class="mono" style="text-align:right;color:var(--muted);">${b!=null?fmt(b):"-"}</td>`;
                  };
                  return `<tr>
                    <td class="mono">${escapeHtml(r.date)}</td>
                    ${cellPair(r.closeSb, r.closeIdx)}
                    ${cellPair(r.valueSb, r.valueIdx)}
                    ${cellPair(r.volumeSb, r.volumeIdx)}
                    ${cellPair(r.netForeignSb, r.netForeignIdx, (v)=>dNum(v,{plusSign:true}))}
                  </tr>`;
                }).join("")}
              </tbody>
            </table>
            <div style="font-size:10.5px;color:var(--muted);margin-top:6px;">
              Kolom kiri tiap pasangan = Stockbit, kanan = IDX (<code>flows</code>). Angka <span style="color:var(--gold);">kuning</span> = beda &gt;1% antar sumber (bukan error — dua penyedia data independen, wajar sedikit beda metodologi/timing).
            </div>
          </div>` : ""}
        </details>
      </div>` : ""}
    </div>`;
}

// Bantu tab Historical Data: `flows` sekarang cuma menyimpan granularitas
// HARIAN (period weekly/monthly di price_history_stockbit_old dulu hampir tidak
// pernah dibaca ulang, jadi tidak dibawa ke migrasi flows+src -- lihat
// catatan migrasi). Kalau user pilih tampilan Mingguan/Bulanan, baris harian
// dari flows digabung di sini, mirip chartAggregateWeekly() tapi menyimpan
// juga value/frequency/foreign & menghitung change/change% antar-periode
// (bukan antar-hari).
function detailHistoricalPeriodKey(dateStr, period){
  const d = new Date(dateStr);
  if(period === "monthly") return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`;
  return chartIsoWeekKey(dateStr); // "weekly"
}
function aggregateDetailHistorical(dailyRowsAsc, period){
  if(period === "daily") return dailyRowsAsc;
  const groups = new Map();
  dailyRowsAsc.forEach(r => {
    const key = detailHistoricalPeriodKey(r.date, period);
    (groups.get(key) || groups.set(key, []).get(key)).push(r);
  });
  const out = [...groups.values()].map(g => {
    const first = g[0], last = g[g.length - 1];
    const highs = g.map(r => chartOhlcOr(r.high, r.close)).filter(v => v != null);
    const lows = g.map(r => chartOhlcOr(r.low, r.close)).filter(v => v != null);
    const hasFb = g.every(r => r.foreignBuy != null), hasFs = g.every(r => r.foreignSell != null);
    const fb = hasFb ? g.reduce((a, r) => a + Number(r.foreignBuy), 0) : null;
    const fs = hasFs ? g.reduce((a, r) => a + Number(r.foreignSell), 0) : null;
    return {
      date: last.date,
      open: chartOhlcOr(first.open, first.close),
      high: highs.length ? Math.max(...highs) : null,
      low: lows.length ? Math.min(...lows) : null,
      close: last.close,
      value: g.reduce((a, r) => a + (Number(r.value) || 0), 0),
      volume: g.reduce((a, r) => a + (Number(r.volume) || 0), 0),
      frequency: g.reduce((a, r) => a + (Number(r.frequency) || 0), 0),
      foreignBuy: fb, foreignSell: fs,
      netForeign: (fb != null && fs != null) ? (fb - fs) : null,
    };
  });
  out.sort((a, b) => a.date < b.date ? -1 : a.date > b.date ? 1 : 0);
  // change / change% dihitung antar-periode (bar ke bar), sama pola dengan daily di bawah
  out.forEach((r, i) => {
    const prev = i > 0 ? out[i - 1] : null;
    r.change = prev && prev.close != null && r.close != null ? r.close - prev.close : null;
    r.changePct = prev && prev.close ? ((r.close - prev.close) / prev.close) * 100 : null;
  });
  return out;
}

// Sumber UTAMA untuk tab Historical Data di modal Detail: baca dari tabel
// `flows` (sejak migrasi flows+src, gabungan IDX + hasil "⬇️ Tarik Data dari
// Stockbit" di sini ATAU "Tarik Otomatis" bulk di toolbar Screener -- yang
// mana pun sumbernya, tersimpan sebagai baris `flows` biasa). Dipanggil
// otomatis tiap kali tab historical dibuka / tombol period diganti (lihat
// setDetailTab & wiring data-hist-period), TIDAK memanggil Stockbit sama
// sekali. Kalau memang perlu data ter-baru yang belum ada di database, pakai
// tombol "⬇️ Tarik Data dari Stockbit" (loadDetailHistorical, live ke
// Stockbit lalu simpan sendiri). Granularitas Mingguan/Bulanan dihitung di
// sini dari baris harian (lihat aggregateDetailHistorical), bukan dibaca
// dari kolom period terpisah seperti dulu.
async function loadDetailHistoricalFromDb(period){
  const ticker = state.detailTicker;
  if(period) state.detailHistoricalPeriod = period;
  if(!ticker) return;
  if(!SUPABASE_URL || !SUPABASE_KEY){ openSettings(); return; }

  state.detailHistoricalLoading = true; state.detailHistoricalMsg = ""; render();
  try {
    const qs = new URLSearchParams({
      ticker: `eq.${ticker}`,
      order: "date.asc",
      select: "date,close,value,volume,open_price,high,low,frequency,foreign_buy,foreign_sell"
    });
    const res = await fetch(`${SUPABASE_URL}/flows?${qs}`, { headers: getSupaHeaders(), cache: "no-store" });
    if(!res.ok) throw new Error(`HTTP ${res.status} ${res.statusText}`);
    const rawRows = await res.json();
    const daily = rawRows.map(r => ({
      date: r.date, close: numOrNull(r.close), value: numOrNull(r.value), volume: numOrNull(r.volume),
      open: numOrNull(r.open_price), high: numOrNull(r.high), low: numOrNull(r.low),
      frequency: numOrNull(r.frequency), foreignBuy: numOrNull(r.foreign_buy), foreignSell: numOrNull(r.foreign_sell),
    }));
    daily.forEach((r, i) => {
      const prev = i > 0 ? daily[i - 1] : null;
      r.change = prev && prev.close != null && r.close != null ? r.close - prev.close : null;
      r.changePct = prev && prev.close ? ((r.close - prev.close) / prev.close) * 100 : null;
      r.netForeign = (r.foreignBuy != null && r.foreignSell != null) ? (r.foreignBuy - r.foreignSell) : null;
    });
    const rows = aggregateDetailHistorical(daily, state.detailHistoricalPeriod);
    state.detailHistoricalRows = rows;
    state.detailHistoricalMsg = rows.length
      ? `Menampilkan ${rows.length} baris dari database (${state.detailHistoricalPeriod}).`
      : `Belum ada data tersimpan di database untuk ${ticker}. Klik "⬇️ Tarik Data dari Stockbit" di bawah, atau pakai "Tarik Otomatis" di tab Screener untuk mengisi database dulu.`;
    state.detailHistoricalMsgError = !rows.length;
  } catch(e) {
    state.detailHistoricalMsg = "Gagal memuat dari database: " + e.message;
    state.detailHistoricalMsgError = true;
    state.detailHistoricalRows = [];
  }
  state.detailHistoricalLoading = false;
  render();
}

// Sumber ALTERNATIF (manual/live): tarik langsung dari Stockbit lewat
// endpoint yang diisi di ⚙️ Pengaturan. Dipicu tombol "⬇️ Tarik Data dari
// Stockbit" — bukan lagi jalur otomatis tab historical (lihat
// loadDetailHistoricalFromDb di atas untuk itu). Hasilnya TIDAK otomatis
// tersimpan; klik "💾 Simpan ke Database" setelahnya (saveDetailHistoricalRows)
// supaya ikut muncul lewat loadDetailHistoricalFromDb lain kali.
async function loadDetailHistorical(period){
  const ticker = state.detailTicker;
  if(period) state.detailHistoricalPeriod = period;
  if(!ticker) return;
  state.detailHistoricalLoading = true; state.detailHistoricalMsg = ""; render();
  // Pakai versi paginasi otomatis (stockbitFetchHistoricalRange), BUKAN
  // stockbitFetchHistorical satu-halaman langsung -- limit defaultnya cuma
  // 50/halaman (lihat catatan di stockbitFetchHistoricalRange), jadi kalau
  // manggil versi satu-halaman di sini, rentang default setahun bakal diam2
  // kepotong jadi cuma 50 baris terbaru tanpa pemberitahuan ke user.
  const res = await stockbitFetchHistoricalRange(ticker, state.detailHistoricalPeriod);
  if(res.error && (!res.rows || !res.rows.length)){
    state.detailHistoricalMsg = res.error;
    state.detailHistoricalMsgError = true;
    state.detailHistoricalRows = [];
  } else {
    const parsed = res.rows;
    if(!parsed || !parsed.length){
      state.detailHistoricalMsg = "Response diterima tapi formatnya tidak dikenali atau kosong. Cek console (F12) untuk lihat JSON mentahnya, lalu sesuaikan parseStockbitHistorical() di app.js.";
      state.detailHistoricalMsgError = true;
      state.detailHistoricalRows = [];
      console.log("Stockbit historical raw response:", res.raw);
    } else {
      state.detailHistoricalRows = parsed;
      state.detailHistoricalMsg = res.error
        ? `Menarik ${parsed.length} baris (${state.detailHistoricalPeriod}) -- SEBAGIAN halaman gagal di tengah jalan (${res.error}), jadi datanya mungkin belum lengkap sampai tanggal paling lama. Klik "💾 Simpan ke Database" untuk simpan yang berhasil didapat, atau coba tarik ulang.`
        : `Berhasil menarik ${parsed.length} baris (${state.detailHistoricalPeriod}) langsung dari Stockbit. Klik "💾 Simpan ke Database" supaya tersimpan permanen dan muncul lagi lewat "🔄 Muat dari Database".`;
      state.detailHistoricalMsgError = !!res.error;
    }
  }
  state.detailHistoricalLoading = false;
  render();
}

// Simpan hasil tarik LIVE dari Stockbit (loadDetailHistorical) ke database.
// Sejak migrasi flows+src, hanya granularitas HARIAN yang disimpan --
// `flows` tidak lagi punya kolom period terpisah untuk weekly/monthly
// (baca catatan di aggregateDetailHistorical). Kalau user sedang melihat
// tampilan Mingguan/Bulanan (hasil live-pull dari Stockbit, bukan agregasi
// lokal), tidak ada baris harian untuk disimpan -- pengguna diarahkan untuk
// menarik ulang dengan periode Harian dulu.
async function saveDetailHistoricalRows(){
  const ticker = state.detailTicker;
  const rows = state.detailHistoricalRows || [];
  if(!ticker || !rows.length) return;
  if(!SUPABASE_URL || !SUPABASE_KEY){ openSettings(); return; }
  if(state.detailHistoricalPeriod !== "daily"){
    state.detailHistoricalMsg = 'Hanya data Harian yang disimpan ke database (Mingguan/Bulanan otomatis dihitung dari data harian saat ditampilkan). Pilih periode "Harian", tarik ulang dari Stockbit, baru simpan.';
    state.detailHistoricalMsgError = true;
    render(); return;
  }
  try{
    const payload = rows.map(r => ({
      ticker, date: r.date, src: "stockbit",
      close: r.close, value: r.value, volume: r.volume,
      open_price: r.open, high: r.high, low: r.low, frequency: r.frequency,
      foreign_buy: r.foreignBuy, foreign_sell: r.foreignSell
    }));
    await supaFetch(`${SUPABASE_URL}/flows?on_conflict=ticker,date`, {
      method: "POST",
      headers: { ...getSupaHeaders(), "Prefer": "resolution=merge-duplicates,return=representation" },
      body: JSON.stringify(payload)
    });
    state.detailHistoricalMsg = `Tersimpan ${payload.length} baris ke tabel flows.`;
    state.detailHistoricalMsgError = false;
  } catch(e){
    state.detailHistoricalMsg = "Gagal menyimpan: " + e.message;
    state.detailHistoricalMsgError = true;
  }
  render();
}

// ==========================================
// TAB "🕵️ INSIDER" — daftar transaksi insider / pemegang saham utama per
// ticker (endpoint exodus.stockbit.com/insider/company/majorholder, lihat
// STOCKBIT_DEFAULT_INSIDER_EP). Beda dari Historical Data: tidak disimpan
// ke Supabase (murni live-pull tiap dibuka/difilter/ganti halaman), karena
// datanya jarang berubah dan volumenya kecil per ticker.
// ==========================================
// Pasangan %+lembar (dipakai kolom Changes/Previous/Current) — panah naik/
// turun cuma ditampilkan untuk Changes (satu-satunya kolom yang punya arah).
function insiderPctSharesCell(pct, shares, dir){
  if(pct==null && shares==null) return "-";
  const arrow = dir==="up" ? `<span style="color:var(--up);">↗</span> ` : dir==="down" ? `<span style="color:var(--down);">↘</span> ` : "";
  const color = dir==="up" ? "var(--up)" : dir==="down" ? "var(--down)" : "inherit";
  return `<div style="color:${color};">${arrow}${pct!=null?dNum(pct,{decimals:2,suffix:'%'}):"-"}</div><div style="font-size:10.5px;color:var(--muted);">${shares!=null?fmtNum(shares):"-"}</div>`;
}

function renderDetailInsider(s){
  const ticker = s.ticker;
  const allRows = state.detailInsiderRows || [];

  // Filter Source (ALL/IDX/KSEI) & Action (dropdown) murni di sisi klien —
  // tidak fetch ulang ke Stockbit, cuma menyaring baris yang sudah ditarik
  // (endpoint yang dikasih user tidak kelihatan mendukung filter ini lewat
  // query param, beda dengan filter nama/tanggal yang memang ada di URL).
  const sources = [...new Set(allRows.map(r => r.source).filter(Boolean))];
  const actions = [...new Set(allRows.map(r => r.action).filter(Boolean))];
  const srcFilter = state.detailInsiderSourceFilter || "ALL";
  const actFilter = state.detailInsiderActionFilter || "ALL";
  let rows = allRows.filter(r =>
    (srcFilter==="ALL" || String(r.source).toUpperCase()===srcFilter) &&
    (actFilter==="ALL" || r.action===actFilter)
  );
  rows = tableSortRows("detailInsider", rows, {
    date: r=>r.date, name: r=>r.name, changes: r=>r.changesPct, previous: r=>r.previousPct,
    current: r=>r.currentPct, price: r=>r.price, broker: r=>r.broker,
    type: r=>r.entityType, action: r=>r.action, source: r=>r.source,
  });

  const sourcePill = (key, label) => `<button type="button" class="btn ${srcFilter===key?'btn-primary':'btn-outline'}" data-ins-source="${escapeHtml(key)}" style="padding:6px 14px;font-size:12px;border-radius:20px;">${escapeHtml(label)}</button>`;

  registerTableExport("detailInsider", () => rows, [
    { label: "Date", get: "date" }, { label: "Name", get: "name" },
    { label: "Changes %", get: r=>r.changesPct!=null?Math.round(r.changesPct*100)/100:"" },
    { label: "Changes Shares", get: r=>r.changesShares!=null?Math.round(r.changesShares):"" },
    { label: "Previous %", get: r=>r.previousPct!=null?Math.round(r.previousPct*100)/100:"" },
    { label: "Previous Shares", get: r=>r.previousShares!=null?Math.round(r.previousShares):"" },
    { label: "Current %", get: r=>r.currentPct!=null?Math.round(r.currentPct*100)/100:"" },
    { label: "Current Shares", get: r=>r.currentShares!=null?Math.round(r.currentShares):"" },
    { label: "Price", get: r=>r.price!=null?Math.round(r.price):"" },
    { label: "Broker", get: r=>r.broker||"-" }, { label: "Type", get: r=>r.entityType||"-" },
    { label: "Action", get: r=>r.action||"-" }, { label: "Source", get: r=>r.source||"-" },
  ], `Insider_${ticker}`);

  const tableRows = rows.map(r => {
    const actionColor = r.isBuy ? "var(--up)" : r.isSell ? "var(--down)" : "var(--muted)";
    return `
    <tr>
      <td class="mono">${r.date ? escapeHtml(r.date) : "-"}</td>
      <td>${escapeHtml(r.name)}</td>
      <td style="text-align:right;">${insiderPctSharesCell(r.changesPct, r.changesShares, r.changesDir)}</td>
      <td style="text-align:right;color:var(--muted);">${insiderPctSharesCell(r.previousPct, r.previousShares, null)}</td>
      <td style="text-align:right;">${insiderPctSharesCell(r.currentPct, r.currentShares, null)}</td>
      <td class="mono" style="text-align:right;">${r.price!=null?fmtNum(r.price):"-"}</td>
      <td style="text-align:center;">${r.broker?escapeHtml(String(r.broker)):"-"}</td>
      <td style="text-align:center;">${r.entityType?escapeHtml(String(r.entityType)):"-"}</td>
      <td style="text-align:center;"><span style="color:${actionColor};font-weight:700;">${r.action!=null?escapeHtml(String(r.action)):"-"}</span></td>
      <td style="text-align:center;color:var(--muted);font-size:11px;">${r.source?escapeHtml(String(r.source)):"-"}</td>
    </tr>`;
  }).join("");

  return `
    <div class="bs-wrap">
      <div class="bs-toolbar" style="flex-wrap:wrap;gap:8px;">
        <span class="mono" style="font-weight:700;font-size:14px;">${escapeHtml(ticker)}</span>
        <input id="dinsFilterName" class="bs-input" type="text" placeholder="Filter nama insider (opsional)" value="${escapeHtml(state.detailInsiderFilterName||"")}" style="min-width:160px;">
        <input id="dinsDateFrom" class="bs-input" type="date" value="${state.detailInsiderDateFrom||""}" title="Dari tanggal (opsional)">
        <span style="color:var(--muted);">–</span>
        <input id="dinsDateTo" class="bs-input" type="date" value="${state.detailInsiderDateTo||""}" title="Sampai tanggal (opsional)">
        <button class="btn btn-outline" id="dinsLoadBtn" ${state.detailInsiderLoading?"disabled":""}>${state.detailInsiderLoading?"Menarik data...":"⬇️ Muat dari Stockbit"}</button>
      </div>

      ${state.detailInsiderMsg ? `<div class="bs-msg ${state.detailInsiderMsgError?"bs-msg-error":"bs-msg-ok"}">${escapeHtml(state.detailInsiderMsg)}</div>` : ""}

      ${!allRows.length ? `<div class="empty-box" style="margin-top:12px;">Belum ada data. Klik "⬇️ Muat dari Stockbit" di atas (butuh Token Stockbit &amp; Endpoint Insider terisi di ⚙️ Pengaturan).</div>` : `
      <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px;margin-top:12px;">
        <div style="display:flex;gap:6px;">
          ${sourcePill("ALL","ALL")}
          ${sources.map(src => sourcePill(String(src).toUpperCase(), String(src).toUpperCase())).join("")}
        </div>
        ${actions.length ? `<select id="dinsActionFilter" class="bs-input" style="max-width:180px;">
          <option value="ALL" ${actFilter==="ALL"?"selected":""}>All Action</option>
          ${actions.map(a => `<option value="${escapeHtml(a)}" ${actFilter===a?"selected":""}>${escapeHtml(a)}</option>`).join("")}
        </select>` : ""}
        ${tableExportBtnHtml("detailInsider")}
      </div>
      <div style="overflow-x:auto;margin-top:12px;">
        <table style="width:100%;border-collapse:collapse;font-size:12.5px;">
          <thead>
            <tr style="color:var(--muted);text-align:right;">
              ${tableSortTh("detailInsider","Date","date","text-align:left;padding:6px 8px;")}
              ${tableSortTh("detailInsider","Name","name","text-align:left;padding:6px 8px;")}
              ${tableSortTh("detailInsider","Changes","changes","padding:6px 8px;")}
              ${tableSortTh("detailInsider","Previous","previous","padding:6px 8px;")}
              ${tableSortTh("detailInsider","Current","current","padding:6px 8px;")}
              ${tableSortTh("detailInsider","Price","price","padding:6px 8px;")}
              ${tableSortTh("detailInsider","Broker","broker","padding:6px 8px;text-align:center;")}
              ${tableSortTh("detailInsider","Type","type","padding:6px 8px;text-align:center;")}
              ${tableSortTh("detailInsider","Action","action","padding:6px 8px;text-align:center;")}
              ${tableSortTh("detailInsider","Source","source","padding:6px 8px;text-align:center;")}
            </tr>
          </thead>
          <tbody>${tableRows}</tbody>
        </table>
        ${!rows.length ? `<div class="empty-box" style="margin-top:10px;">Tidak ada baris yang cocok dengan filter Source/Action di atas.</div>` : ""}
      </div>
      <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:10px;">
        <button type="button" class="btn btn-outline" id="dinsPrevBtn" ${(state.detailInsiderLoading || state.detailInsiderPage<=1)?"disabled":""} style="padding:6px 12px;font-size:12px;">‹ Sebelumnya</button>
        <span class="mono" style="font-size:11.5px;color:var(--muted);">Halaman ${state.detailInsiderPage}</span>
        <button type="button" class="btn btn-outline" id="dinsNextBtn" ${(state.detailInsiderLoading || !state.detailInsiderHasMore)?"disabled":""} style="padding:6px 12px;font-size:12px;">Berikutnya ›</button>
      </div>
      <details style="margin-top:10px;"><summary style="cursor:pointer;font-size:11px;color:var(--teal);">Lihat JSON mentah</summary>
        <pre style="white-space:pre-wrap;word-break:break-all;font-size:10.5px;max-height:260px;overflow:auto;background:rgba(0,0,0,0.15);padding:10px;border-radius:8px;margin-top:6px;">${escapeHtml(JSON.stringify(state.detailInsiderRaw, null, 2))}</pre>
      </details>`}
    </div>`;
}

async function loadDetailInsider(opts = {}){
  const ticker = state.detailTicker;
  if(!ticker) return;
  if(opts.resetPage) state.detailInsiderPage = 1;
  if(opts.page) state.detailInsiderPage = opts.page;
  state.detailInsiderLoading = true; state.detailInsiderMsg = ""; render();
  const res = await stockbitFetchInsider(ticker, {
    insider: state.detailInsiderFilterName,
    dateStart: state.detailInsiderDateFrom,
    dateEnd: state.detailInsiderDateTo,
    page: state.detailInsiderPage,
  });
  if(res.error){
    state.detailInsiderMsg = res.error;
    state.detailInsiderMsgError = true;
    state.detailInsiderRows = [];
    state.detailInsiderRaw = res.raw ?? null;
    state.detailInsiderHasMore = false;
  } else {
    state.detailInsiderRaw = res.raw;
    const parsed = parseStockbitInsider(res.raw);
    if(!parsed || !parsed.length){
      state.detailInsiderMsg = state.detailInsiderPage > 1
        ? "Tidak ada data lagi di halaman ini."
        : "Response diterima tapi formatnya tidak dikenali atau memang kosong untuk ticker/filter ini. Cek \"Lihat JSON mentah\" di bawah, lalu sesuaikan parseStockbitInsider() di app.js kalau formatnya ternyata dikenali tapi salah tebak nama field.";
      state.detailInsiderMsgError = state.detailInsiderPage <= 1;
      if(state.detailInsiderPage > 1) state.detailInsiderPage -= 1; // batal maju kalau halaman berikutnya ternyata kosong
      state.detailInsiderHasMore = false;
    } else {
      state.detailInsiderRows = parsed;
      state.detailInsiderMsg = `Menampilkan ${parsed.length} baris (halaman ${state.detailInsiderPage}) dari Stockbit.`;
      state.detailInsiderMsgError = false;
      const nextPage = res.raw?.data?.paginate?.next_page || res.raw?.paginate?.next_page || null;
      state.detailInsiderHasMore = !!nextPage;
    }
  }
  state.detailInsiderLoading = false;
  render();
}

// ==========================================
// PANEL "BANDINGKAN DENGAN IDX" — validasi silang angka hasil tarik LIVE
// dari Stockbit (state.detailHistoricalRows, BELUM disimpan) vs baris yang
// sudah ada di `flows` (bisa src='idx' atau src='stockbit' dari tarikan
// sebelumnya) untuk ticker & rentang tanggal yang sama. Panel ini murni buat
// verifikasi manual sebelum klik "💾 Simpan ke Database", tidak mengubah
// data apa pun.
// ==========================================
async function loadDetailCompare(){
  const ticker = state.detailTicker;
  const rows = state.detailHistoricalRows || [];
  if(!ticker || !rows.length){
    state.detailCompareMsg = 'Tarik data Stockbit dulu (tombol "⬇️ Tarik Data dari Stockbit" di atas) sebelum membandingkan.';
    render(); return;
  }
  state.detailCompareLoading = true; state.detailCompareMsg = ""; render();
  try{
    const dates = rows.map(r => r.date).filter(Boolean);
    const qs = new URLSearchParams({
      ticker: `eq.${ticker}`,
      date: `in.(${dates.join(",")})`,
      select: "date,close,value,volume,foreign_buy,foreign_sell",
    });
    const res = await fetch(`${SUPABASE_URL}/flows?${qs}`, { headers: getSupaHeaders(), cache: "no-store" });
    if(!res.ok) throw new Error(`HTTP ${res.status}`);
    const flowsRows = await res.json();
    const idxByDate = {};
    flowsRows.forEach(r => { idxByDate[r.date] = r; });

    const combined = rows.map(r => {
      const idx = idxByDate[r.date];
      return {
        date: r.date,
        closeSb: r.close, closeIdx: idx?.close ?? null,
        valueSb: r.value, valueIdx: idx?.value ?? null,
        volumeSb: r.volume, volumeIdx: idx?.volume ?? null,
        netForeignSb: r.netForeign,
        netForeignIdx: (idx?.foreign_buy != null && idx?.foreign_sell != null) ? (idx.foreign_buy - idx.foreign_sell) : null,
      };
    });
    state.detailCompareRows = combined;
    const matchedCount = combined.filter(r => r.closeIdx != null).length;
    state.detailCompareMsg = matchedCount
      ? `${matchedCount}/${combined.length} hari ditemukan juga di \`flows\` (IDX).`
      : `Tidak ada tanggal yang cocok di \`flows\` untuk ${ticker} — kemungkinan sync-idx-full.mjs belum pernah menjangkau ticker/periode ini.`;
    state.detailCompareOpen = true;
  }catch(e){
    state.detailCompareMsg = "Gagal membandingkan: " + e.message;
    state.detailCompareRows = [];
  }
  state.detailCompareLoading = false;
  render();
}

// ==========================================
// TARIK OTOMATIS (BULK) — Historical Data untuk banyak ticker sekaligus,
// dipicu dari toolbar tab Screener (mirip Tarik Otomatis Broker Summary).
// Beda dengan broker summary: endpoint historical TIDAK menerima rentang
// tanggal ({ticker}+{period} saja), jadi per ticker cukup SATU request,
// lalu hasilnya disaring ke rentang Dari-Sampai yang dipilih di UI.
// ==========================================
async function fetchExistingHistoricalDates(ticker, dates){
  if(!dates.length) return new Set();
  try{
    const qs = new URLSearchParams({
      ticker: `eq.${ticker}`,
      date: `in.(${dates.join(",")})`,
      select: "date",
    });
    const res = await fetch(`${SUPABASE_URL}/flows?${qs}`, { headers: getSupaHeaders(), cache: "no-store" });
    if(!res.ok) return new Set();
    const rows = await res.json();
    return new Set(rows.map(r => r.date));
  }catch(e){
    return new Set();
  }
}

async function fetchAndSaveHistoricalBulk(tickers, rangeFrom, rangeTo){
  if(state.stockbitHistoricalBulkLoading) return;
  if(!tickers || !tickers.length){
    state.stockbitHistoricalBulkResults = [{ ticker:"-", date:"-", ok:false, msg:"Centang minimal 1 saham di tab Screener dulu." }];
    render(); return;
  }
  if(!state.stockbitToken){ openSettings(); return; }
  if(!state.stockbitHistoricalEndpoint){
    state.stockbitHistoricalBulkResults = [{ ticker:"-", date:"-", ok:false, msg:'Isi dulu "Endpoint Historical Data" di ⚙️ Pengaturan.' }];
    render(); return;
  }
  if(!SUPABASE_URL || !SUPABASE_KEY){ openSettings(); return; }

  const tradingDates = tradingDaysInRange(rangeFrom, rangeTo);
  if(!tradingDates.length){
    state.stockbitHistoricalBulkResults = [{ ticker:"-", date:"-", ok:false, msg:'Periode tanggal tidak valid atau tidak ada hari bursa di rentang itu — cek lagi tanggal "Dari" dan "Sampai".' }];
    render(); return;
  }
  const fromDate = tradingDates[0];
  const toDate = tradingDates[tradingDates.length - 1];
  const latestDate = toDate; // hari bursa paling baru — tetap ditarik ulang walau sudah ada, sama seperti broker summary

  state.stockbitHistoricalBulkLoading = true;
  state.stockbitHistoricalBulkProgress = { done: 0, total: tickers.length };
  state.stockbitHistoricalBulkResults = [];
  render();

  for(const ticker of tickers){
    const existingDates = await fetchExistingHistoricalDates(ticker, tradingDates);
    const neededDates = tradingDates.filter(d => !existingDates.has(d) || d === latestDate);

    if(!neededDates.length){
      state.stockbitHistoricalBulkResults.push({ ticker, date: `${fromDate}..${toDate}`, ok:true, msg: `Semua ${tradingDates.length} hari sudah ada di database, dilewati (tidak ada request ke Stockbit).` });
      state.stockbitHistoricalBulkProgress.done++;
      render();
      continue;
    }

    // Dulu di sini manggil stockbitFetchHistorical() langsung dengan
    // limit = jumlah hari bursa di rentang (bisa 300+ utk rentang setahun) —
    // itu penyebab "HTTP 400 — Invalid parameter" massal (lihat catatan di
    // stockbitFetchHistoricalRange). Sekarang pakai versi paginasi otomatis
    // yang selalu request dengan limit aman (50) lalu ikuti next_page.
    const res = await stockbitFetchHistoricalRange(ticker, "daily", { startDate: fromDate, endDate: toDate });
    if(res.error && (!res.rows || !res.rows.length)){
      state.stockbitHistoricalBulkResults.push({ ticker, date: `${fromDate}..${toDate}`, ok:false, msg: res.error });
      console.log(`Stockbit historical ERROR (${ticker}):`, res.error, "raw:", res.raw);
    } else {
      const parsed = res.rows;
      if(!parsed || !parsed.length){
        state.stockbitHistoricalBulkResults.push({ ticker, date: `${fromDate}..${toDate}`, ok:false, msg: "Response diterima tapi formatnya tidak dikenali atau kosong (cek console)." });
        console.log(`Stockbit historical raw response (${ticker}):`, res.raw);
      } else {
        if(res.error) console.log(`Stockbit historical PARTIAL (${ticker}) — ada halaman yang gagal tapi sebagian data (${parsed.length} baris) berhasil didapat:`, res.error);
        const inRange = parsed.filter(r => r.date >= fromDate && r.date <= toDate);
        if(!inRange.length){
          state.stockbitHistoricalBulkResults.push({ ticker, date: `${fromDate}..${toDate}`, ok:false, msg: `Endpoint mengembalikan ${parsed.length} baris tapi tidak ada yang jatuh di rentang ${fromDate}..${toDate} — kemungkinan start_date/end_date/limit di endpoint belum sesuai skema aslinya (cek raw JSON di console).` });
        } else {
          try{
            const payload = inRange.map(r => ({
              ticker, date: r.date, src: "stockbit",
              close: r.close, value: r.value, volume: r.volume,
              open_price: r.open, high: r.high, low: r.low, frequency: r.frequency,
              foreign_buy: r.foreignBuy, foreign_sell: r.foreignSell
            }));
            await supaFetch(`${SUPABASE_URL}/flows?on_conflict=ticker,date`, {
              method: "POST",
              headers: { ...getSupaHeaders(), "Prefer": "resolution=merge-duplicates,return=representation" },
              body: JSON.stringify(payload)
            });
            const gotDates = new Set(inRange.map(r=>r.date));
            const missing = neededDates.filter(d => !gotDates.has(d));
            state.stockbitHistoricalBulkResults.push({ ticker, date: `${fromDate}..${toDate}`, ok:true,
              msg: `Tersimpan ${payload.length} baris${missing.length ? ` (${missing.length} hari tidak ada di respons endpoint: ${missing.join(", ")})` : ""}.` });
          } catch(e){
            state.stockbitHistoricalBulkResults.push({ ticker, date: `${fromDate}..${toDate}`, ok:false, msg: "Gagal simpan ke DB: " + e.message });
          }
        }
      }
    }
    state.stockbitHistoricalBulkProgress.done++;
    render();
    await new Promise(r => setTimeout(r, 300)); // jeda antar-ticker, jaga rate limit Stockbit
  }

  state.stockbitHistoricalBulkLoading = false;
  render();
  _btHistMeta.at = 0; // data historical baru saja masuk — jangan pakai cache riwayat Backtest
  Promise.resolve(loadLive()).catch(() => {});
}

// ==========================================
// UPDATE INDIKATOR TEKNIKAL (client-side, sumber Stockbit, bukan IDX)
//
// sync-idx-full.mjs menghitung indikator teknikal dari tabel `flows`
// (diisi lewat IDX + curl, wajib jalan dari koneksi rumah karena
// Cloudflare menyaring berdasarkan sidik jari TLS — TIDAK BISA dipanggil
// dari browser). Blok ini adalah versi paralel yang menghitung indikator
// PERSIS DENGAN RUMUS YANG SAMA, tapi dari tabel `flows` (bisa src idx atau stockbit)
// (diisi lewat tombol "📅 Historical (Daily)" Stockbit di atas, yang
// memang sudah jalan dari browser tanpa masalah CORS/Cloudflare).
//
// Konsekuensi: kolom yang butuh histori sangat panjang (52w high/low,
// YTD, avg volume 3 bulan) akan null sampai `flows`
// untuk ticker itu benar-benar berisi >=252 / dari awal tahun / >=63 hari
// bursa — tarik "Historical (Daily)" dengan rentang tanggal yang cukup
// panjang dulu kalau butuh kolom-kolom itu terisi.
//
// Kolom fundamental (PER/PBV/ROE/dst, diisi Yahoo lewat sync-idx-full.mjs)
// SENGAJA tidak disentuh sama sekali di sini — upsert Supabase hanya
// menimpa kolom yang memang dikirim, kolom lain di baris yang sudah ada
// tetap seperti sebelumnya.
// ==========================================
const TI_MIN_BARS_FOR_CALC = 30;
const TI_MIN_BARS_52W = 252;
const TI_MIN_BARS_3M_VOL = 63;

const ti_average = (arr) => (!arr.length ? 0 : arr.reduce((a, b) => a + (b || 0), 0) / arr.length);
const ti_round2 = (n) => (n == null || Number.isNaN(n) ? null : Math.round(n * 100) / 100);
const ti_round1 = (n) => (n == null || Number.isNaN(n) ? null : Math.round(n * 10) / 10);

function ti_calcEMA(data, period) {
  if (!data || data.length < period) return null;
  const k = 2 / (period + 1);
  let ema = ti_average(data.slice(0, period));
  for (let i = period; i < data.length; i++) ema = (data[i] - ema) * k + ema;
  return ema;
}
function ti_calcRSI(data, period) {
  if (data.length <= period) return 50;
  let gains = 0, losses = 0;
  for (let i = 1; i <= period; i++) {
    const c = data[i] - data[i - 1];
    if (c > 0) gains += c; else losses -= c;
  }
  let avgGain = gains / period, avgLoss = losses / period;
  for (let i = period + 1; i < data.length; i++) {
    const c = data[i] - data[i - 1];
    avgGain = (avgGain * (period - 1) + Math.max(c, 0)) / period;
    avgLoss = (avgLoss * (period - 1) + Math.max(-c, 0)) / period;
  }
  if (avgLoss === 0) return 100;
  return 100 - 100 / (1 + avgGain / avgLoss);
}
function ti_calcEMASeries(data, period) {
  const arr = new Array(data.length).fill(null);
  if (data.length < period) return arr;
  const k = 2 / (period + 1);
  let ema = ti_average(data.slice(0, period));
  arr[period - 1] = ema;
  for (let i = period; i < data.length; i++) { ema = (data[i] - ema) * k + ema; arr[i] = ema; }
  return arr;
}
function ti_calcMACDFull(data) {
  const fastArr = ti_calcEMASeries(data, 12);
  const slowArr = ti_calcEMASeries(data, 26);
  const macdSeries = [];
  for (let i = 0; i < data.length; i++) { if (fastArr[i] != null && slowArr[i] != null) macdSeries.push(fastArr[i] - slowArr[i]); }
  if (macdSeries.length === 0) return { macd: 0, signal: 0, hist: 0, histPrev: 0 };
  const signalPeriod = 9;
  const signalSeries = new Array(macdSeries.length).fill(null);
  if (macdSeries.length < signalPeriod) {
    const avg = ti_average(macdSeries);
    for (let i = 0; i < macdSeries.length; i++) signalSeries[i] = avg;
  } else {
    const k = 2 / (signalPeriod + 1);
    let signal = ti_average(macdSeries.slice(0, signalPeriod));
    signalSeries[signalPeriod - 1] = signal;
    for (let i = signalPeriod; i < macdSeries.length; i++) { signal = (macdSeries[i] - signal) * k + signal; signalSeries[i] = signal; }
  }
  const histSeries = macdSeries.map((m, i) => (signalSeries[i] != null ? m - signalSeries[i] : null));
  const last = macdSeries.length - 1;
  const macd = macdSeries[last];
  const signal = signalSeries[last] != null ? signalSeries[last] : macd;
  const hist = histSeries[last] != null ? histSeries[last] : 0;
  const histPrev = (last > 0 && histSeries[last - 1] != null) ? histSeries[last - 1] : hist;
  return { macd, signal, hist, histPrev };
}
function ti_calcSMA(data, period) { if (!data || data.length < period) return null; return ti_average(data.slice(-period)); }
function ti_calcStdDev(arr) { const m = ti_average(arr); return Math.sqrt(arr.reduce((sq, n) => sq + Math.pow(n - m, 2), 0) / arr.length); }
function ti_calcATR(highs, lows, closes, period) {
  if (closes.length < period + 1) return null;
  const trs = [];
  for (let i = 1; i < closes.length; i++) {
    const h = highs[i] != null ? highs[i] : closes[i];
    const l = lows[i] != null ? lows[i] : closes[i];
    const pc = closes[i - 1];
    trs.push(Math.max(h - l, Math.abs(h - pc), Math.abs(l - pc)));
  }
  return ti_average(trs.slice(-period));
}
// --- Deteksi Swing High/Low (fractal pivot) ---
// Dipakai sbg basis alternatif utk Fibonacci extension yang lebih akurat
// dibanding window tetap 20 hari (yang gampang motong swing asli kalau
// high/low sebenarnya terjadi di luar 20 hari terakhir).
// Sebuah bar dianggap "pivot high" kalau high-nya lebih tinggi dari
// `leftRight` bar di kiri DAN kanan; sebaliknya utk "pivot low".
// Loop berjalan maju di waktu, jadi assignment terakhir = pivot paling baru
// dalam window `lookback`.
function ti_detectSwingPoints(highsArr, lowsArr, lookback, leftRight) {
  lookback = lookback || 60; leftRight = leftRight || 3;
  const n = highsArr.length;
  const start = Math.max(leftRight, n - lookback);
  let swingHigh = null, swingHighIdx = -1, swingLow = null, swingLowIdx = -1;
  for (let i = start; i < n - leftRight; i++) {
    const h = highsArr[i], l = lowsArr[i];
    if (h == null || l == null) continue;
    let isPivotHigh = true, isPivotLow = true;
    for (let j = i - leftRight; j <= i + leftRight; j++) {
      if (j === i) continue;
      if (highsArr[j] == null || lowsArr[j] == null) continue;
      if (highsArr[j] > h) isPivotHigh = false;
      if (lowsArr[j] < l) isPivotLow = false;
    }
    if (isPivotHigh) { swingHigh = h; swingHighIdx = i; }
    if (isPivotLow) { swingLow = l; swingLowIdx = i; }
  }
  return { swingHigh, swingHighIdx, swingLow, swingLowIdx };
}

// --- Backtest Fibonacci TP: hit-rate historis ---
// Simulasi murni dari data historis (bukan proyeksi ke depan): tiap kali
// harga breakout dari resistance window20 (dihitung dari data SEBELUM bar
// itu, jadi bebas lookahead-bias), catat entry + level TP/SL dgn logic yang
// SAMA seperti fibTpSetup live (basis Swing kalau valid, window20 kalau
// tidak), lalu scan forward `forwardBars` hari utk lihat level mana yang
// tersentuh duluan sebelum SL kena. `cooldown` bar dipakai supaya breakout
// yang berturut-turut nggak dihitung sbg sinyal terpisah-pisah.
function ti_simulateFibTpSignals(bars, opts) {
  opts = opts || {};
  const forwardBars = opts.forwardBars || 60;
  const cooldown = opts.cooldown || 10;
  const swingLookback = opts.swingLookback || 90;
  const highs = bars.map((b) => b.high), lows = bars.map((b) => b.low);
  const n = bars.length;
  const minIdx = Math.max(swingLookback, 25);
  const signals = [];
  let lastSignalIdx = -Infinity;
  for (let i = minIdx; i < n - 1; i++) {
    if (i - lastSignalIdx < cooldown) continue;
    const hPrior = highs.slice(0, i), lPrior = lows.slice(0, i);
    const window20H = hPrior.slice(-20), window20L = lPrior.slice(-20);
    if (window20H.length < 20) continue;
    const resistancePrior = Math.max(...window20H);
    const supportPrior = Math.min(...window20L);
    const today = bars[i];
    if (today.close == null || today.close <= resistancePrior) continue; // butuh breakout
    const swingLB = Math.min(i, swingLookback);
    const swingRaw = ti_detectSwingPoints(hPrior.slice(-swingLB), lPrior.slice(-swingLB), swingLB, 3);
    const useSwing = swingRaw.swingLow != null && swingRaw.swingHigh != null &&
      swingRaw.swingHigh > swingRaw.swingLow && swingRaw.swingLowIdx < swingRaw.swingHighIdx;
    const basisHigh = useSwing ? swingRaw.swingHigh : resistancePrior;
    const basisLow = useSwing ? swingRaw.swingLow : supportPrior;
    if (basisHigh <= basisLow) continue;
    const fibRange = basisHigh - basisLow;
    const entry = today.close;
    const slFib = basisHigh - fibRange * 0.618;
    if (slFib >= entry) continue; // setup tidak valid kalau SL sudah di atas entry
    const tp1 = basisHigh + fibRange * 0.272;
    const tp2 = basisHigh + fibRange * 0.618;
    const tp3 = basisHigh + fibRange * 1.0;
    const tp4 = basisHigh + fibRange * 1.618;

    let slHit = false, tp1Hit = false, tp2Hit = false, tp3Hit = false, tp4Hit = false;
    let barsToSl = null, barsToTp1 = null, barsToTp2 = null, barsToTp3 = null, barsToTp4 = null;
    const endIdx = Math.min(n - 1, i + forwardBars);
    for (let j = i + 1; j <= endIdx; j++) {
      const bar = bars[j];
      if (bar.low == null || bar.high == null) continue;
      if (!slHit && bar.low <= slFib) { slHit = true; barsToSl = j - i; }
      if (!tp1Hit && bar.high >= tp1) { tp1Hit = true; barsToTp1 = j - i; }
      if (!tp2Hit && bar.high >= tp2) { tp2Hit = true; barsToTp2 = j - i; }
      if (!tp3Hit && bar.high >= tp3) { tp3Hit = true; barsToTp3 = j - i; }
      if (!tp4Hit && bar.high >= tp4) { tp4Hit = true; barsToTp4 = j - i; }
      if (slHit && tp1Hit && tp2Hit && tp3Hit && tp4Hit) break;
    }
    // "win" per level = level tersentuh sebelum (atau di hari yang sama dengan) SL kena
    const winTp = (hit, barsToHit) => hit && (!slHit || barsToHit <= barsToSl);
    signals.push({
      idx: i, date: today.date, entry, basis: useSwing ? "swing" : "window20",
      slFib, tp1, tp2, tp3, tp4,
      tp1Win: winTp(tp1Hit, barsToTp1), tp2Win: winTp(tp2Hit, barsToTp2),
      tp3Win: winTp(tp3Hit, barsToTp3), tp4Win: winTp(tp4Hit, barsToTp4),
      slHit, barsToSl, barsToTp1, barsToTp2, barsToTp3, barsToTp4,
    });
    lastSignalIdx = i;
  }
  return signals;
}
function ti_aggregateFibBacktest(signals) {
  const total = signals.length;
  const rate = (key) => (total ? (signals.filter((s) => s[key]).length / total) * 100 : null);
  const avgBars = (key) => {
    const vals = signals.filter((s) => s[key] != null).map((s) => s[key]);
    return vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : null;
  };
  return {
    total,
    tp1: { winRate: rate("tp1Win"), avgBars: avgBars("barsToTp1") },
    tp2: { winRate: rate("tp2Win"), avgBars: avgBars("barsToTp2") },
    tp3: { winRate: rate("tp3Win"), avgBars: avgBars("barsToTp3") },
    tp4: { winRate: rate("tp4Win"), avgBars: avgBars("barsToTp4") },
    slRate: rate("slHit"),
  };
}
async function runFibTpBacktest() {
  const ticker = state.detailTicker;
  if (!ticker) return;
  if (!SUPABASE_URL || !SUPABASE_KEY) { openSettings(); return; }
  state.fibBacktestLoading = true; state.fibBacktestTicker = ticker; state.fibBacktestMsg = ""; state.fibBacktestResult = null; render();
  try {
    const bars = await ti_fetchBarsFromDb(ticker);
    if (!bars || bars.length < 120) {
      state.fibBacktestMsg = `Data historis ${ticker} baru ${bars ? bars.length : 0} hari — minimal 120 hari supaya backtest-nya bermakna. Tarik dulu data "📅 Historical (Daily)" untuk rentang yang lebih panjang.`;
    } else {
      const signals = ti_simulateFibTpSignals(bars, {});
      if (!signals.length) {
        state.fibBacktestMsg = `Tidak ditemukan sinyal breakout historis di ${bars.length} hari data ${ticker}.`;
      } else {
        state.fibBacktestResult = ti_aggregateFibBacktest(signals);
      }
    }
  } catch (e) {
    state.fibBacktestMsg = "Gagal menjalankan backtest: " + e.message;
  }
  state.fibBacktestLoading = false;
  render();
}

// ==========================================
// SCAN BACKTEST FIBONACCI TP — SEMUA SAHAM (sub-tab "🔎 Scan Fib" di Backtest)
//
// Menjalankan engine yang SAMA dengan tombol "🧪 Backtest Historis Fibonacci
// TP" di detail saham (ti_simulateFibTpSignals), tetapi untuk seluruh saham
// di universe screener (state.stocks), lalu menampilkan hasilnya sebagai
// tabel yang bisa difilter/di-sort. Saham yang jumlah sinyal breakout
// historisnya cukup + win-rate-nya bagus bisa dicentang lalu dikirim ke
// Watchlist secara massal.
//
// - Data sumber: tabel flows (maks. 450 bar terbaru per
//   saham, lewat ti_fetchBarsFromDb). Saham dengan data < 120 hari dilewati.
// - Hasil scan disimpan di localStorage (LS_FIBSCAN) supaya tidak perlu scan
//   ulang tiap buka aplikasi. Filter (min sinyal, min win-rate, dst) hanya
//   memfilter hasil yang sudah ada -> mengubahnya TIDAK memicu scan ulang.
// - "Skor" memakai shrinkage (prior 50%, bobot 3 sinyal) supaya saham dengan
//   2 sinyal & win-rate 100% tidak otomatis mengalahkan saham dengan 10
//   sinyal & win-rate 80%.
// ==========================================
const LS_FIBSCAN = "ihsg_fibscan_v1";
const LS_FIBSCAN_FILTERS = "ihsg_fibscan_filters_v1";
const FIBSCAN_CONCURRENCY = 6;
const FIBSCAN_MAX_ROWS = 300;

function fibScanShrink(wins, total, k, prior){
  k = k == null ? 3 : k; prior = prior == null ? 0.5 : prior;
  return total > 0 ? (wins + prior * k) / (total + k) : prior;
}

// Ringkas hasil sinyal satu saham jadi satu baris tabel scan.
function ti_summarizeFibSignals(signals, bars){
  const total = signals.length;
  const cnt = (key) => signals.filter(s => s[key]).length;
  const avg = (key) => {
    const v = signals.filter(s => s[key] != null).map(s => s[key]);
    return v.length ? v.reduce((a,b) => a + b, 0) / v.length : null;
  };
  const pct = (n) => total ? (n / total) * 100 : null;
  const tp1n = cnt("tp1Win"), tp2n = cnt("tp2Win"), tp3n = cnt("tp3Win"), tp4n = cnt("tp4Win"), sln = cnt("slHit");
  const skor = 100 * (0.4 * fibScanShrink(tp1n, total) + 0.4 * fibScanShrink(tp2n, total) + 0.2 * (1 - fibScanShrink(sln, total)));
  // Rata-rata nilai transaksi 20 bar terakhir (filter likuiditas)
  const vals = bars.slice(-20).map(b => Number(b.value)).filter(v => Number.isFinite(v) && v > 0);
  const avgValue20 = vals.length ? vals.reduce((a,b) => a + b, 0) / vals.length : null;
  return {
    total,
    tp1Rate: pct(tp1n), tp2Rate: pct(tp2n), tp3Rate: pct(tp3n), tp4Rate: pct(tp4n), slRate: pct(sln),
    avgBarsTp1: avg("barsToTp1"), avgBarsTp2: avg("barsToTp2"),
    skor,
    lastSignalDate: signals[signals.length - 1].date,
    barsCount: bars.length,
    avgValue20,
  };
}

function loadFibScanCache(){
  try{
    const raw = JSON.parse(localStorage.getItem(LS_FIBSCAN) || "null");
    if(raw && Array.isArray(raw.results)){
      state.fibScan.results = raw.results;
      state.fibScan.ranAt = raw.ranAt || null;
      state.fibScan.partial = !!raw.partial;
      state.fibScan.scanned = raw.scanned || 0;
      state.fibScan.skipped = raw.skipped || 0;
    }
  }catch(e){}
  try{
    const f = JSON.parse(localStorage.getItem(LS_FIBSCAN_FILTERS) || "null");
    if(f && typeof f === "object") Object.assign(state.fibScan.filters, f);
  }catch(e){}
}
function saveFibScanFilters(){
  try{ localStorage.setItem(LS_FIBSCAN_FILTERS, JSON.stringify(state.fibScan.filters)); }catch(e){}
}

function fibScanUpdateProgressDom(){
  const fs = state.fibScan;
  const txt = document.getElementById("fibScanProgressText");
  const bar = document.getElementById("fibScanProgressBar");
  const pctDone = fs.total ? (fs.done / fs.total) * 100 : 0;
  if(txt) txt.textContent = `Memindai ${fs.done}/${fs.total} saham... (${fs.skipped} dilewati karena data < 120 hari, ${fs.errors} gagal)`;
  if(bar) bar.style.width = pctDone.toFixed(1) + "%";
}

async function runFibScanAll(){
  const fs = state.fibScan;
  if(fs.running) return;
  if(!SUPABASE_URL || !SUPABASE_KEY){ openSettings(); return; }
  const tickers = [...new Set((state.stocks || []).map(s => s.ticker).filter(Boolean))];
  if(!tickers.length){ fs.msg = "Universe saham masih kosong — muat data screener dulu."; render(); return; }

  fs.running = true; fs.cancel = false; fs.done = 0; fs.total = tickers.length;
  fs.skipped = 0; fs.errors = 0; fs.msg = ""; fs.selected = new Set();
  render();

  const results = [];
  let next = 0;
  const wait = (ms) => new Promise(r => setTimeout(r, ms));
  const worker = async () => {
    while(!fs.cancel){
      const my = next++;
      if(my >= tickers.length) break;
      const t = tickers[my];
      try{
        let bars;
        try{ bars = await ti_fetchBarsFromDb(t); }
        catch(e){ await wait(600); bars = await ti_fetchBarsFromDb(t); } // 1x retry
        if(!bars || bars.length < 120){
          fs.skipped++;
        }else{
          const signals = ti_simulateFibTpSignals(bars, {});
          if(signals.length) results.push(Object.assign({ ticker: t }, ti_summarizeFibSignals(signals, bars)));
        }
      }catch(e){ fs.errors++; }
      fs.done++;
      if(fs.done % 5 === 0 || fs.done === fs.total) fibScanUpdateProgressDom();
    }
  };
  await Promise.all(Array.from({ length: FIBSCAN_CONCURRENCY }, worker));

  fs.results = results;
  fs.ranAt = new Date().toISOString();
  fs.partial = fs.cancel;
  fs.scanned = fs.done;
  fs.running = false;
  fs.msg = fs.cancel
    ? `Scan dihentikan di ${fs.done}/${fs.total} saham — hasil parsial ditampilkan.`
    : `Scan selesai: ${results.length} saham punya minimal 1 sinyal breakout historis dari ${fs.done} saham yang dipindai.`;
  try{
    localStorage.setItem(LS_FIBSCAN, JSON.stringify({ ranAt: fs.ranAt, partial: fs.partial, scanned: fs.scanned, skipped: fs.skipped, results }));
  }catch(e){ /* kuota localStorage penuh -> hasil tetap ada di memori */ }
  render();
}

// Simpan banyak ticker sekaligus ke Watchlist (logika sama dengan
// saveToWatchlist(): harga close sekarang dicatat sbg harga entry, sinkron
// ke Supabase dalam SATU request, rollback lokal kalau gagal).
async function addTickersToWatchlistBulk(tickers){
  const baru = [...new Set(tickers)].filter(t => !state.watchlist.has(t));
  const sudahAda = new Set(tickers).size - baru.length;
  if(baru.length === 0) return alert("Semua saham yang dipilih sudah ada di watchlist.");
  const tglIso = todayLocalISO();
  let meta = {};
  try{ meta = JSON.parse(localStorage.getItem("ihsg_watchlist_meta") || "{}") || {}; }catch(e){}
  baru.forEach(t => {
    const s = (state.stocks || []).find(x => x.ticker === t);
    state.watchlist.add(t);
    meta[t] = { entry: Number(s?.cClose) || null, date: tglIso };
  });
  try{ localStorage.setItem("ihsg_watchlist_meta", JSON.stringify(meta)); }catch(e){}
  saveWatchlist();
  render();
  try{
    await supaFetch(`${SUPABASE_URL}/watchlists`, {
      method: "POST",
      headers: { ...getSupaHeaders(), "Prefer": "resolution=merge-duplicates" },
      body: JSON.stringify(baru.map(t => ({ ticker: t })))
    });
    alert(`${baru.length} saham berhasil disimpan ke Watchlist` + (sudahAda ? ` (${sudahAda} lainnya sudah ada sebelumnya).` : "."));
  }catch(e){
    baru.forEach(t => { state.watchlist.delete(t); delete meta[t]; });
    try{ localStorage.setItem("ihsg_watchlist_meta", JSON.stringify(meta)); }catch(_){}
    saveWatchlist();
    showError(`Gagal menyimpan watchlist ke Supabase: ${e.message}`);
    render();
  }
}

// Daftar hasil scan yang lolos filter angka + kotak pencarian, urut skor desc
// (atau kolom yang di-klik user). Dipakai render & tombol "Simpan Semua".
function getFibScanRows(){
  const fs = state.fibScan, f = fs.filters;
  const byTicker = new Map((state.stocks || []).map(s => [s.ticker, s]));
  const base = fs.results
    .filter(r =>
      r.total >= f.minSignals &&
      (r.tp1Rate ?? 0) >= f.minTp1 &&
      (r.tp2Rate ?? 0) >= f.minTp2 &&
      (r.slRate ?? 100) <= f.maxSl &&
      (!(f.minValueB > 0) || (r.avgValue20 != null && r.avgValue20 >= f.minValueB * 1e9)))
    .map(r => { const s = byTicker.get(r.ticker); return Object.assign({}, r, { name: s?.name || "", sektor: s?.sektor || "" }); })
    .sort((a,b) => b.skor - a.skor);
  const filtered = tableFilterRows("fibScan", base, r => [r.ticker, r.name, r.sektor]);
  return tableSortRows("fibScan", filtered, {
    ticker: r => r.ticker, total: r => r.total,
    tp1: r => r.tp1Rate, tp2: r => r.tp2Rate, tp3: r => r.tp3Rate, tp4: r => r.tp4Rate,
    sl: r => r.slRate, hari: r => r.avgBarsTp1, skor: r => r.skor, last: r => r.lastSignalDate,
  });
}

function renderFibScan(){
  const fs = state.fibScan, f = fs.filters;
  const rateCell = (v, goodFrom) => v == null ? "-"
    : `<span style="color:${v >= goodFrom ? 'var(--up)' : 'inherit'};font-weight:${v >= goodFrom ? 700 : 400};">${v.toFixed(0)}%</span>`;

  const ranAtText = fs.ranAt
    ? `Scan terakhir: ${new Date(fs.ranAt).toLocaleString("id-ID")} — ${fs.results.length} saham punya ≥1 sinyal${fs.partial ? " (parsial, scan dihentikan)" : ""}.`
    : "Belum pernah di-scan.";

  const header = `
    <div class="panel" style="align-items:center; gap:14px; margin-bottom:16px; flex-wrap:wrap;">
      <div style="font-size:12.5px; color:var(--muted); max-width:640px; line-height:1.55;">
        Menjalankan <b>Backtest Historis Fibonacci TP</b> untuk <b>semua saham</b> di universe screener (${(state.stocks||[]).length} saham), lalu menyaring yang jumlah sinyal breakout historisnya cukup &amp; win-rate-nya bagus untuk dijadikan kandidat Watchlist.
        Sumber: data <i>Historical (Daily)</i> yang tersimpan di database (maks. 400 hari; saham dengan data &lt; 120 hari dilewati) — tarik dulu lewat <b>Tarik Data Massal</b> di atas bila banyak yang kosong.
        <div style="margin-top:6px;">${escapeHtml(ranAtText)}</div>
      </div>
      <div style="margin-left:auto; display:flex; gap:8px;">
        ${fs.running
          ? `<button type="button" class="btn btn-outline" id="fibScanCancelBtn">⏹ Hentikan Scan</button>`
          : `<button type="button" class="btn btn-primary" id="fibScanRunBtn">🔎 ${fs.results.length ? "Scan Ulang" : "Jalankan Scan"} Semua Saham</button>`}
      </div>
    </div>`;

  const progress = fs.running ? `
    <div class="panel" style="flex-direction:column; align-items:stretch; margin-bottom:16px;">
      <div id="fibScanProgressText" style="font-size:12.5px; margin-bottom:8px;">Memindai ${fs.done}/${fs.total} saham... (${fs.skipped} dilewati karena data &lt; 120 hari, ${fs.errors} gagal)</div>
      <div style="height:8px; border-radius:6px; background:color-mix(in srgb, currentColor 12%, transparent); overflow:hidden;">
        <div id="fibScanProgressBar" style="height:100%; width:${fs.total ? (fs.done/fs.total*100).toFixed(1) : 0}%; background:var(--teal-grad, var(--up)); transition:width .2s;"></div>
      </div>
    </div>` : (fs.msg ? `<div class="detail-narrative" style="margin-bottom:16px;">${escapeHtml(fs.msg)}</div>` : "");

  const fld = (key, label, step, tip) => `
    <div class="field" style="min-width:130px;" ${tip ? `title="${escapeHtml(tip)}"` : ""}>
      <label style="font-size:10.5px;">${label}</label>
      <input type="number" step="${step}" min="0" data-fibscan-filter="${key}" value="${f[key]}" style="width:110px;">
    </div>`;
  const filters = `
    <div class="panel" style="gap:14px; margin-bottom:16px; flex-wrap:wrap; align-items:flex-end;">
      ${fld("minSignals", "Min. jumlah sinyal", 1, "Jumlah sinyal breakout historis minimum. Makin banyak sinyal, makin bisa dipercaya win-rate-nya.")}
      ${fld("minTp1", "Min. win-rate TP1 (%)", 5)}
      ${fld("minTp2", "Min. win-rate TP2 (%)", 5)}
      ${fld("maxSl", "Maks. kena SL (%)", 5)}
      ${fld("minValueB", "Min. rata-rata nilai transaksi 20D (Miliar Rp)", 0.5, "Filter likuiditas. 0 = nonaktif. Saham tanpa data nilai transaksi ikut tersingkir kalau diisi > 0.")}
      <div style="font-size:11px; color:var(--muted); max-width:300px; line-height:1.5;">Filter hanya menyaring hasil scan yang sudah ada — tidak memicu scan ulang.</div>
    </div>`;

  if(!fs.results.length){
    return header + progress + `<div class="empty-box">${fs.running ? "Scan sedang berjalan..." : "Belum ada hasil scan. Klik <b>Jalankan Scan Semua Saham</b>."}</div>`;
  }

  const all = getFibScanRows();
  const shown = all.slice(0, FIBSCAN_MAX_ROWS);
  registerTableExport("fibScan", () => all, [
    { label: "Ticker", get: "ticker" }, { label: "Nama", get: "name" }, { label: "Sektor", get: "sektor" },
    { label: "Jumlah Sinyal", get: "total" },
    { label: "Win-rate TP1 (%)", get: r=>r.tp1Rate!=null?Math.round(r.tp1Rate*10)/10:"" },
    { label: "Win-rate TP2 (%)", get: r=>r.tp2Rate!=null?Math.round(r.tp2Rate*10)/10:"" },
    { label: "Win-rate TP3 (%)", get: r=>r.tp3Rate!=null?Math.round(r.tp3Rate*10)/10:"" },
    { label: "Win-rate TP4 (%)", get: r=>r.tp4Rate!=null?Math.round(r.tp4Rate*10)/10:"" },
    { label: "Kena SL (%)", get: r=>r.slRate!=null?Math.round(r.slRate*10)/10:"" },
    { label: "Avg Hari ke TP1", get: r=>r.avgBarsTp1!=null?Math.round(r.avgBarsTp1):"" },
    { label: "Skor", get: r=>Math.round(r.skor*10)/10 },
    { label: "Sinyal Terakhir", get: r=>fmtDateID(r.lastSignalDate) },
  ], "FibScan_Backtest_IHSG");
  const shownSelectedAll = shown.length > 0 && shown.every(r => fs.selected.has(r.ticker));
  const selectedCount = [...fs.selected].filter(t => all.some(r => r.ticker === t)).length;

  const rows = shown.map(r => {
    const inWl = state.watchlist.has(r.ticker);
    return `<tr>
      <td><input type="checkbox" data-fibscan-check="${escapeHtml(r.ticker)}" ${fs.selected.has(r.ticker) ? "checked" : ""}></td>
      <td><button type="button" class="link-btn" data-bt-detail="${escapeHtml(r.ticker)}" style="font-weight:700;">${escapeHtml(r.ticker)}</button>
          ${inWl ? `<span class="pill pill-teal" style="margin-left:4px;">⭐ WL</span>` : ""}
          <div style="font-size:10.5px;color:var(--muted);max-width:180px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escapeHtml(r.name)}</div></td>
      <td class="mono" style="font-weight:700;">${r.total}</td>
      <td class="mono">${rateCell(r.tp1Rate, 70)}</td>
      <td class="mono">${rateCell(r.tp2Rate, 60)}</td>
      <td class="mono">${rateCell(r.tp3Rate, 50)}</td>
      <td class="mono">${rateCell(r.tp4Rate, 40)}</td>
      <td class="mono"><span style="color:${(r.slRate ?? 0) > 40 ? 'var(--down)' : 'inherit'};">${r.slRate != null ? r.slRate.toFixed(0) + "%" : "-"}</span></td>
      <td class="mono">${r.avgBarsTp1 != null ? r.avgBarsTp1.toFixed(0) + "h" : "-"}</td>
      <td class="mono" style="font-weight:700;">${r.skor.toFixed(0)}</td>
      <td class="mono" style="font-size:11.5px;">${fmtDateID(r.lastSignalDate)}</td>
    </tr>`;
  }).join("");

  const actions = `
    <div style="display:flex; gap:8px; flex-wrap:wrap; align-items:center; margin-bottom:10px;">
      <button type="button" class="btn btn-primary" id="fibScanSaveSel" ${selectedCount ? "" : "disabled"}>⭐ Simpan Terpilih ke Watchlist (${selectedCount})</button>
      <button type="button" class="btn btn-outline" id="fibScanSaveAll" ${all.length ? "" : "disabled"}>⭐ Simpan Semua yang Lolos (${all.length})</button>
      <span style="font-size:12px; color:var(--muted);">${all.length} saham lolos filter${all.length > FIBSCAN_MAX_ROWS ? ` — menampilkan ${FIBSCAN_MAX_ROWS} teratas` : ""}.</span>
    </div>`;

  return header + progress + filters + tableFilterBoxHtml("fibScan", "Cari ticker / nama / sektor...") + actions + `
    <div class="panel" style="flex-direction:column; align-items:stretch;">
      <div class="table-wrap">
        <table class="mono">
          <thead><tr>
            <th><input type="checkbox" id="fibScanSelectAll" ${shownSelectedAll ? "checked" : ""} title="Pilih semua yang tampil"></th>
            ${tableSortTh("fibScan", "Saham", "ticker")}
            ${tableSortTh("fibScan", "Sinyal", "total")}
            ${tableSortTh("fibScan", "TP1 127.2%", "tp1")}
            ${tableSortTh("fibScan", "TP2 161.8%", "tp2")}
            ${tableSortTh("fibScan", "TP3 200%", "tp3")}
            ${tableSortTh("fibScan", "TP4 261.8%", "tp4")}
            ${tableSortTh("fibScan", "Kena SL", "sl")}
            ${tableSortTh("fibScan", "Avg hari ke TP1", "hari")}
            ${tableSortTh("fibScan", "Skor", "skor")}
            ${tableSortTh("fibScan", "Sinyal Terakhir", "last")}
          </tr></thead>
          <tbody>${rows || `<tr><td colspan="11"><div class="empty-box">Tidak ada saham yang lolos filter. Longgarkan filter di atas.</div></td></tr>`}</tbody>
        </table>
      </div>
      <div style="font-size:11px; color:var(--muted); margin-top:10px; line-height:1.55;">
        <b>Skor</b> (0–100) = 40% win-rate TP1 + 40% win-rate TP2 + 20% (100% − kena SL), masing-masing dikoreksi shrinkage (prior 50% dengan bobot setara 3 sinyal) sehingga saham dengan sedikit sinyal tidak otomatis unggul cuma karena kebetulan 100%.
        Angka identik dengan tombol Backtest di detail saham (jendela maju 60 hari bursa; sinyal yang &lt; 60 hari lalu belum punya jendela penuh sehingga bisa terhitung "belum kena TP"). Ini data historis, bukan garansi hasil ke depan.
      </div>
    </div>`;
}

function wireFibScanControls(){
  const fs = state.fibScan;
  const runBtn = document.getElementById("fibScanRunBtn");
  if(runBtn) runBtn.onclick = () => runFibScanAll();
  const cancelBtn = document.getElementById("fibScanCancelBtn");
  if(cancelBtn) cancelBtn.onclick = () => { fs.cancel = true; cancelBtn.disabled = true; cancelBtn.textContent = "Menghentikan..."; };
  document.querySelectorAll("[data-fibscan-filter]").forEach(inp => {
    inp.onchange = (e) => {
      const v = parseFloat(e.target.value);
      fs.filters[inp.dataset.fibscanFilter] = Number.isFinite(v) && v >= 0 ? v : 0;
      saveFibScanFilters(); render();
    };
  });
  document.querySelectorAll("[data-fibscan-check]").forEach(cb => {
    cb.onchange = () => {
      const t = cb.dataset.fibscanCheck;
      cb.checked ? fs.selected.add(t) : fs.selected.delete(t);
      render();
    };
  });
  const selAll = document.getElementById("fibScanSelectAll");
  if(selAll) selAll.onchange = () => {
    const shown = getFibScanRows().slice(0, FIBSCAN_MAX_ROWS);
    shown.forEach(r => selAll.checked ? fs.selected.add(r.ticker) : fs.selected.delete(r.ticker));
    render();
  };
  const saveSel = document.getElementById("fibScanSaveSel");
  if(saveSel) saveSel.onclick = () => {
    const visible = new Set(getFibScanRows().map(r => r.ticker));
    addTickersToWatchlistBulk([...fs.selected].filter(t => visible.has(t)));
  };
  const saveAll = document.getElementById("fibScanSaveAll");
  if(saveAll) saveAll.onclick = () => {
    const list = getFibScanRows().map(r => r.ticker);
    if(!list.length) return;
    if(!confirm(`Simpan ${list.length} saham yang lolos filter ke Watchlist?`)) return;
    addTickersToWatchlistBulk(list);
  };
}

function ti_calcVWAP(closes, highs, lows, volumes, period) {
  const n = closes.length;
  if (!n) return null;
  const p = Math.min(period, n);
  let sumPV = 0, sumV = 0;
  for (let i = n - p; i < n; i++) {
    const h = highs[i] != null ? highs[i] : closes[i];
    const l = lows[i] != null ? lows[i] : closes[i];
    const typicalPrice = (h + l + closes[i]) / 3;
    const vol = volumes[i] || 0;
    sumPV += typicalPrice * vol; sumV += vol;
  }
  return sumV > 0 ? sumPV / sumV : null;
}
function ti_calcStochastic(highs, lows, closes, periodK, smoothK, periodD) {
  if (closes.length < periodK + smoothK + periodD) return { k: null, d: null, prevK: null, prevD: null };
  const rawK = [];
  for (let i = periodK - 1; i < closes.length; i++) {
    const hh = Math.max(...highs.slice(i - periodK + 1, i + 1).map((x) => (x != null ? x : 0)));
    const ll = Math.min(...lows.slice(i - periodK + 1, i + 1).map((x) => (x != null ? x : Infinity)));
    rawK.push(hh - ll === 0 ? 50 : ((closes[i] - ll) / (hh - ll)) * 100);
  }
  const slowK = [];
  for (let i = smoothK - 1; i < rawK.length; i++) slowK.push(ti_average(rawK.slice(i - smoothK + 1, i + 1)));
  const slowD = [];
  for (let i = periodD - 1; i < slowK.length; i++) slowD.push(ti_average(slowK.slice(i - periodD + 1, i + 1)));
  return {
    k: ti_round1(slowK[slowK.length - 1]), d: ti_round1(slowD[slowD.length - 1]),
    prevK: ti_round1(slowK[slowK.length - 2]), prevD: ti_round1(slowD[slowD.length - 2]),
  };
}
function ti_tentukanTrendHarga(cClose, ma21, ma50, ma100, ma200) {
  const semuaMA = [ma21, ma50, ma100, ma200];
  const maTersedia = semuaMA.filter((m) => m != null);
  if (maTersedia.length === 0) return "Data MA Belum Cukup";
  const diatasSemua = maTersedia.every((m) => cClose > m);
  const dibawahSemua = maTersedia.every((m) => cClose < m);
  const lengkap = maTersedia.length === 4;
  if (diatasSemua) return lengkap ? "Bullish (diatas MA21/50/100/200)" : "Bullish (diatas MA yang tersedia)";
  if (dibawahSemua) return lengkap ? "Bearish (dibawah MA21/50/100/200)" : "Bearish (dibawah MA yang tersedia)";
  return "Sideways/Mixed";
}
function ti_formatCandle(open, high, low, close) {
  if (open == null || close == null) return "";
  const o = ti_round2(open), h = ti_round2(high), l = ti_round2(low), c = ti_round2(close);
  const arah = c >= o ? "Bullish" : "Bearish";
  return `O:${o} H:${h} L:${l} C:${c} (${arah})`;
}
function ti_deteksiPolaCandle(y, t) {
  const bodyY = Math.abs(y.c - y.o);
  const bodyT = Math.abs(t.c - t.o);
  const rangeT = t.h - t.l;
  const upperShadowT = t.h - Math.max(t.o, t.c);
  const lowerShadowT = Math.min(t.o, t.c) - t.l;
  const yBullish = y.c > y.o, yBearish = y.c < y.o;
  const tBullish = t.c > t.o, tBearish = t.c < t.o;
  if (yBearish && tBullish && t.o <= y.c && t.c >= y.o && bodyT > bodyY) return { text: "Bullish Engulfing (potensi reversal naik)", bias: "bullish" };
  if (yBullish && tBearish && t.o >= y.c && t.c <= y.o && bodyT > bodyY) return { text: "Bearish Engulfing (potensi reversal turun)", bias: "bearish" };
  if (yBearish && tBullish && t.o >= y.c && t.c <= y.o && bodyT < bodyY) return { text: "Bullish Harami (tekanan jual mulai melemah)", bias: "bullish" };
  if (yBullish && tBearish && t.o <= y.c && t.c >= y.o && bodyT < bodyY) return { text: "Bearish Harami (tekanan beli mulai melemah)", bias: "bearish" };
  if (rangeT > 0 && bodyT <= rangeT * 0.1) return { text: "Doji (keraguan pasar / potensi pembalikan)", bias: "netral" };
  if (rangeT > 0 && bodyT <= rangeT * 0.35 && lowerShadowT >= bodyT * 2 && upperShadowT <= bodyT * 0.5) {
    return tBullish ? { text: "Hammer (potensi reversal naik setelah downtrend)", bias: "bullish" } : { text: "Hanging Man (waspada reversal turun setelah uptrend)", bias: "bearish" };
  }
  if (rangeT > 0 && bodyT <= rangeT * 0.35 && upperShadowT >= bodyT * 2 && lowerShadowT <= bodyT * 0.5) {
    return tBearish ? { text: "Shooting Star (waspada reversal turun)", bias: "bearish" } : { text: "Inverted Hammer (potensi reversal naik, perlu konfirmasi)", bias: "bullish" };
  }
  return { text: "Tidak ada pola signifikan", bias: "netral" };
}

// Perluasan indikator (screener filter tambahan) — dipakai 2x (bars penuh
// & bars minus 1 hari terakhir) untuk dapat versi "current" & "previous".
function ti_computeExtendedIndicators(bars) {
  const closes = bars.map((b) => b.close);
  const highs = bars.map((b) => (b.high != null ? b.high : b.close));
  const lows = bars.map((b) => (b.low != null ? b.low : b.close));
  const volumes = bars.map((b) => b.volume || 0);
  const values = bars.map((b) => b.value || 0);
  const freqs = bars.map((b) => b.frequency || 0);
  const n = closes.length;
  const sma = (arr, p) => ti_calcSMA(arr, p);
  const smaRound = (arr, p) => (sma(arr, p) != null ? Math.round(sma(arr, p)) : null);
  const frequencyMa20 = smaRound(freqs, 20);
  const frequencyMa50 = smaRound(freqs, 50);
  const curFreq = Math.round(freqs[n - 1] || 0);
  const freqRatio = frequencyMa20 > 0 ? curFreq / frequencyMa20 : null;
  const macdFull = ti_calcMACDFull(closes);
  const bbPeriod = 20;
  let bbUpper = null, bbLower = null;
  if (closes.length >= bbPeriod) {
    const slice = closes.slice(-bbPeriod);
    const mid = ti_average(slice);
    const std = ti_calcStdDev(slice);
    bbUpper = ti_round2(mid + 2 * std); bbLower = ti_round2(mid - 2 * std);
  }
  const adrPeriod = Math.min(14, n);
  const ranges = [];
  for (let i = n - adrPeriod; i < n; i++) ranges.push(highs[i] - lows[i]);
  let fib = { p: null, r1: null, r2: null, r3: null, s1: null, s2: null, s3: null };
  if (n >= 2) {
    const pH = highs[n - 2], pL = lows[n - 2], pC = closes[n - 2];
    const p = (pH + pL + pC) / 3;
    fib = {
      p: ti_round2(p), r1: ti_round2(2 * p - pL), s1: ti_round2(2 * p - pH),
      r2: ti_round2(p + (pH - pL)), s2: ti_round2(p - (pH - pL)),
      r3: ti_round2(pH + 2 * (p - pL)), s3: ti_round2(pL - 2 * (pH - p)),
    };
  }
  return {
    priceMa5: ti_round2(sma(closes, 5)), priceMa10: ti_round2(sma(closes, 10)), priceMa20: ti_round2(sma(closes, 20)),
    priceMa50: ti_round2(sma(closes, 50)), priceMa100: ti_round2(sma(closes, 100)), priceMa200: ti_round2(sma(closes, 200)),
    volumeMa5: smaRound(volumes, 5), volumeMa10: smaRound(volumes, 10), volumeMa20: smaRound(volumes, 20),
    volumeMa50: smaRound(volumes, 50), volumeMa100: smaRound(volumes, 100), volumeMa200: smaRound(volumes, 200),
    valueMa5: ti_round2(sma(values, 5)), valueMa10: ti_round2(sma(values, 10)), valueMa20: ti_round2(sma(values, 20)),
    valueMa50: ti_round2(sma(values, 50)), valueMa100: ti_round2(sma(values, 100)), valueMa200: ti_round2(sma(values, 200)),
    frequencyMa20, frequencyMa50,
    freqSpike: freqRatio != null && freqRatio >= 1.5 ? "Ya" : "Tidak",
    rsi14: ti_round1(ti_calcRSI(closes, 14)),
    macd: ti_round2(macdFull.macd), signal: ti_round2(macdFull.signal), macdHist: ti_round2(macdFull.hist),
    bbUpper, bbLower,
    atr14: ti_round2(ti_calcATR(highs, lows, closes, 14)),
    adr14: ti_round2(ti_average(ranges)),
    vwap: ti_round2(ti_calcVWAP(closes, highs, lows, volumes, 20)),
    ema5: ti_round2(ti_calcEMA(closes, 5)), ema9: ti_round2(ti_calcEMA(closes, 9)), ema10: ti_round2(ti_calcEMA(closes, 10)), ema20: ti_round2(ti_calcEMA(closes, 20)),
    // ema21 basis CLOSE (beda dari ema21h/ema21l di tabel `stocks` yang basis
    // High/Low) -- ditambahkan khusus buat sinyal screener "EMA9×EMA21
    // Golden Cross". prev_ema9/prev_ema21 (buat deteksi fresh-cross) TIDAK
    // dihitung di sini -- diambil dari ti_computeExtendedIndicators(bars
    // MINUS bar terakhir) yang sudah dipanggil terpisah sebagai `prevExt`
    // di updateTechnicalIndicatorsBulk(), lihat extRow di sana.
    ema21: ti_round2(ti_calcEMA(closes, 21)),
    ema50: ti_round2(ti_calcEMA(closes, 50)), ema100: ti_round2(ti_calcEMA(closes, 100)), ema200: ti_round2(ti_calcEMA(closes, 200)),
    fibP: fib.p, fibR1: fib.r1, fibR2: fib.r2, fibR3: fib.r3, fibS1: fib.s1, fibS2: fib.s2, fibS3: fib.s3,
  };
}

// Hitung 1 baris `stocks` (kolom teknikal) dari deretan bar harian
// bars: [{date, open, high, low, close, volume, value, frequency}] terurut naik
function ti_buildStockRowFromBars(ticker, bars, listedShares) {
  if (bars.length < TI_MIN_BARS_FOR_CALC) {
    throw new Error(`Data historis ${ticker} baru ${bars.length} bar (butuh >= ${TI_MIN_BARS_FOR_CALC}) — tarik dulu "Historical (Daily)" untuk rentang tanggal yang lebih panjang.`);
  }
  const closes = bars.map((b) => b.close);
  const opens = bars.map((b) => b.open);
  const highs = bars.map((b) => b.high);
  const lows = bars.map((b) => b.low);
  const volumes = bars.map((b) => b.volume || 0);
  const n = closes.length;
  const highsFilled = highs.map((h, i) => (h != null ? h : closes[i]));
  const lowsFilled = lows.map((l, i) => (l != null ? l : closes[i]));

  const cClose = ti_round2(closes[n - 1]);
  const prevClose = ti_round2(closes[n - 2]);
  const cOpen = ti_round2(opens[n - 1] != null ? opens[n - 1] : closes[n - 2]);
  const cHigh = ti_round2(highs[n - 1] != null ? highs[n - 1] : Math.max(cOpen, cClose));
  const cLow = ti_round2(lows[n - 1] != null ? lows[n - 1] : Math.min(cOpen, cClose));
  const cVol = Math.round(volumes[n - 1] || 0);
  const prevOpen = ti_round2(opens[n - 2] != null ? opens[n - 2] : closes[n - 3]);
  const prevHigh = ti_round2(highs[n - 2] != null ? highs[n - 2] : Math.max(prevOpen, prevClose));
  const prevLow = ti_round2(lows[n - 2] != null ? lows[n - 2] : Math.min(prevOpen, prevClose));
  const prevVol = Math.round(volumes[n - 2] || 0);

  const volMA20 = Math.round(ti_average(volumes.slice(-20)));
  const avgVolume3m = n >= TI_MIN_BARS_3M_VOL ? Math.round(ti_average(volumes.slice(-63))) : null;
  const ema89 = ti_calcEMA(closes, 89);
  const stoch = ti_calcStochastic(highsFilled, lowsFilled, closes, 14, 3, 3);

  let clv = 0;
  if (cHigh !== cLow) clv = ti_round2(((cClose - cLow) - (cHigh - cClose)) / (cHigh - cLow));
  const volRatio = volMA20 > 0 ? ti_round2(cVol / volMA20) : 0;
  let uangGedeMasuk = "Normal";
  if (volRatio > 2.0 && clv > 0.7) uangGedeMasuk = "Akumulasi Kuat (RVOL>2 & CLV>0.7)";
  else if (volRatio > 2.0 && clv < 0) uangGedeMasuk = "Guyuran (RVOL>2 & CLV Negatif)";

  const bbPeriod = 20;
  let currentBBWidth = null, minBBWidth6M = Infinity;
  if (closes.length >= bbPeriod) {
    const startIdx = Math.max(bbPeriod, closes.length - 120);
    for (let i = startIdx; i <= closes.length; i++) {
      const slice = closes.slice(i - bbPeriod, i);
      const mid = ti_average(slice);
      const std = ti_calcStdDev(slice);
      const width = mid === 0 ? 0 : ((mid + 2 * std) - (mid - 2 * std)) / mid;
      if (i === closes.length) currentBBWidth = ti_round2(width);
      if (width < minBBWidth6M) minBBWidth6M = width;
    }
  }
  let isBBSqueeze = "Tidak";
  if (currentBBWidth !== null && currentBBWidth <= minBBWidth6M * 1.05) isBBSqueeze = "Ya (Kompresi Siap Meledak)";

  const atr14 = ti_round2(ti_calcATR(highsFilled, lowsFilled, closes, 14));
  const ma21 = ti_calcSMA(closes, 21), ma50 = ti_calcSMA(closes, 50), ma100 = ti_calcSMA(closes, 100), ma200 = ti_calcSMA(closes, 200);
  // "Jarak ke MA50 (%)" & "Jarak ke MA200 (%)" — dipakai di Rule Builder
  // (RULE_METRICS: vsMa50Pct/vsMa200Pct) & panel Detail Emiten ("vs MA50%"/
  // "vs MA200%"), tapi sebelumnya TIDAK PERNAH dihitung di mana pun (cuma
  // dibaca dari kolom DB yang tidak pernah ditulis) -- akibatnya selalu
  // null/"-" di seluruh aplikasi. Ditambahkan di sini (positif = harga di
  // atas MA, negatif = di bawah MA).
  const vsMa50Pct = (cClose != null && ma50 != null && ma50 !== 0) ? ti_round2(((cClose - ma50) / ma50) * 100) : null;
  const vsMa200Pct = (cClose != null && ma200 != null && ma200 !== 0) ? ti_round2(((cClose - ma200) / ma200) * 100) : null;
  const trendHarga = ti_tentukanTrendHarga(cClose, ma21, ma50, ma100, ma200);

  const yOpen = opens[n - 2], yHigh = highs[n - 2], yLow = lows[n - 2], yClose = closes[n - 2];
  const candleKemarin = ti_formatCandle(yOpen, yHigh, yLow, yClose);
  const candleHariIni = ti_formatCandle(cOpen, cHigh, cLow, cClose);
  let polaCandle = "Data candle kemarin tidak lengkap", polaBias = "netral";
  if (yOpen != null && yHigh != null && yLow != null && yClose != null) {
    const polaResult = ti_deteksiPolaCandle({ o: yOpen, h: yHigh, l: yLow, c: yClose }, { o: cOpen, h: cHigh, l: cLow, c: cClose });
    polaCandle = polaResult.text; polaBias = polaResult.bias;
  }
  const isTrendBullish = trendHarga.startsWith("Bullish");
  const isTrendBearish = trendHarga.startsWith("Bearish");
  const isPolaBullish = polaBias === "bullish";
  const isPolaBearish = polaBias === "bearish";
  const changeAbs = ti_round2(cClose - prevClose);
  const changePct = prevClose ? ti_round2((changeAbs / prevClose) * 100) : 0;

  const has52w = n >= TI_MIN_BARS_52W;
  const window52wH = has52w ? highsFilled.slice(-252) : null;
  const window52wL = has52w ? lowsFilled.slice(-252) : null;
  const high52w = has52w ? ti_round2(Math.max(...window52wH)) : null;
  const low52w = has52w ? ti_round2(Math.min(...window52wL)) : null;
  const closeAYearAgo = n > 253 ? closes[n - 253] : null;
  const week52ChangePct = closeAYearAgo ? ti_round2(((cClose - closeAYearAgo) / closeAYearAgo) * 100) : null;
  // "1 Week Price Returns (%)" & "1 Month Price Returns (%)" — sama pola dengan
  // week52ChangePct di atas, tapi mundur 5 bar (~1 minggu bursa) dan 20 bar
  // (~1 bulan bursa) dari harga penutupan terakhir. Dipakai di RULE_METRICS
  // (rule builder) seperti contoh Stockbit "1 Month Price Returns ≤ -10".
  // Index dipakai n-1-K (bukan n-K): cClose ada di closes[n-1], jadi "K bar
  // lalu" yang benar adalah closes[n-1-K]. n-K salah 1 bar (window jadi K-1
  // hari, bukan K hari) -- REVISI setelah audit off-by-one.
  const close1WAgo = n > 6 ? closes[n - 6] : null;
  const weekChangePct = close1WAgo ? ti_round2(((cClose - close1WAgo) / close1WAgo) * 100) : null;
  const close1MAgo = n > 21 ? closes[n - 21] : null;
  const monthChangePct = close1MAgo ? ti_round2(((cClose - close1MAgo) / close1MAgo) * 100) : null;

  const window20H = highsFilled.slice(-20), window20L = lowsFilled.slice(-20);
  const support = ti_round2(Math.min(...window20L));
  const resistance = ti_round2(Math.max(...window20H));

  // Swing high/low (fractal pivot, lookback ~90 bar, 3 kiri-3 kanan) --
  // basis alternatif Fibonacci yang mengikuti struktur harga yang sebenarnya,
  // bukan cuma window tetap 20 hari. Hanya dianggap valid kalau swing low
  // terjadi SEBELUM swing high (pola naik: low dulu, baru high) -- itu yang
  // relevan sbg basis extension utk target TP long.
  const swingLookback = Math.min(n - 1, 90);
  const swingRaw = ti_detectSwingPoints(highsFilled, lowsFilled, swingLookback, 3);
  let swingHigh = null, swingLow = null;
  if (swingRaw.swingLow != null && swingRaw.swingHigh != null &&
      swingRaw.swingHigh > swingRaw.swingLow && swingRaw.swingLowIdx < swingRaw.swingHighIdx) {
    swingHigh = ti_round2(swingRaw.swingHigh);
    swingLow = ti_round2(swingRaw.swingLow);
  }

  let ytdPct = null;
  const yearNow = new Date().getFullYear();
  const firstBarThisYear = bars.find((b) => Number(String(b.date).slice(0, 4)) === yearNow);
  if (firstBarThisYear && firstBarThisYear.close != null && firstBarThisYear.close > 0) {
    ytdPct = ti_round2((closes[n - 1] / firstBarThisYear.close - 1) * 100);
  }

  const fibRange = resistance - support;
  const fib = {
    f0: resistance, f236: ti_round2(resistance - fibRange * 0.236), f382: ti_round2(resistance - fibRange * 0.382),
    f50: ti_round2(resistance - fibRange * 0.5), f618: ti_round2(resistance - fibRange * 0.618), f100: support,
  };

  const ema21H = ti_calcEMA(highsFilled, 21), ema21L = ti_calcEMA(lowsFilled, 21);
  const rsi7 = ti_calcRSI(closes, 7), rsi21 = ti_calcRSI(closes, 21);
  const macdFull = ti_calcMACDFull(closes);
  const { macd, signal, hist, histPrev } = macdFull;

  let cekHarga = "harga belum cross up";
  if (ema21H != null && ema21L != null) {
    if (cClose > ema21H && cClose > ema21L) cekHarga = "harga crossup ema 21 H dan L";
    else if (cClose > ema21L && cClose <= ema21H) cekHarga = "harga diatas ema 21 L dibawah ema 21 H";
  }
  const cekRsi = rsi7 > rsi21 ? "rsi 7 cross up rsi 21" : "rsi 7 belum cross up";
  let statusRsi = "over bought";
  if (rsi7 <= 30) statusRsi = "over sold"; else if (rsi7 <= 45) statusRsi = "bearish";
  else if (rsi7 <= 55) statusRsi = "netral"; else if (rsi7 <= 70) statusRsi = "bullish";

  const isGoldenCross = histPrev <= 0 && hist > 0;
  const isDeadCross = histPrev >= 0 && hist < 0;
  const histNaik = hist > histPrev;
  let cekMacd = "Wait & See / Bearish";
  if (hist > 0) cekMacd = "Bullish Menguat";
  if (isGoldenCross && ema21H != null && cClose > ema21H) cekMacd = "Buy (Golden Cross)";
  if (hist < 0 && rsi7 <= 35 && histNaik) cekMacd = "Momentum Buy (Early)";
  if (isDeadCross) cekMacd = "Sell (Dead Cross)";

  let cekVolume = "Volume Normal";
  if (volRatio >= 3) cekVolume = "Volume Spike Ekstrem"; else if (volRatio >= 2) cekVolume = "Volume Spike Kuat";
  else if (volRatio >= 1.5) cekVolume = "Volume Spike"; else if (volRatio < 0.7) cekVolume = "Volume Sepi";

  const isVolumeSpike = volRatio >= 1.5;
  const isHargaNaik = changeAbs > 0;
  const isUangGedeMasuk = uangGedeMasuk.includes("Akumulasi Kuat");
  const isBreakoutSqueeze = isBBSqueeze.includes("Ya") && isHargaNaik && isVolumeSpike;
  const isRsiBullish = rsi7 > rsi21 && rsi7 >= 50;
  const isStochGoldenCross = stoch.prevK < stoch.prevD && stoch.k > stoch.d;
  const vwap20 = ti_calcVWAP(closes, highsFilled, lowsFilled, volumes, 20);
  const isDiatasVWAP = vwap20 != null && cClose > vwap20;

  let keyakinanNaik = "Rendah";
  if (cekMacd === "Buy (Golden Cross)" && isVolumeSpike && isHargaNaik && isTrendBullish && isPolaBullish && isUangGedeMasuk) {
    keyakinanNaik = "Sangat Tinggi++ (Perfect Setup: MACD + Trend + Uang Gede)";
  } else if (isBreakoutSqueeze && isDiatasVWAP && isRsiBullish) {
    keyakinanNaik = "Sangat Tinggi (Breakout BB Squeeze & Momentum Kuat)";
  } else if (cekMacd === "Buy (Golden Cross)" && isVolumeSpike && isHargaNaik && isTrendBullish && isPolaBullish) {
    keyakinanNaik = "Sangat Tinggi+ (MACD + Volume + Trend + Candle Bullish, Konfirmasi Penuh)";
  } else if (cekMacd === "Buy (Golden Cross)" && isVolumeSpike && isHargaNaik && (isRsiBullish || isStochGoldenCross)) {
    keyakinanNaik = "Sangat Tinggi (MACD + Volume + RSI/Stoch Konfirmasi)";
  } else if (isTrendBullish && isVolumeSpike && isPolaBullish && isDiatasVWAP) {
    keyakinanNaik = "Tinggi (Trend Bullish + Volume + Candle Bullish + Kuat Intraday)";
  } else if ((cekMacd === "Buy (Golden Cross)" || cekMacd === "Bullish Menguat") && isVolumeSpike) {
    keyakinanNaik = "Tinggi (Ada Konfirmasi Volume)";
  } else if (cekMacd === "Buy (Golden Cross)" || cekMacd === "Bullish Menguat" || cekMacd === "Momentum Buy (Early)") {
    keyakinanNaik = isPolaBullish ? "Sedang (Candle Bullish, Volume Belum Konfirmasi)" : "Sedang (Belum Ada Konfirmasi Volume)";
  } else if (isVolumeSpike && !isHargaNaik && clv < 0) {
    keyakinanNaik = "Sangat Waspada (Distribusi Masif / Guyuran Bandar)";
  } else if (isVolumeSpike && !isHargaNaik) {
    keyakinanNaik = "Waspada (Volume Tinggi tapi Harga Turun)";
  } else if (isTrendBearish && isPolaBearish) {
    keyakinanNaik = "Waspada (Trend Bearish + Candle Bearish)";
  }

  const turnover = Math.round(cClose * cVol);
  const marketCap = listedShares != null && cClose != null ? Math.round(cClose * listedShares) : null;

  return {
    ticker,
    c_open: cOpen, day_high: cHigh, day_low: cLow, price: cClose,
    prev_close: prevClose, change_abs: changeAbs, change_pct: changePct,
    week52_high: high52w, week52_low: low52w, week52_change_pct: week52ChangePct,
    ytd_pct: ytdPct, week_change_pct: weekChangePct, month_change_pct: monthChangePct,
    support, resistance, fibonacci: fib,
    swing_high: swingHigh, swing_low: swingLow,
    ema21h: ti_round2(ema21H), ema21l: ti_round2(ema21L), ema89: ti_round2(ema89),
    rsi7: ti_round1(rsi7), rsi21: ti_round1(rsi21),
    macd: ti_round2(macd), signal: ti_round2(signal), macd_hist: ti_round2(hist),
    cek_harga: cekHarga, cek_rsi: cekRsi, status_rsi: statusRsi, cek_macd: cekMacd,
    volume: cVol, vol_ma20: volMA20, vol_ratio: volRatio, avg_volume_3m: avgVolume3m,
    cek_volume: cekVolume, keyakinan_naik: keyakinanNaik,
    vwap20: ti_round2(vwap20), turnover, value_traded: bars[n - 1].value ?? null,
    ma21: ti_round2(ma21), ma50: ti_round2(ma50), ma100: ti_round2(ma100), ma200: ti_round2(ma200),
    vs_ma50_pct: vsMa50Pct, vs_ma200_pct: vsMa200Pct,
    trend_harga: trendHarga,
    candle_kemarin: candleKemarin, candle_hari_ini: candleHariIni, pola_candle: polaCandle,
    clv, uang_gede_masuk: uangGedeMasuk, bb_width: currentBBWidth, is_bb_squeeze: isBBSqueeze, atr14,
    prev_high: prevHigh, prev_low: prevLow, prev_vol: prevVol,
    stoch_k: stoch.k, stoch_d: stoch.d, prev_stoch_k: stoch.prevK, prev_stoch_d: stoch.prevD,
    shares_outstanding: listedShares ?? null, market_cap: marketCap,
  };
}

// Sejak migrasi flows+src, ini cuma alias tipis ke ti_fetchBarsFromFlows()
// -- price_history_stockbit sudah digabung ke `flows`, jadi tidak ada lagi
// tabel terpisah untuk "data Stockbit doang". Nama fungsi & bentuk return
// (array bars, TANPA listedShares) dipertahankan supaya 3 caller yang sudah
// ada (updateTechnicalIndicatorsBulk non-flows, dst.) tidak perlu diubah.
async function ti_fetchBarsFromDb(ticker) {
  const { bars } = await ti_fetchBarsFromFlows(ticker);
  return bars;
}

// listed_shares tidak tersedia dari Stockbit — pakai shares_outstanding
// yang sudah ada di tabel `stocks` (kalau pernah terisi via sync-idx-full.mjs
// atau update teknikal sebelumnya) supaya market_cap tidak selalu null.
async function ti_fetchExistingSharesOutstanding(ticker) {
  try {
    const res = await fetch(`${SUPABASE_URL}/stocks?ticker=eq.${ticker}&select=shares_outstanding`, { headers: getSupaHeaders(), cache: "no-store" });
    if (!res.ok) return null;
    const rows = await res.json();
    return rows?.[0]?.shares_outstanding ?? null;
  } catch (e) { return null; }
}

// Sumber bar OHLCV untuk indikator teknikal: tabel `flows` (sejak migrasi
// flows+src, gabungan IDX + Stockbit -- lihat ti_fetchBarsFromDb() di atas
// yang sekarang cuma alias ke sini). listed_shares per bar tersedia
// langsung (diisi kalau baris itu src='idx' atau pernah diisi impor
// "Ringkasan Saham"), jadi market_cap tidak perlu nunggu kolom
// shares_outstanding di `stocks` terisi duluan -- diambil fallback ke nilai
// TERAKHIR yang tersedia (bar terbaru bisa saja null), sama seperti
// sync-idx-full.mjs.
async function ti_fetchBarsFromFlows(ticker) {
  const qs = new URLSearchParams({
    ticker: `eq.${ticker}`,
    select: "date,open_price,high,low,close,volume,value,frequency,listed_shares",
    // PENTING: urut DESC + limit = ambil bar TERBARU (dulu asc+limit di
    // ti_fetchBarsFromDb() versi lama malah ambil bar TERLAMA -- lihat
    // catatan yang sudah diperbaiki).
    order: "date.desc", limit: "450",
  });
  const res = await fetch(`${SUPABASE_URL}/flows?${qs}`, { headers: getSupaHeaders(), cache: "no-store" });
  if (!res.ok) throw new Error(`HTTP ${res.status} saat baca flows`);
  const rows = await res.json();
  const bars = rows
    .filter(r => r.close != null)
    .map(r => ({ date: r.date, open: r.open_price, high: r.high, low: r.low, close: r.close, volume: r.volume, value: r.value, frequency: r.frequency, listedShares: r.listed_shares }))
    .reverse(); // kembali urut lama -> baru
  const listedShares = [...bars].reverse().find(b => b.listedShares != null)?.listedShares ?? null;
  return { bars, listedShares };
}

// Sisipkan quote live Stockbit sebagai "bar hari ini yang masih berjalan"
// ke deretan bar harian dari DB (yang cuma sampai hari bursa terakhir yang
// SUDAH final). Kalau bar terakhir di DB tanggalnya sudah hari ini (mis.
// sudah pernah ditarik EOD hari ini juga), live quote MENIMPA bar itu
// (bukan menambah baris baru) — high/low diambil yang paling ekstrem
// antara data lama & quote baru, close & volume selalu dari quote (paling
// baru). Kalau belum ada bar untuk hari ini, quote jadi bar baru, dengan
// open = harga open dari quote (fallback ke close kemarin kalau kosong).
function ti_buildMergedBarsWithLiveQuote(bars, quote) {
  const liveClose = Number(quote?.last);
  if (!bars.length || !Number.isFinite(liveClose) || liveClose <= 0) return bars;
  const today = todayLocalISO();
  const merged = bars.map(b => ({ ...b }));
  const last = merged[merged.length - 1];
  const qHigh = Number(quote.high), qLow = Number(quote.low), qOpen = Number(quote.open), qVol = Number(quote.volume), qFreq = Number(quote.frequency);

  if (last && last.date === today) {
    last.high = Math.max(...[last.high, qHigh, liveClose].filter(Number.isFinite));
    last.low = Math.min(...[last.low, qLow, liveClose].filter(Number.isFinite));
    last.close = liveClose;
    if (Number.isFinite(qVol) && qVol > 0) last.volume = qVol;
    if (Number.isFinite(qFreq) && qFreq > 0) last.frequency = qFreq;
  } else {
    merged.push({
      date: today,
      open: Number.isFinite(qOpen) && qOpen > 0 ? qOpen : (last ? last.close : liveClose),
      high: Number.isFinite(qHigh) && qHigh > 0 ? qHigh : liveClose,
      low: Number.isFinite(qLow) && qLow > 0 ? qLow : liveClose,
      close: liveClose,
      volume: Number.isFinite(qVol) ? qVol : 0,
      value: null,
      frequency: Number.isFinite(qFreq) ? qFreq : 0,
    });
  }
  return merged;
}

// Buang key yang nilainya null/undefined dari sebuah object sebelum dikirim
// ke Supabase (upsert on_conflict=ticker, Prefer: merge-duplicates). PENTING:
// PostgREST/Supabase HANYA menyentuh kolom yang ADA di payload -- kolom yang
// tidak dikirim SAMA SEKALI tetap dipertahankan nilai lamanya di DB. Kalau
// field null tetap dikirim apa adanya (mis. week52_high/week52_low/ytd_pct
// waktu histori di flows belum 252 hari), field itu
// justru DITIMPA jadi kosong -- padahal DB mungkin sudah punya nilai bagus
// dari sumber lain (mis. import IDX/Yahoo harian). Dengan strip null di sini,
// "📊 Update Teknikal" cuma MENGISI kolom yang berhasil dihitung, dan
// membiarkan kolom yang belum bisa dihitung (histori kurang panjang) apa
// adanya -- tidak pernah menimpanya jadi kosong.
function ti_stripNulls(obj) {
  const out = {};
  for (const k in obj) { if (obj[k] !== null && obj[k] !== undefined) out[k] = obj[k]; }
  return out;
}

async function updateTechnicalIndicatorsBulk(tickers, opts) {
  const live = !!(opts && opts.live);
  const fromFlows = !!(opts && opts.source === "flows"); // true = pakai listed_shares dari flows (impor IDX manual) alih-alih fallback ke stocks.shares_outstanding
  if (state.tiBulkLoading) return;
  if (!tickers || !tickers.length) {
    if (live) return; // siklus auto-refresh: diam-diam skip kalau belum ada yang dicentang
    state.tiBulkResults = [{ ticker: "-", ok: false, msg: fromFlows ? "Tidak ada ticker hasil impor untuk dihitung." : "Centang minimal 1 saham di tab Screener dulu." }];
    render(); return;
  }
  if (!SUPABASE_URL || !SUPABASE_KEY) { if (!live) openSettings(); return; }
  if (live && !state.stockbitToken) return;

  state.tiBulkLoading = true;
  state.tiBulkProgress = { done: 0, total: tickers.length };
  state.tiBulkResults = [];
  render();

  for (const ticker of tickers) {
    try {
      let bars, listedSharesFromFlows = null;
      if (fromFlows) {
        const r = await ti_fetchBarsFromFlows(ticker);
        bars = r.bars; listedSharesFromFlows = r.listedShares;
      } else {
        bars = await ti_fetchBarsFromDb(ticker);
      }
      let liveNote = "";
      if (live) {
        const res = await stockbitFetch(state.stockbitQuoteEndpoint, ticker);
        const quote = res.raw ? mapStockbitQuote(res.raw) : null;
        if (!quote || !Number.isFinite(Number(quote.last)) || Number(quote.last) <= 0) {
          throw new Error(res.error || "Quote live Stockbit tidak terbaca (cek Endpoint Quote di Pengaturan).");
        }
        bars = ti_buildMergedBarsWithLiveQuote(bars, quote);
        liveNote = ` [LIVE ${quote.last}]`;
      }
      if (bars.length < TI_MIN_BARS_FOR_CALC) {
        state.tiBulkResults.push({ ticker, ok: false, msg: fromFlows
          ? `Baru ${bars.length} hari data di tabel flows (butuh >= ${TI_MIN_BARS_FOR_CALC}) — impor lebih banyak hari dulu (upload file "Ringkasan Saham" utk tanggal-tanggal sebelumnya).`
          : `Baru ${bars.length} hari data di database (butuh >= ${TI_MIN_BARS_FOR_CALC}) — tarik dulu "📅 Historical (Daily)" untuk rentang tanggal yang lebih panjang.` });
      } else {
        const listedShares = fromFlows ? (listedSharesFromFlows ?? await ti_fetchExistingSharesOutstanding(ticker)) : await ti_fetchExistingSharesOutstanding(ticker);
        const technical = ti_buildStockRowFromBars(ticker, bars, listedShares);
        const ext = ti_computeExtendedIndicators(bars);
        const prevExt = bars.length > 1 ? ti_computeExtendedIndicators(bars.slice(0, -1)) : {};
        const nowIso = new Date().toISOString();

        const stockRow = { ...technical, updated_at: nowIso };
        const extRow = {
          ticker,
          price_ma5: ext.priceMa5, price_ma10: ext.priceMa10, price_ma20: ext.priceMa20,
          prev_price_ma5: prevExt.priceMa5 ?? null, prev_price_ma10: prevExt.priceMa10 ?? null,
          prev_price_ma20: prevExt.priceMa20 ?? null, prev_price_ma50: prevExt.priceMa50 ?? null,
          prev_price_ma100: prevExt.priceMa100 ?? null, prev_price_ma200: prevExt.priceMa200 ?? null,
          volume_ma5: ext.volumeMa5, volume_ma10: ext.volumeMa10, volume_ma50: ext.volumeMa50,
          volume_ma100: ext.volumeMa100, volume_ma200: ext.volumeMa200,
          prev_volume_ma5: prevExt.volumeMa5 ?? null, prev_volume_ma10: prevExt.volumeMa10 ?? null,
          prev_volume_ma20: prevExt.volumeMa20 ?? null, prev_volume_ma50: prevExt.volumeMa50 ?? null,
          prev_volume_ma100: prevExt.volumeMa100 ?? null,
          value_ma5: ext.valueMa5, value_ma10: ext.valueMa10, value_ma20: ext.valueMa20,
          value_ma50: ext.valueMa50, value_ma100: ext.valueMa100, value_ma200: ext.valueMa200,
          frequency_ma20: ext.frequencyMa20, frequency_ma50: ext.frequencyMa50, freq_spike: ext.freqSpike,
          rsi14: ext.rsi14, prev_rsi14: prevExt.rsi14 ?? null,
          prev_macd: prevExt.macd ?? null, prev_signal: prevExt.signal ?? null, prev_macd_hist: prevExt.macdHist ?? null,
          bb_upper: ext.bbUpper, bb_lower: ext.bbLower,
          adr14: ext.adr14, prev_atr14: prevExt.atr14 ?? null, prev_adr14: prevExt.adr14 ?? null,
          vwap: ext.vwap,
          ema5: ext.ema5, ema9: ext.ema9, ema10: ext.ema10, ema20: ext.ema20, ema50: ext.ema50, ema100: ext.ema100, ema200: ext.ema200,
          ema21: ext.ema21, prev_ema9: prevExt.ema9 ?? null, prev_ema21: prevExt.ema21 ?? null,
          prev_ema200: prevExt.ema200 ?? null,
          fib_p: ext.fibP, fib_r1: ext.fibR1, fib_r2: ext.fibR2, fib_r3: ext.fibR3,
          fib_s1: ext.fibS1, fib_s2: ext.fibS2, fib_s3: ext.fibS3,
          updated_at: nowIso,
        };

        await supaFetch(`${SUPABASE_URL}/stocks?on_conflict=ticker`, {
          method: "POST", headers: { ...getSupaHeaders(), "Prefer": "resolution=merge-duplicates,return=minimal" },
          body: JSON.stringify([ti_stripNulls(stockRow)]),
        });
        await supaFetch(`${SUPABASE_URL}/stock_indicators_ext?on_conflict=ticker`, {
          method: "POST", headers: { ...getSupaHeaders(), "Prefer": "resolution=merge-duplicates,return=minimal" },
          body: JSON.stringify([ti_stripNulls(extRow)]),
        });

        state.tiBulkResults.push({ ticker, ok: true, msg: `${live ? "Live" : (fromFlows ? "Terhitung (flows/IDX)" : "Terhitung")} dari ${bars.length} hari data (${bars[0].date}..${bars[bars.length-1].date})${liveNote}. price=${technical.price} trend=${technical.trend_harga}` });
      }
    } catch (e) {
      state.tiBulkResults.push({ ticker, ok: false, msg: e.message });
    }
    state.tiBulkProgress.done++;
    render();
    await new Promise(r => setTimeout(r, live ? 350 : 150)); // jeda lebih longgar untuk siklus live (ikut jeda token Stockbit)
  }

  state.tiBulkLoading = false;
  render();
  // Run manual: muat ulang data screener dari Supabase sekarang juga supaya
  // hasil tulisan ke `stocks` langsung tampil (auto-refresh 45 dtk bisa
  // tertunda kalau fokus sedang di input/select). Siklus live tidak perlu.
  if (!live) Promise.resolve(loadLive()).catch(() => {});
}

function renderDetailVsSektor(s){
  const peers = enriched().filter(x=>x.sektor && x.sektor===s.sektor && x.ticker!==s.ticker);
  const metrics = [{key:'roe',label:'ROE',suffix:'%'},{key:'roa',label:'ROA',suffix:'%'},{key:'npm',label:'NPM',suffix:'%'},{key:'der',label:'DER',suffix:'x',lower:true},{key:'per',label:'PER',suffix:'x',lower:true},{key:'pbv',label:'PBV',suffix:'x',lower:true}];
  const avg = key => {const vals=peers.map(x=>Number(x[key])).filter(v=>isFinite(v)); return vals.length?vals.reduce((a,v)=>a+v,0)/vals.length:null;};
  return `<div class="detail-subtitle">Perbandingan dengan ${escapeHtml(s.sektor||'sektor sejenis')} <span class="pill pill-teal">${peers.length} peer</span></div><div class="sector-compare-list">${metrics.map(m=>{const value=Number(s[m.key]), sector=avg(m.key), max=Math.max(Math.abs(value)||0,Math.abs(sector)||0,1), good=!isFinite(value)||!isFinite(sector)?null:(m.lower?value<=sector:value>=sector); return `<div class="sector-compare-row"><div class="sector-compare-label"><strong>${m.label}</strong><span>${good===null?'':good?'✓ di atas sektor':'△ di bawah sektor'}</span></div><div class="sector-bar-pair"><div class="sector-bar-track"><div class="sector-bar-stock ${good===true?'good':good===false?'bad':''}" style="width:${Math.min(100,Math.abs(value)/max*100)}%"></div></div><div class="sector-bar-values"><span>Emiten <b>${isFinite(value)?value.toFixed(2):'-'}${m.suffix}</b></span><span>Sektor <b>${sector!=null?sector.toFixed(2):'-'}${m.suffix}</b></span></div></div></div>`}).join('')}</div><div class="empty-box" style="margin-top:14px;font-size:11px;">Interpretasi memakai rata-rata peer yang tersedia di universe screener, bukan rekomendasi investasi.</div>`;
}

function renderDetailTradingPlan(s){
  return `<div class="detail-subtitle">Trading Plan berbasis level teknikal</div>${renderDetailAnalisa(s)}
    ${bsjpTradePlanCard(s)}`;
}

// ==========================================
// ANALISIS AI (GEMINI)
//
// Beda dengan "🧠 Analisa" (renderDetailAnalisa) yang skornya rule-based
// murni di app.js — tab ini benar-benar memanggil model Gemini (Google)
// lewat REST API generateContent, dipanggil LANGSUNG dari browser pakai
// API key milik user sendiri (lihat ⚙️ Pengaturan → "Analisis AI (Gemini)"),
// bukan lewat Supabase/proxy manapun.
//
// Sejak revisi ini, request ke Gemini SELALU menyertakan tool
// "google_search" (Search Grounding bawaan Google) — lihat callGeminiModel.
// Konsekuensinya, prompt di bawah sekarang minta Gemini menghasilkan DUA
// bagian yang jelas dipisah:
//   1) Analisis Fundamental/Teknikal/Bandarmologi yang memakai data
//      screener sebagai TITIK AWAL, tapi WAJIB diperkaya dengan
//      interpretasi/analisa versi Gemini sendiri (bukan sekadar
//      membaca ulang angka screener apa adanya).
//   2) Riset independen Gemini DI LUAR konteks screener (berita
//      terbaru/aksi korporasi, kondisi fundamental & teknikal versi
//      Gemini sendiri, serta indikasi bandarmologi/aktivitas
//      institusi/asing) — hasil dari pengetahuan + pencarian Google
//      real-time model itu sendiri, bukan turunan data screener.
// Sumber (link) yang dipakai Gemini saat searching diekstrak dari
// groundingMetadata respons API dan ditampilkan terpisah di UI
// (lihat parseGeminiLevels/runGeminiAnalysis/renderDetailAiGemini).
// ==========================================
function buildGeminiPrompt(s){
  const num = (v, suffix="") => (v===null||v===undefined||isNaN(v)) ? "tidak tersedia" : `${fmtNum(Number(v).toFixed ? Number(Number(v).toFixed(2)) : v)}${suffix}`;
  const bandLabel = s.band ? s.band.label : "tidak tersedia";
  const lines = [
    `Ticker: ${s.ticker}`,
    `Sektor: ${s.sektor || "tidak diketahui"}`,
    `Harga terakhir: ${num(s.cClose)} (${s.changePct!=null ? (s.changePct>=0?'+':'')+Number(s.changePct).toFixed(2)+'%' : 'tidak tersedia'} dari hari sebelumnya)`,
    `Market Cap: ${s.marketCap!=null ? fmtCap(s.marketCap) : "tidak tersedia"} — Kategori: ${marketCapTier(s.marketCap)}`,
    `Turnover: Rp ${num(s.turnover)}`,
    `--- Fundamental ---`,
    `PER: ${num(s.per)}x, PBV: ${num(s.pbv)}x, ROE: ${num(s.roe)}%, ROA: ${num(s.roa)}%, DER: ${num(s.der)}x`,
    `Dividend Yield: ${num(s.divYield)}%, Valuasi (heuristik screener): ${s.valuasi || "tidak tersedia"}`,
    `--- Teknikal ---`,
    `Trend Harga (MA): ${s.trendHarga || "tidak tersedia"}`,
    `RSI 7: ${num(s.rsi7)}, RSI 21: ${num(s.rsi21)}, Status RSI: ${s.statusRsi || "tidak tersedia"}`,
    `Sinyal MACD: ${s.cekMacd || "tidak tersedia"}`,
    `Rasio Volume vs rata-rata: ${num(s.volRatio)}x (${s.sinyalVolume || "tidak tersedia"})`,
    `Support terdekat: ${num(s.support)}, Resistance terdekat: ${num(s.resistance)}`,
    `--- Bandarmologi ---`,
    `Sinyal proxy volume+harga: ${bandLabel}`,
    `Net Asing 20 Hari (data resmi IDX): ${s.foreignNet20D!=null ? fmtRp(s.foreignNet20D) : "tidak tersedia"}`,
    `Hari Asing Net Beli: ${s.foreignUpDays!=null ? `${s.foreignUpDays}/${s.flowDays??20} hari` : "tidak tersedia"}`,
    `Uang Gede Masuk: ${s.uangGedeMasuk || "tidak tersedia"}`,
    `--- Ringkasan Screener (rule-based, BUKAN dari AI) ---`,
    `Keyakinan Naik: ${s.keyakinanNaik || "tidak tersedia"}`,
    `Rekomendasi Setup: ${s.rekomendasi && s.rekomendasi!=="-" ? s.rekomendasi : "tidak ada"}`,
  ];
  return `Kamu adalah asisten riset saham untuk investor ritel di Bursa Efek Indonesia (BEI), dengan akses ke Google Search untuk riset real-time. Untuk ticker ${s.ticker} (${s.sektor || "sektor tidak diketahui"}), buat analisis berbahasa Indonesia dalam DUA BAGIAN besar berikut, persis dengan judul bagian di bawah (format Markdown, gunakan heading "## BAGIAN 1 ..." dan "## BAGIAN 2 ...").

## BAGIAN 1 — ANALISIS FUNDAMENTAL, TEKNIKAL & BANDARMOLOGI (data screener + analisa Gemini)
Data screener di bawah ini adalah TITIK AWAL, bukan satu-satunya sumber. JANGAN sekadar membaca ulang angkanya — untuk tiap aspek, perkaya dengan analisa/interpretasi versi KAMU SENDIRI (dari pengetahuan umum kamu, dan boleh pakai Google Search kalau relevan untuk konteks tambahan seperti rata-rata valuasi sektor, karakteristik bisnis emiten, atau pola teknikal yang lebih luas):
- **Fundamental**: interpretasikan PER/PBV/ROE/ROA/DER/Dividend Yield di atas — apakah wajar/mahal/murah dibanding sektornya, kualitas bisnisnya menurut analisamu, bukan cuma menyebut ulang angka.
- **Teknikal**: interpretasikan trend/RSI/MACD/volume/support-resistance di atas dengan analisa pola & momentum versi kamu sendiri, bukan cuma menyalin status yang sudah ada.
- **Bandarmologi**: interpretasikan sinyal proxy volume+harga dan data Net Asing di atas, lalu tambahkan analisa aliran dana/indikasi aktivitas bandar versi kamu sendiri berdasarkan pengetahuan & pencarian (kalau memang ada dasarnya — jangan mengarang).
Kalau interpretasimu berbeda dari heuristik screener (kolom Valuasi/Keyakinan Naik/Rekomendasi Setup), boleh disebutkan eksplisit sebagai catatan pembanding.

Format:
1. **Ringkasan** (2-3 kalimat kondisi saat ini)
2. **Analisis Fundamental** (gabungan data screener + interpretasi kamu)
3. **Analisis Teknikal** (gabungan data screener + interpretasi kamu)
4. **Analisis Bandarmologi** (gabungan data screener + interpretasi kamu)
5. **Risiko / Hal yang Perlu Diwaspadai** (poin-poin negatif/peringatan)
6. **Catatan Penutup** (satu kalimat netral, TANPA rekomendasi beli/jual/hold eksplisit)
7. **Level Ilustratif** (1-2 kalimat singkat menjelaskan DASAR penentuan level entry/TP/SL di bawah, misalnya mengacu ke support/resistance/MA/ATR dari data teknikal di atas atau analisamu sendiri)

Data screener (semua angka berasal dari data historis/heuristik, BUKAN prediksi — jadikan bahan analisa, bukan sekadar dikutip ulang):
${lines.join("\n")}

## BAGIAN 2 — RISET INDEPENDEN GEMINI (DI LUAR DATA SCREENER)
Di bagian ini, WAJIB gunakan Google Search untuk mencari informasi TERBARU tentang ${s.ticker} yang TIDAK ada di data screener di atas, lalu ringkas dalam 3 sub-poin:
1. **Fundamental (riset independen)** — kondisi bisnis/laporan keuangan terbaru, aksi korporasi (rights issue, buyback, dividen, akuisisi), guidance manajemen, atau berita material terbaru yang kamu temukan.
2. **Teknikal (riset independen)** — pandangan teknikal dari sumber lain di luar data screener ini (mis. pola chart, level psikologis, atau konsensus analis teknikal), kalau memang tersedia dari hasil pencarian.
3. **Bandarmologi / Aliran Dana (riset independen)** — berita atau indikasi soal aktivitas broker besar/asing, insider trading, kepemilikan institusi, atau sentimen pasar terkini yang kamu temukan lewat pencarian — di luar proksi volume/harga dan data Net Asing yang sudah ada di Bagian 1.
Kalau untuk salah satu sub-poin kamu TIDAK menemukan informasi baru yang relevan/terpercaya lewat pencarian, katakan terus terang "tidak ditemukan informasi tambahan yang relevan" untuk sub-poin itu — JANGAN mengarang.

PENTING (berlaku untuk BAGIAN 1 dan BAGIAN 2): Ini BUKAN saran/rekomendasi investasi finansial. Jangan menyebut diri sebagai penasihat keuangan, jangan memberi instruksi eksplisit "beli"/"jual"/"hold", dan ingatkan secara implisit bahwa keputusan akhir tetap di tangan pembaca. Gunakan bahasa Indonesia yang natural dan ringkas (maksimal ~250 kata untuk Bagian 1, maksimal ~200 kata untuk Bagian 2).

SETELAH kedua bagian selesai, WAJIB tambahkan tepat SATU baris baru paling akhir (tanpa markdown code fence, tanpa teks apapun setelahnya) persis berformat:
LEVELS_JSON: {"entry": <angka>, "tp1": <angka>, "tp2": <angka atau null>, "sl": <angka>, "basis": "<alasan singkat, maks 12 kata>"}
Aturan angka level ini: harus turunan wajar dari Harga Terakhir/Support/Resistance/Trend yang sudah ada di data Bagian 1 (bukan mengarang di luar itu), entry mendekati harga terakhir/area support, tp1 < tp2 (kalau ada) di atas entry, sl di bawah entry/support terdekat. Kalau data teknikal terlalu minim untuk membuat level yang wajar, isi entry/tp1/sl dengan angka Harga Terakhir apa adanya dan jelaskan keterbatasannya di "basis".`;
}

// Ekstrak baris "LEVELS_JSON: {...}" dari akhir respons teks Gemini (lihat
// instruksi format di buildGeminiPrompt). Mengembalikan {cleanText, levels}
// — levels bernilai null kalau baris tidak ada / gagal di-parse, dan
// cleanText selalu berupa teks analisis TANPA baris JSON tsb (supaya tidak
// tampil dobel ke pengguna).
function parseGeminiLevels(rawText){
  const lines = String(rawText||"").split("\n");
  let levels = null;
  let cleanLines = lines;
  for(let i = lines.length - 1; i >= 0; i--){
    const m = lines[i].match(/^\s*LEVELS_JSON:\s*(\{.*\})\s*$/);
    if(m){
      try{
        const parsed = JSON.parse(m[1]);
        const num = v => (v===null || v===undefined || v==="" || isNaN(Number(v))) ? null : Number(v);
        levels = {
          entry: num(parsed.entry),
          tp1: num(parsed.tp1),
          tp2: num(parsed.tp2),
          sl: num(parsed.sl),
          basis: (parsed.basis || "").toString().slice(0, 200)
        };
      }catch(e){ levels = null; }
      cleanLines = lines.slice(0, i).concat(lines.slice(i+1));
      break;
    }
  }
  return { cleanText: cleanLines.join("\n").trim(), levels };
}

function sleepMs(ms){ return new Promise(resolve => setTimeout(resolve, ms)); }

// Error 503 "model overloaded"/"high demand" dari Google bersifat TRANSIENT —
// server mereka lagi kebanjiran request, bukan masalah di key/kode kita.
// Ini sering muncul terutama di gemini-2.5-pro/gemini-pro-latest (model
// terberat) walau akun sudah billing aktif. Solusinya retry dengan jeda
// (exponential backoff), bukan langsung nyerah di percobaan pertama.
function isRetryableGeminiError(status, data){
  if(status === 503 || status === 429) return true;
  const msg = (data?.error?.message || "").toLowerCase();
  return msg.includes("overloaded") || msg.includes("high demand") || msg.includes("unavailable");
}

const GEMINI_MAX_ATTEMPTS = 2; // percobaan per model (dikurangi dari 4 karena sekarang ada fallback ANTAR model juga, lihat GEMINI_FALLBACK_MODELS)
const GEMINI_RETRY_BASE_DELAY_MS = 1500; // 1.5s, lalu 3s (exponential backoff + sedikit jitter)
// Kapasitas server Google 503 "overloaded"/"high demand" itu PER MODEL, bukan soal
// quota/key kita (retry model yang sama berkali-kali sering percuma kalau memang model
// itu lagi penuh secara global). Makanya kalau model utama gagal karena overload, kita
// coba model lain yang biasanya lebih longgar (lebih ringan/kurang populer) sebelum menyerah.
// Urutkan dari yang paling murah/ringan dulu supaya fallback cepat & jarang overload.
const GEMINI_FALLBACK_MODELS = ["gemini-3.5-flash-lite", "gemini-flash-latest"];

// Panggil satu model Gemini dengan retry+backoff untuk model itu saja.
// Melempar Error dengan properti .retryable: true kalau errornya khas overload/kapasitas
// (503/429/"overloaded") sehingga pantas coba model lain; false kalau errornya bukan soal
// kapasitas (key salah, diblokir safety filter, request invalid, dll) sehingga fallback ke
// model lain juga percuma.
// Ekstrak daftar sumber unik (judul+link) dari groundingMetadata respons
// Gemini (hasil tool "google_search" — lihat callGeminiModel). Dipakai
// untuk menampilkan "Sumber Riset Independen" di UI supaya klaim di
// BAGIAN 2 (riset independen) bisa ditelusuri user, bukan cuma dipercaya
// mentah-mentah. Return [] kalau tidak ada grounding sama sekali (mis.
// Gemini menilai tidak perlu search untuk ticker ini).
function extractGeminiSources(candidate){
  const chunks = candidate?.groundingMetadata?.groundingChunks || [];
  const seen = new Set();
  const sources = [];
  for(const c of chunks){
    const uri = c?.web?.uri;
    if(!uri || seen.has(uri)) continue;
    seen.add(uri);
    sources.push({ uri, title: c?.web?.title || uri });
  }
  return sources;
}

async function callGeminiModel(model, ticker, s){
  const url = `https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(model)}:generateContent?key=${encodeURIComponent(state.geminiApiKey)}`;
  for(let attempt = 1; attempt <= GEMINI_MAX_ATTEMPTS; attempt++){
    let res, data;
    try{
      res = await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          contents: [{ role: "user", parts: [{ text: buildGeminiPrompt(s) }] }],
          // google_search: Search Grounding bawaan Google — supaya BAGIAN 2
          // (riset independen) di prompt beneran bisa cari info real-time,
          // bukan cuma mengarang dari pengetahuan lama model. Didukung semua
          // model Gemini 2.x/3.x ke atas (termasuk default & fallback di sini).
          tools: [{ google_search: {} }],
          generationConfig: { temperature: 0.4 }
        })
      });
      data = await res.json().catch(()=>null);
    }catch(networkErr){
      // Gagal koneksi (offline, CORS, dll) — bukan soal model, fallback ke model lain percuma.
      networkErr.retryable = false;
      throw networkErr;
    }
    if(res.ok){
      const candidate = data?.candidates?.[0];
      const rawText = (candidate?.content?.parts || []).map(p => p.text || "").join("").trim();
      if(!rawText){
        const blockReason = data?.promptFeedback?.blockReason;
        const err = new Error(blockReason ? `Diblokir oleh safety filter Gemini (${blockReason}).` : "Respons kosong dari Gemini.");
        err.retryable = false;
        throw err;
      }
      return { text: rawText, model, sources: extractGeminiSources(candidate) };
    }
    const errorIsRetryable = isRetryableGeminiError(res.status, data);
    const canRetrySameModel = attempt < GEMINI_MAX_ATTEMPTS && errorIsRetryable;
    if(!canRetrySameModel){
      const err = new Error(data?.error?.message || `HTTP ${res.status}`);
      err.retryable = errorIsRetryable; // true = pantas coba model fallback berikutnya
      throw err;
    }
    const delay = GEMINI_RETRY_BASE_DELAY_MS * Math.pow(2, attempt - 1) * (0.85 + Math.random() * 0.3);
    state.geminiRetryStatus.set(ticker, { attempt, max: GEMINI_MAX_ATTEMPTS, model });
    render();
    await sleepMs(delay);
  }
}

async function runGeminiAnalysis(ticker){
  if(state.geminiLoading.has(ticker)) return;
  if(!state.geminiApiKey){
    state.geminiError.set(ticker, 'API key Gemini belum diisi. Buka "⚙️ Pengaturan" → bagian "🤖 Analisis AI (Gemini)".');
    render();
    return;
  }
  const s = enriched().find(x => x.ticker === ticker);
  if(!s){ state.geminiError.set(ticker, `Data untuk ${ticker} tidak ditemukan.`); render(); return; }

  state.geminiLoading.add(ticker);
  state.geminiError.delete(ticker);
  state.geminiRetryStatus.delete(ticker);
  state.geminiSources.delete(ticker);
  render();

  const primaryModel = state.geminiModel || GEMINI_DEFAULT_MODEL;
  // Rantai fallback: model pilihan user dulu, baru model cadangan (skip yang duplikat).
  const modelChain = [primaryModel, ...GEMINI_FALLBACK_MODELS.filter(m => m !== primaryModel)];
  let triedMoreThanOne = false;
  try{
    for(let i = 0; i < modelChain.length; i++){
      const model = modelChain[i];
      try{
        const result = await callGeminiModel(model, ticker, s);
        const { cleanText, levels } = parseGeminiLevels(result.text);
        state.geminiAnalysis.set(ticker, { text: cleanText, model: result.model, at: Date.now() });
        if(levels) state.geminiLevels.set(ticker, levels); else state.geminiLevels.delete(ticker);
        if(result.sources && result.sources.length) state.geminiSources.set(ticker, result.sources); else state.geminiSources.delete(ticker);
        return; // sukses
      }catch(e){
        const isLastModel = i === modelChain.length - 1;
        if(!isLastModel && e.retryable){
          // Model ini overload -> coba model cadangan berikutnya di chain.
          triedMoreThanOne = true;
          state.geminiRetryStatus.set(ticker, { attempt: 1, max: GEMINI_MAX_ATTEMPTS, model: modelChain[i+1], switchingFrom: model });
          render();
          continue;
        }
        throw e;
      }
    }
  }catch(e){
    const note = triedMoreThanOne
      ? ` (sudah dicoba beberapa model Gemini, server Google masih sibuk — coba lagi beberapa saat lagi)`
      : "";
    state.geminiError.set(ticker, (e.message || String(e)) + note);
  }finally{
    state.geminiLoading.delete(ticker);
    state.geminiRetryStatus.delete(ticker);
    render();
  }
}

// Card Entry/TP/SL dari hasil parse LEVELS_JSON Gemini (lihat parseGeminiLevels).
// Gaya visual disamakan dengan bsjpTradePlanCard() supaya konsisten dengan
// Trading Plan rule-based yang sudah ada.
function geminiLevelsCard(levels){
  if(!levels) return "";
  const row = (label, val, tone) => `<div style="display:flex;justify-content:space-between;padding:5px 0;border-bottom:1px dashed var(--border);"><span style="color:var(--muted);font-size:12px;">${label}</span><span class="mono" style="font-weight:700;color:${tone||'var(--text)'};">${val}</span></div>`;
  const rp = v => v!=null ? "Rp "+fmtNum(Math.round(v)) : "-";
  const rr = (levels.entry!=null && levels.tp1!=null && levels.sl!=null && (levels.entry - levels.sl) > 0)
    ? ((levels.tp1 - levels.entry) / (levels.entry - levels.sl)).toFixed(2)
    : null;
  return `
    <div style="background:rgba(167,139,250,0.06);border:1px solid rgba(167,139,250,0.25);border-radius:10px;padding:14px;margin-top:10px;">
      <div style="font-size:11px;text-transform:uppercase;letter-spacing:.05em;color:var(--muted);font-weight:700;margin-bottom:8px;">🎯 Level Ilustratif dari AI (Entry / TP / SL)</div>
      ${row("Entry", rp(levels.entry))}
      ${row("Target Profit 1", rp(levels.tp1), "var(--up)")}
      ${levels.tp2!=null ? row("Target Profit 2", rp(levels.tp2), "var(--up)") : ""}
      ${row("Stop Loss", rp(levels.sl), "var(--down)")}
      ${rr!=null ? row("Risk : Reward (ke TP1)", "1 : "+rr) : ""}
      ${levels.basis ? `<div style="margin-top:10px;padding-top:10px;border-top:1px dashed var(--border);font-size:11px;color:var(--muted);"><b>Dasar:</b> ${escapeHtml(levels.basis)}</div>` : ""}
      <div style="margin-top:8px;font-size:10px;color:var(--muted);">⚠️ Angka ini dihasilkan model AI dari data yang sama seperti di atas — BUKAN rekomendasi/jaminan, dan bisa saja tidak masuk akal. Selalu cek ulang manual (support/resistance, orderbook, berita) sebelum dipakai.</div>
    </div>`;
}

// Render daftar sumber (link) hasil Google Search grounding yang dipakai
// Gemini di BAGIAN 2 (riset independen) prompt — lihat extractGeminiSources.
// Ditampilkan terpisah dari teks analisis supaya user bisa cek sendiri
// asal klaim "riset independen"-nya, bukan cuma percaya mentah-mentah.
function geminiSourcesCard(sources){
  if(!sources || !sources.length) return "";
  const items = sources.slice(0, 8).map(src =>
    `<li style="margin-bottom:4px;"><a href="${escapeHtml(src.uri)}" target="_blank" rel="noopener noreferrer" style="color:var(--teal);text-decoration:underline;font-size:12px;">${escapeHtml(src.title)}</a></li>`
  ).join("");
  return `
    <div style="background:rgba(56,189,248,0.06);border:1px solid rgba(56,189,248,0.25);border-radius:10px;padding:12px 14px;margin-top:10px;">
      <div style="font-size:11px;text-transform:uppercase;letter-spacing:.05em;color:var(--muted);font-weight:700;margin-bottom:6px;">🔎 Sumber Riset Independen (Google Search)</div>
      <ul style="margin:0;padding-left:18px;">${items}</ul>
    </div>`;
}

function renderDetailAiGemini(s){
  const ticker = s.ticker;
  const loading = state.geminiLoading.has(ticker);
  const cached = state.geminiAnalysis.get(ticker);
  const error = state.geminiError.get(ticker);
  const levels = state.geminiLevels.get(ticker);
  const sources = state.geminiSources.get(ticker);
  const hasKey = !!state.geminiApiKey;
  const retryStatus = state.geminiRetryStatus.get(ticker);

  const analysisHtml = cached
    ? `<div class="empty-box" style="text-align:left;white-space:pre-wrap;line-height:1.6;font-size:13px;background:rgba(167,139,250,0.06);border-color:rgba(167,139,250,0.25);">${escapeHtml(cached.text)}</div>
       <div style="font-size:11px;color:var(--muted);margin-top:6px;">Model: <code>${escapeHtml(cached.model)}</code> · Dihasilkan ${new Date(cached.at).toLocaleString("id-ID")}</div>
       ${geminiSourcesCard(sources)}
       ${geminiLevelsCard(levels)}`
    : "";
  const errorHtml = error
    ? `<div class="empty-box" style="text-align:left;color:#f87171;background:rgba(239,68,68,0.08);border-color:rgba(239,68,68,0.3);">⚠️ ${escapeHtml(error)}</div>`
    : "";

  return `
    <div class="detail-subtitle">🤖 Analisis AI (Gemini) — ${escapeHtml(ticker)}</div>
    <div style="font-size:11.5px;color:var(--muted);margin-bottom:12px;line-height:1.5;">
      Dua bagian: <b>(1)</b> analisa Fundamental/Teknikal/Bandarmologi versi Gemini sendiri — data screener
      cuma jadi titik awal, bukan sekadar dibaca ulang, dan <b>(2)</b> riset independen Gemini via Google Search — berita/aksi korporasi, pandangan
      teknikal, dan indikasi bandarmologi/aliran dana TERBARU di luar data screener. Tetap
      <b>bukan rekomendasi/nasihat investasi</b>. Termasuk level Entry/TP/SL ilustratif dan daftar sumber di bawah.
    </div>
    ${!hasKey ? `<div class="empty-box" style="text-align:left;">API key Gemini belum diisi. Buka <button type="button" onclick="closeDetail();openSettings();" style="background:none;border:none;color:var(--teal);text-decoration:underline;cursor:pointer;padding:0;font-size:12px;">⚙️ Pengaturan</button> → bagian "🤖 Analisis AI (Gemini)" untuk mengisi API key gratis dari Google AI Studio.</div>` : ""}
    <button type="button" class="btn btn-outline" data-gemini-run="${escapeHtml(ticker)}" ${loading || !hasKey ? "disabled" : ""} style="margin-bottom:12px;">
      ${loading ? (retryStatus ? `⏳ Server sibuk, mencoba lagi (${retryStatus.attempt}/${retryStatus.max})...` : "⏳ Menganalisis...") : cached ? "🔄 Analisis Ulang" : "🤖 Buat Analisis AI"}
    </button>
    ${errorHtml}
    ${analysisHtml}
  `;
}

// ==========================================
// TAB "📊 Analisa Saham" (Detail Emiten) -- MENGGANTIKAN tab "🤖 AI (Gemini)"
// di daftar tabs[] renderDetailModalContent(). Sumber data endpoint Arjum
// /api/analysis/{code} (lihat loadArjumAnalysis() dekat loadFundamentalSeasonal
// di atas) -- API pihak ketiga stock.arjum.com yang SAMA dengan panel
// Laporan Keuangan & Seasonality di tab 💰 Fundamental, BUKAN Gemini/Google
// lagi. Fungsi runGeminiAnalysis/renderDetailAiGemini di atas SENGAJA
// dibiarkan ada (tidak dihapus) -- gemini_api_key masih dipakai Edge
// Function Cron notifikasi Telegram (lihat telegram_settings), jadi
// panel "🤖 Analisis AI (Gemini)" di ⚙️ Pengaturan tetap ada untuk itu;
// yang diganti cuma tab di modal Detail Emiten ini.
// ==========================================
// ==========================================
// TAB "📊 Analisa Saham" (Detail Emiten) -- MENGGANTIKAN tab "🤖 AI (Gemini)"
// di daftar tabs[] renderDetailModalContent(). Sumber data endpoint Arjum
// /api/analysis/{code} (lihat loadArjumAnalysis() dekat loadFundamentalSeasonal
// di atas) -- API pihak ketiga stock.arjum.com yang SAMA dengan panel
// Laporan Keuangan & Seasonality di tab 💰 Fundamental, BUKAN Gemini/Google
// lagi. Fungsi runGeminiAnalysis/renderDetailAiGemini di atas SENGAJA
// dibiarkan ada (tidak dihapus) -- gemini_api_key masih dipakai Edge
// Function Cron notifikasi Telegram (lihat telegram_settings), jadi
// panel "🤖 Analisis AI (Gemini)" di ⚙️ Pengaturan tetap ada untuk itu;
// yang diganti cuma tab di modal Detail Emiten ini.
//
// BENTUK RESPONS: dari contoh nyata yang dikonfirmasi user, isi analisanya
// bukan JSON terstruktur per kategori, tapi SATU STRING narasi panjang
// (markdown-lite) dengan header berformat "**📈 JUDUL SEKSI**" di barisnya
// sendiri (Price Action, Teknikal, Volume, Foreign Flow, Broker Netflow,
// Signal, Personality Historis, Rekomendasi, + baris disclaimer "***...***").
// findArjumAnalysisText() menebak field mana di response yang berisi string
// itu (nama field belum dikonfirmasi resmi, bisa beda-beda), lalu
// arjumSplitAnalysisSections() memecahnya per header, dan
// groupArjumSection() mengelompokkan tiap header ke salah satu dari
// 💰 Fundamental / 📊 Teknikal & Harga / 🐋 Bandarmologi / 💡 Insight &
// Rekomendasi / 📌 Lainnya (kalau ada header yang tidak dikenali). Kalau
// field narasinya tidak ketemu sama sekali (bentuk respons ternyata beda),
// jatuh balik ke renderArjumDataTree() (tree generik) supaya tetap ada yang
// ditampilkan, bukan kosong.
// ==========================================

// Cari string narasi panjang di dalam response -- coba nama field yang
// paling mungkin dulu, baru fallback ke string terpanjang di seluruh object
// (maks 2 level nested) kalau nama field di atas semua tidak cocok.
function findArjumAnalysisText(data){
  if(!data) return null;
  if(typeof data === "string") return data;
  if(typeof data !== "object") return null;
  const candidates = ["analysis","analysis_text","analysisText","narrative","text","content","summary","report","output","insight","markdown","result","message","full_text"];
  for(const k of candidates){
    if(typeof data[k] === "string" && data[k].length > 80) return data[k];
  }
  let best = null;
  const scan = (obj, depth) => {
    if(!obj || typeof obj !== "object" || depth > 2) return;
    Object.values(obj).forEach(v => {
      if(typeof v === "string"){ if(!best || v.length > best.length) best = v; }
      else if(v && typeof v === "object") scan(v, depth+1);
    });
  };
  scan(data, 0);
  return (best && best.length > 80) ? best : null;
}

// Pecah narasi jadi { title, subtitle, sections:[{title,lines}], notices:[] }.
// Header seksi = baris yang SELURUHNYA "**...**" (dua bintang, bukan tiga --
// disclaimer pakai tiga bintang, lihat komentar blok di atas). Dua baris
// pertama SEBELUM header manapun ditangkap sbg title/subtitle (nama saham +
// tanggal, nama perusahaan).
function arjumSplitAnalysisSections(text){
  const lines = String(text||"").replace(/\r\n/g,"\n").split("\n");
  const result = { title:"", subtitle:"", sections:[], notices:[] };
  let current = null;
  lines.forEach(rawLine => {
    const line = rawLine.trim();
    if(!line) return;
    const notice = line.match(/^\*{3}(.+?)\*{3}$/);
    if(notice){ result.notices.push(notice[1].trim()); return; }
    const header = line.match(/^\*{2}([^*]+)\*{2}$/);
    if(header){
      current = { title: header[1].trim(), lines: [] };
      result.sections.push(current);
      return;
    }
    if(current){ current.lines.push(line); return; }
    if(!result.title) result.title = line;
    else if(!result.subtitle) result.subtitle = line;
  });
  return result;
}

// Konversi markdown-lite (**bold**, _italic_) satu baris jadi HTML, dengan
// escaping dulu supaya karakter aneh di narasi AI tidak merusak layout.
function arjumMdInline(line){
  let esc = escapeHtml(line);
  esc = esc.replace(/\*\*(.+?)\*\*/g, "<b>$1</b>");
  esc = esc.replace(/_(.+?)_/g, "<i>$1</i>");
  return esc;
}

// Pemetaan header seksi -> kelompok tampilan. Dicocokkan per kata kunci
// (case-insensitive) supaya tahan kalau susunan section/tanda baca sedikit
// beda antar ticker/waktu -- header yang tidak cocok kategori manapun
// tetap ditampilkan (masuk kelompok "📌 Lainnya"), tidak pernah dibuang diam-diam.
const ARJUM_ANALYSIS_GROUPS = [
  { key:"fundamental", label:"💰 Fundamental", match:/FUNDAMENTAL|VALUASI|EPS|PER\b|PBV|ROE|DER\b|LAPORAN KEUANGAN/i },
  { key:"teknikal", label:"📊 Teknikal &amp; Harga", match:/PRICE ACTION|TEKNIKAL|VOLUME|SUPPORT|RESISTANCE|INDIKATOR/i },
  { key:"bandarmologi", label:"🐋 Bandarmologi", match:/FOREIGN|BROKER|BANDAR|AKUMULASI|NETFLOW/i },
  { key:"insight", label:"💡 Insight &amp; Rekomendasi", match:/SIGNAL|PERSONALITY|HISTORIS|REKOMENDASI|KESIMPULAN|SUMMARY/i },
];
function groupArjumSection(title){
  const g = ARJUM_ANALYSIS_GROUPS.find(g => g.match.test(title));
  return g ? g.key : "lainnya";
}

function renderArjumAnalysisSectionCard(sec){
  const bodyHtml = sec.lines.map(l => `<div style="margin-bottom:3px;">${arjumMdInline(l)}</div>`).join("");
  return `
    <div style="background:rgba(255,255,255,0.02);border:1px solid var(--border);border-radius:10px;padding:12px 14px;margin-bottom:10px;">
      <div style="font-weight:700;font-size:12.5px;margin-bottom:6px;">${escapeHtml(sec.title)}</div>
      <div style="font-size:12px;line-height:1.65;">${bodyHtml || '<span style="color:var(--muted);">-</span>'}</div>
    </div>`;
}
function renderArjumAnalysisGroupPanel(label, sections){
  if(!sections || !sections.length) return "";
  return `
    <div class="panel" style="flex-direction:column;align-items:stretch;margin-bottom:14px;">
      <div class="filter-section-title" style="margin-bottom:10px;">${label}</div>
      ${sections.map(renderArjumAnalysisSectionCard).join("")}
    </div>`;
}

// Rangkai semua di atas jadi HTML lengkap tab. Return "" kalau narasinya
// tidak berhasil dipecah jadi section sama sekali (mis. format ternyata
// beda) -- pemanggil (renderDetailAnalisaSaham) jatuh balik ke
// renderArjumDataTree() kalau ini kosong.
function renderArjumAnalysisGrouped(rawText){
  const parsed = arjumSplitAnalysisSections(rawText);
  if(!parsed.sections.length) return "";

  const buckets = { fundamental:[], teknikal:[], bandarmologi:[], insight:[], lainnya:[] };
  parsed.sections.forEach(sec => buckets[groupArjumSection(sec.title)].push(sec));

  const headerHtml = (parsed.title || parsed.subtitle) ? `
    <div style="margin-bottom:14px;">
      ${parsed.title ? `<div style="font-size:14px;font-weight:700;">${arjumMdInline(parsed.title)}</div>` : ""}
      ${parsed.subtitle ? `<div style="font-size:12px;color:var(--muted);font-style:italic;margin-top:2px;">${arjumMdInline(parsed.subtitle)}</div>` : ""}
    </div>` : "";

  const noFundamentalNote = !buckets.fundamental.length
    ? `<div style="font-size:11px;color:var(--muted);margin:-6px 0 14px;">Tidak ada bagian Fundamental di analisa untuk ${parsed.title?"saham ini":"ini"} — API cuma mengembalikan Teknikal/Bandarmologi/Insight kali ini.</div>`
    : "";

  const noticeHtml = parsed.notices.length ? `
    <div style="margin-top:6px;padding:10px 12px;border-radius:8px;background:rgba(239,68,68,0.06);border:1px solid rgba(239,68,68,0.25);font-size:10.5px;color:var(--muted);font-style:italic;line-height:1.5;">
      ${parsed.notices.map(n => `<div>${arjumMdInline(n)}</div>`).join("")}
    </div>` : "";

  return `
    ${headerHtml}
    ${renderArjumAnalysisGroupPanel("💰 Fundamental", buckets.fundamental)}
    ${noFundamentalNote}
    ${renderArjumAnalysisGroupPanel("📊 Teknikal &amp; Harga", buckets.teknikal)}
    ${renderArjumAnalysisGroupPanel("🐋 Bandarmologi", buckets.bandarmologi)}
    ${renderArjumAnalysisGroupPanel("💡 Insight &amp; Rekomendasi", buckets.insight)}
    ${renderArjumAnalysisGroupPanel("📌 Lainnya", buckets.lainnya)}
    ${noticeHtml}
  `;
}

// ==========================================
// TAB "📈 Analisa Saham (Data App)" (Detail Emiten) -- versi LOKAL dari tab
// "📊 Analisa Saham" di sebelahnya. Bedanya: tab ini TIDAK memanggil API
// pihak ketiga manapun (Arjum/Gemini) -- semua narasi disusun INSTAN dari
// data yang SUDAH ada di `s` (hasil enrichOne(), field yang sama dipakai
// tab Teknikal/Fundamental/Bandarmologi/Trading Plan & buildGeminiPrompt di
// atas). Jadi: tidak ada tombol "Muat", tidak ada loading/error, dan tetap
// tersedia walau API key Arjum/Gemini belum diisi atau API-nya lagi down.
//
// Dikelompokkan ke 4 kelompok yang SAMA seperti tab sebelah -- 💰
// Fundamental / 📊 Teknikal & Harga / 🐋 Bandarmologi / 💡 Insight &
// Rekomendasi -- lalu dirender lewat renderArjumAnalysisGroupPanel() yang
// SAMA (dipakai juga oleh renderArjumAnalysisGrouped() di atas) supaya
// tampilan kartunya konsisten dgn tab Arjum, meski isinya dari mesin
// rule-based aplikasi sendiri, bukan string narasi dari API eksternal.
// ==========================================
function renderDetailAnalisaSahamData(s){
  const ticker = s.ticker;
  const num = (v, opts) => dNum(v, opts);

  // --- 💰 Fundamental ---
  const fundLines = [];
  if(s.per!=null || s.pbv!=null){
    fundLines.push(`Valuasi (heuristik screener): **${s.valuasi||"-"}** — PER ${s.per??"-"}x, PBV ${s.pbv??"-"}x, PSR ${s.psr??"-"}x.`);
  } else {
    fundLines.push("Data PER/PBV emiten ini belum lengkap di database, sehingga valuasi belum bisa disimpulkan.");
  }
  fundLines.push(`ROE ${s.roe!=null?num(s.roe,{decimals:2,suffix:'%'}):"-"}, ROA ${s.roa!=null?num(s.roa,{decimals:2,suffix:'%'}):"-"}, NPM ${s.npm!=null?num(s.npm,{decimals:2,suffix:'%'}):"-"}, DER ${s.der??"-"}x.`);
  if(s.revenueGrowth!=null || s.earningsGrowth!=null || s.divYield!=null){
    fundLines.push(`Revenue Growth ${s.revenueGrowth!=null?num(s.revenueGrowth,{plusSign:true,decimals:2,suffix:'%'}):"-"}, Earnings Growth ${s.earningsGrowth!=null?num(s.earningsGrowth,{plusSign:true,decimals:2,suffix:'%'}):"-"}, Dividend Yield ${s.divYield!=null?num(s.divYield,{decimals:2,suffix:'%'}):"-"}.`);
  }
  const graham = grahamFairValue(s);
  if(graham!=null && s.cClose){
    const mos = ((graham - s.cClose)/s.cClose)*100;
    fundLines.push(`Nilai wajar Graham Number ≈ Rp ${num(graham,{decimals:0})} vs harga saat ini Rp ${num(s.cClose)} — margin of safety ${mos>=0?'+':''}${mos.toFixed(1)}% (${mos>=15?"harga di bawah nilai wajar":mos<=-15?"harga di atas nilai wajar":"harga sekitar nilai wajar"}).`);
  }
  fundLines.push(`Skor Fundamental (bagian dari FundTech Score): **${s.fundScore60??0}/60**. Market Cap: ${s.marketCap!=null?`Rp ${fmtCap(s.marketCap)}`:"-"} (${s.capTier||s.capCategory||"-"}).${s.syariahLabel==="Ya"?" Termasuk daftar saham Syariah.":""}`);

  // --- 📊 Teknikal & Harga ---
  const teknikalLines = [];
  teknikalLines.push(`Harga terakhir Rp ${num(s.cClose)} (${s.changePct!=null?num(s.changePct,{plusSign:true,decimals:2,suffix:'%'}):"-"} dari hari sebelumnya). Trend Harga (MA): **${s.trendHarga||"-"}**.`);
  teknikalLines.push(`RSI 7: ${s.rsi7!=null?Number(s.rsi7).toFixed(1):"-"} (status: ${s.statusRsi||"-"}), RSI 21: ${s.rsi21!=null?Number(s.rsi21).toFixed(1):"-"}. Sinyal MACD: **${s.cekMacd||"-"}**.`);
  teknikalLines.push(`Volume vs rata-rata 20 hari: ${s.volRatio!=null?Number(s.volRatio).toFixed(2)+"x":"-"} (${s.sinyalVolume||"-"}). Frekuensi transaksi: ${s.sinyalFrekuensi||"-"}.`);
  teknikalLines.push(`Support terdekat Rp ${num(s.support)}, Resistance terdekat Rp ${num(s.resistance)}. Posisi dalam range 52 Minggu: ${s.pos52w!=null?num(s.pos52w,{decimals:1,suffix:'%'}):"-"}.`);
  if(s.polaCandle) teknikalLines.push(`Pola Candlestick terdeteksi: **${s.polaCandle}**${s.isBBSqueeze==="Ya"?", disertai BB Squeeze (potensi breakout)":""}.`);
  teknikalLines.push(`Skor Teknikal (bagian dari FundTech Score): **${s.techScore40??0}/40**. Status Golden Cross EMA9×21: ${s.ema921Status||"-"}.`);

  // --- 🐋 Bandarmologi ---
  const bandarLines = [];
  bandarLines.push(`Sinyal proxy volume + arah harga: **${(s.band && s.band.label) || "-"}**.`);
  if(s.foreignNet20D!=null || s.foreignNet5D!=null || s.foreignNet1D!=null){
    bandarLines.push(`Net Asing 1 Hari: ${fmtRp(s.foreignNet1D)}, 5 Hari: ${fmtRp(s.foreignNet5D)}, 20 Hari: ${fmtRp(s.foreignNet20D)} (data resmi IDX, per ${s.flowDate||"hari perdagangan terakhir"}).`);
    if(s.foreignUpDays!=null) bandarLines.push(`Asing net beli pada ${s.foreignUpDays} dari ${s.flowDays??20} hari terakhir.`);
  } else {
    bandarLines.push("Belum ada data aliran dana asing IDX untuk emiten ini (kemungkinan suspensi/nyaris tidak diperdagangkan dalam 20 hari terakhir).");
  }
  bandarLines.push(`Indikasi "Uang Gede Masuk" (RVOL &amp; CLV): **${s.uangGedeMasuk||"-"}**.`);

  // --- 💡 Insight & Rekomendasi ---
  const insightLines = [];
  insightLines.push(`Keyakinan Naik (rule-based): **${s.keyakinanNaik||"-"}** (skor ${s.keyakinanScore??0}/100).`);
  insightLines.push(`Rekomendasi Setup: ${s.rekomendasi && s.rekomendasi!=="-" ? `**${s.rekomendasi}**` : "tidak ada setup breakout/pullback yang aktif saat ini"}.`);
  insightLines.push(`Skor Bagger: **${s.baggerScoreTotal??0}/${s.baggerScoreMax??100}** (${s.baggerTier||"-"}). Skor FundTech gabungan (60/40): **${s.fundTechScore??0}/100** (${(s.fundTech && s.fundTech.label)||"-"}).`);
  if(s.bsjp){
    insightLines.push(`Filter BSJP (Beli Sore Jual Pagi): ${s.bsjp.passedCount??"-"}/${s.bsjp.totalChecks??8} kriteria lolos, skor ${s.bsjp.score??"-"}/100 — sinyal **${s.bsjp.signal||"-"}**.`);
  }
  insightLines.push(`***Catatan: seluruh angka di atas murni hasil rumus/aturan di aplikasi ini (bukan AI, bukan API eksternal) dari data screener terakhir — bukan rekomendasi/nasihat investasi.***`);

  const sections = {
    fundamental: [{ title:"Ringkasan Fundamental", lines: fundLines }],
    teknikal: [{ title:"Ringkasan Teknikal &amp; Harga", lines: teknikalLines }],
    bandarmologi: [{ title:"Ringkasan Bandarmologi", lines: bandarLines }],
    insight: [{ title:"Insight &amp; Rekomendasi (Rule-Based)", lines: insightLines }],
  };

  return `
    <div class="detail-subtitle">📈 Analisa Saham (Data App) — ${escapeHtml(ticker)}</div>
    <div style="font-size:11.5px;color:var(--muted);margin-bottom:12px;line-height:1.5;">
      Versi analisa yang disusun <b>instan dari data yang sudah ada di aplikasi ini</b> (indikator teknikal, skor
      Fundamental/Bagger/FundTech, sinyal Bandarmologi proxy, dan Net Asing IDX) — <b>bukan</b> memanggil API pihak
      ketiga (Arjum/Gemini) seperti tab "📊 Analisa Saham" di sebelah, jadi selalu tersedia tanpa API key & tanpa
      loading. Dikelompokkan sama seperti tab sebelah supaya mudah dibandingkan. <b>Bukan rekomendasi/nasihat
      investasi.</b>
    </div>
    ${renderArjumAnalysisGroupPanel("💰 Fundamental", sections.fundamental)}
    ${renderArjumAnalysisGroupPanel("📊 Teknikal &amp; Harga", sections.teknikal)}
    ${renderArjumAnalysisGroupPanel("🐋 Bandarmologi", sections.bandarmologi)}
    ${renderArjumAnalysisGroupPanel("💡 Insight &amp; Rekomendasi", sections.insight)}
  `;
}

function renderDetailAnalisaSaham(s){
  const ticker = s.ticker;
  const loading = state.arjumAnalysisLoading.has(ticker);
  const cached = state.arjumAnalysisCache.get(ticker);
  const error = state.arjumAnalysisError.get(ticker);
  const hasKey = !!(state.arjumApiKey || state.arjumProxyUrl);

  let cachedBodyHtml = "";
  if(cached){
    const rawText = findArjumAnalysisText(cached.data);
    const groupedHtml = rawText ? renderArjumAnalysisGrouped(rawText) : "";
    cachedBodyHtml = `
      <div style="font-size:11px;color:var(--muted);margin-bottom:8px;">Ditarik ${new Date(cached.at).toLocaleString("id-ID")}</div>
      ${groupedHtml || renderArjumDataTree(cached.data, 0)}
      ${groupedHtml ? `
        <details style="margin-top:6px;">
          <summary style="cursor:pointer;color:var(--teal);font-size:11px;">Lihat data mentah dari API</summary>
          <div style="padding:8px 0 2px 10px;border-left:2px solid var(--border);margin-top:6px;">${renderArjumDataTree(cached.data, 0)}</div>
        </details>` : ""}`;
  }

  return `
    <div class="detail-subtitle">📊 Analisa Saham — ${escapeHtml(ticker)}</div>
    <div style="font-size:11.5px;color:var(--muted);margin-bottom:12px;line-height:1.5;">
      Analisa siap-pakai dari API pihak ketiga <a href="https://stock.arjum.com" target="_blank" rel="noopener" style="color:var(--teal);">stock.arjum.com</a>
      (endpoint <code>/api/analysis/{code}</code>) — sumber yang SAMA dengan panel Laporan Keuangan &amp; Seasonality
      di tab 💰 Fundamental, jadi pakai API key Arjum yang sama juga. Dikelompokkan otomatis jadi Fundamental /
      Teknikal / Bandarmologi / Insight di bawah. <b>Bukan rekomendasi/nasihat investasi.</b>
    </div>
    ${!hasKey ? `<div class="empty-box" style="text-align:left;">API key Arjum belum diisi. Buka <button type="button" onclick="closeDetail();openSettings();" style="background:none;border:none;color:var(--teal);text-decoration:underline;cursor:pointer;padding:0;font-size:12px;">⚙️ Pengaturan</button> → bagian "📑 Fundamental Screener (Arjum)" untuk mengisi API key (daftar gratis di stock.arjum.com).</div>` : ""}
    <button type="button" class="btn btn-outline" data-arjum-analysis-run="${escapeHtml(ticker)}" ${loading || !hasKey ? "disabled" : ""} style="margin-bottom:12px;">
      ${loading ? "⏳ Memuat..." : cached ? "🔄 Muat Ulang" : "📊 Muat Analisa Saham"}
    </button>
    ${error ? `<div class="empty-box" style="text-align:left;color:#f87171;background:rgba(239,68,68,0.08);border-color:rgba(239,68,68,0.3);">⚠️ ${escapeHtml(error)}</div>` : ""}
    ${cachedBodyHtml || (!loading && !error ? `<div class="empty-box" style="text-align:left;">Klik "📊 Muat Analisa Saham" di atas untuk menarik analisa terbaru untuk ${escapeHtml(ticker)}.</div>` : "")}
  `;
}


// resolveDetailLiveRow — kalau tab Live Data Stockbit di modal Detail Emiten
// sudah pernah berhasil ditarik untuk ticker ini (state.stockbitLive[ticker],
// bukan loading/error), timpa cClose/cVol/changePct saham ini dengan harga
// live-nya (buildLiveStockRow — fungsi yang SAMA dipakai jalur Alert Live
// dari WS Stockbit), lalu hitung ULANG semua turunan teknikal (band,
// Skor Bagger, FundTech, BSJP, dst.) dari harga live itu lewat enrichOne() —
// supaya harga di header DAN semua tab (Analisa/Teknikal/Trading Plan) ikut
// "hidup", bukan cuma header-nya doang sementara breakdown teknikal di
// bawahnya tetap pakai harga EOD kemarin.
//
// Kalau live belum pernah ditarik / masih loading / error, return null —
// pemanggil (renderDetailModalContent) jatuh balik ke `s` EOD biasa, tidak
// ada perubahan perilaku dari sebelumnya.
function resolveDetailLiveRow(ticker){
  const live = state.stockbitLive[ticker];
  if (!live || live.loading || live.error || !live.mapped) return null;
  const livePrice = Number(live.mapped.last);
  if (!Number.isFinite(livePrice) || livePrice <= 0) return null;
  const rawVol = Number(live.mapped.volume);
  const liveVol = Number.isFinite(rawVol) && rawVol >= 0 ? rawVol : null;
  const raw = state.stocks.find(x => x.ticker === ticker);
  if (!raw) return null;
  const patched = buildLiveStockRow(raw, livePrice, liveVol);
  return { row: enrichOne(patched), fetchedAt: live.fetchedAt };
}

// Ticker yang diklik (dari Backtest/Portfolio/leaderboard/dst) bisa saja
// TIDAK ADA di database screener SAAT INI -- IPO/relisting baru yang belum
// ter-scrape, sudah delisting, salah ketik, atau data screener belum
// di-update. Sebelumnya modal cuma menampilkan satu baris pesan generik
// tanpa konteks apa pun. Sekarang: (1) beri kemungkinan penyebab + saran
// tindakan, dan (2) kalau ticker itu KEBETULAN masih tercatat di riwayat
// Backtest (state.backtests), tampilkan ringkasannya di sini juga --
// supaya user tetap dapat info dasar (tanggal/harga entry/sumber) meski
// detail teknikal lengkap tidak bisa dihitung karena data screener kosong.
function renderDetailNotFound(ticker){
  const occurrences = [];
  (state.backtests||[]).forEach(session => {
    (session.items||[]).forEach(item => {
      if(item.ticker === ticker) occurrences.push({ ...item, sessionDate: session.date });
    });
  });
  occurrences.sort((a,b) => String(b.entryDate||b.sessionDate||"").localeCompare(String(a.entryDate||a.sessionDate||"")));
  const rows = occurrences.map(o => `
    <tr>
      <td>${fmtDateID(o.entryDate || o.sessionDate)}</td>
      <td class="mono">${o.entryPrice!=null ? "Rp"+fmtNum(Math.round(o.entryPrice)) : "-"}</td>
      <td>${escapeHtml(o.sumber || "-")}</td>
      <td style="white-space:normal;max-width:220px;">${escapeHtml(o.kriteria || "-")}</td>
    </tr>`).join("");

  return `
    <div class="empty-box" style="text-align:left;line-height:1.6;">
      Data untuk <b>${escapeHtml(ticker)}</b> tidak ditemukan di database screener saat ini.<br>
      Kemungkinan penyebab: ticker baru IPO/relisting yang belum ter-scrape ke database, sudah delisting,
      kode ticker salah ketik, atau data screener belum di-update — coba jalankan "🔄 Update Data" dulu
      kalau ${escapeHtml(ticker)} masih aktif diperdagangkan.
    </div>
    ${occurrences.length ? `
      <div style="font-size:11px;color:var(--muted);margin:12px 0 6px;">
        Ditemukan ${occurrences.length} riwayat untuk ${escapeHtml(ticker)} di Backtest — teknikal lengkap tidak bisa
        dihitung (data screener kosong), tapi ini catatan yang tersimpan:
      </div>
      <div class="table-wrap">
        <table class="mono">
          <thead><tr><th>Tgl Entry</th><th>Harga Entry</th><th>Sumber</th><th>Kriteria</th></tr></thead>
          <tbody>${rows}</tbody>
        </table>
      </div>` : ""}
  `;
}

function renderDetailModalContent(){
  let s = enriched().find(x => x.ticker === state.detailTicker);
  if(!s){
    return renderDetailNotFound(state.detailTicker);
  }
  const liveResolved = resolveDetailLiveRow(state.detailTicker);
  if (liveResolved) s = liveResolved.row;
  const tabs = [
    { key:"teknikal", label:"📊 Teknikal" },
    { key:"fundamental", label:"💰 Fundamental" },
    { key:"bandarmologi", label:"🐋 Bandarmologi (IDX)" },
    { key:"brokersum", label:"🏦 Broker Summary" },
    { key:"historical", label:"📅 Historical Data" },
    { key:"insider", label:"🕵️ Insider" },
    { key:"aiGemini", label:"📊 Analisa Saham" },
    { key:"analisaData", label:"📈 Analisa Saham (Data App)" },
    { key:"vssektor", label:"⚖️ vs Sektor" },
    { key:"plan", label:"📋 Trading Plan" }
  ];
  const tabBtns = tabs.map(t => `<button type="button" class="detail-tab-btn ${state.detailTab===t.key?'active':''}" data-detail-tab="${t.key}">${t.label}</button>`).join("");
  let body = "";
  if(state.detailTab === "teknikal") body = renderDetailTeknikal(s);
  else if(state.detailTab === "fundamental") body = renderDetailFundamental(s);
  else if(state.detailTab === "bandarmologi") body = renderDetailBandarmologi(s);
  else if(state.detailTab === "brokersum") body = renderDetailBrokerSummary(s);
  else if(state.detailTab === "historical") body = renderDetailHistorical(s);
  else if(state.detailTab === "insider") body = renderDetailInsider(s);
  else if(state.detailTab === "aiGemini") body = renderDetailAnalisaSaham(s);
  else if(state.detailTab === "analisaData") body = renderDetailAnalisaSahamData(s);
  else if(state.detailTab === "vssektor") body = renderDetailVsSektor(s);
  else if(state.detailTab === "plan") body = renderDetailTradingPlan(s);
  else body = renderDetailAnalisa(s);

  const liveBadge = liveResolved
    ? `<span style="font-size:10px;font-weight:700;color:#f87171;margin-left:8px;vertical-align:middle;border:1px solid rgba(239,68,68,0.4);border-radius:5px;padding:1px 6px;" title="Harga & seluruh perhitungan teknikal di tab ini sudah memakai data Live Stockbit (ditarik ${Math.max(0,Math.round((Date.now()-liveResolved.fetchedAt)/1000))} detik lalu), bukan harga EOD">🔴 LIVE</span>`
    : "";
  const navList = state.detailNavList;
  const navIdx = navList ? navList.indexOf(state.detailTicker) : -1;
  const navRow = navIdx >= 0 ? `
    <div class="detail-nav" style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:10px;">
      <button type="button" class="btn btn-outline" data-detail-nav="-1" ${navIdx<=0?"disabled":""} title="Saham sebelumnya di hasil screener" style="padding:6px 12px;font-size:12px;">‹ ${navIdx>0 ? escapeHtml(navList[navIdx-1]) : "Sebelumnya"}</button>
      <span class="mono" style="font-size:12px;color:var(--muted);text-align:center;">${navIdx+1} / ${navList.length} di hasil screener</span>
      <button type="button" class="btn btn-outline" data-detail-nav="1" ${navIdx>=navList.length-1?"disabled":""} title="Saham berikutnya di hasil screener" style="padding:6px 12px;font-size:12px;">${navIdx<navList.length-1 ? escapeHtml(navList[navIdx+1]) : "Berikutnya"} ›</button>
    </div>` : "";
  return `
    ${navRow}
    <div class="detail-head">
      <div>
        <div class="detail-head-price">${dNum(s.cClose)} <span style="font-size:15px;font-weight:600;color:${(s.changePct??0)>=0?'var(--up)':'var(--down)'}">${s.changePct!=null?dNum(s.changePct,{plusSign:true,decimals:2,suffix:'%'}):''}</span>${liveBadge}</div>
        <div class="detail-head-sub">${s.sektor||"Sektor tidak diketahui"} ${s.syariahLabel==="Ya" ? "· Syariah" : ""}</div>
      </div>
      <div style="display:flex;gap:10px;">
        <a class="btn btn-outline" href="#/chart/${encodeURIComponent(s.ticker)}" data-chart="${s.ticker}">Lihat Grafik</a>
        <a class="btn btn-outline btn-tradingview" href="${tvChartPageUrl(s.ticker)}" target="_blank" rel="noopener">TV</a>
        <a class="btn btn-outline btn-stockbit" href="${stockbitUrl(s.ticker)}" target="_blank" rel="noopener">SB</a>
      </div>
    </div>
    <div class="detail-tabs">${tabBtns}</div>
    ${body}
  `;
}


async function loadChart(ticker){
  state.selectedTicker=ticker; state.tab="chart";
  syncHashFromState();
  // Setiap kali buka/ganti ticker, reset tampilan chart ke default yang
  // sudah terbukti paling kepake: rentang 1 bulan, overlay Close/Support/
  // Resisten/EMA21 High-Low/EMA89 aktif (Fibonacci, Bollinger Bands, SAR,
  // SuperTrend, Price Channel dimatikan biar tidak penuh), dan semua panel
  // bawah (Bandar Volume, Volume 20, Stoch RSI, RSI 7&21, Foreign Flow,
  // MACD, Net Foreign Buy/Sell) aktif. User tetap bisa toggle manual
  // sesudahnya lewat checkbox — ini cuma titik awal tiap ganti ticker.
  state.chartRange = "1m";
  state.chartTimeframe = "daily";
  state.chartZoom = 1;
  state.chartSeries = {
    close:true, support:true, resistance:true, fib:false, tpsl:true, bb:false,
    emaHL:true, ema89:true, ema921:false, sar:false, supertrend:false, pc:false,
    bandar:true, vol:true, stochrsi:true, rsi721:true, foreignflow:true, macd:true, netforeign:true
  };
  const stock = enriched().find(s=>s.ticker===ticker);
  state.selectedLevels = stock ? {
    support:stock.support, resistance:stock.resistance,
    ema21H:stock.ema21H, ema21L:stock.ema21L, fib:stock.fib
  } : null;

  // Histori harga ASLI dari tabel `flows` (diisi sync-idx-full.mjs dari
  // IDX), bukan lagi deret acak (genDemoSeries lama). `flows` disimpan
  // sampai ~450 hari kalender terakhir per ticker — lihat MAX_DAYS di
  // sync-idx-full.mjs. Tarik OHLC penuh + foreign_buy/foreign_sell (bukan
  // cuma close/volume) supaya panel chart custom (SAR, SuperTrend, Price
  // Channel, Bandar Volume, Foreign Flow, Net Foreign Buy/Sell) bisa
  // dihitung -- semuanya butuh high/low atau data asing harian.
  //
  // MASALAH yang dulu ditambal 2 query terpisah (flows + susul-tarik
  // price_history_stockbit): sync-idx-full.mjs itu EOD resmi IDX dan
  // harus dijalankan MANUAL dari jaringan rumah, jadi `flows` gampang
  // ketinggalan 1+ hari bursa. SEKARANG itu sudah ditambal di level
  // database (migrasi flows+src, src='idx'|'stockbit'): baris hasil
  // tarik Stockbit langsung diupsert ke `flows` sendiri, jadi SATU query
  // ini sudah otomatis lengkap sampai hari terbaru -- tidak perlu lagi
  // fetch kedua ke price_history_stockbit. Bar yang src='stockbit' tetap
  // tidak punya foreign_buy/foreign_sell (kolom itu tidak ditarik dari
  // Stockbit) jadi foreignBuy/foreignSell-nya null -- panel Foreign
  // Flow/Net Foreign untuk bar itu otomatis kosong sampai IDX menyusul
  // (trigger database lalu mengisi kolom yang masih kosong itu tanpa
  // menimpa harga yang sudah ada), tapi candle/EMA/overlay harga lain
  // tetap ikut update.
  state.chartData = [];
  state.chartLoading = true;
  render();
  try{
    const rows = await fetch(
      `${SUPABASE_URL}/flows?ticker=eq.${encodeURIComponent(ticker)}&select=date,open_price,high,low,close,volume,foreign_buy,foreign_sell,src&order=date.asc`,
      { headers: getSupaHeaders(), cache: "no-store" }
    ).then(r=>r.json());

    if (Array.isArray(rows) && rows.length){
      state.chartData = rows
        .filter(r => r.close != null)
        .map(r => ({
          date: r.date,
          open: r.open_price == null ? null : Number(r.open_price),
          high: r.high == null ? null : Number(r.high),
          low: r.low == null ? null : Number(r.low),
          close: Math.round(r.close),
          volume: r.volume == null ? null : Number(r.volume),
          foreignBuy: r.foreign_buy == null ? null : Number(r.foreign_buy),
          foreignSell: r.foreign_sell == null ? null : Number(r.foreign_sell),
          source: r.src === "stockbit" ? "stockbit" : "flows",
        }));
    }
  } catch(e){
    state.chartData = [];
  }

  state.chartLoading = false;
  // Overlay "Broker Accum" dikunci per-ticker (forTicker) -- data lama
  // ticker sebelumnya dibuang dulu di sini supaya tidak sempat kelihatan
  // "nempel" ke ticker baru sebelum refetch-nya selesai. Kalau overlay
  // sedang aktif (on=true), langsung tarik ulang untuk ticker baru ini.
  if(state.chartBrokerAccum){
    state.chartBrokerAccum.data = null;
    state.chartBrokerAccum.error = null;
    state.chartBrokerAccum.forTicker = null;
    if(state.chartBrokerAccum.on && state.chartData.length) loadChartBrokerAccum();
  }
  render();
}

// ==========================================
// loadChartBrokerAccum — tarik data broker_activity untuk ticker & kode
// broker yang aktif di overlay "Broker Accum" chart, lalu agregasi per
// broker per tanggal bursa (net lot, net value, avg price) + akumulasi
// berjalan (cumLot/cumValue/cumAvgPrice) dari hari paling awal yang ada
// di state.chartData sampai hari terakhir. Dipakai renderLwcChart() untuk
// gambar garis harga rata-rata akumulasi tiap broker (priceLine) & baris
// "BA:" di tooltip saat hover.
//
// avg price dihitung dari NILAI ABSOLUT net value/net lot (calcAvgPrice
// tidak menerima lot negatif) -- tandanya (+/-) tetap dibawa terpisah di
// netLot/netValue/cumLot/cumValue, cuma avgPrice-nya sendiri selalu
// harga positif (harga saham tidak bisa negatif).
// ==========================================
async function loadChartBrokerAccum(){
  const ticker = state.selectedTicker;
  state.chartBrokerAccum = state.chartBrokerAccum || { on:false, codes:"AK,BK,MG", data:null, loading:false, error:null, forTicker:null };
  const codes = parseBrokerCodesInput(state.chartBrokerAccum.codes || "");
  if(!ticker || !codes.length || !state.chartData.length){
    state.chartBrokerAccum.data = null;
    state.chartBrokerAccum.loading = false;
    state.chartBrokerAccum.error = !codes.length ? "Isi kode broker dulu (pisah koma), mis. AK,BK,MG" : null;
    render();
    return;
  }
  state.chartBrokerAccum.loading = true;
  state.chartBrokerAccum.error = null;
  render();
  try{
    const dates = state.chartData.map(d=>String(d.date).slice(0,10)).filter(Boolean).sort();
    const from = dates[0], to = dates[dates.length-1];
    const qs = new URLSearchParams();
    qs.append("stock_code", `eq.${ticker}`);
    qs.append("broker_code", `in.(${codes.join(",")})`);
    qs.append("trade_date", `gte.${from}`);
    qs.append("trade_date", `lte.${to}`);
    qs.append("order", "trade_date.asc");
    const res = await fetch(`${SUPABASE_URL}/broker_activity?${qs.toString()}`, { headers: getSupaHeaders(), cache: "no-store" });
    if(!res.ok) throw new Error(`HTTP ${res.status} ${res.statusText}`);
    const rows = await res.json();

    const byBroker = {};
    codes.forEach(c=> byBroker[c] = { byDate:{}, cumLot:0, cumValue:0 });
    rows.forEach(r=>{
      const code = String(r.broker_code||"").toUpperCase();
      if(!byBroker[code]) return;
      const d = String(r.trade_date).slice(0,10);
      const slot = byBroker[code].byDate[d] || (byBroker[code].byDate[d] = { buyLot:0, buyValue:0, sellLot:0, sellValue:0 });
      const lot = Number(r.lot) || 0, val = Number(r.value_idr) || 0;
      if(r.side === "buy"){ slot.buyLot += lot; slot.buyValue += val; }
      else if(r.side === "sell"){ slot.sellLot += lot; slot.sellValue += val; }
    });
    let anyData = false;
    codes.forEach(code=>{
      const b = byBroker[code];
      Object.keys(b.byDate).sort().forEach(d=>{
        anyData = true;
        const slot = b.byDate[d];
        const netLot = slot.buyLot - slot.sellLot;
        const netValue = slot.buyValue - slot.sellValue;
        b.cumLot += netLot;
        b.cumValue += netValue;
        slot.netLot = netLot;
        slot.netValue = netValue;
        slot.avgPrice = calcAvgPrice(Math.abs(netValue), Math.abs(netLot));
        slot.cumLot = b.cumLot;
        slot.cumValue = b.cumValue;
        slot.cumAvgPrice = calcAvgPrice(Math.abs(b.cumValue), Math.abs(b.cumLot));
      });
    });
    state.chartBrokerAccum.data = byBroker;
    state.chartBrokerAccum.forTicker = ticker;
    state.chartBrokerAccum.error = anyData ? null
      : `Belum ada data broker_activity untuk ${codes.join(", ")} pada ${ticker} di rentang tanggal chart ini (${fmtDateID(from)}–${fmtDateID(to)}). Tarik dulu lewat tab "Lacak Broker".`;
  }catch(e){
    state.chartBrokerAccum.error = "Gagal memuat data broker: " + e.message;
    state.chartBrokerAccum.data = null;
    state.chartBrokerAccum.forTicker = null;
  }
  state.chartBrokerAccum.loading = false;
  render();
}

// Return true kalau sinkron ke Supabase berhasil, false kalau gagal —
// dulu fungsi ini tidak mengembalikan apa pun sehingga pemanggil
// (saveToBacktest, addManualBacktest) tidak pernah tahu apakah data
// betulan tersimpan di server atau cuma di localStorage.
async function syncBacktestToSupabase(sessionId, sessionDate, items) {
  try {
    // `session_date` di Supabase bertipe kolom `date` (YYYY-MM-DD), tapi
    // `sessionDate` yang dikirim ke fungsi ini adalah string tampilan
    // locale Indonesia (mis. "23/8/2026, 11.29.08" dari
    // toLocaleString('id-ID')) — Postgres tidak bisa parse format itu sama
    // sekali (error: "invalid input syntax for type date"). Daripada
    // ikut-ikutan parse string locale itu (rawan salah locale/format lain
    // di kemudian hari), turunkan tanggal ISO langsung dari sessionId
    // (yang selalu berupa String(Date.now()) — lihat saveToBacktest &
    // addManualBacktest) sehingga selalu valid terlepas dari format
    // tampilan yang dipakai UI.
    const ts = Number(sessionId);
    const sessionDateIso = Number.isFinite(ts)
      ? toLocalISODate(new Date(ts))
      : todayLocalISO();

    await supaFetch(`${SUPABASE_URL}/backtest_sessions`, {
      method: "POST",
      headers: { ...getSupaHeaders(), "Prefer": "resolution=merge-duplicates" },
      body: JSON.stringify({ id: sessionId, session_date: sessionDateIso })
    });
    
    // JANGAN kirim `id` di sini — kolom id di tabel backtest_items adalah
    // GENERATED ALWAYS AS IDENTITY (auto-increment di sisi Supabase), jadi
    // dia MENOLAK kalau client menyertakan nilai id sendiri (error: "cannot
    // insert a non-DEFAULT value into column "id" ... Use OVERRIDING SYSTEM
    // VALUE to override"). Sebelumnya kode ini generate id manual
    // (Date.now()+random) dan selalu gagal di sini — makanya backtest tidak
    // pernah benar-benar tersimpan di Supabase meskipun sukses di
    // localStorage. Tidak ada bagian lain di app yang butuh id ini (hapus
    // item pakai session_id+ticker), jadi aman dihilangkan.
    const payloadItems = items.map(it => ({
      session_id: sessionId, ticker: it.ticker,
      entry_price: it.entryPrice || it.hargaEntry || 0,
      source: it.sumber || "Screener", notes: it.filterStr || it.keterangan || "",
      // Kolom baru — nama preset/rule kustom yang menghasilkan entry ini.
      // Butuh kolom `criteria text` di tabel backtest_items (lihat catatan
      // migrasi SQL di bawah); kalau kolom belum ada, Supabase akan
      // menolak insert dengan error "column ... does not exist" — jalankan
      // dulu migrasinya sebelum mencoba lagi.
      criteria: it.kriteria || null,
      // Kolom baru — tanggal entry PER ITEM (bukan cuma tanggal sesi),
      // dipakai kolom "Tanggal Entry" & "Hari" di tab Backtest. Butuh
      // kolom `entry_date date` di tabel backtest_items:
      //   ALTER TABLE backtest_items ADD COLUMN entry_date date;
      // Kalau kolom belum ada, Supabase menolak insert — jalankan migrasi
      // dulu. Selama itu belum dijalankan, data tetap tersimpan lokal
      // (localStorage) dan UI tetap menampilkan tanggal entry dari sana.
      entry_date: it.entryDate || null
    }));
    
    await supaFetch(`${SUPABASE_URL}/backtest_items`, {
      method: "POST",
      headers: { ...getSupaHeaders(), "Prefer": "resolution=merge-duplicates" },
      body: JSON.stringify(payloadItems)
    });
    return true;
  } catch(e) {
    console.error("Gagal sinkron backtest ke Supabase:", e);
    showError(`Backtest tersimpan lokal, tapi GAGAL sinkron ke Supabase: ${e.message}`);
    return false;
  }
}

async function saveToBacktest(){
  const filtered = getFiltered();
  const toSave = filtered.filter(s => state.selectedForBacktest.has(s.ticker));

  if(toSave.length === 0) return alert("Screener kosong atau tidak ada emiten yang dicentang.");

  // Tangkap preset/rule yang SEDANG AKTIF saat tombol ini diklik, supaya
  // kolom Sumber & Kriteria di tab Backtest menunjukkan preset/filter apa
  // yang menghasilkan emiten-emiten ini (bukan cuma "Screener" generik).
  const ctx = getActiveScreenerContext();
  const sessionId = String(Date.now());
  const tglSesi = new Date().toLocaleString('id-ID');
  // Tanggal entry PER ITEM dikunci ke tanggal hari ini SEKALI SAJA saat
  // disimpan (bukan dihitung ulang tiap render) — inilah yang membuat
  // harga & tanggal entry "terkunci": begitu tersimpan, refresh data live
  // di layar tidak pernah menulis ulang entryPrice/entryDate yang sudah
  // ada (lihat renderBacktest — hanya "Harga Live" yang diambil dari data
  // live, "Harga Entry" & "Tanggal Entry" selalu dari item yang tersimpan).
  const tglEntryIso = todayLocalISO();
  const items = toSave.map(s => ({
    ticker: s.ticker,
    entryPrice: s.cClose,
    entryDate: tglEntryIso,
    sumber: ctx.label,
    kriteria: ctx.criteria,
    keterangan: `Harga: ${s.cekHarga}; RSI: ${s.cekRsi}; Status RSI: ${s.statusRsi}; MACD: ${s.cekMacd}; Rasio Vol: ${(s.volRatio??0).toFixed(2)}x (${s.sinyalVolume}); Keyakinan Naik: ${s.keyakinanNaik}`
  }));

  state.backtests.unshift({
    id: sessionId, date: tglSesi,
    items: items.map(it=>({ ticker: it.ticker, entryPrice: it.entryPrice, entryDate: it.entryDate, filterStr: it.keterangan, kriteria: it.kriteria, sumber: it.sumber }))
  });
  saveBacktests();
  state.selectedForBacktest.clear(); 
  render();

  const synced = await syncBacktestToSupabase(sessionId, tglSesi, items);
  alert(synced
    ? `${toSave.length} emiten yang dipilih berhasil disimpan ke tab Backtest.`
    : `${toSave.length} emiten disimpan lokal, tapi gagal sinkron ke Supabase. Lihat pesan error di atas halaman.`);
}

// ==========================================
// "FILTER SAHAM SYARIAH" (tab Screener)
//
// Tombol toggle di toolbar bawah tabel. Sebelumnya tombol ini hanya
// MENCENTANG saham syariah di hasil yang tampil; sekarang ia menyalakan/
// mematikan filter Syariah = "Ya" pada screener itu sendiri, jadi tabel,
// jumlah emiten, pagination, dan chip filter aktif semuanya ikut
// menyempit. Ini SAMA dengan memilih "Ya" di dropdown Syariah (state.
// filters.syariahLabel), jadi bisa dikombinasikan dengan filter lain,
// muncul di chip filter aktif, dan ikut dihapus oleh "Reset Filter".
// Status syariah memakai s.syariahLabel === "Ya", sama seperti kolom
// Syariah & filter Syariah di tabel. Klik lagi untuk mematikan.
// ==========================================
function isSyariahFilterOn(){
  const v = state.filters.syariahLabel;
  return v.length === 1 && v[0] === "Ya";
}
function toggleSyariahFilter(){
  state.filters.syariahLabel = isSyariahFilterOn() ? [] : ["Ya"];
  state.page = 1;
  render();
}

// ==========================================
// "SIMPAN KE WATCHLIST" DARI BARIS YANG DICENTANG (tab Screener)
//
// Memakai centang yang sama dengan "Simpan Pilihan ke Backtest"
// (state.selectedForBacktest) dan logika yang sama dengan toggleFav():
// harga close saat ini dicatat sebagai harga entry (untuk P&L di tab
// Watchlist), lalu disinkronkan ke tabel Supabase `watchlists`. Bedanya,
// sinkronisasi dikirim SEKALI sebagai bulk insert, bukan 1 request per saham.
// Saham yang sudah ada di watchlist dilewati (harga entry lamanya tidak
// ditimpa). Centang TIDAK dikosongkan supaya pilihan yang sama masih bisa
// langsung disimpan ke Backtest.
// ==========================================
async function saveToWatchlist(){
  const filtered = getFiltered();
  const picked = filtered.filter(s => state.selectedForBacktest.has(s.ticker));
  if(picked.length === 0) return alert("Screener kosong atau tidak ada emiten yang dicentang.");

  const baru = picked.filter(s => !state.watchlist.has(s.ticker));
  const sudahAda = picked.length - baru.length;
  if(baru.length === 0){
    return alert(`Semua ${picked.length} emiten yang dicentang sudah ada di watchlist.`);
  }

  // Update lokal dulu (UI langsung responsif) + catat harga entry per saham.
  const tglIso = todayLocalISO();
  let meta = {};
  try{ meta = JSON.parse(localStorage.getItem("ihsg_watchlist_meta")||"{}") || {}; }catch(e){}
  baru.forEach(s => {
    state.watchlist.add(s.ticker);
    meta[s.ticker] = { entry: Number(s.cClose) || null, date: tglIso };
  });
  try{ localStorage.setItem("ihsg_watchlist_meta", JSON.stringify(meta)); }catch(e){}
  saveWatchlist();
  render();

  try{
    await supaFetch(`${SUPABASE_URL}/watchlists`, {
      method: "POST",
      headers: { ...getSupaHeaders(), "Prefer": "resolution=merge-duplicates" },
      body: JSON.stringify(baru.map(s => ({ ticker: s.ticker })))
    });
    alert(`${baru.length} emiten berhasil disimpan ke Watchlist` +
      (sudahAda ? ` (${sudahAda} lainnya sudah ada sebelumnya).` : "."));
  }catch(e){
    // Gagal sinkron ke Supabase — batalkan perubahan lokal, sama seperti
    // toggleFav(), supaya UI tidak "berbohong" bahwa item sudah tersimpan.
    baru.forEach(s => { state.watchlist.delete(s.ticker); delete meta[s.ticker]; });
    try{ localStorage.setItem("ihsg_watchlist_meta", JSON.stringify(meta)); }catch(_){}
    saveWatchlist();
    showError(`Gagal menyimpan watchlist ke Supabase: ${e.message}`);
    render();
  }
}

// ==========================================
// "SIMPAN KE BACKTEST" GENERIK — dipakai tab EPS Scanner, Kraken Flow
// (ORCA), BSJP, dan Smart Pick ("Lihat Daftar Lengkap"). Sengaja dibuat
// terpisah dari saveToBacktest() (yang khusus tab Screener & bergantung
// pada getActiveScreenerContext/getFiltered) supaya tiap tab bisa kirim
// item apa adanya (ticker, harga saat itu, label sumber & keterangan
// sendiri) tanpa perlu berpura-pura datang dari filter Screener.
//
// Cara pakai di sebuah renderXxx(): panggil renderBacktestSaveBar(ns, items)
// di tempat toolbar tabel, dengan items = [{ticker, price, kriteria?, keterangan?}].
// Wiring klik/centangnya otomatis lewat wireBacktestSaveControls() yang
// dipanggil dari attachContentEvents() — lihat di bawah.
// ==========================================
function getBacktestSelection(namespace){
  if(!state.genericBacktestSelections[namespace]) state.genericBacktestSelections[namespace] = new Set();
  return state.genericBacktestSelections[namespace];
}

// Merender toolbar kecil "Pilih semua" + tombol "💾 Simpan ke Backtest" di
// atas/bawah sebuah tabel hasil. SEKALIGUS menyimpan snapshot `items` ke
// state.genericBacktestItems[namespace] — inilah yang dibaca wiring
// (select-all & tombol simpan) saat diklik nanti, supaya tidak perlu
// closure atas array yang mungkin sudah basi setelah render berikutnya.
function renderBacktestSaveBar(namespace, items, opts){
  opts = opts || {};
  state.genericBacktestItems[namespace] = items;
  const sel = getBacktestSelection(namespace);
  const validItems = items.filter(it => it && it.ticker && it.price > 0);
  const selectedCount = validItems.filter(it => sel.has(it.ticker)).length;
  const allChecked = validItems.length > 0 && validItems.every(it => sel.has(it.ticker));
  if(!validItems.length) return "";
  return `
    <div class="bt-savebar" style="display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:${opts.margin || "10px 0"};padding:8px 12px;background:rgba(6,182,212,0.06);border:1px solid rgba(6,182,212,0.2);border-radius:8px;">
      <label style="display:flex;align-items:center;gap:6px;font-size:11.5px;color:var(--muted);cursor:pointer;">
        <input type="checkbox" class="custom-checkbox" data-bt-select-all="${namespace}" ${allChecked?"checked":""}> Pilih semua (${validItems.length})
      </label>
      <span style="font-size:11px;color:var(--muted);">${selectedCount} dipilih untuk dikirim ke 🔬 Backtest</span>
      <button type="button" class="btn btn-primary" data-bt-save="${namespace}" ${selectedCount===0?"disabled":""} style="margin-left:auto;padding:6px 14px;font-size:12px;">
        💾 Simpan ke Backtest${selectedCount>0?` (${selectedCount})`:""}
      </button>
    </div>`;
}

// Checkbox per-baris — dipasang di kolom pertama tiap <tr>. `item` dipakai
// hanya untuk validasi (ticker & harga wajib ada, kalau tidak baris ini
// tidak bisa dicentang sama sekali — mis. baris tanpa harga live).
function backtestRowCheckbox(namespace, item){
  if(!item || !item.ticker || !(item.price > 0)) return `<td style="width:28px;"></td>`;
  const checked = getBacktestSelection(namespace).has(item.ticker);
  return `<td style="width:28px;"><input type="checkbox" class="custom-checkbox" data-bt-row="${namespace}::${escapeHtml(item.ticker)}" ${checked?"checked":""}></td>`;
}

async function saveGenericListToBacktest(namespace, contextLabel){
  const items = state.genericBacktestItems[namespace] || [];
  const sel = getBacktestSelection(namespace);
  const toSave = items.filter(it => it && it.ticker && it.price > 0 && sel.has(it.ticker));
  if(!toSave.length) return alert("Tidak ada emiten yang dicentang.");

  const sessionId = String(Date.now());
  const tglSesi = new Date().toLocaleString('id-ID');
  // Sama seperti saveToBacktest(): tanggal & harga entry dikunci SEKALI
  // saat disimpan, tidak pernah ditulis ulang oleh refresh data live
  // berikutnya (lihat renderBacktest).
  const tglEntryIso = todayLocalISO();
  const entryItems = toSave.map(it => ({
    ticker: it.ticker,
    entryPrice: it.price,
    entryDate: tglEntryIso,
    sumber: contextLabel,
    kriteria: it.kriteria || contextLabel,
    keterangan: it.keterangan || contextLabel
  }));

  state.backtests.unshift({
    id: sessionId, date: tglSesi,
    items: entryItems.map(it => ({ ticker: it.ticker, entryPrice: it.entryPrice, entryDate: it.entryDate, filterStr: it.keterangan, kriteria: it.kriteria, sumber: it.sumber }))
  });
  saveBacktests();
  sel.clear();
  render();

  const synced = await syncBacktestToSupabase(sessionId, tglSesi, entryItems);
  alert(synced
    ? `${toSave.length} emiten dari "${contextLabel}" berhasil disimpan ke tab Backtest.`
    : `${toSave.length} emiten disimpan lokal, tapi gagal sinkron ke Supabase. Lihat pesan error di atas halaman.`);
}

// Dipanggil dari attachContentEvents() (untuk area tab utama) dan dari
// render() tepat setelah #spListModalContent diisi (untuk modal "Lihat
// Daftar Lengkap" Smart Pick) — scopeEl membatasi querySelectorAll supaya
// tidak salah pasang handler ke elemen di luar area yang baru di-render.
function wireBacktestSaveControls(scopeEl){
  if(!scopeEl) return;
  scopeEl.querySelectorAll("[data-bt-row]").forEach(chk => {
    chk.onchange = () => {
      const [ns, ticker] = String(chk.dataset.btRow).split("::");
      const sel = getBacktestSelection(ns);
      if(chk.checked) sel.add(ticker); else sel.delete(ticker);
      render();
    };
  });
  scopeEl.querySelectorAll("[data-bt-select-all]").forEach(chk => {
    chk.onchange = () => {
      const ns = chk.dataset.btSelectAll;
      const items = (state.genericBacktestItems[ns] || []).filter(it => it && it.ticker && it.price > 0);
      const sel = getBacktestSelection(ns);
      if(chk.checked) items.forEach(it => sel.add(it.ticker));
      else items.forEach(it => sel.delete(it.ticker));
      render();
    };
  });
  scopeEl.querySelectorAll("[data-bt-save]").forEach(btn => {
    btn.onclick = () => {
      const ns = btn.dataset.btSave;
      const labelByNs = {
        eps: "Entry Price Scanner",
        orca: "Kraken Flow (ORCA)",
        bsjp: "BSJP (Beli Sore, Jual Pagi)",
        smartpick: `Smart Pick — ${spTitleFor(state.spListOpenDefId)}`
      };
      saveGenericListToBacktest(ns, labelByNs[ns] || ns);
    };
  });
}

// Versi single-item dari mekanisme "Simpan ke Backtest" generik, khusus
// tab 🎯 Target Bandar — tab ini menganalisis SATU ticker pada satu waktu
// (bukan tabel banyak baris seperti EPS/ORCA/BSJP/Smart Pick), jadi cukup
// satu tombol langsung tanpa checkbox/select-all.
async function saveTargetBandarToBacktest(){
  const ticker = String(state.targetStockCode||"").trim().toUpperCase();
  const price = Math.round(state.targetCurrentPrice||0);
  const avgB = state.targetAvgBandar, lv = state.targetLevels;
  if(!ticker) return alert("Isi dulu Kode Saham di atas.");
  if(!price) return alert("Harga sekarang belum tersedia — klik \"Muat Data\" dulu.");
  const keterangan = (avgB && lv)
    ? `Avg Bandar: ${fmtNum(Math.round(avgB.avgPrice))}; Target R1: ${fmtNum(Math.round(lv.r1))}; Target Max: ${fmtNum(Math.round(lv.max))}${avgB.isEstimate?' (Avg Bandar estimasi)':''}`
    : "Target Bandar";
  state.genericBacktestItems.targetbandar = [{ ticker, price, kriteria: "Target Bandar", keterangan }];
  getBacktestSelection("targetbandar").add(ticker);
  await saveGenericListToBacktest("targetbandar", "Target Bandar");
}

async function addManualBacktest(sessionId, ticker, entryPrice, keterangan, entryDate){
  ticker = String(ticker || "").trim().toUpperCase().replace(".JK","");
  if(!ticker) return alert("Ticker wajib diisi.");
  entryPrice = parseFloat(entryPrice) || 0;
  if(!entryPrice) return alert("Harga entry wajib diisi.");
  const note = keterangan && keterangan.trim() ? keterangan.trim() : "Input manual (uji di luar screener)";
  // Tanggal entry: pakai yang diisi user di form (kalau ada), fallback ke
  // hari ini. Ini yang dikunci sebagai "Tanggal Entry" item — tidak pernah
  // berubah lagi setelah tersimpan (lihat catatan di saveToBacktest).
  const tglEntryIso = (entryDate && /^\d{4}-\d{2}-\d{2}$/.test(entryDate)) ? entryDate : todayLocalISO();

  let sid = sessionId || "";
  let session = sid ? state.backtests.find(b => String(b.id) === String(sid)) : null;
  if(!session){
    sid = String(Date.now());
    session = { id: sid, date: new Date().toLocaleString('id-ID'), items: [] };
    state.backtests.unshift(session);
  }

  // KUNCI HARGA ENTRY: kalau ticker ini sudah ada di sesi yang sama,
  // JANGAN timpa item lama (baik lokal maupun saat upsert ke Supabase
  // lewat "Prefer: resolution=merge-duplicates" pada session_id+ticker
  // yang sama) — tolak dan minta user hapus dulu item lama kalau memang
  // mau mengganti harga/tanggal entry-nya. Tanpa guard ini, menambahkan
  // ticker yang sama dua kali diam-diam mengganti harga entry yang sudah
  // "terkunci" sebelumnya.
  if(session.items.some(it => it.ticker === ticker)){
    return alert(`${ticker} sudah ada di sesi ini dengan harga entry yang sudah terkunci. Hapus item lama dulu (tombol "Hapus" di baris tabel) kalau memang ingin mengganti harga/tanggal entry-nya.`);
  }

  // Manual entry TIDAK punya kriteria screener (ticker & harga diketik
  // sendiri di luar hasil filter), jadi kolom Kriteria diisi keterangan
  // netral, bukan ikut-ikutan preset yang mungkin kebetulan sedang aktif
  // di tab Screener saat ini (itu tidak relevan untuk entry manual).
  const manualKriteria = "Input manual — tidak melalui filter screener";
  session.items.push({ ticker, entryPrice, entryDate: tglEntryIso, filterStr: note, kriteria: manualKriteria, sumber: "Manual" });
  saveBacktests();
  render();

  await syncBacktestToSupabase(sid, session.date, [{ ticker, entryPrice, entryDate: tglEntryIso, sumber: "Manual", filterStr: note, kriteria: manualKriteria }]);
  // Kalau gagal, showError() di dalam syncBacktestToSupabase sudah
  // menampilkan alasannya di banner atas halaman.
}

async function deleteBacktestSession(id){
  if(!confirm("Hapus sesi backtest ini?")) return;
  state.backtests = state.backtests.filter(b => String(b.id) !== String(id));
  saveBacktests();
  render();
  try{ await supaFetch(`${SUPABASE_URL}/backtest_sessions?id=eq.${id}`, { method: "DELETE", headers: getSupaHeaders() }); }
  catch(e){ showError(`Sesi dihapus lokal, tapi gagal dihapus di Supabase (bisa muncul lagi setelah refresh): ${e.message}`); }
}

async function deleteBacktestItem(sessionId, ticker){
  const session = state.backtests.find(b => String(b.id) === String(sessionId));
  if(session){
    session.items = session.items.filter(it => it.ticker !== ticker);
    if(session.items.length === 0) state.backtests = state.backtests.filter(b => String(b.id) !== String(sessionId));
  }
  saveBacktests();
  render();
  try{ await supaFetch(`${SUPABASE_URL}/backtest_items?session_id=eq.${sessionId}&ticker=eq.${ticker}`, { method: "DELETE", headers: getSupaHeaders() }); }
  catch(e){ showError(`Item dihapus lokal, tapi gagal dihapus di Supabase (bisa muncul lagi setelah refresh): ${e.message}`); }
}

// ==========================================
// EKSPOR EXCEL — TAB SCREENER
//
// Mengekspor hasil screener yang SEDANG TAMPIL (sudah kena filter,
// Rules Kustom, preset DSI, pencarian, dan urutan sort) — bukan cuma
// halaman aktif, tapi SELURUH baris hasil filter. Kolom yang diekspor
// mengikuti kolom yang sedang dipilih lewat panel "🧩 Kolom" (state.visibleCols),
// supaya konsisten dengan apa yang dilihat user di tabel.
// ==========================================
let lastScreenerExport = { rows: [], columns: [] };

// Sebagian kolom nilainya nested (mis. "fib.f382", "band.label") atau
// perlu dibulatkan/diformat supaya enak dibaca di Excel (bukan HTML).
function screenerRawValue(s, col){
  switch(col.key){
    case "fib.f382": return s.fib?.f382 ?? null;
    case "fib.f50": return s.fib?.f50 ?? null;
    case "fib.f618": return s.fib?.f618 ?? null;
    case "band.label": return s.band?.label ?? null;
    case "syariah": return (s.syariah===true||s.syariah==="true"||s.syariah==="Ya") ? "Ya" : "Tidak";
    case "changePct": case "volChangePct": case "week52ChangePct": case "vsMa50Pct": case "vsMa200Pct":
      return s[col.key]!=null ? Number(s[col.key].toFixed ? s[col.key].toFixed(2) : s[col.key]) : null;
    case "freqRatio": case "volRatio":
      return s[col.key]!=null ? Number(Number(s[col.key]).toFixed(2)) : null;
    default: {
      const v = s[col.key];
      if(v === undefined) return null;
      if(typeof v === "number") return Number.isFinite(v) ? v : null;
      return v ?? null;
    }
  }
}

function exportScreenerToExcel(){
  const { rows, columns } = lastScreenerExport;
  if(!rows || !rows.length){
    return alert("Tidak ada data screener untuk diekspor (cek filter/pencarian yang aktif).");
  }

  // Selalu sertakan Ticker + Nama Emiten di depan, lalu kolom-kolom
  // yang sedang tampil di tabel (sesuai urutan SCREENER_COLUMNS).
  const data = rows.map(s => {
    const row = { "Ticker": s.ticker, "Nama Emiten": s.name || "-" };
    columns.forEach(col => { row[col.label] = screenerRawValue(s, col); });
    return row;
  });

  const worksheet = XLSX.utils.json_to_sheet(data);
  const workbook = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(workbook, worksheet, "Hasil Screener");

  // Lebar kolom otomatis: dasar dari panjang label, minimum 10 char.
  const headers = Object.keys(data[0]);
  worksheet['!cols'] = headers.map(h => ({ wch: Math.max(10, h.length + 2) }));

  const dateStr = todayLocalISO();
  XLSX.writeFile(workbook, `Screener_IHSG_${dateStr}.xlsx`);
}

function exportBacktestToExcel(id) {
  const session = state.backtests.find(b => String(b.id) === String(id));
  if (!session) return;
  
  // 1. Siapkan data dengan kolom "Tanggal Entry"
  const data = session.items.map(item => {
    const liveData = state.stocks.find(s => s.ticker === item.ticker);
    const currentPrice = liveData ? liveData.cClose : item.entryPrice;
    const period = backtestPeriodMetrics(item, currentPrice);
    const pl = period.endPL ?? (item.entryPrice ? ((currentPrice - item.entryPrice) / item.entryPrice) * 100 : null);
    const hariSejak = daysSinceEntry(item.entryDate);

    return {
      "Tanggal Entry": fmtDateID(item.entryDate) !== "-" ? fmtDateID(item.entryDate) : session.date, // fallback ke waktu tangkap/sesi kalau item lama belum punya tanggal sendiri
      "Ticker": item.ticker,
      "Sumber": item.sumber || "Screener",
      "Kriteria Screener": item.kriteria || "-",
      "Harga Entry": item.entryPrice,
      "Harga Live": currentPrice,
      "Profit/Loss (%)": pl != null ? parseFloat(pl.toFixed(2)) : "-",
      "Harga Tertinggi": period.highPeriod ?? "-",
      "Capai P/L (%)": period.maxPL != null ? parseFloat(period.maxPL.toFixed(2)) : "-",
      "Hari": hariSejak ?? "-",
      "Filter / Keterangan": item.filterStr || "-"
    };
  });

  // 2. Buat Workbook & Worksheet Excel murni
  const worksheet = XLSX.utils.json_to_sheet(data);
  const workbook = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(workbook, worksheet, "Data Backtest");
  
  // 3. Atur lebar kolom agar rapi
  const wscols = [
    {wch: 14}, // Tanggal Entry
    {wch: 10}, // Ticker
    {wch: 12}, // Sumber
    {wch: 40}, // Kriteria Screener
    {wch: 12}, // Harga Entry
    {wch: 12}, // Harga Live
    {wch: 15}, // Profit/Loss (%)
    {wch: 16}, // Harga Tertinggi
    {wch: 14}, // Capai P/L (%)
    {wch: 8},  // Hari
    {wch: 50}  // Keterangan
  ];
  worksheet['!cols'] = wscols;

  // 4. Unduh file sebagai .xlsx
  XLSX.writeFile(workbook, `Backtest_IHSG_${session.id}.xlsx`);
}

function exportAllBacktestToExcel() {
  if (!state.backtests || state.backtests.length === 0) {
    return alert("Belum ada data backtest untuk diekspor.");
  }

  let allData = [];
  
  // Looping untuk menggabungkan seluruh item dari semua sesi
  state.backtests.forEach(session => {
    session.items.forEach(item => {
      const liveData = state.stocks.find(s => s.ticker === item.ticker);
      const currentPrice = liveData ? liveData.cClose : item.entryPrice;
      const period = backtestPeriodMetrics(item, currentPrice);
      const pl = period.endPL ?? (item.entryPrice ? ((currentPrice - item.entryPrice) / item.entryPrice) * 100 : null);
      const hariSejak = daysSinceEntry(item.entryDate);

      allData.push({
        "Tanggal Entry": fmtDateID(item.entryDate) !== "-" ? fmtDateID(item.entryDate) : session.date,
        "Ticker": item.ticker,
        "Sumber": item.sumber || "Screener",
        "Kriteria Screener": item.kriteria || "-",
        "Harga Entry": item.entryPrice,
        "Harga Live": currentPrice,
        "Profit/Loss (%)": pl != null ? parseFloat(pl.toFixed(2)) : "-",
        "Harga Tertinggi": period.highPeriod ?? "-",
        "Capai P/L (%)": period.maxPL != null ? parseFloat(period.maxPL.toFixed(2)) : "-",
        "Hari": hariSejak ?? "-",
        "Filter / Keterangan": item.filterStr || "-"
      });
    });
  });

  if (allData.length === 0) {
    return alert("Sesi backtest kosong, tidak ada item untuk diekspor.");
  }

  // Buat file Excel
  const worksheet = XLSX.utils.json_to_sheet(allData);
  const workbook = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(workbook, worksheet, "Semua Backtest");
  
  // Mengatur lebar kolom agar rapi
  const wscols = [
    {wch: 14}, // Tanggal Entry
    {wch: 10}, // Ticker
    {wch: 12}, // Sumber
    {wch: 40}, // Kriteria Screener
    {wch: 12}, // Harga Entry
    {wch: 12}, // Harga Live
    {wch: 15}, // Profit/Loss (%)
    {wch: 16}, // Harga Tertinggi
    {wch: 14}, // Capai P/L (%)
    {wch: 8},  // Hari
    {wch: 50}  // Keterangan
  ];
  worksheet['!cols'] = wscols;

  // Unduh dengan nama file otomatis memakai tanggal hari ini
  const dateStr = todayLocalISO();
  XLSX.writeFile(workbook, `Semua_Backtest_IHSG_${dateStr}.xlsx`);
}

// exportBacktestRekapToExcel — ekspor tab "Rekap per Saham" (agregasi
// lintas sesi per ticker, lihat computeTickerRekap()/renderBacktestRekap()).
// Beda dari exportAllBacktestToExcel(): itu 1 baris per KEMUNCULAN (per
// item per sesi), ini 1 baris per TICKER (sudah diagregasi) — angkanya
// SELALU mengikuti mode target TP (% Tetap / Auto per saham) yang lagi
// aktif di layar saat tombol diklik, sama seperti yang tampil di tabel.
function exportBacktestRekapToExcel(){
  if (!state.backtests || !state.backtests.length){
    return alert("Belum ada sesi backtest yang disimpan.");
  }
  const tpPct = Number(state.backtestTargetTpPct) > 0 ? Number(state.backtestTargetTpPct) : 5;
  const mode = state.backtestTpMode === "auto" ? "auto" : "percent";
  const rekap = computeTickerRekap(tpPct, mode);
  if (!rekap.length){
    return alert("Belum ada item tersimpan di sesi manapun.");
  }
  const tpLabel = mode === "auto" ? "Auto (TP1/saham)" : `${tpPct}%`;
  const targetCol = `Target TP Tercapai (${tpLabel})`;

  const data = rekap.map(r => ({
    "Ticker": r.ticker,
    "Muncul di Screener": r.screenerSet.join(" | "),
    "Jumlah Kemunculan": r.occurrenceCount,
    "Menang": r.winCount,
    "Kalah": r.lossCount,
    "Total P/L Closing (%)": r.totalPL != null ? parseFloat(r.totalPL.toFixed(2)) : "-",
    "P/L Tertinggi (%)": r.bestPL != null ? parseFloat(r.bestPL.toFixed(2)) : "-",
    [targetCol]: r.trackedCount === 0 ? "-" : `${r.achievedCount}/${r.trackedCount}`,
    "Tercepat (Hari)": r.fastestDays ?? "-",
    "Rata-rata (Hari)": r.avgDays != null ? parseFloat(r.avgDays.toFixed(1)) : "-",
  }));

  const worksheet = XLSX.utils.json_to_sheet(data);
  const workbook = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(workbook, worksheet, "Rekap per Saham");

  const wscols = [
    {wch: 10}, // Ticker
    {wch: 55}, // Muncul di Screener
    {wch: 14}, // Jumlah Kemunculan
    {wch: 8},  // Menang
    {wch: 8},  // Kalah
    {wch: 18}, // Total P/L Closing (%)
    {wch: 16}, // P/L Tertinggi (%)
    {wch: 24}, // Target TP Tercapai
    {wch: 12}, // Tercepat (Hari)
    {wch: 12}, // Rata-rata (Hari)
  ];
  worksheet['!cols'] = wscols;

  const dateStr = todayLocalISO();
  XLSX.writeFile(workbook, `Rekap_Per_Saham_IHSG_${dateStr}.xlsx`);
}

