async function syncPortoToServer_(record) {
  const payload = {
    id: record.id, ticker: record.ticker, jenis_porto: record.jenisPorto || PORTO_JENIS_DEFAULT, status: record.status,
    tgl_beli: record.tglBeli || null, harga_beli: record.hargaBeli || 0,
    lot_beli: record.lotBeli || 0, fee_beli_pct: record.feeBeliPct || 0, total_beli: record.totalBeli || 0,
    support: record.support || null, resistance: record.resistance || null,
    fib618: record.fib618 || null, target_tp: record.targetTP || null, cut_loss: record.cutLoss || null,
    tgl_jual: record.tglJual || null, harga_jual: record.hargaJual || 0,
    lot_jual: record.lotJual || 0, fee_jual_pct: record.feeJualPct || 0, net_jual: record.netJual || 0,
    jangka_waktu: record.jangkaWaktu !== "" ? record.jangkaWaktu : null,
    persen_pl: record.persenPL !== "" ? record.persenPL : null,
    nilai_pl: record.nilaiPL !== "" ? record.nilaiPL : null,
    catatan: record.catatan || "", entries: record.entries || []
  };

  // Menggunakan supaFetch agar error dari Supabase tertangkap dan tidak diam-diam gagal
  await supaFetch(`${SUPABASE_URL}/portfolios?on_conflict=id`, {
    method: "POST",
    headers: { ...getSupaHeaders(), "Prefer": "resolution=merge-duplicates" },
    body: JSON.stringify(payload)
  });
}

async function submitPortoForm(){
  const v = readPortoForm();
  if(!v.ticker) return alert("Nama emiten wajib diisi.");
  if(!v.tglBeli || !v.hargaBeli || !v.lotBeli) return alert("Tanggal beli, harga beli, dan jumlah lot wajib diisi.");
  
  const btn = document.getElementById("pfSubmitBtn");
  if (btn) { btn.disabled = true; btn.textContent = "Menyimpan..."; }

  const c = hitungPorto(v);
  const record = {
    id: state.portoEditId || String(Date.now()),
    ticker: v.ticker, jenisPorto: v.jenisPorto || PORTO_JENIS_DEFAULT, tglBeli: v.tglBeli, hargaBeli: v.hargaBeli, lotBeli: v.lotBeli,
    feeBeliPct: isNaN(v.feeBeliPct) ? (state.feeBeliDefaultPct ?? FEE_BELI_DEFAULT_PCT) : v.feeBeliPct, totalBeli: c.totalBeli,
    support: v.support, resistance: v.resistance, fib618: v.fib618, targetTP: v.targetTP, cutLoss: v.cutLoss,
    tglJual: v.tglJual, hargaJual: v.hargaJual, lotJual: v.lotJual,
    feeJualPct: isNaN(v.feeJualPct) ? (state.feeJualDefaultPct ?? FEE_JUAL_DEFAULT_PCT) : v.feeJualPct, netJual: c.netJual,
    jangkaWaktu: c.jangkaWaktu, persenPL: c.persenPL, nilaiPL: c.nilaiPL, status: c.status,
    catatan: v.catatan
  };

  try {
    // Coba simpan ke database server dulu
    if (SUPABASE_URL) await syncPortoToServer_(record);
    
    // Jika server menerima, baru simpan secara lokal dan tampilkan
    const idx = state.portfolio.findIndex(p => String(p.id) === String(record.id));
    if(idx >= 0) state.portfolio[idx] = record; else state.portfolio.unshift(record);
    savePortoLocal();
    
    state.portoEditId = null;
    state.portoModalOpen = false;
    state.portoPrefill = null;
    render();
  } catch (e) {
    // Memunculkan pop-up error asli dari server
    alert("GAGAL MENYIMPAN KE DATABASE!\n\n" + e.message);
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = state.portoEditId ? "Update Transaksi" : "Simpan Transaksi"; }
  }
}
async function deletePortoRecord(id){
  if(!confirm("Hapus catatan portofolio ini?")) return;
  state.portfolio = state.portfolio.filter(p => String(p.id) !== String(id));
  state.selectedPorto.delete(String(id));
  savePortoLocal();
  render();
  try { await fetch(`${SUPABASE_URL}/portfolios?id=eq.${id}`, { method: "DELETE", headers: getSupaHeaders() }); } catch(e) {}
}

async function bulkDeletePorto(){
  const ids = [...state.selectedPorto];
  if(ids.length === 0) return alert("Belum ada transaksi yang dicentang. Centang dulu di kolom paling kiri tabel.");
  if(!confirm(`Hapus ${ids.length} transaksi portofolio yang dicentang?`)) return;
  state.portfolio = state.portfolio.filter(p => !ids.includes(String(p.id)));
  state.selectedPorto.clear();
  savePortoLocal();
  render();
  try { await fetch(`${SUPABASE_URL}/portfolios?id=in.(${ids.join(',')})`, { method: "DELETE", headers: getSupaHeaders() }); } catch(e) {}
}

// ==========================================================================
// IMPOR & EKSPOR PORTOFOLIO (Excel/CSV)
//
// Kolom ekspor SENGAJA dibuat 1:1 dengan kolom yang dibaca ulang saat impor
// (lihat PORTO_IMPORT_COLUMNS di bawah) supaya file hasil "📤 Ekspor" bisa
// langsung dipakai lagi sebagai file "📥 Impor" tanpa perlu diedit — alur
// paling umum: ekspor buat backup/edit massal di Excel, edit, lalu impor
// balik. Kolom hasil HITUNGAN (Total Beli, Net Jual, %P/L, dst.) ikut
// diekspor sebagai referensi/bacaan saja, TAPI SENGAJA DIABAIKAN saat impor
// -- selalu dihitung ULANG dari hitungPorto() memakai kolom mentah (harga,
// lot, fee, tanggal), supaya angkanya konsisten dengan yang dihasilkan form
// manual dan tidak bisa "disuntik" nilai P/L palsu lewat file impor.
// ==========================================================================
function exportPortfolioToExcel(){
  if(!state.portfolio.length) return alert("Belum ada transaksi portofolio untuk diekspor.");
  const data = state.portfolio.map(p => ({
    "ID": p.id, "Ticker": p.ticker, "Jenis Portofolio": p.jenisPorto || PORTO_JENIS_DEFAULT,
    "Tgl Beli": p.tglBeli || "", "Harga Beli": p.hargaBeli || 0, "Lot Beli": p.lotBeli || 0, "Fee Beli %": p.feeBeliPct ?? "",
    "Tgl Jual": p.tglJual || "", "Harga Jual": p.hargaJual || "", "Lot Jual": p.lotJual || "", "Fee Jual %": p.feeJualPct ?? "",
    "Support": p.support || "", "Resistance": p.resistance || "", "Fib618": p.fib618 || "", "Target TP": p.targetTP || "", "Cut Loss": p.cutLoss || "",
    "Catatan": p.catatan || "",
    // --- kolom hasil hitungan, referensi saja (diabaikan saat impor) ---
    "Total Beli (otomatis)": p.totalBeli || "", "Net Jual (otomatis)": p.netJual || "",
    "Jangka Waktu Hari (otomatis)": p.jangkaWaktu !== "" ? p.jangkaWaktu : "",
    "%P/L (otomatis)": p.persenPL !== "" ? p.persenPL : "", "Nilai P/L (otomatis)": p.nilaiPL !== "" ? p.nilaiPL : "",
    "Status (otomatis)": p.status || "",
  }));
  const worksheet = XLSX.utils.json_to_sheet(data);
  worksheet['!cols'] = Object.keys(data[0]).map(k => ({ wch: Math.max(10, k.length + 2) }));
  const workbook = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(workbook, worksheet, "Portofolio");
  XLSX.writeFile(workbook, `Portofolio_IHSG_${todayLocalISO()}.xlsx`);
}

function triggerPortoImportFile(){
  document.getElementById("portoImportFileInput")?.click();
}

// Template kosong (+ 1 baris contoh) buat kolom-kolom yang dibaca
// handlePortoImportFile()/mapPortoImportRow() -- headernya diambil dari
// alias PERTAMA tiap kolom di PORTO_IMPORT_COLUMNS (bukan ditulis ulang
// terpisah di sini), supaya kalau nanti PORTO_IMPORT_COLUMNS berubah
// (nama kolom baru ditambah/diganti), template ini otomatis ikut sinkron
// -- tidak ada 2 sumber kebenaran yang bisa saling ketinggalan.
function portoImportTemplateHeaders(){
  // Urutan tampilan yang enak dibaca (bukan urutan object PORTO_IMPORT_COLUMNS
  // yang tidak dijamin konsisten) -- ID sengaja TIDAK disertakan di template
  // kosong (cuma relevan kalau mau UPDATE baris yang sudah ada, bukan buat
  // input transaksi baru, lihat catatan di sheet "Petunjuk").
  const order = ["ticker","jenisPorto","tglBeli","hargaBeli","lotBeli","feeBeliPct","tglJual","hargaJual","lotJual","feeJualPct","support","resistance","fib618","targetTP","cutLoss","catatan"];
  // Judul kolom manusiawi = alias pertama tiap key, huruf awal tiap kata dikapitalkan.
  const titleCase = (s) => s.replace(/(^|\s)\S/g, c => c.toUpperCase());
  return order.map(key => titleCase(PORTO_IMPORT_COLUMNS[key][0]));
}

function downloadPortoImportTemplate(){
  const headers = portoImportTemplateHeaders();
  // Nilai contoh disusun SEBAGAI ARRAY, cocok posisi indeks dengan `headers`
  // (bukan object key-value yang dicocokkan lewat json_to_sheet({header})) --
  // sengaja dihindari supaya tidak rawan mismatch diam-diam kalau nanti
  // titleCase() menghasilkan teks yang beda dari perkiraan (mis. singkatan
  // seperti "TP" ikut ter-titleCase jadi "Tp", lihat BUG yang sempat
  // ketemu sendiri: header computed "Target Tp" vs key hardcode "Target TP"
  // -> baris contoh utk kolom itu jadi kosong diam-diam). Array-of-array
  // lewat aoa_to_sheet() tidak butuh kecocokan nama sama sekali.
  const contohValues = {
    ticker: "BBCA", jenisPorto: "Investasi", tglBeli: "2026-01-15", hargaBeli: 9500, lotBeli: 10, feeBeliPct: state.feeBeliDefaultPct ?? FEE_BELI_DEFAULT_PCT,
    tglJual: "", hargaJual: "", lotJual: "", feeJualPct: state.feeJualDefaultPct ?? FEE_JUAL_DEFAULT_PCT,
    support: "9300", resistance: "9800", fib618: "", targetTP: "10200", cutLoss: "9100",
    catatan: "Contoh baris -- hapus/timpa dengan transaksi Anda sendiri",
  };
  const order = ["ticker","jenisPorto","tglBeli","hargaBeli","lotBeli","feeBeliPct","tglJual","hargaJual","lotJual","feeJualPct","support","resistance","fib618","targetTP","cutLoss","catatan"];
  const contohRow = order.map(key => contohValues[key]);
  const sheetTemplate = XLSX.utils.aoa_to_sheet([headers, contohRow]);
  sheetTemplate['!cols'] = headers.map(h => ({ wch: Math.max(12, h.length + 2) }));

  const petunjuk = [
    ["Petunjuk Impor Transaksi Portofolio"],
    [""],
    ["1. Wajib diisi tiap baris: Ticker, Tgl Beli, Harga Beli, Lot Beli. Baris tanpa salah satu dari 4 kolom ini akan DILEWATI saat impor (tidak menggagalkan baris lain)."],
    ["2. Jenis Portofolio: isi salah satu dari Investasi / Scalping / Swing (sesuai 3 porto di Stockbit). Kalau dikosongkan atau diisi teks lain, otomatis dianggap \"Investasi\"."],
    ["3. Format Tgl Beli / Tgl Jual: YYYY-MM-DD (mis. 2026-01-15). Boleh juga DD/MM/YYYY atau tanggal Excel asli (hasil ketik langsung di sel bertipe Date)."],
    [`4. Fee Beli % / Fee Jual %: kalau dikosongkan, otomatis dipakai default ${state.feeBeliDefaultPct ?? FEE_BELI_DEFAULT_PCT}% (beli) / ${state.feeJualDefaultPct ?? FEE_JUAL_DEFAULT_PCT}% (jual) sesuai Pengaturan > Fee Default, sama seperti form manual.`],
    ["5. Tgl Jual, Harga Jual, Lot Jual boleh dikosongkan kalau transaksi masih Open (belum dijual)."],
    ["6. Kolom Total Beli, Net Jual, %P/L, Nilai P/L, Status TIDAK ada di template ini karena SELALU dihitung ulang otomatis dari kolom di atas -- mengisinya manual tidak akan berpengaruh."],
    ["7. Mau UPDATE transaksi yang sudah ada (bukan tambah baru)? Tambahkan kolom \"ID\" berisi ID transaksi tersebut (lihat kolom ID di file hasil \"📤 Ekspor Excel\") -- baris dengan ID yang cocok akan DITIMPA, bukan dobel."],
    ["8. Header kolom fleksibel (tidak case-sensitive, boleh pakai/tanpa spasi) -- tapi paling aman pakai persis nama di sheet Template ini."],
    ["9. Satu sheet pertama di file = yang dibaca. Kalau ada beberapa sheet, pastikan datanya di sheet paling pertama."],
  ];
  const sheetPetunjuk = XLSX.utils.aoa_to_sheet(petunjuk);
  sheetPetunjuk['!cols'] = [{ wch: 110 }];

  const workbook = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(workbook, sheetTemplate, "Template");
  XLSX.utils.book_append_sheet(workbook, sheetPetunjuk, "Petunjuk");
  XLSX.writeFile(workbook, "Template_Impor_Portofolio_IHSG.xlsx");
}


// Alias nama kolom yang diterima saat impor -- tolerant terhadap variasi
// penamaan header (huruf besar/kecil, spasi, pakai "%" atau tidak, dst.)
// supaya file yang sudah pernah diedit manual di Excel (header sedikit
// berubah) tidak langsung ditolak semua barisnya.
const PORTO_IMPORT_COLUMNS = {
  id: ["id"],
  ticker: ["ticker", "kode", "kode saham", "saham"],
  jenisPorto: ["jenis portofolio", "jenis porto", "jenis", "tipe portofolio", "tipe", "kategori", "kategori porto"],
  tglBeli: ["tgl beli", "tanggal beli", "tgl_beli"],
  hargaBeli: ["harga beli", "harga_beli"],
  lotBeli: ["lot beli", "lot_beli", "jumlah lot beli"],
  feeBeliPct: ["fee beli %", "fee beli", "fee_beli_pct"],
  tglJual: ["tgl jual", "tanggal jual", "tgl_jual"],
  hargaJual: ["harga jual", "harga_jual"],
  lotJual: ["lot jual", "lot_jual", "jumlah lot jual"],
  feeJualPct: ["fee jual %", "fee jual", "fee_jual_pct"],
  support: ["support"], resistance: ["resistance"], fib618: ["fib618", "fib 618", "fib 0.618"],
  targetTP: ["target tp", "target_tp", "tp"], cutLoss: ["cut loss", "cut_loss", "cl"],
  catatan: ["catatan", "notes", "note"],
};

// Excel/SheetJS kadang mengirim tanggal sebagai serial number (mis. 46000)
// alih-alih string, tergantung format sel di file aslinya -- dinormalisasi
// ke "YYYY-MM-DD" lokal. String yang sudah dalam format itu (atau kosong)
// dikembalikan apa adanya.
function normImportDate(v){
  if(v == null || v === "") return "";
  if(typeof v === "number"){
    const d = XLSX.SSF.parse_date_code(v);
    if(d) return `${d.y}-${String(d.m).padStart(2,"0")}-${String(d.d).padStart(2,"0")}`;
  }
  const s = String(v).trim();
  if(/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0,10);
  const m = s.match(/^(\d{1,2})[-\/](\d{1,2})[-\/](\d{4})$/);
  if(m) return `${m[3]}-${m[2].padStart(2,"0")}-${m[1].padStart(2,"0")}`;
  const parsed = new Date(s);
  return isNaN(parsed) ? "" : toLocalISODate(parsed);
}

// Baca satu baris hasil XLSX.utils.sheet_to_json (object dengan header ASLI
// dari file, nama kolom bisa bervariasi) -> objek "v" siap dipakai
// hitungPorto(), sama persis bentuknya dengan readPortoForm(). Normalisasi
// nama header: lowercase + trim supaya cocok dengan PORTO_IMPORT_COLUMNS.
function mapPortoImportRow(rawRow){
  const norm = {};
  Object.entries(rawRow).forEach(([k,v]) => { norm[String(k).trim().toLowerCase()] = v; });
  const pick = (aliases) => { for(const a of aliases){ if(norm[a] != null && norm[a] !== "") return norm[a]; } return ""; };
  const num = (v) => { const n = parseFloat(v); return isNaN(n) ? 0 : n; };
  return {
    id: pick(PORTO_IMPORT_COLUMNS.id) || "",
    ticker: String(pick(PORTO_IMPORT_COLUMNS.ticker) || "").trim().toUpperCase().replace(".JK",""),
    jenisPorto: (() => {
      const raw = String(pick(PORTO_IMPORT_COLUMNS.jenisPorto) || "").trim();
      const match = PORTO_JENIS_LIST.find(j => j.toLowerCase() === raw.toLowerCase());
      return match || PORTO_JENIS_DEFAULT; // teks tak dikenali/kosong -> default "Investasi", bukan ditolak
    })(),
    tglBeli: normImportDate(pick(PORTO_IMPORT_COLUMNS.tglBeli)),
    hargaBeli: num(pick(PORTO_IMPORT_COLUMNS.hargaBeli)),
    lotBeli: num(pick(PORTO_IMPORT_COLUMNS.lotBeli)),
    feeBeliPct: pick(PORTO_IMPORT_COLUMNS.feeBeliPct) !== "" ? num(pick(PORTO_IMPORT_COLUMNS.feeBeliPct)) : (state.feeBeliDefaultPct ?? FEE_BELI_DEFAULT_PCT),
    tglJual: normImportDate(pick(PORTO_IMPORT_COLUMNS.tglJual)),
    hargaJual: num(pick(PORTO_IMPORT_COLUMNS.hargaJual)),
    lotJual: num(pick(PORTO_IMPORT_COLUMNS.lotJual)),
    feeJualPct: pick(PORTO_IMPORT_COLUMNS.feeJualPct) !== "" ? num(pick(PORTO_IMPORT_COLUMNS.feeJualPct)) : (state.feeJualDefaultPct ?? FEE_JUAL_DEFAULT_PCT),
    support: String(pick(PORTO_IMPORT_COLUMNS.support) || ""),
    resistance: String(pick(PORTO_IMPORT_COLUMNS.resistance) || ""),
    fib618: String(pick(PORTO_IMPORT_COLUMNS.fib618) || ""),
    targetTP: String(pick(PORTO_IMPORT_COLUMNS.targetTP) || ""),
    cutLoss: String(pick(PORTO_IMPORT_COLUMNS.cutLoss) || ""),
    catatan: String(pick(PORTO_IMPORT_COLUMNS.catatan) || ""),
  };
}

// Dipanggil dari <input type="file" id="portoImportFileInput" onchange=...>.
// Menerima .xlsx/.xls/.csv (SheetJS membaca ketiganya lewat API yang sama).
// Baris dengan ticker/tgl beli/harga beli/lot beli kosong DILEWATI (bukan
// dianggap gagal fatal) supaya baris kosong/judul di file Excel tidak
// menghentikan impor baris lain yang valid -- tapi tetap dihitung &
// dilaporkan di ringkasan akhir supaya user sadar ada baris yang terlewat.
async function handlePortoImportFile(fileInput){
  const file = fileInput.files && fileInput.files[0];
  fileInput.value = ""; // reset supaya file yang sama bisa dipilih lagi kalau mau diulang
  if(!file) return;

  state.portoImporting = true; state.portoImportMsg = ""; state.portoImportMsgError = false; render();
  try{
    const buf = await file.arrayBuffer();
    const wb = XLSX.read(buf, { type: "array", cellDates: false });
    const sheet = wb.Sheets[wb.SheetNames[0]];
    const json = XLSX.utils.sheet_to_json(sheet, { defval: "" });
    if(!json.length) throw new Error("File kosong atau format tidak terbaca (pastikan baris pertama adalah header kolom).");

    const records = [];
    let skipped = 0;
    json.forEach(rawRow => {
      const v = mapPortoImportRow(rawRow);
      if(!v.ticker || !v.tglBeli || !v.hargaBeli || !v.lotBeli){ skipped++; return; }
      const c = hitungPorto(v);
      records.push({
        id: v.id || (String(Date.now()) + "_" + records.length), // suffix indeks: beberapa baris diimpor di milidetik yang sama akan tabrakan id kalau cuma pakai Date.now()
        ticker: v.ticker, jenisPorto: v.jenisPorto || PORTO_JENIS_DEFAULT, tglBeli: v.tglBeli, hargaBeli: v.hargaBeli, lotBeli: v.lotBeli,
        feeBeliPct: v.feeBeliPct, totalBeli: c.totalBeli,
        support: v.support, resistance: v.resistance, fib618: v.fib618, targetTP: v.targetTP, cutLoss: v.cutLoss,
        tglJual: v.tglJual, hargaJual: v.hargaJual, lotJual: v.lotJual,
        feeJualPct: v.feeJualPct, netJual: c.netJual,
        jangkaWaktu: c.jangkaWaktu, persenPL: c.persenPL, nilaiPL: c.nilaiPL, status: c.status,
        catatan: v.catatan,
      });
    });

    if(!records.length) throw new Error(`Tidak ada baris valid untuk diimpor (${skipped} baris dilewati -- pastikan kolom Ticker, Tgl Beli, Harga Beli, dan Lot Beli terisi).`);

    // Upsert BATCH (satu request array, bukan loop N request) -- sama pola
    // dengan fetchAndSaveBrokerSummaryBulk, PostgREST menerima array JSON di
    // body POST + Prefer: resolution=merge-duplicates utk upsert massal.
    if(SUPABASE_URL){
      await supaFetch(`${SUPABASE_URL}/portfolios?on_conflict=id`, {
        method: "POST",
        headers: { ...getSupaHeaders(), "Prefer": "resolution=merge-duplicates" },
        body: JSON.stringify(records.map(r => ({
          id: r.id, ticker: r.ticker, jenis_porto: r.jenisPorto || PORTO_JENIS_DEFAULT, status: r.status,
          tgl_beli: r.tglBeli || null, harga_beli: r.hargaBeli || 0,
          lot_beli: r.lotBeli || 0, fee_beli_pct: r.feeBeliPct || 0, total_beli: r.totalBeli || 0,
          support: r.support || null, resistance: r.resistance || null,
          fib618: r.fib618 || null, target_tp: r.targetTP || null, cut_loss: r.cutLoss || null,
          tgl_jual: r.tglJual || null, harga_jual: r.hargaJual || 0,
          lot_jual: r.lotJual || 0, fee_jual_pct: r.feeJualPct || 0, net_jual: r.netJual || 0,
          jangka_waktu: r.jangkaWaktu !== "" ? r.jangkaWaktu : null,
          persen_pl: r.persenPL !== "" ? r.persenPL : null,
          nilai_pl: r.nilaiPL !== "" ? r.nilaiPL : null,
          catatan: r.catatan || "", entries: []
        })))
      });
    }

    // Server (kalau ada) berhasil menerima -> commit ke state lokal + cache.
    records.forEach(record => {
      const idx = state.portfolio.findIndex(p => String(p.id) === String(record.id));
      if(idx >= 0) state.portfolio[idx] = record; else state.portfolio.unshift(record);
    });
    savePortoLocal();
    state.portoImportMsg = `✅ ${records.length} transaksi berhasil diimpor${skipped ? ` (${skipped} baris dilewati karena kolom wajib kosong)` : ""}.`;
    state.portoImportMsgError = false;
  } catch(e){
    state.portoImportMsg = "Gagal impor: " + e.message;
    state.portoImportMsgError = true;
  }
  state.portoImporting = false;
  render();
}

// ==========================================
// 📥 Impor Data Harian IDX (flows) — alternatif manual utk sync-idx-full.mjs.
//
// idx.co.id memblokir request dari server/curl (Cloudflare, lihat catatan
// di kepala sync-idx-full.mjs) -- makanya data harian selama ini WAJIB
// ditarik dari PC (koneksi rumah). Tapi sesi BROWSER BIASA (bukan curl/
// server) lolos Cloudflare, jadi user bisa login/buka sendiri halaman
//   https://www.idx.co.id/id/data-pasar/ringkasan-perdagangan/ringkasan-saham/
// lalu unduh file Excel/CSV "Ringkasan Saham" hari itu dari sana, dan
// upload file itu ke sini. Baris-barisnya diupsert ke tabel `flows`
// (on_conflict ticker,date) -- SAMA PERSIS skema kolom yang ditulis
// sync-idx-full.mjs (lihat blok `payload` di fungsi utamanya), jadi
// tombol "📊 Update Teknikal (dari flows)" di bawah bisa langsung
// menghitung ulang stocks/stock_indicators_ext dari data ini, tanpa
// perlu jalan apa pun dari PC.
//
// Alias nama kolom yang diterima -- toleran terhadap variasi header file
// unduhan IDX (label ID/EN, spasi/underscore, huruf besar-kecil) supaya
// file yang formatnya sedikit beda tidak langsung ditolak semua barisnya.
// pickFlowsCol() menormalisasi header (lowercase, spasi dirapikan) dulu
// sebelum dicocokkan ke daftar alias di bawah.
const FLOWS_IMPORT_COLUMNS = {
  ticker: ["kode saham", "kode", "stock code", "stockcode", "kode emiten", "ticker"],
  open: ["open price", "openprice", "open"],
  high: ["tertinggi", "high"],
  low: ["terendah", "low"],
  close: ["penutupan", "close", "closing price", "close price"],
  volume: ["volume"],
  value: ["nilai", "value"],
  frequency: ["frekuensi", "frequency"],
  foreignBuy: ["foreign buy", "foreignbuy", "asing beli"],
  foreignSell: ["foreign sell", "foreignsell", "asing jual"],
  nonRegVolume: ["non regular volume", "nonregular volume", "nonregularvolume", "volume non reguler", "non reguler volume"],
  nonRegValue: ["non regular value", "nonregular value", "nonregularvalue", "nilai non reguler", "non reguler nilai"],
  listedShares: ["listed shares", "listedshares", "saham tercatat", "jumlah saham tercatat"],
  offer: ["offer", "offer price"],
  offerVolume: ["offer volume", "offervolume", "volume offer"],
  bid: ["bid", "bid price"],
  bidVolume: ["bid volume", "bidvolume", "volume bid"],
  date: ["tanggal perdagangan terakhir", "tanggal", "date", "trade date", "last trading date"],
};

// Header file Excel dirapikan dulu (lowercase + spasi/underscore dirapikan
// jadi 1 spasi) sebelum dicocokkan ke FLOWS_IMPORT_COLUMNS -- supaya
// "Foreign_Buy", "foreign  buy", "FOREIGN BUY" semua kena alias yang sama.
function normFlowsHeader(k){
  return String(k).trim().toLowerCase().replace(/[_\.]+/g, " ").replace(/\s+/g, " ");
}
function pickFlowsCol(norm, aliases){
  for(const a of aliases){ if(norm[a] != null && norm[a] !== "") return norm[a]; }
  return "";
}
// Angka dari Excel/IDX kadang string berformat "1,234,567" atau pakai spasi
// -- dirapikan dulu sebelum parseFloat, sama pola dengan num() di
// sync-idx-full.mjs supaya hasil impor manual & hasil sync-idx-full.mjs
// konsisten.
function numFlowsImport(v){
  if(v === null || v === undefined || v === "") return null;
  const n = Number(typeof v === "string" ? v.replace(/,/g, "").trim() : v);
  return Number.isFinite(n) ? n : null;
}

// Baca satu baris hasil XLSX.utils.sheet_to_json -> objek siap upsert ke
// `flows`. `fallbackDate` dipakai kalau file tidak punya kolom tanggal per
// baris (lazim -- file "Ringkasan Saham" IDX isinya 1 hari utk semua
// ticker, tanggalnya dipilih user lewat input tanggal di UI, bukan per baris).
function mapFlowsImportRow(rawRow, fallbackDate){
  const norm = {};
  Object.entries(rawRow).forEach(([k,v]) => { norm[normFlowsHeader(k)] = v; });
  const pick = (aliases) => pickFlowsCol(norm, aliases);
  const dateRaw = pick(FLOWS_IMPORT_COLUMNS.date);
  return {
    ticker: String(pick(FLOWS_IMPORT_COLUMNS.ticker) || "").trim().toUpperCase().replace(".JK", ""),
    date: (dateRaw ? normImportDate(dateRaw) : "") || fallbackDate || "",
    src: "idx", // wajib eksplisit: tanpa ini, baris yang sebelumnya src='stockbit'
                // tetap berlabel 'stockbit' walau datanya sudah ditimpa resmi IDX
                // (upsert PostgREST cuma menimpa kolom yang dikirim di payload)
    open_price: numFlowsImport(pick(FLOWS_IMPORT_COLUMNS.open)),
    high: numFlowsImport(pick(FLOWS_IMPORT_COLUMNS.high)),
    low: numFlowsImport(pick(FLOWS_IMPORT_COLUMNS.low)),
    close: numFlowsImport(pick(FLOWS_IMPORT_COLUMNS.close)),
    volume: numFlowsImport(pick(FLOWS_IMPORT_COLUMNS.volume)),
    value: numFlowsImport(pick(FLOWS_IMPORT_COLUMNS.value)),
    frequency: numFlowsImport(pick(FLOWS_IMPORT_COLUMNS.frequency)),
    foreign_buy: numFlowsImport(pick(FLOWS_IMPORT_COLUMNS.foreignBuy)),
    foreign_sell: numFlowsImport(pick(FLOWS_IMPORT_COLUMNS.foreignSell)),
    nonreg_volume: numFlowsImport(pick(FLOWS_IMPORT_COLUMNS.nonRegVolume)),
    nonreg_value: numFlowsImport(pick(FLOWS_IMPORT_COLUMNS.nonRegValue)),
    listed_shares: numFlowsImport(pick(FLOWS_IMPORT_COLUMNS.listedShares)),
    offer: numFlowsImport(pick(FLOWS_IMPORT_COLUMNS.offer)),
    offer_volume: numFlowsImport(pick(FLOWS_IMPORT_COLUMNS.offerVolume)),
    bid: numFlowsImport(pick(FLOWS_IMPORT_COLUMNS.bid)),
    bid_volume: numFlowsImport(pick(FLOWS_IMPORT_COLUMNS.bidVolume)),
  };
}

function triggerFlowsImportFile(){
  document.getElementById("flowsImportFileInput")?.click();
}

// Dipanggil dari <input type="file" id="flowsImportFileInput" onchange=...>.
// Menerima .xlsx/.xls/.csv hasil unduhan "Ringkasan Saham" idx.co.id.
// Baris tanpa ticker/close/tanggal valid DILEWATI (bukan gagal fatal),
// supaya baris judul/kosong di file IDX tidak menghentikan baris lain.
async function handleFlowsImportFile(fileInput){
  const file = fileInput.files && fileInput.files[0];
  fileInput.value = ""; // reset supaya file yang sama bisa dipilih lagi
  if(!file) return;
  if(!SUPABASE_URL || !SUPABASE_KEY){ openSettings(); return; }

  // Tanggal perdagangan: pakai input tanggal di UI kalau sudah diisi user,
  // kalau belum coba tebak dari nama file (pola umum unduhan IDX:
  // "...20260922..." atau "...22092026...", DD-MM-YYYY, dst), fallback
  // hari ini. User tetap bisa koreksi manual sebelum/steelah upload lewat
  // input tanggal -- import berikutnya akan pakai tanggal itu.
  let fallbackDate = state.flowsImportDate || "";
  if(!fallbackDate){
    const m8 = file.name.match(/(20\d{2})[-_]?(\d{2})[-_]?(\d{2})/); // YYYYMMDD / YYYY-MM-DD
    if(m8) fallbackDate = `${m8[1]}-${m8[2]}-${m8[3]}`;
    else {
      const mDmy = file.name.match(/(\d{2})[-_](\d{2})[-_](20\d{2})/); // DD-MM-YYYY
      if(mDmy) fallbackDate = `${mDmy[3]}-${mDmy[2]}-${mDmy[1]}`;
    }
    if(!fallbackDate) fallbackDate = todayLocalISO();
    state.flowsImportDate = fallbackDate;
  }

  state.flowsImporting = true; state.flowsImportMsg = ""; state.flowsImportMsgError = false; render();
  try{
    const buf = await file.arrayBuffer();
    const wb = XLSX.read(buf, { type: "array", cellDates: false });
    const sheet = wb.Sheets[wb.SheetNames[0]];
    const json = XLSX.utils.sheet_to_json(sheet, { defval: "" });
    if(!json.length) throw new Error('File kosong atau format tidak terbaca (pastikan baris pertama adalah header kolom, mis. "Kode Saham", "Penutupan", dst).');

    const rows = [];
    let skipped = 0;
    json.forEach(rawRow => {
      const r = mapFlowsImportRow(rawRow, fallbackDate);
      if(!r.ticker || !r.date || r.close == null){ skipped++; return; }
      rows.push(r);
    });
    if(!rows.length) throw new Error(`Tidak ada baris valid untuk diimpor (${skipped} baris dilewati — pastikan kolom Kode Saham & Penutupan terisi, dan tanggal sudah dipilih di atas).`);

    // Upsert BATCH per 200 baris (sama pola dengan sync-idx-full.mjs) --
    // PostgREST terima array JSON di body POST + Prefer: merge-duplicates.
    for(const part of chunkArray(rows, 200)){
      await supaFetch(`${SUPABASE_URL}/flows?on_conflict=ticker,date`, {
        method: "POST",
        headers: { ...getSupaHeaders(), "Prefer": "resolution=merge-duplicates,return=minimal" },
        body: JSON.stringify(part),
      });
    }

    const tickers = [...new Set(rows.map(r => r.ticker))];
    state.flowsImportedTickers = tickers;
    state.flowsImportedDate = fallbackDate;
    state.flowsImportMsg = `✅ ${rows.length} saham berhasil diimpor ke flows untuk tanggal ${fallbackDate}${skipped ? ` (${skipped} baris dilewati karena kolom wajib kosong)` : ""}. Klik "📊 Update Teknikal (dari flows)" di tab Screener untuk menghitung ulang indikator.`;
    state.flowsImportMsgError = false;
  } catch(e){
    state.flowsImportMsg = "Gagal impor: " + e.message;
    state.flowsImportMsgError = true;
  }
  state.flowsImporting = false;
  render();
}

function hitungPorto(v){
  const nilaiBeli = (v.hargaBeli||0) * (v.lotBeli||0) * 100;
  const feeBeliRp = nilaiBeli * ((v.feeBeliPct||0)/100);
  const totalBeli = nilaiBeli > 0 ? Math.round(nilaiBeli + feeBeliRp) : 0;

  const nilaiJual = (v.hargaJual||0) * (v.lotJual||0) * 100;
  const feeJualRp = nilaiJual * ((v.feeJualPct||0)/100);
  const netJual = nilaiJual > 0 ? Math.round(nilaiJual - feeJualRp) : 0;

  let jangkaWaktu = "";
  if(v.tglBeli && v.tglJual){
    const d1 = new Date(v.tglBeli), d2 = new Date(v.tglJual);
    if(!isNaN(d1) && !isNaN(d2)) jangkaWaktu = Math.round((d2-d1)/86400000);
  }

  let persenPL = "", nilaiPL = "", status = "Open";
  if(totalBeli > 0 && netJual > 0){
    nilaiPL = netJual - totalBeli;
    persenPL = +((nilaiPL/totalBeli)*100).toFixed(2);
    status = nilaiPL > 0 ? "Win" : (nilaiPL < 0 ? "Loss" : "BEP");
  }
  return { totalBeli, netJual, jangkaWaktu, persenPL, nilaiPL, status };
}

function readPortoForm(){
  const g = id => document.getElementById(id);
  return {
    ticker: (g("pfTicker").value||"").trim().toUpperCase().replace(".JK",""),
    jenisPorto: g("pfJenis") ? g("pfJenis").value : PORTO_JENIS_DEFAULT,
    tglBeli: g("pfTglBeli").value,
    hargaBeli: parseFloat(g("pfHargaBeli").value) || 0,
    lotBeli: parseFloat(g("pfLotBeli").value) || 0,
    feeBeliPct: parseFloat(g("pfFeeBeli").value),
    support: g("pfSupport").value,
    resistance: g("pfResistance").value,
    fib618: g("pfFib618").value,
    targetTP: g("pfTargetTP").value,
    cutLoss: g("pfCutLoss").value,
    tglJual: g("pfTglJual").value,
    hargaJual: parseFloat(g("pfHargaJual").value) || 0,
    lotJual: parseFloat(g("pfLotJual").value) || 0,
    feeJualPct: parseFloat(g("pfFeeJual").value),
    catatan: g("pfCatatan").value
  };
}

function recalcPortoForm(){
  const v = readPortoForm();
  const c = hitungPorto(v);
  document.getElementById("pfTotalBeli").value = c.totalBeli ? fmtNum(c.totalBeli) : "";
  document.getElementById("pfNetJual").value = c.netJual ? fmtNum(c.netJual) : "";
  document.getElementById("pfJangka").value = c.jangkaWaktu !== "" ? c.jangkaWaktu + " hari" : "";
  document.getElementById("pfPersenPL").value = c.persenPL !== "" ? (c.persenPL>0?"+":"") + c.persenPL + "%" : "";
  document.getElementById("pfNilaiPL").value = c.nilaiPL !== "" ? fmtNum(c.nilaiPL) : "";
  const statusEl = document.getElementById("pfStatus");
  statusEl.value = c.status;
  statusEl.className = c.status==="Win" ? "status-win" : c.status==="Loss" ? "status-loss" : "status-open";
}

function resetPortoForm(){
  state.portoEditId = null;
  state.portoModalOpen = false;
  state.portoPrefill = null;
  render();
}

function openPortoModal(id){
  state.portoEditId = id || null;
  state.portoModalOpen = true;
  state.portoPrefill = null;
  render();
}

// ==========================================
// TAMBAH KE PORTOFOLIO DARI TAB BACKTEST — dipicu klik kode emiten
// (ticker) di baris tabel Backtest. Membuka modal "Tambah Transaksi
// Portofolio" dalam mode TAMBAH BARU (bukan edit), dengan Ticker, Tanggal
// Beli, dan Harga Beli sudah terisi dari harga/tanggal entry backtest
// yang SUDAH TERKUNCI (item.entryPrice/item.entryDate — lihat catatan di
// saveToBacktest/addManualBacktest) — bukan dari harga live saat ini,
// supaya entry backtest dan entry portofolio konsisten.
// ==========================================
function addBacktestItemToPortfolio(sessionId, ticker){
  const session = state.backtests.find(b => String(b.id) === String(sessionId));
  const item = session ? session.items.find(it => it.ticker === ticker) : null;
  if(!item) return;
  state.portoEditId = null;
  state.portoPrefill = {
    ticker: item.ticker,
    hargaBeli: item.entryPrice || "",
    tglBeli: item.entryDate || todayLocalISO()
  };
  state.portoModalOpen = true;
  render();
}

function autofillPortoFromScreener(){
  const el = document.getElementById("pfTicker");
  if(!el) return;
  const ticker = (el.value||"").trim().toUpperCase().replace(".JK","");
  const s = enriched().find(x=>x.ticker===ticker);
  if(!s) return;
  const sSupport = document.getElementById("pfSupport");
  const sResistance = document.getElementById("pfResistance");
  const sFib618 = document.getElementById("pfFib618");
  if(sSupport) sSupport.value = s.support ?? "";
  if(sResistance) sResistance.value = s.resistance ?? "";
  if(sFib618) sFib618.value = s.fib?.f618 ?? "";
}

